#ifndef SB_GRAPHICS
// ShoreBreak calculations ported to CUDA for SamG-Coder's WebCuda.
// Production precision conversion: match upstream RGBA16F render targets.
__global__ void quantizeField(float4* values,int width,int height,int offset){
 int x=blockIdx.x*blockDim.x+threadIdx.x,y=blockIdx.y*blockDim.y+threadIdx.y;if(x>=width||y>=height)return;
 int i=offset+y*width+x;float4 v=values[i];__half a=__float2half_rn(v.x),b=__float2half_rn(v.y),c=__float2half_rn(v.z),d=__float2half_rn(v.w);
 values[i]=make_float4(__half2float(a),__half2float(b),__half2float(c),__half2float(d));
}
