  float u=sb_clamp((time-sb.uSwellMinTime)/(-sb.uSwellMinTime),0.0f,1.0f);
  return sb_lookup(lookup,sb_vec2((u*4095.0f+.5f)/4096.0f,.375f),0.0f);
