__device__ float2 originalWaterField_rot0(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.9563048f*v.x+ -0.2923717f*v.y, 0.2923717f*v.x+ 0.9563048f*v.y);}__device__ float2 originalWaterField_rot0T(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.9563048f*v.x+ 0.2923717f*v.y, -0.2923717f*v.x+ 0.9563048f*v.y);}
__device__ float2 originalWaterField_rot1(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.8571673f*v.x+ 0.5150381f*v.y, -0.5150381f*v.x+ 0.8571673f*v.y);}__device__ float2 originalWaterField_rot1T(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.8571673f*v.x+ -0.5150381f*v.y, 0.5150381f*v.x+ 0.8571673f*v.y);}
__device__ float2 originalWaterField_rot2(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.7313537f*v.x+ -0.6819984f*v.y, 0.6819984f*v.x+ 0.7313537f*v.y);}__device__ float2 originalWaterField_rot2T(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v){return sb_vec2(0.7313537f*v.x+ 0.6819984f*v.y, -0.6819984f*v.x+ 0.7313537f*v.y);}

__device__ float2 originalWaterField_ocVar(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 v, float c2) { return sb_vec2(c2 * v.x + (1.0f - c2) * v.y, (1.0f - c2) * v.x + c2 * v.y); }





__device__ float originalWaterField_pawFbm(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 p, float fz, int oct) {
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 5; i++) {
    if (i >= oct) break;
    s += a * gnoise(events,lookup,sb,p) * (1.0f - sb_smoothstep(0.25f, 0.5f, fz));
    p = sb_vec2(1.6f*p.x-1.2f*p.y,1.2f*p.x+1.6f*p.y); a *= 0.5f; fz *= 2.0f;
  }
  return s;
}
__device__ float originalWaterField_catsPaw(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t, float fp) {
  float2 q = xz * sb_vec2(0.055f, 0.16f);
  float a = originalWaterField_pawFbm(events,lookup,sb,data,descriptors,sbuParams,q + sb_vec2(0.021f, -0.12f) * t, fp * 0.16f, 4);
  float b = originalWaterField_pawFbm(events,lookup,sb,data,descriptors,sbuParams,q * 1.7f + sb_vec2(-0.05f, -0.2f) * t + 11.3f, fp * 0.27f, 3);
  float f = 0.5f + 0.8f * (0.62f * a + 0.38f * b);
#ifdef originalWaterField_OPT_EXPLORE


  float D = sb_max(4.1f - xz.y, 1.0f);
  float r = xz.x / (0.72f * D);
  float lane = sb_clamp(0.45f * gnoise(events,lookup,sb,sb_vec2(xz.x * 0.013f + 0.37f, xz.y * 0.009f - 1.3f)), -0.5f, 0.5f);
  float u = sb_mix(sb_clamp(r, -0.5f, 0.5f), lane, sb_smoothstep(0.6f, 1.6f, sb_abs(r)));
#else
  float D = sb_max(sbuParams.cameraPosition.z - xz.y, 1.0f);
  float u = sb_clamp(xz.x / (0.72f * D), -0.5f, 0.5f);
#endif
  float lr = 1.0f - 1.1f * u;
  return sb_mix(1.0f, sb_clamp(f, 0.15f, 1.6f) * lr, sbuParams.uOceanAmp.w);
}



#ifdef originalWaterField_OPT_EXPLORE
__device__ float originalWaterField_oceanFarGain(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return sb_mix(sbuParams.uSeaTune5.w, 1.0f, sb_smoothstep(15.0f, 40.0f, 4.1f - xz.y)); }

__device__ float originalWaterField_viewDistH(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return length(xz - sb_sw_xz(sbuParams.cameraPosition)); }
#else
__device__ float originalWaterField_oceanFarGain(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return sb_mix(sbuParams.uSeaTune5.w, 1.0f, sb_smoothstep(15.0f, 40.0f, sbuParams.cameraPosition.z - xz.y)); }
__device__ float originalWaterField_viewDistH(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return sbuParams.cameraPosition.z - xz.y; }
#endif



__device__ float3 originalWaterField_oceanDisp(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float fp, float paw, float2& slope) {
  float3 d = sb_vec3(0.0f); slope = sb_vec2(0.0f);
  float lf = log2f(sb_max(fp, 1e-4f) * 256.0f) + 0.5f;
  float l0 = lf - log2f(sbuParams.uOceanL.x), l1 = lf - log2f(sbuParams.uOceanL.y), l2 = lf - log2f(sbuParams.uOceanL.z);
  paw = sb_max(paw, 0.0f);
  float3 a = sb_sw_xyz(sbuParams.uOceanAmp) * sb_vec3(originalWaterField_oceanFarGain(events,lookup,sb,data,descriptors,sbuParams,xz), sb_sqrt(paw), paw);
  float4 D = sb_sampleArray(data,descriptors,0,sb_vec3(originalWaterField_rot0(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.x, 0.0f),l0);
  float4 S = sb_sampleArray(data,descriptors,1,sb_vec3(originalWaterField_rot0(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.x, 0.0f),l0);
  d.y = D.y * a.x; {float2 swizzle0=(originalWaterField_rot0T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xz(D))) * a.x;d.x=swizzle0.x;d.z=swizzle0.y;}
  slope += (originalWaterField_rot0T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xy(S))) * a.x;
  if (l1 < 8.0f) {
    D = sb_sampleArray(data,descriptors,0,sb_vec3(originalWaterField_rot1(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.y, 1.0f),l1); S = sb_sampleArray(data,descriptors,1,sb_vec3(originalWaterField_rot1(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.y, 1.0f),l1);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l1);
    d.y += D.y * a.y * keep; {float2 swizzle1=sb_sw_xz(d)+((originalWaterField_rot1T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xz(D))) * a.y * keep);d.x=swizzle1.x;d.z=swizzle1.y;} slope += (originalWaterField_rot1T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xy(S))) * a.y * keep;
  }
  if (l2 < 8.0f) {
    D = sb_sampleArray(data,descriptors,0,sb_vec3(originalWaterField_rot2(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.z, 2.0f),l2); S = sb_sampleArray(data,descriptors,1,sb_vec3(originalWaterField_rot2(events,lookup,sb,data,descriptors,sbuParams,xz) / sbuParams.uOceanL.z, 2.0f),l2);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l2);
    d.y += D.y * a.z * keep; {float2 swizzle2=sb_sw_xz(d)+((originalWaterField_rot2T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xz(D))) * a.z * keep);d.x=swizzle2.x;d.z=swizzle2.y;} slope += (originalWaterField_rot2T(events,lookup,sb,data,descriptors,sbuParams,sb_sw_xy(S))) * a.z * keep;
  }
  return d;
}


__device__ float3 originalWaterField_chopWaves(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t, float lod) {
  float2 s; float3 d = originalWaterField_oceanDisp(events,lookup,sb,data,descriptors,sbuParams,xz, lod, 1.0f, s);
  return sb_vec3(d.y, s);
}








__device__ float2 originalWaterField_sweUV(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return (xz - sb_sw_xy(sbuParams.uSweDom)) / sb_sw_zw(sbuParams.uSweDom); }
__device__ float originalWaterField_sweInside(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) {
  float2 uv = originalWaterField_sweUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  float2 e = sb_min(uv, 1.0f - uv);

  return sb_smoothstep(0.0f, 0.04f, sb_min(e.x, e.y * sbuParams.uSweDom.w / 9.8f));
}

#ifndef originalWaterField_SWASH_FAR_CORE_DEF
#define originalWaterField_SWASH_FAR_CORE_DEF 1
#define originalWaterField_SWASH_FAR_ON 1





__device__ float originalWaterField_swashFarU(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float x) {
  float g = sbuParams.uSwashFarMap.y * sb_asinh((x - sbuParams.uSwashFarMap.x) / sbuParams.uSwashFarMap.y);
  return 0.5f + 0.5f * g / sbuParams.uSwashFarMap.z;
}
__device__ float originalWaterField_swashFarXofColumn(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float i) {
  float g = ((i + 0.5f) / sbuParams.uSwashFarMapZ.w - 0.5f) * 2.0f * sbuParams.uSwashFarMap.z;
  return sbuParams.uSwashFarMap.x + sbuParams.uSwashFarMap.y * sb_sinh(g / sbuParams.uSwashFarMap.y);
}
__device__ float2 originalWaterField_swashFarUV(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) { return sb_vec2(originalWaterField_swashFarU(events,lookup,sb,data,descriptors,sbuParams,xz.x), (xz.y - sbuParams.uSwashFarMapZ.x) / (sbuParams.uSwashFarMapZ.y * sbuParams.uSwashFarMapZ.z) + 0.5f / sbuParams.uSwashFarMapZ.z); }
__device__ float originalWaterField_swashVisualFocusX(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams) {


  return sb_clamp(sbuParams.uSwashFocus.x, sbuParams.uSwashFarWin.x - 1.1f, sbuParams.uSwashFarWin.x + 1.1f);
}
__device__ float originalWaterField_swashFarWeight(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) {




  float visible = sb_smoothstep(sbuParams.uSwashFarWin.y, sbuParams.uSwashFarWin.z, sb_abs(xz.x - originalWaterField_swashVisualFocusX(events,lookup,sb,data,descriptors,sbuParams)));


  float bounds = sb_smoothstep(9.95f, 10.14f, sb_abs(xz.x - sbuParams.uSwashFarWin.x));
  return sbuParams.uSwashFarWin.w * sb_max(visible, bounds);
}




__device__ float originalWaterField_swashFarInZ(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 uv) { return sb_step(0.0f, uv.y) * sb_step(uv.y, 1.0f); }
__device__ float4 originalWaterField_swashFar(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t) {
  float2 uv = originalWaterField_swashFarUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  float4 result = sb_vec4(0.0f);
  if (originalWaterField_swashFarInZ(events,lookup,sb,data,descriptors,sbuParams,uv) < 0.5f) { float B = bedProfile(events,lookup,sb,xz.y); result = sb_vec4(sb_max(-B, 0.0f), 0.0f, 0.0f, sb_max(B, 0.0f)); }
  else result = sb_sample(data,descriptors,6,uv,0.0f);
  return result;
}
__device__ float4 originalWaterField_swashFarFoam(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t) {
  float2 uv = originalWaterField_swashFarUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  return sb_sample(data,descriptors,7,uv,0.0f) * originalWaterField_swashFarInZ(events,lookup,sb,data,descriptors,sbuParams,uv);
}
__device__ float2 originalWaterField_swashFarWet(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t) {
  float2 uv = originalWaterField_swashFarUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  float2 result = sb_vec2(0.0f);
  if (originalWaterField_swashFarInZ(events,lookup,sb,data,descriptors,sbuParams,uv) < 0.5f) result = sb_vec2(0.0f, 1.0f - sb_smoothstep(0.35f, 0.75f, bedProfile(events,lookup,sb,xz.y)));
  else result = sb_sw_xy(sb_sample(data,descriptors,8,uv,0.0f));
  return result;
}
__device__ float4 originalWaterField_swashFarLace(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t) {
  float2 uv = originalWaterField_swashFarUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  float d = sb_sample(data,descriptors,8,uv,0.0f).z * originalWaterField_swashFarInZ(events,lookup,sb,data,descriptors,sbuParams,uv);
  return sb_vec4(0.0f, -d, 0.0f, -d);
}
__device__ float2 originalWaterField_swashFarGrad(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t) {
  float ex = 0.05f, ez = sbuParams.uSwashFarMapZ.y;
  float wE = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,xz + sb_vec2(ex, 0.0f), t).w, wW = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,xz - sb_vec2(ex, 0.0f), t).w;
  float wN = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,xz + sb_vec2(0.0f, ez), t).w, wS = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,xz - sb_vec2(0.0f, ez), t).w;
  return sb_vec2((wE - wW) / (2.0f * ex), (wN - wS) / (2.0f * ez));
}
__device__ void originalWaterField_swashFarAll(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t, float4& view, float4& foam, float2& wet, float4& lace) {
  float2 uv = originalWaterField_swashFarUV(events,lookup,sb,data,descriptors,sbuParams,xz);
  float inZ = originalWaterField_swashFarInZ(events,lookup,sb,data,descriptors,sbuParams,uv);
  float B = bedProfile(events,lookup,sb,xz.y);
  view = inZ > 0.5f ? sb_sample(data,descriptors,6,uv,0.0f) : sb_vec4(sb_max(-B, 0.0f), 0.0f, 0.0f, sb_max(B, 0.0f));
  foam = sb_sample(data,descriptors,7,uv,0.0f) * inZ;
  float4 w = sb_sample(data,descriptors,8,uv,0.0f);
  wet = inZ > 0.5f ? sb_sw_xy(w) : sb_vec2(0.0f, 1.0f - sb_smoothstep(0.35f, 0.75f, B));
  lace = sb_vec4(0.0f, -w.z, 0.0f, -w.z) * inZ;
}
