#ifndef originalWaterField_OPT_EXPLORE
#define originalWaterField_OPT_EXPLORE 1
#endif


__device__ float originalWaterField_chopWeight(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float depth0) { return sb_smoothstep(0.05f, 1.2f, depth0); }


#ifdef originalWaterField_OPT_EXPLORE

__device__ float3 originalWaterField_swellAt(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz) {
  float v=sb_log(1.0f+sb_max(-xz.y-6.0f,0.0f)/8.0f)/sb_log(81.5f);
  float2 uv=sb_vec2((xz.x+512.0f)/1024.0f,v);
  float fade=(1.0f-sb_smoothstep(420.0f,512.0f,sb_abs(xz.x)))*sb_smoothstep(-650.0f,-460.0f,xz.y);
  return sb_sw_xyz(sb_sample(data,descriptors,9,uv,0.0f))*fade;
}
