__device__ float originalWaterField_waterParts(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t, float lod, float2& gMacro, float3& chop, float2& gChop, float4& info, float& paw) {
  float2 d = sb_vec2(0.0f); float crestFoam = 0.0f;


  float aa = 1.0f - sb_smoothstep(0.08f, 0.35f, lod);
  float eta = 0.0f;
#ifdef originalWaterField_OPT_EXPLORE
  aa=sb_mix(aa,1.0f-sb_smoothstep(.7f,3.0f,lod),1.0f-sb_smoothstep(-11.0f,-7.0f,xz.y));
  if (aa > 0.0f && xz.y > -40.0f) {
#endif
  eta = brkSurface(events,lookup,sb,xz, t, d, crestFoam);
  float etaX = brkSurfaceOnly(events,lookup,sb,xz + sb_vec2(0.04f, 0.0f), t);
  d.x = (etaX - eta) / 0.04f;
#ifdef originalWaterField_OPT_EXPLORE
  }
#endif
  eta *= aa; d *= aa; crestFoam *= aa;
#ifdef originalWaterField_OPT_EXPLORE
  float sw=1.0f-sb_smoothstep(-32.0f,-22.0f,xz.y);
  if(sw>0.0f){
    float3 farSwell=originalWaterField_swellAt(events,lookup,sb,data,descriptors,sbuParams,xz)*(1.0f-sb_smoothstep(3.0f,14.0f,lod));
    float q=sb_clamp((xz.y+32.0f)/10.0f,0.0f,1.0f);
    float slope=-.6f*q*(1.0f-q);
    d=sb_mix(d,sb_sw_yz(farSwell),sw)+sb_vec2(0.0f,(farSwell.x-eta)*slope);
    eta=sb_mix(eta,farSwell.x,sw);
  }
#endif
  sbuParams.gBrkEta = eta;
  float B = bedProfile(events,lookup,sb,xz.y);
  float depth0 = sb_max(-B, 0.0f);
  float chopW = originalWaterField_chopWeight(events,lookup,sb,data,descriptors,sbuParams,depth0);

  chopW *= 1.0f / (1.0f + 1.5f * dot(d, d));
  paw = originalWaterField_catsPaw(events,lookup,sb,data,descriptors,sbuParams,xz, t, lod);
  chop = sb_vec3(0.0f); gChop = sb_vec2(0.0f);



  float chopFar = 1.0f - sb_smoothstep(sbuParams.uSeaTune4.z, sbuParams.uSeaTune4.w, originalWaterField_viewDistH(events,lookup,sb,data,descriptors,sbuParams,xz));
#ifdef originalWaterField_OPT_EXPLORE
  if (chopW > 0.0f && chopFar > 0.0f) { chop = originalWaterField_oceanDisp(events,lookup,sb,data,descriptors,sbuParams,xz, lod, paw, gChop) * chopW; gChop *= chopW; }
#else
  if (chopW > 0.0f) { chop = originalWaterField_oceanDisp(events,lookup,sb,data,descriptors,sbuParams,xz, lod, paw, gChop) * chopW; gChop *= chopW; }
#endif
  chop *= chopFar;

  {float2 swizzle3=sb_sw_xz(chop)*(1.0f - sb_smoothstep(0.04f, 0.2f, eta));chop.x=swizzle3.x;chop.z=swizzle3.y;}

  float wIn = originalWaterField_sweInside(events,lookup,sb,data,descriptors,sbuParams,xz);
  float4 sv = sb_sample(data,descriptors,2,originalWaterField_sweUV(events,lookup,sb,data,descriptors,sbuParams,xz),0.0f);
  float sweEta = sb_mix(0.0f, sv.w, wIn);
  float sweH = sv.x;

  float wF = originalWaterField_swashFarWeight(events,lookup,sb,data,descriptors,sbuParams,xz);
  if (wF > 0.0f) {
    float4 sf = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,xz, t);
    sweEta = sb_mix(sweEta, sf.w, wF);
    sweH = sb_mix(sweH, sf.x, wF);
  }
  gMacro = d;
  info = sb_vec4(crestFoam, sweH, sb_max(wIn, wF), chopW);
  return sweEta + eta;
}

__device__ float2 originalWaterField_clampLen(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 g, float m) { float l = length(g); return l > m ? g * (m / l) : g; }



__device__ float2 originalWaterField_sweGradient(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float e0, float4& far) {
  float2 g = sb_vec2(0.0f);
  far = sb_vec4(0.0f);
  float wIn = originalWaterField_sweInside(events,lookup,sb,data,descriptors,sbuParams,xz);
  if (wIn > 0.0f) {
    float2 uv = originalWaterField_sweUV(events,lookup,sb,data,descriptors,sbuParams,xz); float2 e = sbuParams.uSweTexel * e0;
    float wE = sb_sample(data,descriptors,2,uv + sb_vec2(e.x, 0.0f),0.0f).w, wW = sb_sample(data,descriptors,2,uv - sb_vec2(e.x, 0.0f),0.0f).w;
    float wN = sb_sample(data,descriptors,2,uv + sb_vec2(0.0f, e.y),0.0f).w, wS = sb_sample(data,descriptors,2,uv - sb_vec2(0.0f, e.y),0.0f).w;
    g = wIn * sb_vec2(wE - wW, wN - wS) / (2.0f * e * sb_sw_zw(sbuParams.uSweDom));
  }
  float wF = originalWaterField_swashFarWeight(events,lookup,sb,data,descriptors,sbuParams,xz);
  if (wF > 0.0f) {

    float h = 0.03f;
    float3 w = sb_vec3(0.0f);
    for (int k = 0; k < 3 + sb_min(sb.uEvtCount, 0); k++) {
      float2 p = xz + (k == 1 ? sb_vec2(h, 0.0f) : (k == 2 ? sb_vec2(0.0f, h) : sb_vec2(0.0f)));
      float4 fk = originalWaterField_swashFar(events,lookup,sb,data,descriptors,sbuParams,p, sb.uTime);
      if (k == 0) { w.x = fk.w; far = fk; } else if (k == 1) w.y = fk.w; else w.z = fk.w;
    }
    g = sb_mix(g, sb_vec2(w.y - w.x, w.z - w.x) / h, wF);
  }
  return g;
}



__device__ float originalWaterField_waterHeight(const float4* events,const float4* lookup,SBUniforms sb,const float4* data,const float4* descriptors,originalWaterFieldParams& sbuParams,float2 xz, float t, float lod, float2& grad, float4& info) {
  float2 gm, gc; float3 ch; float paw;
  float y = originalWaterField_waterParts(events,lookup,sb,data,descriptors,sbuParams,xz, t, lod, gm, ch, gc, info, paw);
  grad = gm + gc;
  return y + ch.y;
}


























__global__ void originalWaterField(const float4* events,const float4* lookup,const SBUniforms* uniforms,const float4* data,const float4* descriptors,const originalWaterFieldParams* params,float4* output,int width,int height){
 int px=blockIdx.x*blockDim.x+threadIdx.x,py=blockIdx.y*blockDim.y+threadIdx.y;if(px>=width||py>=height)return;int index=py*width+px;SBUniforms sb=uniforms[0];originalWaterFieldParams sbuParams=params[0];float2 vUv=(sb_vec2(px,py)+0.5f)/sb_vec2(width,height);
 float2 xz=sb_sw_xy(sbuParams.uFieldDom)+(sb_vec2(px,py)-.5f)/(sbuParams.uFieldSize-1.0f)*sb_sw_zw(sbuParams.uFieldDom);
 float2 gm,gc;float3 ch;float4 info;float paw;
 float y=originalWaterField_waterParts(events,lookup,sb,data,descriptors,sbuParams,xz,sb.uTime,.016f,gm,ch,gc,info,paw);
 float4 far;gm+=originalWaterField_clampLen(events,lookup,sb,data,descriptors,sbuParams,originalWaterField_sweGradient(events,lookup,sb,data,descriptors,sbuParams,xz,1.5f,far),sbuParams.uSweSlope.x);
 output[0*width*height+index]=sb_vec4(y+ch.y,info.x,info.y,sbuParams.gBrkEta);
 output[1*width*height+index]=sb_vec4(gm+gc,ch.x,ch.z);
}



