__device__ float3 refract(float3 i,float3 n,float eta){float d=dot(n,i),k=1.0f-eta*eta*(1.0f-d*d);if(k<0.0f)return make_float3(0.0f,0.0f,0.0f);return eta*i-(eta*d+sqrtf(k))*n;}
