__device__ float2 operator*(SBMat2 m,float2 v){return m.c0*v.x+m.c1*v.y;}
__device__ float2 operator*(float2 v,SBMat2 m){return make_float2(dot(v,m.c0),dot(v,m.c1));}
__device__ SBMat2 operator*(SBMat2 a,SBMat2 b){return sb_mat2(a*b.c0,a*b.c1);}
__device__ SBMat2 transpose(SBMat2 a){return sb_mat2(a.c0.x,a.c1.x,a.c0.y,a.c1.y);}
