struct GraphicsContext {
SBMat4 modelMatrix;
SBMat4 modelViewMatrix;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
SBMat3 normalMatrix;
float3 cameraPosition;
float3 position;
float3 normal;
float2 uv;
SBMat4 instanceMatrix;
float4 gl_Position;
int gl_VertexID;
int gl_InstanceID;
};
__device__ void main(GraphicsContext& ctx){float4 p=sb_vec4(ctx.position,1.0f);
p=ctx.instanceMatrix*p;
ctx.gl_Position=ctx.projectionMatrix*ctx.modelViewMatrix*p;}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

