    float Rb = 1.25f* sb_mix(0.3f,1.3f,patchF)* sb_exp((0-(sb_max(tau - tc - 0.5f* rs,0.0f)))/ 0.5f)* cover * sb_smoothstep((0-(0.95f)),(0-(0.65f)),z)* sb_smoothstep(0.0f,0.35f,tau);
    float df = (S - z) / 0.4f;
    float Rf = adv ? 0.8f* sb_mix(0.6f,1.15f,patchF)* sb_exp((0-(df ))* df)* cover * sb_smoothstep(0.0f,0.3f,tau - tc + 0.3f)* (1.0f- sb_smoothstep(0.6f,1.0f,(tau - tc) / tup)) : 0.0f;


    float zj = zt - 0.12f+ 0.08f* gnoise(ctx,sb_vec2(x * 1.7f+ sd,tau * 0.8f));
    float dj = (z - zj) / 0.1f;
