    float G = sb_max(1.3f* sb_mix(0.45f,1.2f,patchF)* sb_smoothstep(0.0f,0.5f,ageF)* sb_exp((0-(sb_max(tau - tc - 1.6f* rs,0.0f)))/ 2.2f)* ((reached && tau < tLeft + 0.3f) ? 1.0f: 0.0f),1.8f* sb_mix(0.5f,1.1f,patchP)* sb_smoothstep(0.2f,0.8f,tau)* sb_exp((0-(sb_max(tau - 1.5f,0.0f)))/ 2.2f)* sb_exp((0-(lg ))* lg));
    float sea = sb_smoothstep(zI - 1.4f,zI - 0.2f,z);
    float Mk = (0.25f+ 0.55f* sb_smoothstep(0.0f,0.4f,ageF)* sb_exp((0-(sb_max(tau - tc - 1.2f* rs,0.0f)))/ 1.25f)) * sb_max(reached ? 1.0f: 0.0f,sb_step(z,0.0f)* sea);
    float Kp = 1.6f* sb_exp((0-(sb_max(tau - 1.3f,0.0f)))/ 1.2f)* sb_smoothstep(0.1f,0.9f,tau)* sb_exp((0-(0.5f))* (z - zp) * (z - zp) / 0.36f);
    float Kl = 2.8f* (adv ? sb_exp((0-(sb_max(tau - tc - 1.4f,0.0f)))/ 1.2f): 0.55f+ 0.45f* sb_exp((0-((tau - tm))))) * cover * sb_step(zt - 0.3f,z);
