struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float uT;
float3 uL;
float4 out1;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ float2 cmul(GraphicsContext& ctx,float2 a,float2 b){ return sb_vec2(a.x* b.x- a.y* b.y,a.x* b.y+ a.y* b.x); }

__device__ void main(GraphicsContext& ctx){
  float2 p = sb_ivec2(sb_sw_xy(ctx.gl_FragCoord));
  int c = int(p.x)/ 256;
  int n = int(p.x)- c * 256;
  int m = int(p.y);
  float L = c == 0 ? ctx.uL.x: (c == 1 ? ctx.uL.y: ctx.uL.z);
  float dk = 6.283185307f/ L;
  float2 k = dk * sb_vec2(n < 128 ? n : n - 256,m < 128 ? m : m - 256);
  float kl = length(k);
  float4 h0 = __sb_texelFetch(0,p,0);
  float w = sb_sqrt(9.81f* kl * (1.0f+ kl * kl / 136900.0f));

  float ph = sb_mod(w * ctx.uT,6.283185307f);
  float2 e = sb_vec2(sb_cos(ph),sb_sin(ph));

  float2 h = cmul(ctx,sb_sw_xy(h0),sb_vec2(e.x,(0-(e.y))))+ cmul(ctx,sb_vec2(h0.z,(0-(h0.w))),e);
  float2 ih = sb_vec2((0-(h.y)),h.x);
  float2 kn = kl > 1e-6f? k / kl : sb_vec2(0.0f);

  float2 sx = k.x* ih, sz = k.y* ih;
  float2 dx = (0-(kn.x))* ih, dz = (0-(kn.y))* ih;
  float2 A = h + sb_vec2((0-(sx.y)),sx.x);
  float2 B = sz + sb_vec2((0-(dx.y)),dx.x);
  ctx.gl_FragColor =sb_vec4(A,B);
  ctx.out1 =sb_vec4(dz,0.0f,0.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

