struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
int uSub;
int uHoriz;
float4 out1;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ float2 cmul(GraphicsContext& ctx,float2 a,float2 b){ return sb_vec2(a.x* b.x- a.y* b.y,a.x* b.y+ a.y* b.x); }

__device__ void main(GraphicsContext& ctx){
  float2 p = sb_ivec2(sb_sw_xy(ctx.gl_FragCoord));
  int idx = ctx.uHoriz == 1 ? (int(p.x)& 255) : int(p.y);
  int hs = ctx.uSub >> 1;
  int ev = (idx / ctx.uSub) * hs + (idx & (hs - 1));
  int od = ev + 128;
  float2 pe = ctx.uHoriz == 1 ? sb_ivec2(int(p.x)- idx + ev,int(p.y)): sb_ivec2(int(p.x),float(ev));
  float2 po = ctx.uHoriz == 1 ? sb_ivec2(int(p.x)- idx + od,int(p.y)): sb_ivec2(int(p.x),float(od));
  float ang = 6.283185307f* float(idx & (ctx.uSub - 1))/ float(ctx.uSub);
  float2 w = sb_vec2(sb_cos(ang),sb_sin(ang));
  float4 e0 = __sb_texelFetch(0,pe,0), o0 = __sb_texelFetch(0,po,0);
  float4 e1 = __sb_texelFetch(1,pe,0), o1 = __sb_texelFetch(1,po,0);
  ctx.gl_FragColor =sb_vec4(sb_sw_xy(e0)+ cmul(ctx,w,sb_sw_xy(o0)),sb_sw_zw(e0)+ cmul(ctx,w,sb_sw_zw(o0)));
  ctx.out1 =sb_vec4(sb_sw_xy(e1)+ cmul(ctx,w,sb_sw_xy(o1)),sb_sw_zw(e1)+ cmul(ctx,w,sb_sw_zw(o1)));
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

#endif

