struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
int uCascade;
float uChopK;
float4 outS;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ void main(GraphicsContext& ctx){
  float2 p = sb_ivec2(sb_sw_xy(ctx.gl_FragCoord));
  float2 q = sb_ivec2(int(p.x)+ ctx.uCascade * 256,int(p.y));
  float4 a = __sb_texelFetch(0,q,0);
  float4 b = __sb_texelFetch(1,q,0);
  float h = a.x, sx = a.y, sz = a.z, dx = a.w, dz = b.x;
  ctx.gl_FragColor =sb_vec4(dx * ctx.uChopK,h,dz * ctx.uChopK,0.0f);
  ctx.outS =sb_vec4(sx,sz,sx * sx,sz * sz);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

#endif

