    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l1);
    d.y=d.y+(D.y* a.y* keep); {float2 sb_write1=sb_sw_xz(d)+((sb_sw_xz(D)* ctx.OCR1) * a.y* keep);d.x=sb_write1.x;d.z=sb_write1.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR1) * a.y* keep);
  }
