__device__ float cdfAt(GraphicsContext& ctx,int i,int k){ return __sb_texelFetch(14,sb_ivec2(float(i),float(k)),0).x; }

__device__ float sampleX(GraphicsContext& ctx,int k,float u){
  int lo = 0, hi = 222 - 1;
  for (int it = 0; it < 9 + sb_min(ctx.uEvtCount,0); it++) {
    if (lo >= hi) break;
    int mid = (lo + hi) / 2;
    if (cdfAt(ctx,mid,k)>= u) hi =mid; else lo =mid + 1;
  }
  float c = cdfAt(ctx,lo,k);
  float prev = lo > 0 ? cdfAt(ctx,lo - 1,k): 0.0f;
  float f = sb_clamp((u - prev) / sb_max(c - prev,1e-6f),0.0f,1.0f);
  float e0 = __sb_texelFetch(14,sb_ivec2(float(lo),float(15)),0).x, e1 = __sb_texelFetch(14,sb_ivec2(lo + 1,float(15)),0).x;
  return e0 + f * (e1 - e0);
}

__device__ float lodAt(GraphicsContext& ctx,float x){ return sb_clamp(sb_pow(ctx.uLod.z/ sb_max(length(sb_vec2(x - ctx.uLod.x,(0-(2.00f))- ctx.uLod.y)),1e-3f),ctx.uLod.w),0.070f,1.0f); }

