  float n001 = hash11(ctx,dot(i + sb_vec3(float(0),float(0),float(1)),sb_vec3(1.0f,57.0f,113.0f))), n101 = hash11(ctx,dot(i + sb_vec3(float(1),float(0),float(1)),sb_vec3(1.0f,57.0f,113.0f)));
  float n011 = hash11(ctx,dot(i + sb_vec3(float(0),float(1),float(1)),sb_vec3(1.0f,57.0f,113.0f))), n111 = hash11(ctx,dot(i + sb_vec3(float(1),float(1),float(1)),sb_vec3(1.0f,57.0f,113.0f)));
  return sb_mix(sb_mix(sb_mix(n000,n100,f.x),sb_mix(n010,n110,f.x),f.y),sb_mix(sb_mix(n001,n101,f.x),sb_mix(n011,n111,f.x),f.y),f.z);
