__device__ float patchiness(GraphicsContext& ctx,float2 xz,float seed){
  float n = 0.65f* vnoise(ctx,sb_vec3(xz.x/ 0.4f,xz.y/ 0.4f,ctx.uTime / 0.4f+ seed * 17.0f))+ 0.35f* vnoise(ctx,sb_vec3(xz.x/ 0.17f,xz.y/ 0.17f,ctx.uTime / 0.25f+ 5.3f));
