  }




  float aF0 = 1.0f- sb_exp((0-(sb_pow(ctx.uFoamK.x* tauD,ctx.uFoamK2.x))));


  aF0 =sb_max(aF0,splash * 0.6f* (1.0f- sb_exp((0-(4.0f))* ctx.uFoamK.x* tauD)));
  float aF = aF0 * (1.0f- hole);
  float aW = 1.0f- sb_exp((0-(ctx.uFoamK2.y))* tauW);


  float r1 = sb_clamp(0.013f/ pxm,1.0f,6.0f), r2 = sb_clamp(0.04f/ pxm,2.5f,16.0f);
  float2 g1 = sb_vec2(0.0f), g2 = sb_vec2(0.0f), gw = sb_vec2(0.0f);
  float ring1 = 0.0f, ring2 = 0.0f;
  for (int i = 0; i < 8; i++) {
    float a = float(i)* 0.785398f+ 0.3927f;
    float2 d = sb_vec2(sb_cos(a),sb_sin(a));
    float2 t1 = sb_sw_wy(__sb_textureLod(11,ctx.vUv + d * e * r1,0.0f));
    float h1 = hOf(ctx,t1.x);
    float h2 = H(ctx,ctx.vUv + d * e * r2);
    g1 =g1 +(d * h1); g2 =g2 +(d * h2);
    ring1 =ring1 +(h1); ring2 =ring2 +(h2);
    gw =gw +(d * sb_log(1.0f+ ctx.uFoamK2.y* t1.y));
  }
  g1 =g1 /(4.0f* r1 * pxm);
  g2 =g2 /(4.0f* r2 * pxm);
  gw =gw /(4.0f* r1 * pxm);


  float2 gB = sb_vec2(0.0f);
  float lapB = 0.0f;
  for (int k = 0; k < 2; k++) {
    float s = k == 0 ? 0.09f: 0.22f;
    float rt = s / pxm;
    float lod = sb_log2(sb_max(0.5f* rt,1.0f));
    float c0 = HL(ctx,ctx.vUv,lod);
    float hxp = HL(ctx,ctx.vUv + sb_vec2(e.x* rt,0.0f),lod), hxm = HL(ctx,ctx.vUv - sb_vec2(e.x* rt,0.0f),lod);
    float hyp = HL(ctx,ctx.vUv + sb_vec2(0.0f,e.y* rt),lod), hym = HL(ctx,ctx.vUv - sb_vec2(0.0f,e.y* rt),lod);
    float wk = k == 0 ? 0.6f: 0.4f;
    gB =gB +(wk * sb_vec2(hxp - hxm,hyp - hym)/ (2.0f* s));
    lapB =lapB +(wk * (hxp + hxm + hyp + hym - 4.0f* c0) / s);
  }


  float2 grad = (0.6f* g1 + 0.4f* g2) * ctx.uFoamK.y+ gB * ctx.uFoamK2.z* sb_mix(1.0f,ctx.uSplashK.y,splash)+ bilG;

  float wNear = sb_smoothstep(4.5e-3f,1.8e-3f,pxm);
  if (wNear > 0.0f) {
    float r0 = sb_clamp(0.0035f/ pxm,1.0f,2.5f);
    float2 g0 = sb_vec2(0.0f);
    for (int i = 0; i < 4; i++) {
      float a = float(i)* 1.5707963f+ 0.7853982f;
      float2 d = sb_vec2(sb_cos(a),sb_sin(a));
      g0 =g0 +(d * H(ctx,ctx.vUv + d * e * r0));
    }
    g0 =g0 /(2.0f* r0 * pxm);
    grad =sb_mix(grad,(0.35f* g0 + 0.4f* g1 + 0.25f* g2) * ctx.uFoamK.y+ gB * ctx.uFoamK2.z+ bilG,wNear);
  }


  float2 nL = Dt.y> 1e-3f? sb_sw_xy(__sb_texture(13,ctx.vUv))/ Dt.y: sb_vec2(0.0f);
  nL =nL *(sb_smoothstep(0.0f,0.08f,Dt.y)* sb_mix(1.0f,ctx.uSplashK.x,splash));


  float3 nV = normalize(sb_vec3((0-(grad.x))+ ctx.uFoamK3.w* nL.x,sb_max((0-(grad.y))+ ctx.uFoamK3.w* nL.y,ctx.uFoamK3.x),1.0f));

  float3 N = normalize(ctx.uCamRot * nV + sb_vec3(0.0f,0.35f+ ctx.uBilUp * wLow,0.0f));

  float lap = (ring2 - ring1) / (8.0f* r2 * pxm);
  float cav = sb_clamp(1.0f- ctx.uFoamK.w* lap * 1.5f- ctx.uFoamK2.w* lapB,ctx.uFoamK3.z,1.08f);
  cav =cav *(1.0f- ctx.uBil.z* (0.5f- bil));
  cav =sb_mix(cav,1.0f,ctx.uSplashK.z* splash);



  float kS = __sb_textureLod(14,ctx.vUv,0.0f).x;


  if (kS > 0.0f&& ctx.uCrev.x> 0.0f&& wLow < 0.99f) {
    float zS = 1.0f/ kS, dzF = 0.0f, dzN = 0.0f;
    for (int i = 0; i < 6; i++) {
      float a = float(i)* 1.0471976f+ 0.3f;
      float rr = i < 3 ? 2.5f: 5.0f;
      float kN = __sb_textureLod(14,ctx.vUv + sb_vec2(sb_cos(a),sb_sin(a))* rr * e,0.0f).x;
      if (kN > 0.0f) {
        float dz = zS - 1.0f/ kN;
        dzF =sb_max(dzF,dz);
        dzN =sb_max(dzN,(0-(dz)));
      }
    }
    float kc = 1.0f- wLow;
    cav =cav *(1.0f- ctx.uCrev.x* kc * (1.0f- 0.5f* splash) * sb_smoothstep(ctx.uCrev.z,3.0f* ctx.uCrev.z,dzF));
    cav =cav *(1.0f+ ctx.uCrev.y* kc * sb_smoothstep(ctx.uCrev.z,3.0f* ctx.uCrev.z,dzN));
  }


  float occ = 0.0f;
  for (int i = 1; i <= 4; i++) {
    float dm = 0.02f* float(i * i);
    float2 ts = sb_sw_xy(__sb_textureLod(11,ctx.vUv + ctx.uSunScreen * sb_min(dm / pxm,60.0f)* e,0.0f));
    occ =occ +((1.0f- sb_exp((0-(0.5f))* (ts.x+ 0.3f* ts.y))) * (1.2f- 0.2f* float(i)));
  }
  float shadow = sb_mix(ctx.uShadow,1.0f,sb_exp((0-(0.45f))* occ));



  float ndl = dot(N,ctx.uSunDir);
  float wrap = 0.5f+ 0.5f* sb_clamp((ndl + 0.8f) / 1.8f,0.0f,1.0f);
  wrap =wrap *(1.0f+ ctx.uLight.z* sb_smoothstep(0.5f,0.9f,ndl));
  float3 amb = ctx.uAmbCol * sb_mix(ctx.uFoamK3.y,1.05f,0.5f+ 0.5f* N.y);
  const float SUNVIS = 0.87f;
  float3 col = ctx.uAlbedo * (ctx.uSunColor * (ctx.uLight.x/ 3.14159f) * wrap * SUNVIS * shadow + amb * ctx.uLight.y* sb_mix(0.8f,1.0f,shadow)) * cav;
  col =col *(sb_clamp(1.0f+ ctx.uDetCol * det * sb_mix(1.0f,1.6f,splash),0.78f,1.15f));

  float3 V = normalize(ctx.uCamRot * ray);
  float nh = dot(N,normalize(ctx.uSunDir - V));
  float2 capQ = (sb_sw_xz(Pw)- sb_sw_yz(sv)* inW * 0.03f) / 0.009f;
  float2 gc = sb_floor(capQ);
  float2 gp = hash22(ctx,gc + 0.37f);
  float gd = length(sb_fract(capQ)- gp)* 0.009f/ sb_max(px,0.0005f);
  float glint = ctx.uCrev.w* sb_smoothstep(0.985f,0.998f,nh)* sb_step(hash12(ctx,gc * 1.7f+ 0.3f),0.3f)* (1.0f- sb_smoothstep(0.4f,1.2f,gd)) * shadow;
  col =col +(ctx.uSunColor * 0.25f* glint);


  col =col +(ctx.uSunColor * ctx.uLaceK.z* rimL * shadow);


  float3 colW = ctx.uWaterCol * sb_mix(0.7f,1.0f,shadow)* sb_mix(0.85f,1.05f,wrap);
  float sheen = sb_smoothstep(4.0f,16.0f,length(gw));
  colW =colW +((sb_vec3(0.55f,0.62f,0.66f)+ 0.25f* ctx.uSunColor * shadow) * sheen * ctx.uGlass);

  float aH = hole * ctx.uLaceK.y* sb_mix(0.8f,1.2f,ee)* sb_smoothstep(0.05f,0.5f,aF0);
  aW =sb_max(aW,aH);
  colW =sb_mix(colW,sb_vec3(0.3f,0.5f,0.52f)+ 0.06f* ctx.uSunColor,hole);

  aF =sb_max(aF,0.85f* speck);
  col =sb_mix(col,ctx.uAlbedo * ctx.uSunColor * 0.62f+ 0.1f,speck);

  float sceneZ = linearizeDepth(ctx,__sb_textureLod(15,ctx.vUv,0.0f).x);
  float vis = sb_smoothstep((0-(0.6f)),(0-(0.2f)),sceneZ - zAvg);
  aF =aF *(vis); aW =aW *(vis);

  float alpha = 1.0f- (1.0f- aF) * (1.0f- aW);
