  if (ctx.uDbg == 1) ctx.gl_FragColor =sb_vec4(sb_vec3(tauF / 20.0f,tauW / 20.0f,aF),1.0f);
  if (ctx.uDbg == 2) ctx.gl_FragColor =sb_vec4(N * 0.5f+ 0.5f,1.0f);
  if (ctx.uDbg == 3) ctx.gl_FragColor =sb_vec4(sb_vec3(shadow,wrap,cav - 0.5f),1.0f);
  if (ctx.uDbg == 6) ctx.gl_FragColor =sb_vec4(sb_vec3(0.5f+ 0.2f* det),1.0f);
  if (ctx.uDbg == 7) ctx.gl_FragColor =sb_vec4(eroA,hole,rimL,1.0f);
  if (ctx.uDbg == 8) ctx.gl_FragColor =sb_vec4(nL * 0.5f+ 0.5f,kS * 0.2f,1.0f);
  if (ctx.uDbg == 10) ctx.gl_FragColor =sb_vec4(aF,aW,alpha,1.0f);
  if (ctx.uDbg == 11) ctx.gl_FragColor =sb_vec4(sb_vec3(shadow),1.0f);
  if (ctx.uDbg == 12) ctx.gl_FragColor =sb_vec4(sb_vec3(cav),1.0f);
  if (ctx.uDbg == 13) ctx.gl_FragColor =sb_vec4(sb_vec3(wrap),1.0f);
  if (ctx.uDbg == 14) ctx.gl_FragColor =sb_vec4(sb_vec3(0.5f+ 0.5f* N.y),1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.WATER_SIGMA_A=sb_vec3(0.46f,0.075f,0.062f);
ctx.WATER_SIGMA_S=sb_vec3(0.020f,0.030f,0.032f);
ctx.OCR0=sb_mat2(0.9563048f,0.2923717f,(0-(0.2923717f)),0.9563048f);
ctx.OCR1=sb_mat2(0.8571673f,(0-(0.5150381f)),0.5150381f,0.8571673f);
ctx.OCR2=sb_mat2(0.7313537f,0.6819984f,(0-(0.6819984f)),0.7313537f);
