struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ void main(GraphicsContext& ctx){
  float2 e = sb_vec2(0.25f/ 16.0f);
  float lum = 0.0f;
  for (int i=0;i<4;i++) {
    float2 q = ctx.vUv + (sb_vec2(float(i&1),float(i>>1))* 2.0f- 1.0f)*e;
    lum =lum +(sb_log2(sb_clamp(dot(sb_sw_xyz(__sb_textureLod(0,q,0.0f)),sb_vec3(.2126f,.7152f,.0722f)),.025f,4.0f)));
  }
  float2 p=(ctx.vUv-.5f)*sb_vec2(1.0f,1.15f);
  float w=.3f+.7f*sb_exp((0-(dot(p,p)))*6.0f);
  ctx.gl_FragColor=sb_vec4(lum*.25f*w,w,float(0),float(1));
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

