struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float uDt;
float uReset;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ void main(GraphicsContext& ctx){
  float2 sum=sb_vec2(float(0));
  for(int y=0;y<16;y++)for(int x=0;x<16;x++)sum=sum+(sb_sw_xy(__sb_texelFetch(0,sb_ivec2(float(x),float(y)),0)));
  float target=sb_clamp((sb_log2(.38f)-sum.x/sb_max(sum.y,.001f))*.38f,(0-(.50f)),.40f);
  float old=__sb_texelFetch(1,sb_ivec2(float(0)),0).x;
  float tau=target<old?.65f:1.6f;
  float ev=sb_mix(old,target,ctx.uReset>.5f?1.0f:1.0f-sb_exp((0-(ctx.uDt))/tau));
  ctx.gl_FragColor=sb_vec4(ev,sb_exp2(ev),target,float(1));
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

