struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uTexel;
float uThreshold;
float uFirst;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ float3 pre(GraphicsContext& ctx,float3 c){
  if (ctx.uFirst < 0.5f) return c;
  float br = sb_max(c.x,sb_max(c.y,c.z));
  float knee = ctx.uThreshold * 0.6f;
  float soft = sb_clamp(br - ctx.uThreshold + knee,0.0f,2.0f* knee);
  soft =soft * soft / (4.0f* knee + 1e-4f);
  float w = sb_max(soft,br - ctx.uThreshold)/ sb_max(br,1e-4f);
  return c * w;
}

__device__ void main(GraphicsContext& ctx){
  float2 t = ctx.uTexel;
  float3 a = pre(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2((0-(1.0f)),(0-(1.0f))))));
  float3 b = pre(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2(1.0f,(0-(1.0f))))));
  float3 c = pre(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2((0-(1.0f)),1.0f))));
  float3 d = pre(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2(1.0f,1.0f))));
  float3 e = pre(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv)));
  ctx.gl_FragColor =sb_vec4((a + b + c + d) * 0.125f+ e * 0.5f,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

#endif

