struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uStep;
float3 uW;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ void main(GraphicsContext& ctx){
  float3 s = sb_sw_xyz(__sb_texture(0,ctx.vUv))* ctx.uW.x+ (sb_sw_xyz(__sb_texture(0,ctx.vUv + ctx.uStep))+ sb_sw_xyz(__sb_texture(0,ctx.vUv - ctx.uStep))) * ctx.uW.y+ (sb_sw_xyz(__sb_texture(0,ctx.vUv + 2.0f* ctx.uStep))+ sb_sw_xyz(__sb_texture(0,ctx.vUv - 2.0f* ctx.uStep))) * ctx.uW.z;
  ctx.gl_FragColor =sb_vec4(s,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

