struct GraphicsContext {
float3 LUMA709;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float uExposure;
float uMeterOn;
float uBloomStrength;
float uBloomTail;
float uSaturation;
float uShoulder;
float uSunOn;
float3 uSunV;
float4 uSunPx;
float uFocal;
float3 uSunTint;
float4 uGlare;
float4 uStar;
float uSunEV;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant LUMA709 is initialized in each invocation.
__device__ float ghostDisc(GraphicsContext& ctx,float2 p,float2 c,float rad){
  float d = length(p - c)/ ctx.uFocal;
  return sb_smoothstep(rad,rad * 0.55f,d)* (0.7f+ 0.3f* sb_smoothstep(rad * 0.4f,rad * 0.95f,d));
}


__device__ float hashA(GraphicsContext& ctx,float i){ return sb_fract(sb_sin(i * 12.9898f+ 4.1f)* 43758.5453f); }

__device__ float angNoise(GraphicsContext& ctx,float phi,float n){
  float x = (phi / 6.2831853f+ 0.5f) * n, i = sb_floor(x), f = sb_fract(x);
  f =f * f * (3.0f- 2.0f* f);
  return sb_mix(hashA(ctx,sb_mod(i,n)),hashA(ctx,sb_mod(i + 1.0f,n)),f);
}

__device__ float3 sunGlare(GraphicsContext& ctx,float vis){
  float2 p = sb_sw_xy(ctx.gl_FragCoord);
  float3 rd = normalize(sb_vec3((p - sb_sw_zw(ctx.uSunPx)) / ctx.uFocal,(0-(1.0f))));
  float th = 2.0f* asin(sb_min(length(rd - ctx.uSunV)* 0.5f,1.0f));
  float2 d = (p - sb_sw_xy(ctx.uSunPx)) / ctx.uFocal;
  float phi = sb_atan(d.y,d.x);

  float streak = 1.0f+ 0.3f* (angNoise(ctx,phi,163.0f)+ 0.6f* angNoise(ctx,phi,347.0f)- 0.8f) * sb_smoothstep(0.004f,0.025f,th)* (1.0f- sb_smoothstep(0.05f,0.14f,th));
  float k2 = ctx.uGlare.y* ctx.uGlare.y;
  float3 g = ctx.uSunTint * (ctx.uGlare.x/ (1.0f+ th * th / k2) * (1.0f- sb_smoothstep(0.17f,0.35f,th)) * streak + ctx.uGlare.z);
  float3 star = sb_vec3(0.0f);
  for (int i = 0; i < 3; i++) {
    float a = ctx.uStar.z+ float(i)* 1.0471976f;
    float2 ax = sb_vec2(sb_cos(a),sb_sin(a));
    float al = dot(d,ax)/ ctx.uStar.x, ac = d.x* ax.y- d.y* ax.x;
    float3 w = ctx.uStar.y* sb_vec3(1.2f,1.0f,0.85f);
    star =star +((i == 0 ? 1.0f: (i == 1 ? 0.75f: 0.55f)) * sb_exp((0-(0.5f))* ac * ac / (w * w))/ (1.0f+ al * al * sb_sqrt(sb_abs(al))));
  }
  g =g +(ctx.uSunTint * star * ctx.uGlare.w);

  float2 c = sb_sw_zw(ctx.uSunPx), ax = sb_sw_xy(ctx.uSunPx)- c;
  float3 gh = sb_vec3(0.25f,1.0f,0.45f)* 1.4f* ghostDisc(ctx,p,c - ax * 0.62f,0.016f)+ sb_vec3(0.85f,0.45f,1.0f)* 0.30f* ghostDisc(ctx,p,c - ax * 1.10f,0.060f)+ sb_vec3(1.0f,0.72f,0.36f)* 0.45f* ghostDisc(ctx,p,c + ax * 0.38f,0.026f);
  g =g +(gh * ctx.uStar.w);
  return g * vis * ctx.uSunOn;
}




__device__ float3 phoneLook(GraphicsContext& ctx,float3 c,float exposure){
  c =c *(exposure);
  float Y = dot(c,ctx.LUMA709);
  c =Y + (c - Y) * ctx.uSaturation;
  float pk = sb_max(c.x,sb_max(c.y,c.z));
  float S = ctx.uShoulder, D = 1.0f- ctx.uShoulder;
  if (pk > S) {
    float np = 1.0f- D * D / (pk + D - S);
    c =c *(np / pk);
    float g = 1.0f- 1.0f/ (0.15f* (pk - np) + 1.0f);
    c =sb_mix(c,sb_vec3(np),g);
  }
  return sb_clamp(c,0.0f,1.0f);
}

__device__ float3 toSRGB(GraphicsContext& ctx,float3 c){
  c =sb_clamp(c,0.0f,1.0f);
  return sb_mix(c * 12.92f,1.055f* sb_pow(c,sb_vec3(1.0f/ 2.4f))- 0.055f,sb_step(0.0031308f,c));
}

__device__ void main(GraphicsContext& ctx){
  float3 bloom = sb_sw_xyz(__sb_texture(1,ctx.vUv))+ sb_sw_xyz(__sb_texture(2,ctx.vUv))* ctx.uBloomTail;
  float3 hdr = sb_sw_xyz(__sb_texture(0,ctx.vUv))+ bloom * ctx.uBloomStrength;
  float exposure = ctx.uExposure * sb_mix(1.0f,__sb_texelFetch(3,sb_ivec2(float(0)),0).y,ctx.uMeterOn);
  if (ctx.uSunOn > 0.0f) {
    float vis = __sb_texelFetch(4,sb_ivec2(float(0)),0).x;
    hdr =hdr +(sunGlare(ctx,vis));
    exposure =exposure *(sb_exp2((0-(ctx.uSunEV ))* vis));
  }
  ctx.gl_FragColor =sb_vec4(toSRGB(ctx,phoneLook(ctx,hdr,exposure)),1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.LUMA709=sb_vec3(0.2126f,0.7152f,0.0722f);
main(ctx);output[0]=ctx;}

#endif

