struct GraphicsContext {
float3 LUMA709;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uSunUv;
float2 uRadUv;
float uLref;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant LUMA709 is initialized in each invocation.
__device__ void main(GraphicsContext& ctx){
  float s = 0.0f;
  for (int i = 0; i < 13; i++) {
    float ring = i == 0 ? 0.0f: (i < 7 ? 0.45f: 0.8f);
    float a = float(i)* 1.0471976f+ (i < 7 ? 0.0f: 0.5235988f);
    float2 uv = ctx.uSunUv + ring * sb_vec2(sb_cos(a),sb_sin(a))* ctx.uRadUv;
    float v = 1.0f;
    if (uv.x>= 0.0f&& uv.y>= 0.0f&& uv.x<= 1.0f&& uv.y<= 1.0f) {
      float limb = 0.45f+ 0.55f* sb_sqrt(sb_max(1.0f- ring * ring,0.0f));
      v =sb_smoothstep(0.08f,0.6f,dot(sb_sw_xyz(__sb_textureLod(0,uv,0.0f)),ctx.LUMA709)/ (ctx.uLref * limb));
    }
    s =s +(v);
  }
  ctx.gl_FragColor =sb_vec4(s / 13.0f,0.0f,0.0f,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.LUMA709=sb_vec3(0.2126f,0.7152f,0.0722f);
main(ctx);output[0]=ctx;}

