struct GraphicsContext {
float3 LUMA709;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uHorizon;
float2 uRowDV;
int uBins;
int uNU;
int uNV;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant LUMA709 is initialized in each invocation.
__device__ void main(GraphicsContext& ctx){
  float bins = float(ctx.uBins);
  float i0 = sb_floor(ctx.gl_FragCoord.x);
  float2 sz = sb_vec2(__sb_textureSize(0,0));
  float s = 0.0f, s2 = 0.0f;
  for (int j = 0; j < ctx.uNV; j++) {
    float dv = ctx.uRowDV.x+ (ctx.uRowDV.y- ctx.uRowDV.x) * (i0 + (float(j)+ 0.5f) / float(ctx.uNV)) / bins;
    for (int i = 0; i < ctx.uNU; i++) {
      float u = 0.05f+ 0.9f* (float(i)+ 0.5f) / float(ctx.uNU);
      float v = ctx.uHorizon.x+ ctx.uHorizon.y* u + dv;

      float2 ip = sb_clamp(sb_ivec2(sb_vec2(u,1.0f- v)* sz),sb_ivec2(float(0)),sb_ivec2(sz)- 1);
      float y = dot(sb_sw_xyz(__sb_texelFetch(0,ip,0)),ctx.LUMA709);
      s =s +(y); s2 =s2 +(y * y);
    }
  }
  float n = float(ctx.uNU * ctx.uNV);
  ctx.gl_FragColor =sb_vec4(s / n,s2 / n,0.0f,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.LUMA709=sb_vec3(0.2126f,0.7152f,0.0722f);
main(ctx);output[0]=ctx;}

#endif

