struct GraphicsContext {
float3 LUMA709;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uTexel;
float uSharpen;
float uChromaOff;
float uTime;
float uMaroon;
SBMat4 uInvViewProj;
float3 uCamPos;
float2 uHorizon;
float2 uRowDV;
float uGust;
float uContrast;
float uCVTarget;
float4 uMar;
float2 uMarW;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant LUMA709 is initialized in each invocation.
__device__ float3 toYCC(GraphicsContext& ctx,float3 c){ float y = dot(c,ctx.LUMA709); return sb_vec3(y,(c.z- y) / 1.8556f,(c.x- y) / 1.5748f); }

__device__ float3 fromYCC(GraphicsContext& ctx,float3 q){
  float r = q.x+ 1.5748f* q.z, b = q.x+ 1.8556f* q.y;
  return sb_vec3(r,(q.x- 0.2126f* r - 0.0722f* b) / 0.7152f,b);
}

__device__ float hash12(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* 0.1031f); p3 =p3 +(dot(p3,sb_sw_yzx(p3)+ 33.33f)); return sb_fract((p3.x+ p3.y) * p3.z); }

__device__ float hash13(GraphicsContext& ctx,float3 p){ p =sb_fract(p * sb_vec3(0.1031f,0.1030f,0.0973f)); p =p +(dot(p,sb_sw_yzx(p)+ 33.33f)); return sb_fract((p.x+ p.y) * p.z); }

__device__ float vnoise(GraphicsContext& ctx,float3 p){
  float3 i = sb_floor(p), f = sb_fract(p);
  f =f * f * (3.0f- 2.0f* f);
  float2 e = sb_vec2(1.0f,0.0f);
  float a = sb_mix(sb_mix(hash13(ctx,i),hash13(ctx,i + sb_sw_xyy(e)),f.x),sb_mix(hash13(ctx,i + sb_sw_yxy(e)),hash13(ctx,i + sb_sw_xxy(e)),f.x),f.y);
  float b = sb_mix(sb_mix(hash13(ctx,i + sb_sw_yyx(e)),hash13(ctx,i + sb_sw_xyx(e)),f.x),sb_mix(hash13(ctx,i + sb_sw_yxx(e)),hash13(ctx,i + sb_sw_xxx(e)),f.x),f.y);
  return sb_mix(a,b,f.z)* 2.0f- 1.0f;
}









__device__ bool maroonSetup(GraphicsContext& ctx,float3 ycc,float ymin,float4& th,float2& target){
  th =sb_vec4(0.0f); target =sb_vec2(0.0f);

  float gH = sb_smoothstep((0-(0.10f)),(0-(0.16f)),ycc.z)* sb_step(0.0f,ycc.y);
  if (gH <= 0.0f) return false;
  float4 p = ctx.uInvViewProj * sb_vec4(ctx.vUv * 2.0f- 1.0f,1.0f,1.0f);
  float3 dir = sb_sw_xyz(p)/ p.w- ctx.uCamPos;
  float b = (0-(dir.y))/ sb_max(length(sb_sw_xz(dir)),1e-6f);
  if (b <= 1e-5f) return false;
  float D = ctx.uCamPos.y/ b;


  float gD = (1.0f- 0.7f* sb_smoothstep(95.0f,190.0f,D)) * (1.0f- sb_smoothstep(190.0f,420.0f,D));
  if (gD <= 0.0f|| D < 18.5f) return false;
  float u = ctx.vUv.x;
  float dv = (1.0f- ctx.vUv.y) - (ctx.uHorizon.x+ ctx.uHorizon.y* u);
  float x = sb_clamp((dv - ctx.uRowDV.x) / (ctx.uRowDV.y- ctx.uRowDV.x) * 16.0f- 0.5f,0.0f,15.0f);
  int i0 = int(x);
  float2 rs = sb_mix(sb_sw_xy(__sb_texelFetch(1,sb_ivec2(float(i0),float(0)),0)),sb_sw_xy(__sb_texelFetch(1,sb_ivec2(sb_min(i0 + 1,15),float(0)),0)),x - float(i0));
  float rowInv = 1.0f/ sb_max(rs.x,0.02f);

  float cg = sb_clamp(ctx.uContrast * ctx.uCVTarget / sb_max(sb_sqrt(sb_max(rs.y- rs.x* rs.x,0.0f))* rowInv,1e-3f),0.7f,1.8f);

  float T = ctx.uMar.x+ ctx.uMar.w* (0.5f- u) * 2.0f- 0.15f* (1.0f- sb_smoothstep(18.5f,25.0f,D));
  float zmin = (1.0f+ (ymin * rowInv - 1.0f) * cg) * ctx.uGust;
  if (zmin > T + 0.8f* (ctx.uMar.y+ ctx.uMar.z) + ctx.uMarW.x) return false;
  float az = sb_atan(dir.x,(0-(dir.z)));
  float t = ctx.uTime;

  float paws = 0.65f* vnoise(ctx,sb_vec3(az / 0.05f,b / 0.012f,t * 0.7f))+ 0.35f* vnoise(ctx,sb_vec3(az / 0.021f,b / 0.005f,t * 1.1f+ 17.0f));

  float3 pd = sb_vec3(az / 0.0040f,b / 0.0011f,t * 2.0f);
  float blob = vnoise(ctx,pd + sb_vec3(0.0f,0.0f,5.0f));
  float elig = sb_smoothstep((0-(0.32f)),(0-(0.12f)),vnoise(ctx,pd * sb_vec3(0.8f,0.9f,1.0f)+ sb_vec3(0.0f,0.0f,41.0f)));
  th =sb_vec4(T + ctx.uMar.y* blob + ctx.uMar.z* paws,gD * gH * elig * ctx.uMarW.y,rowInv,cg);

  target =sb_vec2(15.0f+ 14.0f* vnoise(ctx,pd * 0.7f+ sb_vec3(0.0f,0.0f,73.0f)),(0-(11.0f))+ 22.0f* vnoise(ctx,pd * 0.7f+ sb_vec3(0.0f,0.0f,97.0f)))/ 255.0f;
  return true;
}


__device__ float maroonW(GraphicsContext& ctx,float y,float4 th){
  float z = (1.0f+ (y * th.z- 1.0f) * th.w) * ctx.uGust;
  return sb_smoothstep((0-(ctx.uMarW.x)),ctx.uMarW.x,th.x- z)* th.y;
}

__device__ void main(GraphicsContext& ctx){
  float2 t = ctx.uTexel;
  float3 c = sb_sw_xyz(__sb_texture(0,ctx.vUv));

  float yc = dot(c,ctx.LUMA709);
  float yn = sb_pow(dot(sb_sw_xyz(__sb_texture(0,ctx.vUv + sb_vec2(0.0f,t.y))),ctx.LUMA709),2.2f)+ sb_pow(dot(sb_sw_xyz(__sb_texture(0,ctx.vUv - sb_vec2(0.0f,t.y))),ctx.LUMA709),2.2f)+ sb_pow(dot(sb_sw_xyz(__sb_texture(0,ctx.vUv + sb_vec2(t.x,0.0f))),ctx.LUMA709),2.2f)+ sb_pow(dot(sb_sw_xyz(__sb_texture(0,ctx.vUv - sb_vec2(t.x,0.0f))),ctx.LUMA709),2.2f);
  float yl = sb_pow(yc,2.2f);
  float ys = sb_pow(sb_max(yl + (yl - yn * 0.25f) * ctx.uSharpen,0.0f),1.0f/ 2.2f);

  float o = ctx.uChromaOff;
  float3 q0 = toYCC(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2(o,o)))), q1 = toYCC(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2((0-(o)),o))));
  float3 q2 = toYCC(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2(o,(0-(o)))))), q3 = toYCC(ctx,sb_sw_xyz(__sb_texture(0,ctx.vUv + t * sb_vec2((0-(o)),(0-(o))))));
  float3 q = (q0 + q1 + q2 + q3) * 0.25f;

  float4 th; float2 target;
  if (ctx.uMaroon > 0.0f&& maroonSetup(ctx,q,sb_min(sb_min(q0.x,q1.x),sb_min(q2.x,q3.x)),th,target)) {
    th.y=th.y*(ctx.uMaroon);
    {float2 sb_write0=(sb_mix(sb_sw_yz(q0),target,sb_clamp(maroonW(ctx,q0.x,th),0.0f,1.0f))+ sb_mix(sb_sw_yz(q1),target,sb_clamp(maroonW(ctx,q1.x,th),0.0f,1.0f))+ sb_mix(sb_sw_yz(q2),target,sb_clamp(maroonW(ctx,q2.x,th),0.0f,1.0f))+ sb_mix(sb_sw_yz(q3),target,sb_clamp(maroonW(ctx,q3.x,th),0.0f,1.0f))) * 0.25f;q.y=sb_write0.x;q.z=sb_write0.y;}}
  q.x=ys;
  float3 s = sb_clamp(fromYCC(ctx,q),0.0f,1.0f);

  s =s +((hash12(ctx,sb_sw_xy(ctx.gl_FragCoord)+ sb_fract(ctx.uTime * 7.13f)* 91.0f)- 0.5f) / 255.0f);
  ctx.gl_FragColor =sb_vec4(s,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.LUMA709=sb_vec3(0.2126f,0.7152f,0.0722f);
main(ctx);output[0]=ctx;}

#endif

