struct LuminanceData {

			float m; float n; float e; float s; float w;
			float ne; float nw; float se; float sw;
			float highest; float lowest; float contrast;

		};


struct EdgeData {

			bool isHorizontal;
			float pixelStep;
			float oppositeLuminance; float gradient;

		};


struct GraphicsContext {
float edgeSteps[6];
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 resolution;
float2 vUv;
float _ContrastThreshold;
float _RelativeThreshold;
float _SubpixelBlending;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ LuminanceData sb_new_LuminanceData(float p_m,float p_n,float p_e,float p_s,float p_w,float p_ne,float p_nw,float p_se,float p_sw,float p_highest,float p_lowest,float p_contrast){LuminanceData a;a.m=p_m;a.n=p_n;a.e=p_e;a.s=p_s;a.w=p_w;a.ne=p_ne;a.nw=p_nw;a.se=p_se;a.sw=p_sw;a.highest=p_highest;a.lowest=p_lowest;a.contrast=p_contrast;return a;}
__device__ EdgeData sb_new_EdgeData(bool p_isHorizontal,float p_pixelStep,float p_oppositeLuminance,float p_gradient){EdgeData a;a.isHorizontal=p_isHorizontal;a.pixelStep=p_pixelStep;a.oppositeLuminance=p_oppositeLuminance;a.gradient=p_gradient;return a;}
// Constant edgeSteps is initialized in each invocation.
__device__ float4 Sample(GraphicsContext& ctx,int tex2D,float2 uv){

			return __sb_texture(tex2D,uv );

		}


__device__ float SampleLuminance(GraphicsContext& ctx,int tex2D,float2 uv){

			return dot(sb_sw_xyz(Sample(ctx,tex2D,uv )),sb_vec3(0.3f,0.59f,0.11f));

		}


__device__ float SampleLuminance(GraphicsContext& ctx,int tex2D,float2 texSize,float2 uv,float uOffset,float vOffset){

			uv =uv +(texSize * sb_vec2(uOffset,vOffset));
			return SampleLuminance(ctx,tex2D,uv);

		}


__device__ LuminanceData SampleLuminanceNeighborhood(GraphicsContext& ctx,int tex2D,float2 texSize,float2 uv){

			LuminanceData l;
			l.m=SampleLuminance(ctx,tex2D,uv );
			l.n=SampleLuminance(ctx,tex2D,texSize,uv,0.0f,1.0f);
			l.e=SampleLuminance(ctx,tex2D,texSize,uv,1.0f,0.0f);
			l.s=SampleLuminance(ctx,tex2D,texSize,uv,0.0f,(0-(1.0f)));
			l.w=SampleLuminance(ctx,tex2D,texSize,uv,(0-(1.0f)),0.0f);

			l.ne=SampleLuminance(ctx,tex2D,texSize,uv,1.0f,1.0f);
			l.nw=SampleLuminance(ctx,tex2D,texSize,uv,(0-(1.0f)),1.0f);
			l.se=SampleLuminance(ctx,tex2D,texSize,uv,1.0f,(0-(1.0f)));
			l.sw=SampleLuminance(ctx,tex2D,texSize,uv,(0-(1.0f)),(0-(1.0f)));

			l.highest=sb_max(sb_max(sb_max(sb_max(l.n,l.e),l.s),l.w),l.m);
			l.lowest=sb_min(sb_min(sb_min(sb_min(l.n,l.e),l.s),l.w),l.m);
			l.contrast=l.highest- l.lowest;
			return l;

		}


__device__ bool ShouldSkipPixel(GraphicsContext& ctx,LuminanceData l){

			float threshold = sb_max(ctx._ContrastThreshold,ctx._RelativeThreshold * l.highest);
			return l.contrast< threshold;

		}


__device__ float DeterminePixelBlendFactor(GraphicsContext& ctx,LuminanceData l){

			float f = 2.0f* ( l.n+ l.e+ l.s+ l.w);
			f =f +(l.ne+ l.nw+ l.se+ l.sw);
			f =f *(1.0f/ 12.0f);
			f =sb_abs(f - l.m);
			f =sb_clamp(f / l.contrast,0.0f,1.0f);

			float blendFactor = sb_smoothstep(0.0f,1.0f,f );
			return blendFactor * blendFactor * ctx._SubpixelBlending;

		}


__device__ EdgeData DetermineEdge(GraphicsContext& ctx,float2 texSize,LuminanceData l){

			EdgeData e;
			float horizontal =
				sb_abs(l.n+ l.s- 2.0f* l.m)* 2.0f+
				sb_abs(l.ne+ l.se- 2.0f* l.e)+
				sb_abs(l.nw+ l.sw- 2.0f* l.w);
			float vertical =
				sb_abs(l.e+ l.w- 2.0f* l.m)* 2.0f+
				sb_abs(l.ne+ l.nw- 2.0f* l.n)+
				sb_abs(l.se+ l.sw- 2.0f* l.s);
			e.isHorizontal=horizontal >= vertical;

			float pLuminance = e.isHorizontal? l.n: l.e;
			float nLuminance = e.isHorizontal? l.s: l.w;
			float pGradient = sb_abs(pLuminance - l.m);
			float nGradient = sb_abs(nLuminance - l.m);

			e.pixelStep=e.isHorizontal? texSize.y: texSize.x;

			if (pGradient < nGradient) {

				e.pixelStep=(0-(e.pixelStep));
				e.oppositeLuminance=nLuminance;
				e.gradient=nGradient;

			} else {

				e.oppositeLuminance=pLuminance;
				e.gradient=pGradient;

			}

			return e;

		}


__device__ float DetermineEdgeBlendFactor(GraphicsContext& ctx,int tex2D,float2 texSize,LuminanceData l,EdgeData e,float2 uv){

			float2 uvEdge = uv;
			float2 edgeStep;
			if (e.isHorizontal) {

				uvEdge.y=uvEdge.y+(e.pixelStep* 0.5f);
				edgeStep =sb_vec2(texSize.x,0.0f);

			} else {

				uvEdge.x=uvEdge.x+(e.pixelStep* 0.5f);
				edgeStep =sb_vec2(0.0f,texSize.y);

			}

			float edgeLuminance = ( l.m+ e.oppositeLuminance) * 0.5f;
			float gradientThreshold = e.gradient* 0.25f;

			float2 puv = uvEdge + edgeStep * ctx.edgeSteps[0];
			float pLuminanceDelta = SampleLuminance(ctx,tex2D,puv )- edgeLuminance;
			bool pAtEnd = sb_abs(pLuminanceDelta )>= gradientThreshold;

			for ( int i = 1; i < 6 && !pAtEnd; i++ ) {

				puv =puv +(edgeStep * ctx.edgeSteps[i]);
				pLuminanceDelta =SampleLuminance(ctx,tex2D,puv )- edgeLuminance;
				pAtEnd =sb_abs(pLuminanceDelta )>= gradientThreshold;

			}

			if ( !pAtEnd ) {

				puv =puv +(edgeStep * 8.0f);

			}

			float2 nuv = uvEdge - edgeStep * ctx.edgeSteps[0];
			float nLuminanceDelta = SampleLuminance(ctx,tex2D,nuv )- edgeLuminance;
			bool nAtEnd = sb_abs(nLuminanceDelta )>= gradientThreshold;

			for ( int i = 1; i < 6 && !nAtEnd; i++ ) {

				nuv =nuv -(edgeStep * ctx.edgeSteps[i]);
				nLuminanceDelta =SampleLuminance(ctx,tex2D,nuv )- edgeLuminance;
				nAtEnd =sb_abs(nLuminanceDelta )>= gradientThreshold;

			}

			if ( !nAtEnd ) {

				nuv =nuv -(edgeStep * 8.0f);

			}

			float pDistance, nDistance;
			if ( e.isHorizontal) {

				pDistance =puv.x- uv.x;
				nDistance =uv.x- nuv.x;

			} else {

				pDistance =puv.y- uv.y;
				nDistance =uv.y- nuv.y;

			}

			float shortestDistance;
			bool deltaSign;
			if ( pDistance <= nDistance ) {

				shortestDistance =pDistance;
				deltaSign =pLuminanceDelta >= 0.0f;

			} else {

				shortestDistance =nDistance;
				deltaSign =nLuminanceDelta >= 0.0f;

			}

			if ( deltaSign == ( l.m- edgeLuminance >= 0.0f) ) {

				return 0.0f;

			}

			return 0.5f- shortestDistance / ( pDistance + nDistance );

		}


__device__ float4 ApplyFXAA(GraphicsContext& ctx,int tex2D,float2 texSize,float2 uv){

			LuminanceData luminance = SampleLuminanceNeighborhood(ctx,tex2D,texSize,uv );
			if ( ShouldSkipPixel(ctx,luminance )) {

				return Sample(ctx,tex2D,uv );

			}

			float pixelBlend = DeterminePixelBlendFactor(ctx,luminance );
			EdgeData edge = DetermineEdge(ctx,texSize,luminance );
			float edgeBlend = DetermineEdgeBlendFactor(ctx,tex2D,texSize,luminance,edge,uv );
			float finalBlend = sb_max(pixelBlend,edgeBlend );

			if (edge.isHorizontal) {

				uv.y=uv.y+(edge.pixelStep* finalBlend);

			} else {

				uv.x=uv.x+(edge.pixelStep* finalBlend);

			}

			return Sample(ctx,tex2D,uv );

		}


__device__ void main(GraphicsContext& ctx){

			ctx.gl_FragColor =ApplyFXAA(ctx,0,sb_sw_xy(ctx.resolution),ctx.vUv );

		}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.edgeSteps[0]=1.0f;
ctx.edgeSteps[1]=1.5f;
ctx.edgeSteps[2]=2.0f;
ctx.edgeSteps[3]=2.0f;
ctx.edgeSteps[4]=2.0f;
ctx.edgeSteps[5]=4.0f;
ctx._ContrastThreshold=0.0312f;
ctx._RelativeThreshold=0.063f;
ctx._SubpixelBlending=0.65f;
main(ctx);output[0]=ctx;}

#endif

