struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
SBMat4 uInvProjection;
float2 uTexel;
float2 uFocal;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ float3 pointAt(GraphicsContext& ctx,float2 uv){



  float2 size=__sb_textureSize(0,0);
  float2 pixel=sb_clamp(sb_ivec2(sb_floor(uv*sb_vec2(size))),sb_ivec2(float(0)),size-1);
  float2 centre=(sb_vec2(pixel)+.5f)/sb_vec2(size);
  float4 p=ctx.uInvProjection*sb_vec4(centre*2.0f-1.0f,__sb_texelFetch(0,pixel,0).x*2.0f-1.0f,1.0f);
  return sb_sw_xyz(p)/p.w;
}

__device__ void main(GraphicsContext& ctx){
  float3 P=pointAt(ctx,ctx.vUv);
  if((0-(P.z))>220.0f){ctx.gl_FragColor=sb_vec4(float(1),float(0),float(0),float(1));return;}
  float3 px=pointAt(ctx,ctx.vUv+sb_vec2(ctx.uTexel.x,float(0)))-P, mx=P-pointAt(ctx,ctx.vUv-sb_vec2(ctx.uTexel.x,float(0)));
  float3 py=pointAt(ctx,ctx.vUv+sb_vec2(float(0),ctx.uTexel.y))-P, my=P-pointAt(ctx,ctx.vUv-sb_vec2(float(0),ctx.uTexel.y));
  float3 N=normalize(cross(sb_abs(px.z)<sb_abs(mx.z)?px:mx,sb_abs(py.z)<sb_abs(my.z)?py:my));
  if(dot(N,(0-(P)))<0.0f)N=(0-(N));
  float radius=sb_mix(.12f,1.6f,sb_smoothstep(4.0f,75.0f,(0-(P.z))));
  float2 ruv=sb_min(sb_vec2(.08f),ctx.uFocal*radius/sb_max((0-(P.z)),.1f));
  float occ=0.0f;
  for(int i=0;i<12;i++) {
    float a=float(i%6)*1.04719755f+.31f;
    float ring=i<6?.38f:1.0f;
    float2 uv=ctx.vUv+sb_vec2(sb_cos(a),sb_sin(a))*ruv*ring;
    if(sb_min(uv.x,uv.y)<0.0f||sb_max(uv.x,uv.y)>1.0f)continue;
    float3 D=pointAt(ctx,uv)-P;float d=length(D);
    float h=sb_max(dot(N,D)/sb_max(d,.001f)-.12f,0.0f);
    occ=occ+(h*(1.0f-sb_smoothstep(radius*.35f,radius*1.8f,d)));
  }
  float ao=sb_clamp(1.0f-occ*.13f,.70f,1.0f);
  ctx.gl_FragColor=sb_vec4(ao,(0-(P.z)),float(0),float(1));
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

#endif

