struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uContactTexel;
float2 uCameraRange;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ float contactAt(GraphicsContext& ctx,float2 uv,float depth){
  float n=ctx.uCameraRange.x,f=ctx.uCameraRange.y;
  float z=n*f/(f-depth*(f-n));
  float sum=0.0f,wSum=0.0f;
  for(int i=0;i<4;i++) {
    float2 o=(sb_vec2(float(i&1),float(i>>1))-.5f)*ctx.uContactTexel;
    float2 a=sb_sw_xy(__sb_textureLod(2,uv+o,0.0f));
    float w=sb_exp((0-(sb_abs(a.y-z)))/sb_max(.06f,z*.015f));
    sum=sum+(a.x*w);wSum=wSum+(w);
  }
  return wSum>.001f?sum/wSum:1.0f;
}

__device__ void main(GraphicsContext& ctx){float d=__sb_texture(1,ctx.vUv).x;ctx.gl_FragColor=sb_vec4(sb_sw_xyz(__sb_texture(0,ctx.vUv))*contactAt(ctx,ctx.vUv,d),float(1));ctx.gl_FragDepth=d;}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

