__device__ float2 swashFarUV(GraphicsContext& ctx,float2 xz){ return sb_vec2(swashFarU(ctx,xz.x),(xz.y- ctx.uSwashFarMapZ.x) / (ctx.uSwashFarMapZ.y* ctx.uSwashFarMapZ.z) + 0.5f/ ctx.uSwashFarMapZ.z); }

__device__ float swashVisualFocusX(GraphicsContext& ctx){


  return sb_clamp(ctx.uSwashFocus.x,ctx.uSwashFarWin.x- 1.1f,ctx.uSwashFarWin.x+ 1.1f);
