__device__ float chopWeight(GraphicsContext& ctx,float depth0){ return sb_smoothstep(0.05f,1.2f,depth0); }



__device__ float3 swellAt(GraphicsContext& ctx,float2 xz){
  float v=sb_log(1.0f+sb_max((0-(xz.y))-6.0f,0.0f)/8.0f)/sb_log(81.5f);
  float2 uv=sb_vec2((xz.x+512.0f)/1024.0f,v);
