};
// Constant UW_EXTINCTION is initialized in each invocation.
// Constant UW_SCATTER is initialized in each invocation.
__device__ float softplus_(GraphicsContext& ctx,float x){ return x > 20.0f? x : sb_log(1.0f+ sb_exp(x)); }

__device__ float bedProfile(GraphicsContext& ctx,float z){
  float y = 0.1f* z;
  y =y +(0.1f* 5.0f* softplus_(ctx,(z - ((0-(60.0f)))) / 5.0f));
  y =y +(0.8f* 1.2f* softplus_(ctx,(z - ((0-(22.5f)))) / 1.2f));
  y =y +((0-(0.9f))* 0.5f* softplus_(ctx,(z - ((0-(16.8f)))) / 0.5f));
  y =y +(0.01999999999999999f* 2.0f* softplus_(ctx,(z - ((0-(12.0f)))) / 2.0f));
  y =y +(0.22999999999999998f* 0.22f* softplus_(ctx,(z - ((0-(2.3f)))) / 0.22f));
  y =y +((0-(0.21499999999999997f))* 0.18f* softplus_(ctx,(z - ((0-(0.6f)))) / 0.18f));
  y =y +((0-(0.05f))* 1.5f* softplus_(ctx,(z - (11.0f)) / 1.5f));
  y =y +((0-(0.135f))* 1.2f* softplus_(ctx,(z - (19.0f)) / 1.2f));
  return sb_max(y + ((0-(9.51869802609202f))),(0-(30.0f)));
}



__device__ float hash11(GraphicsContext& ctx,float p){ p =sb_fract(p * 0.1031f); p =p *(p + 33.33f); p =p *(p + p); return sb_fract(p); }

__device__ float hash12(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* 0.1031f); p3 =p3 +(dot(p3,sb_sw_yzx(p3)+ 33.33f)); return sb_fract((p3.x+ p3.y) * p3.z); }

__device__ float2 hash22(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yzx(p3)+ 33.33f)); return sb_fract((sb_sw_xx(p3)+ sb_sw_yz(p3)) * sb_sw_zy(p3)); }

__device__ float3 hash32(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yxz(p3)+ 33.33f)); return sb_fract((sb_sw_xxy(p3)+ sb_sw_yzz(p3)) * sb_sw_zyx(p3)); }

__device__ float3 hash33(GraphicsContext& ctx,float3 p3){ p3 =sb_fract(p3 * sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yxz(p3)+ 33.33f)); return sb_fract((sb_sw_xxy(p3)+ sb_sw_yxx(p3)) * sb_sw_zyx(p3)); }



__device__ float vnoise(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float2 u = f * f * f * (f * (f * 6.0f- 15.0f) + 10.0f);
  float a = hash12(ctx,i), b = hash12(ctx,i + sb_vec2(float(1),float(0))), c = hash12(ctx,i + sb_vec2(float(0),float(1))), d = hash12(ctx,i + sb_vec2(float(1),float(1)));
  return sb_mix(sb_mix(a,b,u.x),sb_mix(c,d,u.x),u.y);
}


__device__ float3 gnoised(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float2 u = f * f * f * (f * (f * 6.0f- 15.0f) + 10.0f);
  float2 du = 30.0f* f * f * (f * (f - 2.0f) + 1.0f);
  float2 ga = hash22(ctx,i)* 2.0f- 1.0f, gb = hash22(ctx,i + sb_vec2(float(1),float(0)))* 2.0f- 1.0f;
  float2 gc = hash22(ctx,i + sb_vec2(float(0),float(1)))* 2.0f- 1.0f, gd = hash22(ctx,i + sb_vec2(float(1),float(1)))* 2.0f- 1.0f;
  float va = dot(ga,f), vb = dot(gb,f - sb_vec2(float(1),float(0))), vc = dot(gc,f - sb_vec2(float(0),float(1))), vd = dot(gd,f - sb_vec2(float(1),float(1)));
  float v = va + u.x* (vb - va) + u.y* (vc - va) + u.x* u.y* (va - vb - vc + vd);
  float2 d = ga + u.x* (gb - ga) + u.y* (gc - ga) + u.x* u.y* (ga - gb - gc + gd)
         + du * (sb_sw_yx(u)* (va - vb - vc + vd) + sb_vec2(vb,vc)- va);
  return sb_vec3(v * 1.6f,d * 1.6f);
}

__device__ float gnoise(GraphicsContext& ctx,float2 p){ return gnoised(ctx,p).x; }

__device__ float fbm(GraphicsContext& ctx,float2 p,int oct){
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 8; i++) { if (i >= oct) break; s =s +(a * gnoise(ctx,p)); p =sb_mat2(1.6f,1.2f,(0-(1.2f)),1.6f)* p; a =a *(0.5f); }
  return s;
}


__device__ float vnoise3(GraphicsContext& ctx,float3 p){
  float3 i = sb_floor(p), f = sb_fract(p);
  float3 u = f * f * (3.0f- 2.0f* f);
  float n000 = hash33(ctx,i).x, n100 = hash33(ctx,i + sb_vec3(float(1),float(0),float(0))).x, n010 = hash33(ctx,i + sb_vec3(float(0),float(1),float(0))).x, n110 = hash33(ctx,i + sb_vec3(float(1),float(1),float(0))).x;
  float n001 = hash33(ctx,i + sb_vec3(float(0),float(0),float(1))).x, n101 = hash33(ctx,i + sb_vec3(float(1),float(0),float(1))).x, n011 = hash33(ctx,i + sb_vec3(float(0),float(1),float(1))).x, n111 = hash33(ctx,i + sb_vec3(float(1),float(1),float(1))).x;
  return sb_mix(sb_mix(sb_mix(n000,n100,u.x),sb_mix(n010,n110,u.x),u.y),sb_mix(sb_mix(n001,n101,u.x),sb_mix(n011,n111,u.x),u.y),u.z);
}


__device__ float3 worley(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float f1 = 8.0f, f2 = 8.0f, id = 0.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float2 o = hash22(ctx,i + g);
    float2 r = g + o - f;
    float d = dot(r,r);
    if (d < f1) { f2 =f1; f1 =d; id =hash12(ctx,i + g); } else if (d < f2) { f2 =d; }
  }
  return sb_vec3(sb_sqrt(f1),sb_sqrt(f2),id);
}

__device__ float sat(GraphicsContext& ctx,float x){ return sb_clamp(x,0.0f,1.0f); }

__device__ float sech2(GraphicsContext& ctx,float x){ float e = sb_exp((0-(2.0f))* sb_abs(x)); float s = 2.0f* sb_exp((0-(sb_abs(x))))/ (1.0f+ e); return s * s; }

__device__ float remap(GraphicsContext& ctx,float v,float a,float b){ return sb_clamp((v - a) / (b - a),0.0f,1.0f); }




__device__ float bedRelief(GraphicsContext& ctx,float2 xz){
  float face = sb_smoothstep((0-(1.2f)),0.2f,xz.y)* sb_smoothstep(5.0f,2.5f,xz.y);
  float cusp = 0.003f* sb_sin(xz.x* 5.2f+ 0.8f* sb_sin(xz.x* 1.7f))+ 0.0025f* sb_sin(xz.x* 14.5f+ 1.3f);
  float lumps = 0.010f* gnoise(ctx,xz * 1.3f+ 3.1f)+ 0.005f* gnoise(ctx,xz * 4.1f- 1.3f);
  return (cusp + lumps) * face;
}

__device__ float bedHeight(GraphicsContext& ctx,float2 xz){ return bedProfile(ctx,xz.y)+ bedRelief(ctx,xz); }

__device__ float rockBedHeight(GraphicsContext& ctx,float2 xz){
  if(ctx.uRockDomain.z<= 0.0f) return (0-(100.0f));
  float2 uv=(xz-sb_sw_xy(ctx.uRockDomain))/sb_sw_zw(ctx.uRockDomain);
  if(sb_min(uv.x,uv.y)<0.0f|| sb_max(uv.x,uv.y)>1.0f) return (0-(100.0f));
  return __sb_textureLod(0,uv,0.0f).x;
}

__device__ float hydraulicBedHeight(GraphicsContext& ctx,float2 xz){return sb_max(bedHeight(ctx,xz),rockBedHeight(ctx,xz));}

__device__ float localRockShadow(GraphicsContext& ctx,float3 P,float3 L){
  if(sb_abs(P.x)>65.0f|| sb_abs(P.z)>3.3f|| P.y>.65f) return 1.0f;
  float shade=1.0f;
  for(int i=0;i<4;i++){
    float h=.045f+.042f*float((i+1)*(i+1));
    float3 q=P+L*(h/sb_max(L.y,.15f));
    shade=sb_min(shade,sb_smoothstep((0-(.018f)),.035f,q.y-rockBedHeight(ctx,sb_sw_xz(q))));
  }
  return shade;
}


__device__ float3 skyRadiance(GraphicsContext& ctx,float3 d){
  float el = degrees(asin(sb_clamp(d.y,(0-(1.0f)),1.0f)));
  float e = sb_max(el,0.0f);
  float3 c = sb_sw_yzw(ctx.uSkyLut[0]);
  for (int i = 1; i < 18; i++) {
    float4 a = ctx.uSkyLut[i - 1], b = ctx.uSkyLut[i];
    if (e >= a.x) c =sb_mix(sb_sw_yzw(a),sb_sw_yzw(b),sb_clamp((e - a.x) / (b.x- a.x),0.0f,1.0f));
  }

  float az = degrees(sb_atan(d.x,(0-(d.z))));
  float k = sb_mix(0.0029f,0.0043f,sb_clamp(e / 22.0f,0.0f,1.0f));
  c =c *(1.0f+ k * sb_clamp(az,(0-(80.0f)),80.0f));

  float mu = sb_max(dot(d,ctx.uSunDir),0.0f);
  c =c +(ctx.uSunColor * (0.004f* sb_pow(mu,12.0f)+ 0.02f* sb_pow(mu,200.0f)));

  c =sb_mix(sb_vec3(0.05f,0.20f,0.26f),c,sb_smoothstep((0-(6.0f)),0.0f,el));
  return c;
}

__device__ float3 sunDisk(GraphicsContext& ctx,float3 d){
  float mu = dot(d,ctx.uSunDir);
  return ctx.uSunColor * 400.0f* sb_smoothstep(0.99996f,0.99999f,mu);
}


__device__ float3 skyAmbient(GraphicsContext& ctx,float3 N){
  float3 ground = sb_vec3(0.13f,0.12f,0.11f);
  return sb_mix(ground,ctx.uSkyAmb,0.62f+ 0.38f* N.y);
}


__device__ float submergedAt(GraphicsContext& ctx,float3 p){
  if(ctx.uUnderwaterOn<.5f)return 0.f;
  float h=__sb_texelFetch(1,sb_ivec2(float(0),float(0)),0).x;
  float2 slope=sb_vec2(__sb_texelFetch(1,sb_ivec2(float(2),float(0)),0).x-__sb_texelFetch(1,sb_ivec2(float(1),float(0)),0).x,__sb_texelFetch(1,sb_ivec2(float(4),float(0)),0).x-__sb_texelFetch(1,sb_ivec2(float(3),float(0)),0).x)/.64f;
  return sb_smoothstep((0-(.018f)),.018f,h+dot(slope,sb_sw_xz(p)-ctx.uProbeOrigin)-p.y);
}

__device__ float3 waterTravel(GraphicsContext& ctx,float3 radiance,float distanceM){
  float3 tr=sb_exp((0-(ctx.UW_EXTINCTION))*sb_max(distanceM,0.f));
  return radiance*tr+ctx.UW_SCATTER*(1.f-tr);
}


__device__ float cloudNoise(GraphicsContext& ctx,float3 p){return __sb_textureLod3D(5,(p+.5f)/64.f,0.f).x;}

__device__ float4 coastAt(GraphicsContext& ctx,float2 p){return __sb_textureLod(3,sb_vec2((p.x-ctx.uFieldLeft)/48.f,(p.y-ctx.uCrashZ.x)/(ctx.uCrashZ.y-ctx.uCrashZ.x)),0.f);}

__device__ float surfaceAt(GraphicsContext& ctx,float2 p){return coastAt(ctx,p).x;}





__device__ float3 cloud(GraphicsContext& ctx,float3 p,float footprint){
  float ux=(p.x-ctx.uFieldLeft)/48.f;
  if(ux<0.f||ux>1.f)return sb_vec3(0.f);
  float4 coast=coastAt(ctx,sb_sw_xz(p));
  float ceiling=coast.x;
  float bed=hydraulicBedHeight(ctx,sb_sw_xz(p));
  float depth=sb_max(ceiling-bed,0.f);
  float waterMask=(1.f-sb_smoothstep(ceiling-.035f,ceiling+.015f,p.y))
    *sb_smoothstep(.003f,sb_min(.085f,sb_max(.008f,depth*.25f)),p.y-bed)*sb_smoothstep(.008f,.04f,depth);
  if(waterMask<.001f)return sb_vec3(0.f);
  float density=0.f,shade=0.f,sand=0.f;
  for(int i=0;i<6;i++){
    if(i>=ctx.uPlumeCount)break;
    float row=float(i)*3.f;
    float4 f=__sb_textureLod(2,sb_vec2(ux,(row+.5f)/18.f),0.f);
    float a=f.x,rs=f.z;
    if(a<=0.f||a>=4.8f||f.w<.001f)continue;
    float4 motion=__sb_textureLod(2,sb_vec2(ux,(row+1.5f)/18.f),0.f);
    float4 shape=__sb_textureLod(2,sb_vec2(ux,(row+2.5f)/18.f),0.f);
    float life=shape.x*f.w,finger=shape.y,seed=shape.z;
    float cz=motion.y,cy=surfaceAt(ctx,sb_vec2(p.x,cz))-motion.x;
    float2 radii=sb_sw_zw(motion);
    float2 q=sb_vec2(p.y-cy,p.z-cz);
    float theta=.40f*sb_sin(p.x*1.7f+a*1.3f+seed*17.f);
    q=sb_mat2(sb_cos(theta),(0-(sb_sin(theta))),sb_sin(theta),sb_cos(theta))*q;
    float r=length(q/radii);
    if(r>1.8f)continue;
    float3 npos=sb_vec3(p.x*3.8f+seed*41.f,(p.y-cy)*6.f,(p.z-cz)*6.f);
    float spin=(1.f-sb_exp((0-(a))*.75f))*2.8f;
    {float2 sb_write0=sb_mat2(sb_cos(spin),(0-(sb_sin(spin))),sb_sin(spin),sb_cos(spin))*sb_sw_yz(npos);npos.y=sb_write0.x;npos.z=sb_write0.y;}float detail=1.f-sb_smoothstep(.055f,.17f,footprint);
    float n=cloudNoise(ctx,npos)+.36f*sb_mix(.5f,cloudNoise(ctx,npos*2.31f+7.3f),detail);
    float boundary=r+(.69f-n)*1.75f;
    float d=(1.f-sb_smoothstep(.28f,1.08f,boundary))*life*(.22f+.78f*finger);


    float fine=sb_mix(.5f,cloudNoise(ctx,npos*4.7f-a*.16f),1.f-sb_smoothstep(.025f,.085f,footprint));
    d=d*(.22f+1.45f*fine*fine);
    float top=sb_clamp((cy+radii.x-p.y)/(radii.x*2.f),0.f,1.f);
    float lightNoise=cloudNoise(ctx,npos+sb_vec3(ctx.uSunDir.x,ctx.uSunDir.y,ctx.uSunDir.z)*1.4f);
    float relief=sb_clamp((lightNoise-n/1.36f)*2.4f,(0-(.5f)),.5f);
    density=density+(d);shade=shade+(d*sb_clamp(top+relief,0.f,1.f));


    sand=sand+(d*sb_smoothstep(.10f,.45f,a)*(1.f-sb_smoothstep(1.5f,4.2f,a))
      *sb_exp((0-(sb_max(p.y-bed,0.f)))*2.4f)*sb_smoothstep(.65f,1.35f,rs));
  }




  if(ctx.uShoreChurn>0.f&&sb_max(coast.y,coast.z)>.0001f){
  float aboveBed=sb_max(p.y-bed,0.f),belowSurface=sb_max(ceiling-p.y,0.f);
  float airReach=sb_min(depth*.8f,.12f+.45f*coast.y);
  float airProfile=sb_exp((0-(belowSurface))/sb_max(airReach,.025f));
  float sandProfile=sb_exp((0-(aboveBed))/sb_max(.025f,sb_min(depth*.42f,.19f)));
  float detail=1.f-sb_smoothstep(.05f,.20f,footprint);
  float n=sb_mix(.5f,cloudNoise(ctx,sb_vec3(p.x*3.1f,p.y*7.f-ctx.uTime*.18f,p.z*3.1f)+coast.w*2.2f),detail);
  float patchWeight=sb_smoothstep(.20f,.72f,coast.w*.72f+n*.28f);
  float air=ctx.uShoreChurn*coast.y*airProfile*(.025f+.19f*patchWeight);
  float sediment=ctx.uShoreChurn*coast.z*sandProfile*(.06f+.20f*patchWeight);


  float tail=(air+sediment)*sb_exp((0-(density))*2.5f);
  shade=shade+(tail*sb_clamp(belowSurface/sb_max(depth,.025f),0.f,1.f));
  sand=sand+(tail*sb_clamp((sediment+.18f*air)/sb_max(air+sediment,.00001f),0.f,1.f));
  density=density+(tail);
  }
  return sb_vec3(density*24.f*waterMask,shade/sb_max(density,.00001f),sand/sb_max(density,.00001f));
}

__device__ void main(GraphicsContext& ctx){
  ctx.gl_FragColor=sb_vec4(0.f);
  float4 np=ctx.uInverseVP*sb_vec4(ctx.vUv*2.f-1.f,(0-(1.f)),1.f);
  float3 ray=normalize(sb_sw_xyz(np)/np.w-ctx.uEye);
  float wet=submergedAt(ctx,sb_sw_xyz(np)/np.w);
  if(wet<.002f||ctx.uPlumeCount==0)return;
  float4 endp=ctx.uInverseVP*sb_vec4(ctx.vUv*2.f-1.f,__sb_textureLod(4,ctx.vUv,0.0f).x*2.f-1.f,1.f);
  float endD=sb_min(length(sb_sw_xyz(endp)/endp.w-ctx.uEye),18.f);
  float3 inv=sb_sign(ray+sb_vec3(1e-8f))/sb_max(sb_abs(ray),sb_vec3(1e-5f));
  float3 t0=(sb_vec3(ctx.uFieldLeft,(0-(1.7f)),ctx.uCrashZ.x)-ctx.uEye)*inv;
  float3 t1=(sb_vec3(ctx.uFieldLeft+48.f,1.8f,ctx.uCrashZ.y)-ctx.uEye)*inv;
  float3 lo=sb_min(t0,t1),hi=sb_max(t0,t1);
  float enter=sb_max(sb_max(sb_max(lo.x,lo.y),lo.z),0.f);
  float leave=sb_min(sb_min(sb_min(hi.x,hi.y),hi.z),endD);
  if(leave<=enter)return;
  float stepM=(leave-enter)/36.f;
  float tr=1.f;float3 color=sb_vec3(0.f);


  float offset=.04f+.92f*hash12(ctx,sb_sw_xy(ctx.gl_FragCoord));
  for(int j=0;j<36;j++){
    float dist=enter+(float(j)+offset)*stepM;
    float3 p=ctx.uEye+ray*dist;
    float3 d=cloud(ctx,p,stepM);d.x=d.x*(1.f-sb_smoothstep(14.f,18.f,dist));
    if(d.x<.005f)continue;
    float a=1.f-sb_exp((0-(d.x))*stepM);
    float direct=sb_exp((0-(d.y))*2.7f);
    float forward=.5f+.5f*sb_pow(sb_max(dot(ray,ctx.uSunDir),0.f),6.f);
    float3 light=ctx.uSkyAmb*(.16f+.46f*direct)+ctx.uSunColor*(.012f+.38f*direct)*forward;
    light=light*(sb_mix(sb_vec3(.50f,.73f,.76f),sb_vec3(.95f,.98f,.97f),direct));
    light=light*(sb_mix(sb_vec3(1.f),sb_vec3(1.06f,.90f,.67f),sb_clamp(d.z*.7f,0.f,.7f)));
    color=color+(tr*a*waterTravel(ctx,light,dist));
    tr=tr*(1.f-a);
    if(tr<.025f)break;
  }
  ctx.gl_FragColor=sb_vec4(color*wet,(1.f-tr)*wet);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.UW_EXTINCTION=sb_vec3(.245f,.066f,.046f);
ctx.UW_SCATTER=sb_vec3(.022f,.155f,.185f);
main(ctx);output[0]=ctx;}

#endif

