    l0 =sb_vec4((0-(0.1000000f)),7.000000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.000000f,(0-(1.000000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,3.800000f); q1 =sb_vec4(0.000000f,0.000000f,0.000000f,(0-(0.2000000f))); }
  else if (tn < (0-(2.000000f))) { t0 =(0-(3.000000f)); iw =1.000000f; cz =sb_vec4((0-(11.30000f)),4.250000f,0.02500000f,0.02500000f); cy =sb_vec4(0.2800000f,0.04500000f,(0-(0.02125000f)),0.02625000f);
    l0 =sb_vec4((0-(0.1000000f)),6.000000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.000000f,(0-(2.000000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,3.600000f); q1 =sb_vec4(0.000000f,0.000000f,0.000000f,(0-(0.4000000f))); }
  else if (tn < (0-(1.400000f))) { t0 =(0-(2.000000f)); iw =1.666667f; cz =sb_vec4((0-(7.000000f)),2.625000f,0.1800000f,(0-(0.1050000f))); cy =sb_vec4(0.3300000f,0.04875000f,0.06450000f,(0-(0.03325000f)));
    l0 =sb_vec4((0-(0.1000000f)),4.000000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.01000000f,(0-(1.800000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,3.200000f); q1 =sb_vec4(0.000000f,0.000000f,0.000000f,(0-(0.3000000f))); }
  else if (tn < (0-(1.000000f))) { t0 =(0-(1.400000f)); iw =2.500000f; cz =sb_vec4((0-(4.300000f)),1.780000f,0.05666667f,(0-(0.08666667f))); cy =sb_vec4(0.4100000f,0.05200000f,(0-(0.01400000f)),0.01200000f);
    l0 =sb_vec4((0-(0.09000000f)),2.200000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.01000000f,(0-(0.8000000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,2.900000f); q1 =sb_vec4(0.2000000f,0.000000f,0.000000f,(0-(0.2000000f))); }
  else if (tn < (0-(0.8000000f))) { t0 =(0-(1.000000f)); iw =5.000000f; cz =sb_vec4((0-(2.550000f)),0.8166667f,(0-(0.1866667f)),0.07000000f); cy =sb_vec4(0.4600000f,0.03000000f,0.02088889f,(0-(0.01088889f)));
