__device__ void swashFarAll(GraphicsContext& ctx,float2 xz,float t,float4& view,float4& foam,float2& wet,float4& lace){
  float2 uv = swashFarUV(ctx,xz);
  float inZ = swashFarInZ(ctx,uv);
  float B = bedProfile(ctx,xz.y);
  view =inZ > 0.5f? __sb_textureLod(8,uv,0.0f): sb_vec4(sb_max((0-(B)),0.0f),0.0f,0.0f,sb_max(B,0.0f));
  foam =__sb_textureLod(9,uv,0.0f)* inZ;
  float4 w = __sb_textureLod(10,uv,0.0f);
  wet =inZ > 0.5f? sb_sw_xy(w): sb_vec2(0.0f,1.0f- sb_smoothstep(0.35f,0.75f,B));
  lace =sb_vec4(0.0f,(0-(w.z)),0.0f,(0-(w.z)))* inZ;
}


__device__ float4 sweBlendView(GraphicsContext& ctx,float2 xz,float t,float& wAll){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(4,sweUV(ctx,xz),0.0f);
  wAll =sb_max(wIn,wf);
  if (wf <= 0.0f) return s * wIn;
  return sb_mix(s * wIn,swashFar(ctx,xz,t),wf);
}

__device__ float4 sweBlendFoam(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(5,sweUV(ctx,xz),0.0f)* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarFoam(ctx,xz,t),wf);
}

__device__ float2 sweBlendWet(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float2 s = sb_sw_xy(__sb_textureLod(7,sweUV(ctx,xz),0.0f))* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarWet(ctx,xz,t),wf);
}

__device__ float4 sweBlendLace(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(6,sweUV(ctx,xz),0.0f)* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarLace(ctx,xz,t),wf);
}


__device__ float4 macroNoise(GraphicsContext& ctx,float2 p,float2 lam){ return __sb_texture(11,p / (32.0f* lam))* 2.0f- 1.0f; }

__device__ float4 macroNoiseLod(GraphicsContext& ctx,float2 p,float2 lam){ return __sb_textureLod(11,p / (32.0f* lam),0.0f)* 2.0f- 1.0f; }


__device__ float4 macroNoiseG(GraphicsContext& ctx,float2 p,float2 lam,float2 dx,float2 dy){ float2 s = 1.0f/ (32.0f* lam); return __sb_textureGrad(11,p * s,dx * s,dy * s)* 2.0f- 1.0f; }




__device__ float highCloudAmount(GraphicsContext& ctx,float3 d){
  float h = sb_max(d.y,0.09f);
  float2 q = sb_sw_xz(d)/ h;
  q =sb_mat2(0.92f,0.39f,(0-(0.39f)),0.92f)* q;
  float broad = vnoise(ctx,q * sb_vec2(0.38f,0.9f)+ 31.6f);
  float strands = vnoise(ctx,q * sb_vec2(0.7f,7.0f)+ sb_vec2(4.1f,broad * 2.0f));
  float fine = vnoise(ctx,q * sb_vec2(2.1f,21.0f)+ broad * 3.0f);
  float density = sb_smoothstep(0.57f,0.82f,broad)* sb_smoothstep(0.24f,0.76f,strands * 0.75f+ fine * 0.25f);
  return density * 0.095f* sb_smoothstep(0.08f,0.22f,d.y);
}

__device__ float3 highCloud(GraphicsContext& ctx,float3 d,float3 sky){
  float a = highCloudAmount(ctx,d);
  float3 cloud = sb_vec3(0.68f,0.73f,0.75f)+ ctx.uSunColor * 0.045f* sb_pow(sb_max(dot(d,ctx.uSunDir),0.0f),6.0f);
  return sb_mix(sky,cloud,a);
}


__device__ float skySunLobe(GraphicsContext& ctx,float g){ return 1.0f+ 4.05f* sb_exp((0-(g ))/ 0.7f); }


__device__ float3 skyAzimuthGain(GraphicsContext& ctx,float3 d){
  float sy = sb_clamp(d.y,0.0f,1.0f);
  float ch = sb_sqrt(sb_max(1.0f- sy * sy,0.0f));
  float2 hz = sb_sw_xz(d)/ sb_max(length(sb_sw_xz(d)),1e-5f);
  float3 dd = sb_vec3(hz.x* ch,sy,hz.y* ch);
  float g = acos(sb_clamp(dot(dd,ctx.uSunDir),(0-(1.0f)),1.0f));
  float g0 = acos(sb_clamp(sy * ctx.uSunDir.y- ch * ctx.uSunDir.z,(0-(1.0f)),1.0f));
  float F = skySunLobe(ctx,g)/ skySunLobe(ctx,g0);
  float fe = sb_clamp(degrees(asin(sy))/ 22.0f,0.0f,1.0f);
  return sb_pow(sb_vec3(F),sb_mix(sb_vec3(2.03f,1.0f,1.0f),sb_vec3(2.16f,1.26f,0.88f),fe));
}


__device__ float3 skyProfile(GraphicsContext& ctx,float elDeg){
  float e = sb_max(elDeg,0.0f);
  float3 c = sb_sw_yzw(ctx.uSkyLut[0]);
  for (int i = 1; i < 18; i++) {
    float4 a = ctx.uSkyLut[i - 1], b = ctx.uSkyLut[i];
    if (e >= a.x) c =sb_mix(sb_sw_yzw(a),sb_sw_yzw(b),sb_clamp((e - a.x) / (b.x- a.x),0.0f,1.0f));
  }
  return c;
}




__device__ float3 skyAureole(GraphicsContext& ctx,float g){
  return ctx.uSunColor * (1.6f* sb_exp((0-(g ))/ 0.011f)+ 0.30f* sb_exp((0-(g ))/ 0.035f)+ 0.05f* sb_exp((0-(g ))/ 0.12f)+ 0.012f* sb_exp((0-(g ))/ 0.35f));
}


__device__ float3 landHazeColor(GraphicsContext& ctx,float3 dir){
  float3 h = normalize(sb_vec3(dir.x,0.0f,dir.z)+ sb_vec3(0.0f,1e-4f,0.0f));
  return skyProfile(ctx,0.2f)* skyAzimuthGain(ctx,sb_vec3(h.x,0.0035f,h.z));
}

__device__ float landHaze(GraphicsContext& ctx,float d){ return 1.0f- sb_exp((0-(sb_max(d - 60.0f,0.0f)))/ 7400.0f- 0.055f* (1.0f- sb_exp((0-(sb_max(d,0.0f)))/ 480.0f))); }


__device__ float bayBend(GraphicsContext& ctx,float x){ float d = sb_max(sb_abs(x)- 150.0f,0.0f); return d * d / 20000.0f; }

__device__ float bayBendSlope(GraphicsContext& ctx,float x){ return sb_sign(x)* sb_max(sb_abs(x)- 150.0f,0.0f)/ 10000.0f; }


__device__ float3 bayRotate(GraphicsContext& ctx,float3 n,float x){
  float s = bayBendSlope(ctx,x), c = sb_inversesqrt(1.0f+ s * s);
  return sb_vec3(c * n.x+ s * c * n.z,n.y,(0-(s ))* c * n.x+ c * n.z);
}


__device__ float coastShadow(GraphicsContext& ctx,float3 P,float3 N){
  float4 q = ctx.uCoastShadowMatrix * sb_vec4(P + N * 0.07f,1.0f);
  float3 p = sb_sw_xyz(q)/ q.w;
  if (sb_min(sb_min(p.x,p.y),p.z)< 0.0f|| sb_max(sb_max(p.x,p.y),p.z)> 1.0f) return 1.0f;
  float s = 0.0f;
  for (int i=0; i<4; i++) {
    float2 o = sb_vec2(float(i&1)-0.5f,float(i>>1)-0.5f)/ sb_vec2(2048.0f,1024.0f);
    s =s +(sb_step(p.z- 0.00035f,__sb_textureLod(12,sb_sw_xy(p)+o,0.0f).x));
  }
  return sb_mix(1.0f,s*0.25f,sb_smoothstep(0.0f,0.055f,sb_min(sb_min(p.x,1.0f-p.x),sb_min(p.y,1.0f-p.y))));
}


__device__ float2 causticSlope(GraphicsContext& ctx,float2 p,float lod){
  float2 a=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR0*p/ctx.uOceanL.x,0.0f),lod))*ctx.OCR0;
  float2 b=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR1*p/ctx.uOceanL.y,1.0f),sb_max(lod-1.f,0.f)))*ctx.OCR1;
  float2 c=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR2*p/ctx.uOceanL.z,2.0f),sb_max(lod+sb_log2(ctx.uOceanL.x/ctx.uOceanL.z),0.f)))*ctx.OCR2;
  return a*ctx.uOceanAmp.x*oceanFarGain(ctx,p)+b*ctx.uOceanAmp.y*.7f+c*ctx.uOceanAmp.z*.55f;
}

__device__ float seabedCaustic(GraphicsContext& ctx,float3 p,float depth){
  if(depth<.025f||depth>12.f)return 1.f;
  float footprint=sb_max(length(__sb_dFdx(sb_sw_xz(p))),length(__sb_dFdy(sb_sw_xz(p))));
  float e=sb_max(.025f+depth*.012f,footprint*1.5f);
  float lod=sb_log2(e*256.f/ctx.uOceanL.x);
  float2 q=sb_sw_xz(p)-sb_sw_xz(ctx.uSunDir)*depth/sb_max(ctx.uSunDir.y,.4f)/1.333f;
  q=q-(causticSlope(ctx,q,lod)*depth*.25f);
  float2 dx=(causticSlope(ctx,q+sb_vec2(e,float(0)),lod)-causticSlope(ctx,q-sb_vec2(e,float(0)),lod))/(2.f*e);
  float2 dz=(causticSlope(ctx,q+sb_vec2(float(0),e),lod)-causticSlope(ctx,q-sb_vec2(float(0),e),lod))/(2.f*e);
  float k=sb_min(depth,5.f)*.25f;
  float jac=(1.f-k*dx.x)*(1.f-k*dz.y)-k*k*dx.y*dz.x;
  float width=.22f+depth*.015f+footprint*3.f;
  float focus=.97f+.72f*sb_exp((0-(jac))*jac/(width*width));
  float strength=sb_smoothstep(.025f,.16f,depth)*sb_exp((0-(depth))*.13f)*(1.f-sb_smoothstep(.08f,.35f,footprint));
  return sb_mix(1.f,focus,strength*.72f);
}


__device__ float2 sandMoisture(GraphicsContext& ctx,float2 p){
  float w=sweInside(ctx,p)*(1.f-swashFarWeight(ctx,p));
  float2 wet=sb_sw_xy(__sb_textureLod(7,sweUV(ctx,p),0.0f))*w;
  if(w<1.f)wet=wet+((1.f-w)*swashFarWet(ctx,p,ctx.uTime));
  return wet;
}

__device__ void main(GraphicsContext& ctx){
  float3 P=ctx.vWorld,V=normalize(ctx.cameraPosition-P+sb_vec3(float(0),float(0),bayBend(ctx,P.x))),Nb=normalize(ctx.vNb);
  float2 uv=sb_sw_xz(P)*.5f;

  SBMat2 rot=sb_mat2(.6f,.8f,(0-(.8f)),.6f);float2 uv2=rot*uv*.73f+sb_vec2(.317f,.671f);
  float blend=sb_smoothstep((0-(.55f)),.55f,gnoise(ctx,sb_sw_xz(P)*.14f+17.3f));
  float3 photo=sb_mix(sb_sw_xyz(__sb_texture(13,uv)),sb_sw_xyz(__sb_texture(13,uv2)),blend);
  float4 nr1=__sb_texture(14,uv),nr2=__sb_texture(14,uv2);
  float3 n1=sb_sw_xyz(nr1)*2.f-1.f,n2=sb_sw_xyz(nr2)*2.f-1.f;
  float footprint=sb_max(length(__sb_dFdx(sb_sw_xz(P))),length(__sb_dFdy(sb_sw_xz(P))));


  float fine=1.f-sb_smoothstep(.0015f,.014f,footprint);
  float2 slope=sb_mix(sb_sw_xy(n1),transpose(rot)*sb_sw_xy(n2),blend)*.36f*sb_mix(.35f,1.f,fine);
  float rippleZone=sb_smoothstep((0-(.22f)),(0-(.7f)),P.y)*(1.f-sb_smoothstep(.008f,.025f,footprint));
  float ripplePhase=P.z*48.f+2.1f*gnoise(ctx,sb_sw_xz(P)*.85f)+.7f*gnoise(ctx,sb_sw_xz(P)*2.2f);
  slope.y=slope.y+(sb_sin(ripplePhase)*.095f*rippleZone);
  float3 Tx=normalize(sb_vec3(Nb.y,(0-(Nb.x)),float(0))),Tz=cross(Tx,Nb);
  float3 N=normalize(Nb+Tx*slope.x+Tz*slope.y);
  float w=sweInside(ctx,sb_sw_xz(P))*(1.f-swashFarWeight(ctx,sb_sw_xz(P)));float2 su=sweUV(ctx,sb_sw_xz(P));
  float4 sv=__sb_textureLod(4,su,0.0f);float2 wet=sandMoisture(ctx,sb_sw_xz(P));



  if(P.y>(0-(.02f))&&P.y<.8f){
    float2 blur=(sandMoisture(ctx,sb_sw_xz(P)+sb_vec2(.16f,float(0)))+sandMoisture(ctx,sb_sw_xz(P)-sb_vec2(.16f,float(0)))+
               sandMoisture(ctx,sb_sw_xz(P)+sb_vec2(float(0),.16f))+sandMoisture(ctx,sb_sw_xz(P)-sb_vec2(float(0),.16f)))*.25f;
    float feather=sb_smoothstep((0-(.02f)),.05f,P.y)*(1.f-sb_smoothstep(.65f,.8f,P.y));
    wet=sb_mix(wet,sb_mix(wet,blur,sb_vec2(.45f,.8f)),feather);
  }
  float4 far=sb_vec4(float(0));if(w<1.f)far=swashFar(ctx,sb_sw_xz(P),ctx.uTime);
  float wave=P.z<.5f&&P.z> (0-(9.f))?brkSurfaceOnly(ctx,sb_sw_xz(P),ctx.uTime):0.f;



  float column=sb_max(sb_mix(far.x,sv.x,w),0.f);
  float h=sb_max(sb_mix(sb_max(far.w,0.f),sv.w,w)+wave-P.y,0.f)*sb_smoothstep(.0003f,.002f,column);
  float sub=sb_smoothstep(.001f,.008f,h);
  float damp=sb_max(wet.y,1.f-sb_smoothstep(.04f,.40f,P.y+.018f*gnoise(ctx,sb_sw_xz(P)*1.1f)));
  float skin=sb_max(sub,sb_pow(sb_clamp(wet.x,0.f,1.f),3.8f));


  float grain=sb_clamp(dot(photo,sb_vec3(.2126f,.7152f,.0722f))/.165f,.35f,2.2f);
  float3 alb=sb_vec3(.63f,.555f,.423f)*sb_pow(grain,sb_mix(.23f,.32f,fine));
  alb=alb*(1.f+.025f*sb_cos(ripplePhase)*rippleZone);
  alb=alb*(1.f+.045f*gnoise(ctx,sb_sw_xz(P)*.27f)+.035f*gnoise(ctx,sb_sw_xz(P)*1.7f));
  alb=sb_mix(alb,alb*sb_vec3(.51f,.48f,.43f),sb_clamp(damp*.70f+skin*.30f,0.f,1.f));
  float rough=sb_mix(sb_clamp(sb_mix(nr1.w,nr2.w,blend),.68f,.94f),.23f,skin);
  float3 L=ctx.uSunDir,H=normalize(L+V);float nl=sb_max(dot(N,L),0.f),nv=sb_max(dot(N,V),.001f);
  float sh=coastShadow(ctx,P,N)*localRockShadow(ctx,P+N*.014f,L);
  float3 Ts=sb_exp((0-(ctx.WATER_SIGMA_A))*h/sb_max(L.y,.2f));
  float3 col=alb*(ctx.uSunColor*nl*sh/3.14159265f*Ts+skyAmbient(ctx,N)*sb_exp((0-(ctx.WATER_SIGMA_A))*h*.7f));
  float a=rough*rough,F=fresnelSchlick(ctx,sb_max(dot(V,H),0.f),sb_mix(.035f,.0204f,skin));
  col=col+(ctx.uSunColor*sb_min(D_GGX(ctx,sb_max(dot(N,H),0.f),a)*V_SmithGGXCorrelated(ctx,nv,nl,a)*F*nl,.7f)*sh);

  col=col*(sb_mix(1.f,seabedCaustic(ctx,P,h),nl*sh));
  col=sb_mix(col,landHazeColor(ctx,(0-(V))),landHaze(ctx,length(ctx.cameraPosition-P)));
  ctx.gl_FragColor=sb_vec4(col,1.f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.WATER_SIGMA_A=sb_vec3(0.46f,0.075f,0.062f);
ctx.WATER_SIGMA_S=sb_vec3(0.020f,0.030f,0.032f);
ctx.OCR0=sb_mat2(0.9563048f,0.2923717f,(0-(0.2923717f)),0.9563048f);
ctx.OCR1=sb_mat2(0.8571673f,(0-(0.5150381f)),0.5150381f,0.8571673f);
ctx.OCR2=sb_mat2(0.7313537f,0.6819984f,(0-(0.6819984f)),0.7313537f);
ctx.OCC2=sb_vec3(0.9145188f,0.7347358f,0.5348782f);
main(ctx);output[0]=ctx;}

#endif

