struct GraphicsContext {
SBMat4 modelMatrix;
SBMat4 modelViewMatrix;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
SBMat3 normalMatrix;
float3 cameraPosition;
float3 position;
float3 normal;
float2 uv;
float2 aWetUV;
float3 aPhoto;
float3 vW;
float3 vN;
float3 vPhoto;
float2 vRockWet;
float4 gl_Position;
int gl_VertexID;
int gl_InstanceID;
};
__device__ void main(GraphicsContext& ctx){ctx.vW=ctx.position;ctx.vN=ctx.normal;ctx.vPhoto=ctx.aPhoto;ctx.vRockWet=sb_sw_xy(__sb_textureLod(0,ctx.aWetUV,0.f));ctx.gl_Position=ctx.projectionMatrix*ctx.viewMatrix*sb_vec4(ctx.position,1.f);}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

