struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float4 uSkyLut[18];
float3 uSunDir;
float3 uSunColor;
float3 uSkyAmb;
SBMat4 uCoastShadowMatrix;
float3 vW;
float3 vN;
float3 vColor;
