__device__ float softplus_(GraphicsContext& ctx,float x){ return x > 20.0f? x : sb_log(1.0f+ sb_exp(x)); }

__device__ float bedProfile(GraphicsContext& ctx,float z){
  float y = 0.1f* z;
  y =y +(0.1f* 5.0f* softplus_(ctx,(z - ((0-(60.0f)))) / 5.0f));
  y =y +(0.8f* 1.2f* softplus_(ctx,(z - ((0-(22.5f)))) / 1.2f));
  y =y +((0-(0.9f))* 0.5f* softplus_(ctx,(z - ((0-(16.8f)))) / 0.5f));
  y =y +(0.01999999999999999f* 2.0f* softplus_(ctx,(z - ((0-(12.0f)))) / 2.0f));
  y =y +(0.22999999999999998f* 0.22f* softplus_(ctx,(z - ((0-(2.3f)))) / 0.22f));
  y =y +((0-(0.21499999999999997f))* 0.18f* softplus_(ctx,(z - ((0-(0.6f)))) / 0.18f));
  y =y +((0-(0.05f))* 1.5f* softplus_(ctx,(z - (11.0f)) / 1.5f));
  y =y +((0-(0.135f))* 1.2f* softplus_(ctx,(z - (19.0f)) / 1.2f));
  return sb_max(y + ((0-(9.51869802609202f))),(0-(30.0f)));
}



__device__ float hash11(GraphicsContext& ctx,float p){ p =sb_fract(p * 0.1031f); p =p *(p + 33.33f); p =p *(p + p); return sb_fract(p); }

__device__ float hash12(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* 0.1031f); p3 =p3 +(dot(p3,sb_sw_yzx(p3)+ 33.33f)); return sb_fract((p3.x+ p3.y) * p3.z); }

__device__ float2 hash22(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yzx(p3)+ 33.33f)); return sb_fract((sb_sw_xx(p3)+ sb_sw_yz(p3)) * sb_sw_zy(p3)); }

__device__ float3 hash32(GraphicsContext& ctx,float2 p){ float3 p3 = sb_fract(sb_vec3(sb_sw_xyx(p))* sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yxz(p3)+ 33.33f)); return sb_fract((sb_sw_xxy(p3)+ sb_sw_yzz(p3)) * sb_sw_zyx(p3)); }

__device__ float3 hash33(GraphicsContext& ctx,float3 p3){ p3 =sb_fract(p3 * sb_vec3(0.1031f,0.1030f,0.0973f)); p3 =p3 +(dot(p3,sb_sw_yxz(p3)+ 33.33f)); return sb_fract((sb_sw_xxy(p3)+ sb_sw_yxx(p3)) * sb_sw_zyx(p3)); }



__device__ float vnoise(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float2 u = f * f * f * (f * (f * 6.0f- 15.0f) + 10.0f);
  float a = hash12(ctx,i), b = hash12(ctx,i + sb_vec2(float(1),float(0))), c = hash12(ctx,i + sb_vec2(float(0),float(1))), d = hash12(ctx,i + sb_vec2(float(1),float(1)));
  return sb_mix(sb_mix(a,b,u.x),sb_mix(c,d,u.x),u.y);
}


__device__ float3 gnoised(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float2 u = f * f * f * (f * (f * 6.0f- 15.0f) + 10.0f);
  float2 du = 30.0f* f * f * (f * (f - 2.0f) + 1.0f);
  float2 ga = hash22(ctx,i)* 2.0f- 1.0f, gb = hash22(ctx,i + sb_vec2(float(1),float(0)))* 2.0f- 1.0f;
  float2 gc = hash22(ctx,i + sb_vec2(float(0),float(1)))* 2.0f- 1.0f, gd = hash22(ctx,i + sb_vec2(float(1),float(1)))* 2.0f- 1.0f;
  float va = dot(ga,f), vb = dot(gb,f - sb_vec2(float(1),float(0))), vc = dot(gc,f - sb_vec2(float(0),float(1))), vd = dot(gd,f - sb_vec2(float(1),float(1)));
  float v = va + u.x* (vb - va) + u.y* (vc - va) + u.x* u.y* (va - vb - vc + vd);
  float2 d = ga + u.x* (gb - ga) + u.y* (gc - ga) + u.x* u.y* (ga - gb - gc + gd)
         + du * (sb_sw_yx(u)* (va - vb - vc + vd) + sb_vec2(vb,vc)- va);
  return sb_vec3(v * 1.6f,d * 1.6f);
}

__device__ float gnoise(GraphicsContext& ctx,float2 p){ return gnoised(ctx,p).x; }

__device__ float fbm(GraphicsContext& ctx,float2 p,int oct){
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 8; i++) { if (i >= oct) break; s =s +(a * gnoise(ctx,p)); p =sb_mat2(1.6f,1.2f,(0-(1.2f)),1.6f)* p; a =a *(0.5f); }
  return s;
}


__device__ float vnoise3(GraphicsContext& ctx,float3 p){
  float3 i = sb_floor(p), f = sb_fract(p);
  float3 u = f * f * (3.0f- 2.0f* f);
  float n000 = hash33(ctx,i).x, n100 = hash33(ctx,i + sb_vec3(float(1),float(0),float(0))).x, n010 = hash33(ctx,i + sb_vec3(float(0),float(1),float(0))).x, n110 = hash33(ctx,i + sb_vec3(float(1),float(1),float(0))).x;
  float n001 = hash33(ctx,i + sb_vec3(float(0),float(0),float(1))).x, n101 = hash33(ctx,i + sb_vec3(float(1),float(0),float(1))).x, n011 = hash33(ctx,i + sb_vec3(float(0),float(1),float(1))).x, n111 = hash33(ctx,i + sb_vec3(float(1),float(1),float(1))).x;
  return sb_mix(sb_mix(sb_mix(n000,n100,u.x),sb_mix(n010,n110,u.x),u.y),sb_mix(sb_mix(n001,n101,u.x),sb_mix(n011,n111,u.x),u.y),u.z);
}


__device__ float3 worley(GraphicsContext& ctx,float2 p){
  float2 i = sb_floor(p), f = sb_fract(p);
  float f1 = 8.0f, f2 = 8.0f, id = 0.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float2 o = hash22(ctx,i + g);
    float2 r = g + o - f;
    float d = dot(r,r);
    if (d < f1) { f2 =f1; f1 =d; id =hash12(ctx,i + g); } else if (d < f2) { f2 =d; }
  }
  return sb_vec3(sb_sqrt(f1),sb_sqrt(f2),id);
}

__device__ float sat(GraphicsContext& ctx,float x){ return sb_clamp(x,0.0f,1.0f); }

__device__ float sech2(GraphicsContext& ctx,float x){ float e = sb_exp((0-(2.0f))* sb_abs(x)); float s = 2.0f* sb_exp((0-(sb_abs(x))))/ (1.0f+ e); return s * s; }

__device__ float remap(GraphicsContext& ctx,float v,float a,float b){ return sb_clamp((v - a) / (b - a),0.0f,1.0f); }


__device__ float3 skyRadiance(GraphicsContext& ctx,float3 d){
  float el = degrees(asin(sb_clamp(d.y,(0-(1.0f)),1.0f)));
  float e = sb_max(el,0.0f);
  float3 c = sb_sw_yzw(ctx.uSkyLut[0]);
  for (int i = 1; i < 18; i++) {
    float4 a = ctx.uSkyLut[i - 1], b = ctx.uSkyLut[i];
    if (e >= a.x) c =sb_mix(sb_sw_yzw(a),sb_sw_yzw(b),sb_clamp((e - a.x) / (b.x- a.x),0.0f,1.0f));
  }

  float az = degrees(sb_atan(d.x,(0-(d.z))));
  float k = sb_mix(0.0029f,0.0043f,sb_clamp(e / 22.0f,0.0f,1.0f));
  c =c *(1.0f+ k * sb_clamp(az,(0-(80.0f)),80.0f));

  float mu = sb_max(dot(d,ctx.uSunDir),0.0f);
  c =c +(ctx.uSunColor * (0.004f* sb_pow(mu,12.0f)+ 0.02f* sb_pow(mu,200.0f)));

  c =sb_mix(sb_vec3(0.05f,0.20f,0.26f),c,sb_smoothstep((0-(6.0f)),0.0f,el));
  return c;
}

__device__ float3 sunDisk(GraphicsContext& ctx,float3 d){
  float mu = dot(d,ctx.uSunDir);
  return ctx.uSunColor * 400.0f* sb_smoothstep(0.99996f,0.99999f,mu);
}


__device__ float3 skyAmbient(GraphicsContext& ctx,float3 N){
  float3 ground = sb_vec3(0.13f,0.12f,0.11f);
  return sb_mix(ground,ctx.uSkyAmb,0.62f+ 0.38f* N.y);
}




__device__ float highCloudAmount(GraphicsContext& ctx,float3 d){
  float h = sb_max(d.y,0.09f);
  float2 q = sb_sw_xz(d)/ h;
  q =sb_mat2(0.92f,0.39f,(0-(0.39f)),0.92f)* q;
  float broad = vnoise(ctx,q * sb_vec2(0.38f,0.9f)+ 31.6f);
  float strands = vnoise(ctx,q * sb_vec2(0.7f,7.0f)+ sb_vec2(4.1f,broad * 2.0f));
  float fine = vnoise(ctx,q * sb_vec2(2.1f,21.0f)+ broad * 3.0f);
  float density = sb_smoothstep(0.57f,0.82f,broad)* sb_smoothstep(0.24f,0.76f,strands * 0.75f+ fine * 0.25f);
  return density * 0.095f* sb_smoothstep(0.08f,0.22f,d.y);
}

__device__ float3 highCloud(GraphicsContext& ctx,float3 d,float3 sky){
  float a = highCloudAmount(ctx,d);
  float3 cloud = sb_vec3(0.68f,0.73f,0.75f)+ ctx.uSunColor * 0.045f* sb_pow(sb_max(dot(d,ctx.uSunDir),0.0f),6.0f);
  return sb_mix(sky,cloud,a);
}


__device__ float skySunLobe(GraphicsContext& ctx,float g){ return 1.0f+ 4.05f* sb_exp((0-(g ))/ 0.7f); }


__device__ float3 skyAzimuthGain(GraphicsContext& ctx,float3 d){
  float sy = sb_clamp(d.y,0.0f,1.0f);
  float ch = sb_sqrt(sb_max(1.0f- sy * sy,0.0f));
  float2 hz = sb_sw_xz(d)/ sb_max(length(sb_sw_xz(d)),1e-5f);
  float3 dd = sb_vec3(hz.x* ch,sy,hz.y* ch);
  float g = acos(sb_clamp(dot(dd,ctx.uSunDir),(0-(1.0f)),1.0f));
  float g0 = acos(sb_clamp(sy * ctx.uSunDir.y- ch * ctx.uSunDir.z,(0-(1.0f)),1.0f));
  float F = skySunLobe(ctx,g)/ skySunLobe(ctx,g0);
  float fe = sb_clamp(degrees(asin(sy))/ 22.0f,0.0f,1.0f);
  return sb_pow(sb_vec3(F),sb_mix(sb_vec3(2.03f,1.0f,1.0f),sb_vec3(2.16f,1.26f,0.88f),fe));
}


__device__ float3 skyProfile(GraphicsContext& ctx,float elDeg){
  float e = sb_max(elDeg,0.0f);
  float3 c = sb_sw_yzw(ctx.uSkyLut[0]);
  for (int i = 1; i < 18; i++) {
    float4 a = ctx.uSkyLut[i - 1], b = ctx.uSkyLut[i];
    if (e >= a.x) c =sb_mix(sb_sw_yzw(a),sb_sw_yzw(b),sb_clamp((e - a.x) / (b.x- a.x),0.0f,1.0f));
  }
  return c;
}




__device__ float3 skyAureole(GraphicsContext& ctx,float g){
  return ctx.uSunColor * (1.6f* sb_exp((0-(g ))/ 0.011f)+ 0.30f* sb_exp((0-(g ))/ 0.035f)+ 0.05f* sb_exp((0-(g ))/ 0.12f)+ 0.012f* sb_exp((0-(g ))/ 0.35f));
}


__device__ float3 landHazeColor(GraphicsContext& ctx,float3 dir){
  float3 h = normalize(sb_vec3(dir.x,0.0f,dir.z)+ sb_vec3(0.0f,1e-4f,0.0f));
  return skyProfile(ctx,0.2f)* skyAzimuthGain(ctx,sb_vec3(h.x,0.0035f,h.z));
}

__device__ float landHaze(GraphicsContext& ctx,float d){ return 1.0f- sb_exp((0-(sb_max(d - 60.0f,0.0f)))/ 7400.0f- 0.055f* (1.0f- sb_exp((0-(sb_max(d,0.0f)))/ 480.0f))); }


__device__ float bayBend(GraphicsContext& ctx,float x){ float d = sb_max(sb_abs(x)- 150.0f,0.0f); return d * d / 20000.0f; }

__device__ float bayBendSlope(GraphicsContext& ctx,float x){ return sb_sign(x)* sb_max(sb_abs(x)- 150.0f,0.0f)/ 10000.0f; }


__device__ float3 bayRotate(GraphicsContext& ctx,float3 n,float x){
  float s = bayBendSlope(ctx,x), c = sb_inversesqrt(1.0f+ s * s);
  return sb_vec3(c * n.x+ s * c * n.z,n.y,(0-(s ))* c * n.x+ c * n.z);
}


__device__ void main(GraphicsContext& ctx){
  ctx.vW =ctx.position;
  ctx.vA =ctx.aLayer;
  ctx.gl_Position =ctx.projectionMatrix * ctx.viewMatrix * sb_vec4(ctx.position,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

#endif

