float3 cameraPosition;
float4 uSkyLut[18];
float3 uSunDir;
float3 uSunColor;
float3 uSkyAmb;
SBMat4 uCoastShadowMatrix;
float uLeaf;
float3 vW;
float3 vN;
float3 vColor;
