__device__ float brkCrestSpeed(GraphicsContext& ctx,Brk b,float t){ return (brkCrestZ(ctx,b,t + 0.01f)- brkCrestZ(ctx,b,t - 0.01f)) / 0.02f; }



__device__ float brkHeight(GraphicsContext& ctx,Brk b,float t){
