  if (xi > g.lf) {
    const float La = 1.5f;
    float e = (xi - g.lf) / La;
    float ex = sb_exp((0-(e ))* e);
    return sb_vec2(g.yt* ex,g.yt* ex * ((0-(2.0f))* e / La));
