  if (chopW > 0.0f&& chopFar > 0.0f) { chop =oceanDisp(ctx,xz,lod,paw,gChop)* chopW; gChop =gChop *(chopW); }
  chop =chop *(chopFar);

  {float2 sb_write3=sb_sw_xz(chop)*(1.0f- sb_smoothstep(0.04f,0.2f,eta));chop.x=sb_write3.x;chop.z=sb_write3.y;}float wIn = sweInside(ctx,xz);
  float4 sv = __sb_textureLod(4,sweUV(ctx,xz),0.0f);
