}

























__device__ float4 crestGeometry(GraphicsContext& ctx,float2 xz,float t,float etaR,float3& aux,float3& faceNormal){
  aux =sb_vec3(0.0f,1.0f,0.0f); faceNormal=sb_vec3(0.0f,1.0f,0.0f);

  int best = (0-(1)); float bestD = 2.5f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f|| t < b.tb- 9.0f|| t > b.ti+ 0.6f) continue;
    float dC = sb_abs(xz.y- brkCrestZ(ctx,b,t));
    if (dC < bestD) { bestD =dC; best =i; }
  }
  if (best < 0) return sb_vec4(0.0f);
  Brk b = brkAt(ctx,best,xz.x);
  float tn = brkTn(ctx,b,t);
  if (tn < (0-(6.0f))|| tn > 0.85f) return sb_vec4(0.0f);
  BrkStage g = brkStage(ctx,tn);
  float2 A = brkApex(ctx,b,g,tn);

  float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str;
  float2 sh0 = brkShape(ctx,g,(xz.y- A.x) / b.s);
  float eta0 = sh0.x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y));
  aux.z=sb_max((0-(sh0.y))* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y)),0.0f);

  float fd = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  float ya = g.ya* b.s* amp * fd, yt = g.yt* b.s* amp * fd;
  eta0 =sb_clamp(etaR,yt,ya);
  float sFace = sb_clamp((ya - eta0) / sb_max(ya - yt,0.05f),0.0f,1.2f);



  if(g.st>.12f){
  float xiFace=brkFrontXi(ctx,g,sb_clamp(1.0f-sFace,.001f,.999f));
  if(xz.y<A.x) xiFace=(0-(g.lb))*acosh(sb_sqrt(sb_max(ya/sb_max(eta0,.0001f),1.00001f)));
  float dzSlope=brkShape(ctx,g,xiFace).y*amp*fd;


  float zLeft=0.0f,zRight=0.0f;
  for(int n=0;n<2+sb_min(ctx.uEvtCount,0);n++){
    Brk nb=brkAt(ctx,best,xz.x+(float(n)-.5f)*.5f);
    float zc=nb.zI-b.c*(nb.ti-nb.D-b.ti);
    if(n==0)zLeft=zc;else zRight=zc;
  }
  float crestTilt=sb_clamp((zRight-zLeft)/.5f,(0-(.6f)),.6f);
  faceNormal=normalize(sb_vec3(crestTilt*dzSlope,1.0f,(0-(dzSlope))));
  }
  float hMax = eta0, occ = 0.0f;
  float rise = ctx.uSunDir.y/ sb_max((0-(ctx.uSunDir.z)),0.05f);
  for (int k = 1; k <= 8 + sb_min(ctx.uEvtCount,0); k++) {
    float dz = 0.04f* sb_pow(float(k),1.6f);
    float zk = xz.y- dz;
    float y = brkShape(ctx,g,(zk - A.x) / b.s).x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,zk));
    hMax =sb_max(hMax,y);
    occ =sb_max(occ,y - eta0 - rise * dz);
  }


  float support=1.0f-sb_smoothstep(1.45f,2.48f,bestD);
  aux.x=(hMax - eta0)*support;
  aux.z=aux.z*(support);



  float xi = (xz.y- A.x) / b.s;
  if (xz.y> (0-(9.0f))&& xz.y< 0.5f&& tn > (0-(1.6f))&& tn < 0.25f&& xi > (0-(0.3f))) {
    float ahead = (xi - g.lf) * b.s;
    float fa = sb_smoothstep((0-(0.1f)),0.1f,ahead);
    float live = sb_mix(1.0f- sb_smoothstep((0-(0.05f)),0.25f,tn),0.85f* (1.0f- sb_smoothstep((0-(0.45f)),(0-(0.15f)),tn)),fa);
    aux.y=1.0f- sb_smoothstep((0-(0.3f)),0.0f,xi)* sb_smoothstep(0.55f,0.1f,ahead)* sb_smoothstep((0-(1.6f)),(0-(0.9f)),tn)* live;
  }
  aux.y=sb_mix(1.0f,aux.y,support);
  return sb_vec4(sFace,g.st,occ*support,support);
}




__device__ float foamHoles(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float acc = 0.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float3 hh = hash32(ctx,i + g);
    float2 r = g + sb_sw_xy(hh)- f;
    float a = dot(r,t);
    float d = sb_sqrt(sb_max(dot(r,r)- k * a * a,0.0f))+ 0.9f* hh.z;
    acc =acc +(sb_exp((0-(d ))* 12.5f));
  }
  return (0-(0.08f))* sb_log(sb_max(acc,1e-30f));
}


__device__ float laceWall(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float f1 = 8.0f, f2 = 8.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float2 r = g + hash22(ctx,i + g)- f;
    float a = dot(r,t);
    float d = dot(r,r)- k * a * a;
    if (d < f1) { f2 =f1; f1 =d; } else if (d < f2) { f2 =d; }
  }
  return 0.5f* (sb_sqrt(f2)- sb_sqrt(f1));
}










__device__ FoamSet foamSet(GraphicsContext& ctx,float2 p,float seed,float fp,float2 t,float an,float anL,bool tearOn,bool netOn,float wmul){
  FoamSet s = sb_new_FoamSet(0.5f,0.0f,0.0f,0.0f,0.5f);

  float2 pw = p + ctx.uFoamLook2.w* sb_vec2(gnoise(ctx,p * 1.3f+ sb_vec2(seed,1.7f)),gnoise(ctx,p * 1.3f+ sb_vec2(4.1f- seed,(0-(2.3f)))));
  if (tearOn) {
    float2 q = pw * ctx.uFoamLook2.x;
    q =q +(0.6f* sb_vec2(gnoise(ctx,q * 0.7f+ sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 0.7f+ sb_vec2(5.2f- seed,0.0f))));
    float h = foamHoles(ctx,q + seed * 7.3f,t,1.0f- 1.0f/ (an * an))* sb_sqrt(an);

    float raw = h + 0.25f* gnoise(ctx,p * 1.7f+ sb_vec2(seed * 2.3f,(0-(seed))))- (0.78f+ 0.11f* (an - 1.0f));
    float ca = 0.57f+ 0.092f* (an - 1.0f);
    s.tear=sb_smoothstep((0-(ca)),ca,raw);
    float cw = 0.545f+ 0.1f* (an - 1.0f);
    s.wall=sb_smoothstep((0-(cw)),cw,h - (0.781f+ 0.112f* (an - 1.0f)));
  }
  if (netOn) {
    float2 q = pw * ctx.uFoamLook.x;
    q =q +(0.55f* sb_vec2(gnoise(ctx,q * 0.55f+ sb_vec2(seed,0.0f)),gnoise(ctx,q * 0.55f+ sb_vec2(5.2f- seed,0.0f)))+ 0.2f* sb_vec2(gnoise(ctx,q * 1.9f- sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 1.9f+ sb_vec2(seed + 1.7f,0.0f))));
    float lf = laceWall(ctx,q + seed * 13.1f,t,1.0f- 1.0f/ (anL * anL));


    float w0 = ctx.uFoamLook.y* wmul;
    float we = sb_max(w0,0.7f* fp * ctx.uFoamLook.x);
    float core = sb_exp((0-((lf * lf) ))/ (we * we))* (w0 / we);


    float seg = sb_smoothstep(0.34f,0.62f,0.5f+ 0.5f* gnoise(ctx,p * 13.0f+ seed * 2.9f));
    float pch = sb_smoothstep((0-(0.25f)),0.65f,gnoise(ctx,p * 2.1f+ sb_vec2(seed * 1.7f,3.1f))+ 0.5f* gnoise(ctx,p * 4.7f- sb_vec2(seed,0.0f)));
    s.net=core * seg * (0.5f+ 0.5f* sb_smoothstep((0-(0.6f)),0.6f,gnoise(ctx,p * 27.0f- seed * 4.1f))) * sb_mix(0.02f,1.55f,pch*pch);
  }


  float ga = 1.0f- sb_smoothstep(0.0015f,0.004f,fp);
  if (ga > 0.0f) s.grain=ga * (1.4f* (vnoise(ctx,p * 380.0f+ seed * 17.0f)- 0.5f) + 0.9f* (vnoise(ctx,p * 760.0f- seed * 9.0f)- 0.5f) * (1.0f- sb_smoothstep(0.0008f,0.002f,fp)));

  float gc = 1.0f- sb_smoothstep(0.006f,0.014f,fp);
  if (gc > 0.0f) s.clump=gc * (0.45f* gnoise(ctx,p * 19.0f- seed * 5.3f)+ 0.25f* gnoise(ctx,p * 43.0f+ seed * 3.1f));
  return s;
}






__device__ float lumpField(GraphicsContext& ctx,float2 p,float seed,float t){
  float n1 = gnoise(ctx,p * 4.5f+ seed), n2 = gnoise(ctx,p * 10.0f+ sb_vec2(0.9f* t,(0-(0.6f))* t)- seed);
  float fold = 1.0f- sb_abs(gnoise(ctx,p * sb_vec2(6.0f,4.0f)+ sb_vec2((0-(0.5f))* t,0.7f* t)+ seed * 0.3f));
  return 0.5f+ 0.5f* (0.6f* n1 + 0.4f* n2) - 0.35f* fold * fold * fold * fold;
}

__device__ float blanketLumps(GraphicsContext& ctx,float2 xz,float2 suv,float t,float wf,float2 farVel){
  const float T = 0.5f;
  float2 e = 3.0f* ctx.uSweTexel;
  float2 vel = 0.4f* sb_sw_yz(__sb_textureLod(4,suv,0.0f))+ 0.15f* (sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(0.0f,e.y),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(0.0f,e.y),0.0f)));
  vel =sb_mix(vel,farVel,wf);
  float2 d = vel * T;
  d =d *(sb_min(1.0f,0.4f/ sb_max(length(d),1e-4f)));
  float ca = t / T, cb = ca + 0.5f;
  float fa = sb_fract(ca), fb = sb_fract(cb);
  float w = 1.0f- sb_abs(2.0f* fa - 1.0f);
  float la = lumpField(ctx,xz - d * fa,sb_floor(ca)* 1.618f,t), lb = lumpField(ctx,xz - d * fb,sb_floor(cb)* 2.414f+ 0.5f,t);
  return 0.5f+ (w * (la - 0.5f) + (1.0f- w) * (lb - 0.5f)) / sb_sqrt(w * w + (1.0f- w) * (1.0f- w));
}



__device__ float4 surfaceFoam(GraphicsContext& ctx,float3 P,float t,float crestFoam,float2& flowUV,float& turb){
  float2 suv = sweUV(ctx,sb_sw_xz(P));
  float wIn = sweInside(ctx,sb_sw_xz(P));
  float4 fm = __sb_textureLod(5,suv,0.0f)* wIn;
  float4 lo = __sb_textureLod(6,suv,0.0f)* wIn;
  float4 handoffDelta = sb_vec4(0.0f);
  float4 svw = __sb_textureLod(4,suv,0.0f);


  float hE = __sb_textureLod(4,suv + sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x, hW = __sb_textureLod(4,suv - sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x;
  float hw = (2.0f* svw.x+ hE + hW) * 0.25f;
  float hMin = sb_min(svw.x,sb_min(hE,hW));
  float2 fvel = sb_sw_yz(svw);

  float wf = swashFarWeight(ctx,sb_sw_xz(P));
  float2 farVel = sb_vec2(0.0f);
  if (wf > 0.0f) {

    float2 fuv = swashFarUV(ctx,sb_sw_xz(P));
    float4 fV = __sb_textureLod(8,fuv,0.0f);
    float fD = __sb_textureLod(10,fuv,0.0f).z;
    fm =sb_mix(fm,__sb_textureLod(9,fuv,0.0f),wf);
    handoffDelta =sb_vec4(0.0f,(0-(fD)),0.0f,(0-(fD)))- lo;
    lo =lo +(wf * handoffDelta);
    hw =sb_mix(hw,fV.x,wf);
    farVel =sb_sw_yz(fV);
    fvel =sb_mix(fvel,farVel,wf);
  }
  turb =fm.z;

  float phA = ctx.uLacePhase.x;
  float wa = sb_smoothstep(0.0f,0.22f,phA)* (1.0f- sb_smoothstep(0.5f,0.72f,phA));
  float wb = 1.0f- wa;
  float2 pa = sb_sw_xz(P)+ sb_sw_xy(lo), pb = sb_sw_xz(P)+ sb_sw_zw(lo);


  flowUV =sb_sw_xz(P)+ 0.3f* (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo));


  float3 dPx = __sb_dFdx(P), dPy = __sb_dFdy(P);
  float fp = sb_max(sb_max(length(dPx),length(dPy)),1.0e-4f);
  float ny = sb_abs(normalize(cross(dPx,dPy)).y);
  float fpXZ = sb_max(length(sb_sw_xz(dPx))+ length(sb_sw_xz(dPy)),1.0e-5f);



  float4 frameDx = __sb_dFdx(lo)- handoffDelta * __sb_dFdx(wf);
  float4 frameDy = __sb_dFdy(lo)- handoffDelta * __sb_dFdy(wf);
  float strA = (length(sb_sw_xy(frameDx))+ length(sb_sw_xy(frameDy))) / fpXZ;
  float strB = (length(sb_sw_zw(frameDx))+ length(sb_sw_zw(frameDy))) / fpXZ;

  float cf = crestFoam * sb_smoothstep(0.35f,0.75f,ny)* sb_smoothstep(0.2f,0.8f,0.5f+ 0.5f* gnoise(ctx,sb_sw_xz(P)* sb_vec2(7.0f,11.0f)+ sb_vec2(0.0f,(0-(t ))* 3.0f))+ crestFoam * 0.5f);
  if (fm.x< 0.01f&& fm.y< 0.01f) return sb_vec4(cf,cf > 0.0f? 0.85f: 0.0f,0.0f,cf);

  float R = fm.x, G = sb_clamp(fm.y,0.0f,1.5f);


  float spd = length(fvel);
  float2 dir = spd > 1.0e-3f? fvel / spd : sb_vec2(0.0f,1.0f);

  float fast = sb_smoothstep(0.3f,1.2f,spd)* sb_smoothstep((0-(0.2f)),0.4f,fvel.y/ sb_max(spd,0.1f));

  float an = sb_mix(1.0f,ctx.uFoamLook2.y,fast), anL = sb_mix(1.0f,1.65f,sb_smoothstep(.25f,1.4f,spd));
  float amtG = 1.0f- sb_exp((0-(G ))/ 0.9f);


  float flatW = sb_smoothstep(0.5f,0.8f,ny);

  float keepA = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strA));
  float keepB = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strB));



  float edgeFade = sb_smoothstep(0.002f,0.009f,hw)* sb_smoothstep(0.0005f,0.004f,hMin + wf);
  float ribVis = 1.0f- sb_smoothstep(0.022f,0.12f,fp);

  float netVis = 1.0f- sb_smoothstep(0.16f,0.60f,fp * ctx.uFoamLook.x);


  float tearVis = ribVis * (1.0f- sb_smoothstep(1.05f,1.4f,R));
  bool torn = tearVis > 0.0f;
  bool laced = G > 0.02f&& R < 0.7f;
  bool netOn = laced && R < 0.45f&& netVis > 0.0f;
  float thin = 1.0f- sb_smoothstep(0.3f,1.0f,R);

  float tearAcc = 0.0f, netAcc = 0.0f, grainAcc = 0.0f, clumpAcc = 0.0f, wallAcc = 0.0f;
  for (int k = 0; k < 2 + sb_min(ctx.uEvtCount,0); k++) {
    float wk = k == 0 ? wa : wb;
    if (wk <= 0.0f) continue;
    FoamSet S = foamSet(ctx,k == 0 ? pa : pb,k == 0 ? ctx.uLaceSeeds.x: ctx.uLaceSeeds.y+ 3.3f,fp,dir,an,anL,torn,netOn,1.0f+ 2.5f* amtG * amtG);
    float kk = wk * (k == 0 ? keepA : keepB);
    tearAcc =tearAcc +(kk * (S.tear- 0.5f));
    wallAcc =wallAcc +(kk * (S.wall- 0.5f));
    netAcc =netAcc +(kk * S.net);


    grainAcc =grainAcc +(kk * S.grain);
    clumpAcc =clumpAcc +(kk * S.clump);
  }
  float ka = wa * keepA, kb = wb * keepB;
  float nrm = 1.0f/ sb_max(sb_sqrt(wa * wa + wb * wb),1e-3f);
  float clump = clumpAcc * nrm;


  float rib = 0.5f+ tearAcc * nrm * tearVis + 0.09f* clump;
  float wall = 0.5f+ wallAcc * nrm * tearVis + 0.08f* clump;
  float net = netAcc;
  float grain = grainAcc * nrm * ctx.uFoamLook2.z;
  float lump = R > 0.3f? sb_mix(0.5f,blanketLumps(ctx,sb_sw_xz(P),suv,t,wf,farVel),flatW*sb_smoothstep(.3f,.55f,R)): 0.5f;
  float sup = ka + kb;
  float strVis = sup * ribVis;




  float cB = (1.0f- sb_exp((0-(sb_pow(R / 0.42f,1.4f))))) * sb_smoothstep(0.02f,0.1f,R);


  float ew = sb_mix(0.16f,0.36f,sb_smoothstep(0.3f,0.8f,cB));
  float th = cB >= ew ? 1.0f- cB : 1.0f+ ew - 2.0f* sb_sqrt(ew * cB);


  float rbHi = sb_clamp(1.0f- 2.0f* (1.0f- cB) * (1.0f- rib),0.0f,1.0f);
  float rbLo = sb_clamp((rib - th) / (2.0f* ew) + 0.5f,0.0f,1.0f);
  rbLo =rbLo * rbLo * (3.0f- 2.0f* rbLo);


  float rb = sb_mix(cB * (1.0f- 0.65f* ribVis * (1.0f- sup)),sb_mix(rbLo,rbHi,sb_smoothstep(0.6f,0.8f,cB)),strVis);


  float pocket = (1.0f- sb_smoothstep(0.0f,0.3f,rib)) * sb_smoothstep(0.5f,1.2f,R)* strVis;


  float aR = sb_mix(0.7f,0.94f,sb_smoothstep(0.3f,1.2f,R))* (1.0f- 0.45f* pocket);
  float haze = 0.12f* sb_smoothstep(0.02f,0.5f,R + 0.12f* G)* thin;

  float blanket = rb * aR * sb_mix(sb_mix(0.62f,0.85f,sb_smoothstep(0.5f,0.9f,cB)),1.0f,sb_smoothstep(th,th + 0.45f,rib))* (1.0f+ (0.8f* grain + 0.3f* clump) * thin);
  blanket =sb_clamp(blanket + haze * (1.0f- blanket),0.0f,1.0f)* ctx.uFoamLook.w;



  float lace = 0.0f, laceD = 0.25f;
  if (laced) {

    float amt = amtG;


    float cL = 0.07f* amt * amt;
    float ewL = 0.2f;
    float thL = cL >= ewL ? 1.0f- cL : 1.0f+ ewL - 2.0f* sb_sqrt(ewL * cL);
    float rl = sb_clamp((wall - thL) / (2.0f* ewL) + 0.5f,0.0f,1.0f);
    float ribL = sb_mix(cL * (1.0f- 0.65f* ribVis * (1.0f- sup)),rl * rl * (3.0f- 2.0f* rl),strVis);

    float netMean = 0.09f* (1.0f+ 2.5f* amt * amt);
    float netL = sb_mix(netMean * (1.0f- 0.65f* netVis * (1.0f- sup)),net,sup * netVis)* sb_min(1.3f* amt,1.0f)* sb_smoothstep(0.45f,0.1f,R);

    float sL = 0.8f* sb_clamp(ribL * (1.0f+ grain + 0.35f* clump),0.0f,1.0f);
    float nL = sb_mix(ctx.uFoamLook.z,0.85f,sb_smoothstep(0.45f,0.8f,amt))* sb_clamp(netL * (1.0f+ grain + 0.3f* clump),0.0f,1.0f);
    lace =sb_max(sL,nL)* sb_smoothstep(0.02f,0.12f,G)* (1.0f- sb_smoothstep(0.3f,0.7f,R));
    laceD =sb_mix(sb_mix(0.25f,0.5f,sb_smoothstep(0.45f,0.8f,amt)),0.6f,sL / sb_max(sL + nL,1e-3f));
  }


  float milkyBack = sb_smoothstep(0.25f,0.55f,fm.w)* sb_smoothstep((0-(0.15f)),(0-(0.5f)),fvel.y)* (1.0f- sb_smoothstep(0.2f,0.5f,R)) * (ka + kb);
  milkyBack =milkyBack *(sb_smoothstep(0.0f,0.025f,milkyBack));
  if (milkyBack > 0.0f&& fp < 0.008f) {
    float2 rq = (sb_sw_xz(P)+ (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo))) / 0.07f;
    float3 wr = worley(ctx,rq + sb_vec2(ctx.uLaceSeeds.x* 3.1f,0.0f));
    float rr = sb_mix(0.1f,0.17f,sb_fract(wr.z* 7.31f));
    float rw = sb_max(0.035f,0.6f* fp / 0.07f);
    float ring = sb_exp((0-(sb_pow((wr.x- rr) / rw,2.0f))))* sb_step(wr.z,0.22f)* sb_min(1.0f,0.035f/ rw);
    lace =sb_max(lace,0.55f* ring * milkyBack * (1.0f- sb_smoothstep(0.005f,0.008f,fp)));
  }






  float dBl = sb_mix(0.6f,0.95f,sb_smoothstep(0.3f,1.2f,R))+ 1.1f* (lump - 0.5f) * (1.0f- thin) + (0.35f* grain + 0.1f* clump) * (1.0f- thin)
            - 0.3f* (1.0f- rb) * (1.0f- thin) - 0.35f* pocket;
  dBl =sb_mix(sb_clamp(dBl,0.0f,1.0f),sb_mix(0.3f,0.6f,rb)* (1.0f+ 0.5f* grain + 0.3f* clump),thin);
  float wBl = blanket * edgeFade, wLa = lace * edgeFade * (1.0f- wBl);
  float dense = sb_clamp((dBl * wBl + laceD * wLa + 0.85f* cf) / sb_max(wBl + wLa + cf,1e-3f),0.0f,1.0f);

  float cov = 1.0f- (1.0f- blanket * edgeFade) * (1.0f- lace * edgeFade) * (1.0f- cf);
  return sb_vec4(sb_clamp(cov,0.0f,1.0f),dense,lace * edgeFade,cf);
}


__device__ SBMat2 rot2(GraphicsContext& ctx,float a){ float c = sb_cos(a), s = sb_sin(a); return sb_mat2(c,(0-(s)),s,c); }



__device__ float2 rippleGrad(GraphicsContext& ctx,float2 p,float t,float dist,float strength){
  float2 g = sb_vec2(0.0f);
  float px = sb_max(dist * ctx.uPxAng,0.5f* sb_max(length(__sb_fwidth(p)),1e-5f));
  float L = 1.6f;
  for (int i = 0; i < 6 + sb_min(ctx.uEvtCount,0); i++) {
    float keep = sb_smoothstep(px * 3.0f,px * 9.0f,L);
    if (keep > 0.0f) {
      float2 q = rot2(ctx,float(i)* 1.93f)* p / L;
      float c = sb_sqrt(9.81f* L / 6.2831f);
      q =q +(rot2(ctx,float(i)* 1.93f)* ctx.uWind * t * c / L * 0.7f);
      float3 n = gnoised(ctx,q + float(i)* 17.3f);
      g =g +(sb_sw_yz(n)* 0.075f* keep);
    }
    L =L *(0.48f);
  }
  return g * strength;
}










__device__ float3 filmRipple(GraphicsContext& ctx,float2 p,float t,float px,float2& ridgeDir){



  float2 d0=normalize(sb_vec2(.18f,1.f)),d1=normalize(sb_vec2((0-(.43f)),.90f)),d2=normalize(sb_vec2(.94f,.34f));
  float warp=.42f*gnoise(ctx,p*1.7f);
  float a=dot(p,d0)*44.9f-t*14.8f+warp;
  float b=dot(p,d1)*89.8f-t*27.1f+.6f*gnoise(ctx,p*2.3f+7.1f);
  float c=dot(p,d2)*157.1f-t*43.7f-warp;
  float2 g=d0*(.030f*sb_sin(a))*(1.f-sb_smoothstep(.006f,.024f,px))
    +d1*(.018f*sb_sin(b))*(1.f-sb_smoothstep(.003f,.012f,px))
    +d2*(.009f*sb_sin(c))*(1.f-sb_smoothstep(.0018f,.007f,px));
  ridgeDir=d0;


  return sb_vec3(g,0.f);
}



__device__ void main(GraphicsContext& ctx){
  float3 P = ctx.vWorld;
  float depth = P.y- hydraulicBedHeight(ctx,sb_sw_xz(P));
  if (depth < 0.0012f) {ctx.discarded=true;return;}ctx.gl_FragColor =sb_vec4(1.0f/ ctx.vViewZ,0.0f,0.0f,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.WATER_SIGMA_A=sb_vec3(0.46f,0.075f,0.062f);
ctx.WATER_SIGMA_S=sb_vec3(0.020f,0.030f,0.032f);
ctx.OCR0=sb_mat2(0.9563048f,0.2923717f,(0-(0.2923717f)),0.9563048f);
ctx.OCR1=sb_mat2(0.8571673f,(0-(0.5150381f)),0.5150381f,0.8571673f);
ctx.OCR2=sb_mat2(0.7313537f,0.6819984f,(0-(0.6819984f)),0.7313537f);
ctx.OCC2=sb_vec3(0.9145188f,0.7347358f,0.5348782f);
main(ctx);output[0]=ctx;}

#endif

