__device__ float lipDrape(GraphicsContext& ctx,Brk b,BrkLip L){ return 0.14f* b.s* sb_smoothstep(0.0f,0.15f,L.fl)* L.grow; }








__device__ bool lipCulled(GraphicsContext& ctx,float x,float4 EA){
  if (ctx.uLipX0.y> 1e3f) return false;
