__device__ float3 sheetResidual(GraphicsContext& ctx,float3 own,float2 xz,float t,float ownDX){
  float2 gr; float4 inf;
  float wh = waterHeight(ctx,xz,t,0.016f,gr,inf);

  return sb_vec3(wh - own.x,gr.x- (ownDX - own.x) / 0.04f,gr.y- own.y);
