__device__ void main(GraphicsContext& ctx){
  float x = lipColumn(ctx,ctx.position.x+ ctx.uLipX0.x);
  float t = ctx.uTime;
  float4 EA = ctx.uEvtA[ctx.uSlot];

  float4 meta = sb_vec4(0.0f,(0-(2.0f)),9.0f,0.0f), meta2 = sb_vec4(1.0f,0.0f,0.0f,0.0f); float2 knee = sb_vec2(0.0f);






  float dr = 0.004f, dx = 0.04f;
  float2 q = sb_vec2(EA.z- 0.5f,(0-(0.25f))* EA.y/ 0.45f), qa = sb_vec2(0.0f), qb = sb_vec2(0.0f), qx = sb_vec2(0.0f);
  Brk b = brkAt(ctx,ctx.uSlot,x); float ownDX = 0.0f;
  int nEval = (lipCulled(ctx,x,EA)? 0 : (ctx.uPass == 1 ? 1 : 4)) + sb_min(ctx.uEvtCount,0);
  for (int k = 0; k < nEval; k++) {
    float rr = k == 1 ? sb_min(ctx.aRow + dr,6.0f): (k == 2 ? sb_max(ctx.aRow - dr,0.0f): ctx.aRow);
    Brk bk = brkAt(ctx,ctx.uSlot,x + (k == 3 ? dx : 0.0f));
    float4 mk, mk2; float2 kn;
    float2 qk = sheetRaw(ctx,bk,rr,t,mk,mk2,kn);
    if (k == 0) { b =bk; q =qk; meta =mk; meta2 =mk2; knee =kn; if (meta.y< (0-(1.5f))) break; }
    else if (k == 1) qa =qk;
    else if (k == 2) qb =qk;
    else { qx =qk; ownDX =brkProfile(ctx,bk,q.x,t).x; }
  }
  if (meta.y< (0-(1.5f))) {

    ctx.vWorld =sb_vec3(x,q.y,q.x); ctx.vNrm =sb_vec3(0.0f,1.0f,0.0f);
    ctx.vLip =sb_vec4(ctx.aRow,0.0f,(0-(2.0f)),(0-(1.0f))); ctx.vLip2 =sb_vec4(meta.z,0.0f,0.0f,x); ctx.vLip3 =sb_vec4(1.0f,0.0f,0.0f,0.0f); ctx.vKnee =sb_vec2(0.0f);
    float4 mv0 = ctx.viewMatrix * sb_vec4(ctx.vWorld,1.0f);
    ctx.vViewZ =(0-(mv0.z));
