__device__ float swashFarInZ(GraphicsContext& ctx,float2 uv){ return sb_step(0.0f,uv.y)* sb_step(uv.y,1.0f); }

__device__ float4 swashFar(GraphicsContext& ctx,float2 xz,float t){
  float2 uv = swashFarUV(ctx,xz);
