  L.g=g;
  L.A=brkApex(ctx,b,g,tn);
  L.grow=sb_smoothstep(((0-(0.42f)))     ,((0-(0.42f)))      + 0.06f,tn);
  L.wR=0.075f* b.s;


  L.R=L.A+ sb_vec2(sb_mix(0.02f,0.10f,sb_smoothstep(((0-(0.42f)))     ,((0-(0.33f)))      + 0.05f,tn))* b.s,(0-(0.5f))* L.wR);
  float2 rel = sb_vec2(0.17f,(0-(0.043f)))* b.s;
  if (tn < ((0-(0.33f)))     ) {
    float f = sb_smoothstep(((0-(0.42f)))     ,((0-(0.33f)))     ,tn);
    L.T=L.A+ sb_mix(sb_vec2(0.03f,(0-(0.06f)))* b.s,rel,f);
    L.vT=sb_vec2(1.5f,(0-(0.3f)))* b.rs;
    L.fl=0.0f;
  } else {
    BrkStage gE = brkStage(ctx,((0-(0.33f)))     );
    float2 Te = brkApex(ctx,b,gE,((0-(0.33f)))     )+ rel;
    float2 V0 = brkLipV0(ctx,b);
    L.fl=(tn - ((0-(0.33f)))     ) * b.rs;
    float fb = sb_min(L.fl,b.Tj);
    L.T=Te + V0 * fb + sb_vec2(0.0f,(0-(0.5f))* 9.81f* fb * fb);
    L.vT=V0 + sb_vec2(0.0f,(0-(9.81f))* fb);
    if (L.fl> b.Tj) {

      float a = L.fl- b.Tj;
      L.T=L.T+(sb_vec2(V0.x* a * 0.6f,(0-(0.25f))* b.s* sb_smoothstep(0.0f,0.25f* b.rs,a)));
    }
  }
  float2 ch = L.T- L.R;
  float len = sb_max(length(ch),1e-4f);
  float2 dT = normalize(ch / len + normalize(L.vT));
  L.P1=L.R+ sb_vec2(0.45f* sb_max(ch.x,0.02f* b.s)+ 0.1f* len,0.0f);
  L.P2=L.T- dT * 0.35f* len;
  L.wT=0.035f* b.s* (1.0f- 0.5f* sb_min(L.fl/ 0.3f,1.0f)) * L.grow;
  return L;
}


__device__ float4 brkLipCurve(GraphicsContext& ctx,BrkLip L,float sg){
  float u = 1.0f- sg;
  float2 p = u * u * u * L.R+ 3.0f* u * u * sg * L.P1+ 3.0f* u * sg * sg * L.P2+ sg * sg * sg * L.T;
  float2 dp = 3.0f* u * u * (L.P1- L.R) + 6.0f* u * sg * (L.P2- L.P1) + 3.0f* sg * sg * (L.T- L.P2);
  float l = length(dp);
  return sb_vec4(p,l > 1e-6f? dp / l : sb_vec2(1.0f,0.0f));
}

__device__ float brkLipWidth(GraphicsContext& ctx,BrkLip L,float sg){ return L.wT+ (L.wR- L.wT) * sb_pow(1.0f- sb_clamp(sg,0.0f,1.0f),0.8f); }



__device__ float3 brkJet(GraphicsContext& ctx,Brk b,float sigma,float t){
  BrkLip L = brkLip(ctx,b,t);
  float sg = 1.0f- sb_clamp(sigma,0.0f,1.0f);
  float4 c = brkLipCurve(ctx,L,sg);
  return sb_vec3(sb_sw_xy(c),brkLipWidth(ctx,L,sg));
}


__device__ float brkImpactSpeed(GraphicsContext& ctx,Brk b){
  float2 v = brkLipV0(ctx,b)+ sb_vec2(0.0f,(0-(9.81f))* b.Tj);
  return length(v);
}






__device__ float brkGamma(GraphicsContext& ctx,float tau,float T){ return tau > 0.0f? tau / (T * T) * sb_exp((0-(tau ))/ T): 0.0f; }



__device__ float brkThrow(GraphicsContext& ctx,Brk b){ return sb_mix(0.3f,1.0f,sb_smoothstep(0.4f,0.75f,b.style)); }








__device__ float brkLobes(GraphicsContext& ctx,Brk b){
  float x = b.x;
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float ph = far * 2.5f* sb_sin(0.37f* x + b.seed* 5.1f+ 1.7f* sb_sin(0.13f* x));
  float am = sb_mix(1.0f,0.45f+ 0.9f* (0.5f+ 0.5f* sb_sin(0.29f* x + b.seed* 3.3f)* sb_sin(0.71f* x + 1.1f)),far);

  float wm = 1.1f* sb_sin(1.9f* x + b.seed* 13.7f)+ 0.6f* sb_sin(4.4f* x + b.seed* 29.3f);
  float fine = 0.6f* sb_sin(24.1f* x + b.seed* 53.3f+ 2.1f* sb_sin(3.7f* x + b.seed* 9.0f))+ 0.4f* sb_sin(37.9f* x + b.seed* 71.9f+ 1.7f* sb_sin(5.9f* x + b.seed* 4.0f));
  return am * (ctx.uInjL.x* sb_sin(5.236f* x + b.seed* 37.1f+ ph)+ ctx.uInjL.y* sb_sin(14.96f* x + b.seed* 91.7f+ wm + 1.9f* ph)+ ctx.uInjL.z* fine);
}






__device__ float brkRunupMod(GraphicsContext& ctx,float x,float seed){
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float und = 0.6f* sb_sin(0.21f* x + seed * 7.3f+ 0.5f* sb_sin(0.09f* x + seed * 3.1f))+ 0.4f* sb_sin(0.47f* x + seed * 13.1f);
  float cph = x / 17.0f+ 0.25f* sb_sin(x / 23.0f+ 1.1f);
  float horn = 1.0f- sb_abs(sb_sin(3.14159f* cph));
  return far * (0.14f* und + 0.13f* (1.0f- 2.0f* horn * horn));
}

__device__ float3 brkInjection(GraphicsContext& ctx,float2 xz,float t){
  float3 src = sb_vec3(0.0f);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float hs = sb_sqrt(b.H/ 0.45f);

    float M = ctx.uInjMass * 0.2025f* sb_pow(b.H/ 0.45f,1.5f)* b.str* sb_max(ctx.uEvtG[i].x,0.0f);

    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = 0.22f* hs + 0.20f* tJ;
    float qJ = M * ctx.uInjJ.x* brkGamma(ctx,tJ,ctx.uInjJ.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f))/ (2.5066f* sJ);

    float tR = tau - ctx.uInjR.x;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ ctx.uInjR.z* sb_max(tR,0.0f);
    float sR = 0.30f* hs + 0.15f* sb_max(tR,0.0f);
    float qR = M * (1.0f- ctx.uInjJ.x) * brkGamma(ctx,tR,ctx.uInjR.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f))/ (2.5066f* sR);

    float thr = brkThrow(ctx,b);
    float mz = ctx.uInjSpeed * (qJ * ctx.uInjJ.w* sb_mix(0.5f,1.0f,thr)+ qR * ctx.uInjR.w* sb_mix(0.6f,1.0f,thr))
             * (1.0f+ brkLobes(ctx,b)) * (1.0f+ 0.5f* brkRunupMod(ctx,b.x,b.seed));
    src =src +(sb_vec3(qJ + qR,mz,mz * ctx.uInjL.w));
  }
  return src;
}





__device__ float brkFoam(GraphicsContext& ctx,float2 xz,float t){
  float f = 0.0f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;




    float spl = sb_smoothstep(0.5f,0.9f,b.spill)* (1.0f- sb_smoothstep(0.1f,0.3f,b.style)) * b.str;

    if (spl > 0.0f&& tau > (0-(0.3f))&& tau < 2.4f) {


      float on = sb_smoothstep((0-(0.3f)),0.0f,tau)* (1.0f- sb_smoothstep(ctx.uFoamSpillK.y- 1.1f,ctx.uFoamSpillK.y,tau));
      float zc = b.zI+ 0.1f+ ctx.uFoamSpillK.x* sb_max(tau,0.0f);
      f =f +(ctx.uFoamSpill * spl * (b.H/ 0.45f) * on * sb_exp((0-(0.5f))* sb_pow((xz.y- zc) / (0.3f+ 0.2f* sb_max(tau,0.0f)),2.0f)));
    }
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float E = (b.H* b.H) / (0.45f* 0.45f) * b.str* sb_mix(0.6f,1.0f,b.style);
    float2 gain = sb_max(sb_sw_xy(ctx.uEvtG[i]),sb_vec2(0.0f));
    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = ctx.uFoamSrc.w* (0.25f+ 0.30f* sb_max(tJ,0.0f));
    f =f +(E * gain.y* ctx.uFoamSrc.x* brkGamma(ctx,tJ,ctx.uFoamSrc.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f)));

    float tR = tau - 0.21f;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ 0.55f* sb_max(tR,0.0f);
    float sR = 0.35f+ 0.2f* sb_max(tR,0.0f);
    f =f +(E * gain.x* ctx.uFoamSrc.z* brkGamma(ctx,tR,0.4f)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f)));
  }
  return f;
}








__device__ float brkSweFoamKeep(GraphicsContext& ctx,float2 xz,float t){
  float keep = 1.0f;
  if (xz.y< (0-(9.0f))|| xz.y> 0.6f) return keep;
  float fade = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tn = brkTn(ctx,b,t);
    if (tn < (0-(2.4f))|| tn > 0.5f) continue;
    BrkStage g = brkStage(ctx,tn);
    float2 A = brkApex(ctx,b,g,tn);
    float xi = (xz.y- A.x) / b.s;
    if (xi < (0-(0.8f))|| xi > g.lf) continue;
    float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str* fade;
    float eta = brkShape(ctx,g,xi).x* b.s* amp;
    float raised = sb_smoothstep(0.012f,0.06f,eta - 0.5f* g.yt* b.s* amp);
    float front = sb_smoothstep((0-(0.8f)),(0-(0.2f)),xi);
    float grown = sb_smoothstep((0-(2.4f)),(0-(1.5f)),tn);
    float live = 1.0f- sb_smoothstep(0.1f,0.5f,tn);
    keep =sb_min(keep,1.0f- front * raised * grown * live);
  }
  return keep;
}


__device__ float2 ocVar(GraphicsContext& ctx,float2 v,float c2){ return sb_vec2(c2 * v.x+ (1.0f- c2) * v.y,(1.0f- c2) * v.x+ c2 * v.y); }






__device__ float pawFbm(GraphicsContext& ctx,float2 p,float fz,int oct){
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 5; i++) {
    if (i >= oct) break;
    s =s +(a * gnoise(ctx,p)* (1.0f- sb_smoothstep(0.25f,0.5f,fz)));
    p =sb_mat2(1.6f,1.2f,(0-(1.2f)),1.6f)* p; a =a *(0.5f); fz =fz *(2.0f);
  }
  return s;
}

__device__ float catsPaw(GraphicsContext& ctx,float2 xz,float t,float fp){
  float2 q = xz * sb_vec2(0.055f,0.16f);
  float a = pawFbm(ctx,q + sb_vec2(0.021f,(0-(0.12f)))* t,fp * 0.16f,4);
  float b = pawFbm(ctx,q * 1.7f+ sb_vec2((0-(0.05f)),(0-(0.2f)))* t + 11.3f,fp * 0.27f,3);
  float f = 0.5f+ 0.8f* (0.62f* a + 0.38f* b);


  float D = sb_max(4.1f- xz.y,1.0f);
  float r = xz.x/ (0.72f* D);
  float lane = sb_clamp(0.45f* gnoise(ctx,sb_vec2(xz.x* 0.013f+ 0.37f,xz.y* 0.009f- 1.3f)),(0-(0.5f)),0.5f);
  float u = sb_mix(sb_clamp(r,(0-(0.5f)),0.5f),lane,sb_smoothstep(0.6f,1.6f,sb_abs(r)));
  float lr = 1.0f- 1.1f* u;
  return sb_mix(1.0f,sb_clamp(f,0.15f,1.6f)* lr,ctx.uOceanAmp.w);
}




__device__ float oceanFarGain(GraphicsContext& ctx,float2 xz){ return sb_mix(ctx.uSeaTune5.w,1.0f,sb_smoothstep(15.0f,40.0f,4.1f- xz.y)); }


__device__ float viewDistH(GraphicsContext& ctx,float2 xz){ return length(xz - sb_sw_xz(ctx.cameraPosition)); }




__device__ float3 oceanDisp(GraphicsContext& ctx,float2 xz,float fp,float paw,float2& slope){
  float3 d = sb_vec3(0.0f); slope =sb_vec2(0.0f);
  float lf = sb_log2(sb_max(fp,1e-4f)* 256.0f)+ 0.5f;
  float l0 = lf - sb_log2(ctx.uOceanL.x), l1 = lf - sb_log2(ctx.uOceanL.y), l2 = lf - sb_log2(ctx.uOceanL.z);
  paw =sb_max(paw,0.0f);
  float3 a = sb_sw_xyz(ctx.uOceanAmp)* sb_vec3(oceanFarGain(ctx,xz),sb_sqrt(paw),paw);
  float4 D = __sb_textureLodArray(2,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),l0);
  float4 S = __sb_textureLodArray(3,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),l0);
  d.y=D.y* a.x; {float2 sb_write0=(sb_sw_xz(D)* ctx.OCR0) * a.x;d.x=sb_write0.x;d.z=sb_write0.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR0) * a.x);
  if (l1 < 8.0f) {
    D =__sb_textureLodArray(2,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),l1); S =__sb_textureLodArray(3,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),l1);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l1);
    d.y=d.y+(D.y* a.y* keep); {float2 sb_write1=sb_sw_xz(d)+((sb_sw_xz(D)* ctx.OCR1) * a.y* keep);d.x=sb_write1.x;d.z=sb_write1.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR1) * a.y* keep);
  }
  if (l2 < 8.0f) {
    D =__sb_textureLodArray(2,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),l2); S =__sb_textureLodArray(3,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),l2);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l2);
    d.y=d.y+(D.y* a.z* keep); {float2 sb_write2=sb_sw_xz(d)+((sb_sw_xz(D)* ctx.OCR2) * a.z* keep);d.x=sb_write2.x;d.z=sb_write2.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR2) * a.z* keep);
  }
  return d;
}



__device__ float3 chopWaves(GraphicsContext& ctx,float2 xz,float t,float lod){
  float2 s; float3 d = oceanDisp(ctx,xz,lod,1.0f,s);
  return sb_vec3(d.y,s);
}


__device__ float2 sweUV(GraphicsContext& ctx,float2 xz){ return (xz - sb_sw_xy(ctx.uSweDom)) / sb_sw_zw(ctx.uSweDom); }

__device__ float sweInside(GraphicsContext& ctx,float2 xz){
  float2 uv = sweUV(ctx,xz);
  float2 e = sb_min(uv,1.0f- uv);

  return sb_smoothstep(0.0f,0.04f,sb_min(e.x,e.y* ctx.uSweDom.w/ 9.8f));
}




__device__ float swashFarU(GraphicsContext& ctx,float x){
  float g = ctx.uSwashFarMap.y* asinh((x - ctx.uSwashFarMap.x) / ctx.uSwashFarMap.y);
  return 0.5f+ 0.5f* g / ctx.uSwashFarMap.z;
}

__device__ float swashFarXofColumn(GraphicsContext& ctx,float i){
  float g = ((i + 0.5f) / ctx.uSwashFarMapZ.w- 0.5f) * 2.0f* ctx.uSwashFarMap.z;
  return ctx.uSwashFarMap.x+ ctx.uSwashFarMap.y* sinh(g / ctx.uSwashFarMap.y);
}

__device__ float2 swashFarUV(GraphicsContext& ctx,float2 xz){ return sb_vec2(swashFarU(ctx,xz.x),(xz.y- ctx.uSwashFarMapZ.x) / (ctx.uSwashFarMapZ.y* ctx.uSwashFarMapZ.z) + 0.5f/ ctx.uSwashFarMapZ.z); }

__device__ float swashVisualFocusX(GraphicsContext& ctx){


  return sb_clamp(ctx.uSwashFocus.x,ctx.uSwashFarWin.x- 1.1f,ctx.uSwashFarWin.x+ 1.1f);
}

__device__ float swashFarWeight(GraphicsContext& ctx,float2 xz){




  float visible = sb_smoothstep(ctx.uSwashFarWin.y,ctx.uSwashFarWin.z,sb_abs(xz.x- swashVisualFocusX(ctx)));


  float bounds = sb_smoothstep(9.95f,10.14f,sb_abs(xz.x- ctx.uSwashFarWin.x));
  return ctx.uSwashFarWin.w* sb_max(visible,bounds);
}


__device__ float swashFarInZ(GraphicsContext& ctx,float2 uv){ return sb_step(0.0f,uv.y)* sb_step(uv.y,1.0f); }

__device__ float4 swashFar(GraphicsContext& ctx,float2 xz,float t){
  float2 uv = swashFarUV(ctx,xz);
  float4 result = sb_vec4(0.0f);
  if (swashFarInZ(ctx,uv)< 0.5f) { float B = bedProfileT(ctx,xz.y); result =sb_vec4(sb_max((0-(B)),0.0f),0.0f,0.0f,sb_max(B,0.0f)); }
  else result =__sb_textureLod(8,uv,0.0f);
  return result;
}

__device__ float4 swashFarFoam(GraphicsContext& ctx,float2 xz,float t){
  float2 uv = swashFarUV(ctx,xz);
  return __sb_textureLod(9,uv,0.0f)* swashFarInZ(ctx,uv);
}

__device__ float2 swashFarWet(GraphicsContext& ctx,float2 xz,float t){
  float2 uv = swashFarUV(ctx,xz);
  float2 result = sb_vec2(0.0f);
  if (swashFarInZ(ctx,uv)< 0.5f) result =sb_vec2(0.0f,1.0f- sb_smoothstep(0.35f,0.75f,bedProfileT(ctx,xz.y)));
  else result =sb_sw_xy(__sb_textureLod(10,uv,0.0f));
  return result;
}

__device__ float4 swashFarLace(GraphicsContext& ctx,float2 xz,float t){
  float2 uv = swashFarUV(ctx,xz);
  float d = __sb_textureLod(10,uv,0.0f).z* swashFarInZ(ctx,uv);
  return sb_vec4(0.0f,(0-(d)),0.0f,(0-(d)));
}

__device__ float2 swashFarGrad(GraphicsContext& ctx,float2 xz,float t){
  float ex = 0.05f, ez = ctx.uSwashFarMapZ.y;
  float wE = swashFar(ctx,xz + sb_vec2(ex,0.0f),t).w, wW = swashFar(ctx,xz - sb_vec2(ex,0.0f),t).w;
  float wN = swashFar(ctx,xz + sb_vec2(0.0f,ez),t).w, wS = swashFar(ctx,xz - sb_vec2(0.0f,ez),t).w;
  return sb_vec2((wE - wW) / (2.0f* ex),(wN - wS) / (2.0f* ez));
}

__device__ void swashFarAll(GraphicsContext& ctx,float2 xz,float t,float4& view,float4& foam,float2& wet,float4& lace){
  float2 uv = swashFarUV(ctx,xz);
  float inZ = swashFarInZ(ctx,uv);
  float B = bedProfileT(ctx,xz.y);
  view =inZ > 0.5f? __sb_textureLod(8,uv,0.0f): sb_vec4(sb_max((0-(B)),0.0f),0.0f,0.0f,sb_max(B,0.0f));
  foam =__sb_textureLod(9,uv,0.0f)* inZ;
  float4 w = __sb_textureLod(10,uv,0.0f);
  wet =inZ > 0.5f? sb_sw_xy(w): sb_vec2(0.0f,1.0f- sb_smoothstep(0.35f,0.75f,B));
  lace =sb_vec4(0.0f,(0-(w.z)),0.0f,(0-(w.z)))* inZ;
}


__device__ float4 sweBlendView(GraphicsContext& ctx,float2 xz,float t,float& wAll){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(4,sweUV(ctx,xz),0.0f);
  wAll =sb_max(wIn,wf);
  if (wf <= 0.0f) return s * wIn;
  return sb_mix(s * wIn,swashFar(ctx,xz,t),wf);
}

__device__ float4 sweBlendFoam(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(5,sweUV(ctx,xz),0.0f)* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarFoam(ctx,xz,t),wf);
}

__device__ float2 sweBlendWet(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float2 s = sb_sw_xy(__sb_textureLod(7,sweUV(ctx,xz),0.0f))* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarWet(ctx,xz,t),wf);
}

__device__ float4 sweBlendLace(GraphicsContext& ctx,float2 xz,float t){
  float wIn = sweInside(ctx,xz), wf = swashFarWeight(ctx,xz);
  float4 s = __sb_textureLod(6,sweUV(ctx,xz),0.0f)* wIn;
  return wf <= 0.0f? s : sb_mix(s,swashFarLace(ctx,xz,t),wf);
}




__device__ float chopWeight(GraphicsContext& ctx,float depth0){ return sb_smoothstep(0.05f,1.2f,depth0); }



__device__ float3 swellAt(GraphicsContext& ctx,float2 xz){
  float v=sb_log(1.0f+sb_max((0-(xz.y))-6.0f,0.0f)/8.0f)/sb_log(81.5f);
  float2 uv=sb_vec2((xz.x+512.0f)/1024.0f,v);
  float fade=(1.0f-sb_smoothstep(420.0f,512.0f,sb_abs(xz.x)))*sb_smoothstep((0-(650.0f)),(0-(460.0f)),xz.y);
  return sb_sw_xyz(__sb_textureLod(11,uv,0.0f))*fade;
}


__device__ float waterParts(GraphicsContext& ctx,float2 xz,float t,float lod,float2& gMacro,float3& chop,float2& gChop,float4& info,float& paw){
  float2 d = sb_vec2(0.0f); float crestFoam = 0.0f;


  float aa = 1.0f- sb_smoothstep(0.08f,0.35f,lod);
  float eta = 0.0f;
  aa=sb_mix(aa,1.0f-sb_smoothstep(.7f,3.0f,lod),1.0f-sb_smoothstep((0-(11.0f)),(0-(7.0f)),xz.y));
  if (aa > 0.0f&& xz.y> (0-(40.0f))) {
  eta =brkSurface(ctx,xz,t,d,crestFoam);
  float etaX = brkSurfaceOnly(ctx,xz + sb_vec2(0.04f,0.0f),t);
  d.x=(etaX - eta) / 0.04f;
  }
  eta =eta *(aa); d =d *(aa); crestFoam =crestFoam *(aa);
  float sw=1.0f-sb_smoothstep((0-(32.0f)),(0-(22.0f)),xz.y);
  if(sw>0.0f){
    float3 farSwell=swellAt(ctx,xz)*(1.0f-sb_smoothstep(3.0f,14.0f,lod));
    float q=sb_clamp((xz.y+32.0f)/10.0f,0.0f,1.0f);
    float slope=(0-(.6f))*q*(1.0f-q);
    d=sb_mix(d,sb_sw_yz(farSwell),sw)+sb_vec2(0.0f,(farSwell.x-eta)*slope);
    eta=sb_mix(eta,farSwell.x,sw);
  }
  ctx.gBrkEta =eta;
  float B = bedProfileT(ctx,xz.y);
  float depth0 = sb_max((0-(B)),0.0f);
  float chopW = chopWeight(ctx,depth0);

  chopW =chopW *(1.0f/ (1.0f+ 1.5f* dot(d,d)));
  paw =catsPaw(ctx,xz,t,lod);
  chop =sb_vec3(0.0f); gChop =sb_vec2(0.0f);



  float chopFar = 1.0f- sb_smoothstep(ctx.uSeaTune4.z,ctx.uSeaTune4.w,viewDistH(ctx,xz));
  if (chopW > 0.0f&& chopFar > 0.0f) { chop =oceanDisp(ctx,xz,lod,paw,gChop)* chopW; gChop =gChop *(chopW); }
  chop =chop *(chopFar);

  {float2 sb_write3=sb_sw_xz(chop)*(1.0f- sb_smoothstep(0.04f,0.2f,eta));chop.x=sb_write3.x;chop.z=sb_write3.y;}float wIn = sweInside(ctx,xz);
  float4 sv = __sb_textureLod(4,sweUV(ctx,xz),0.0f);
  float sweEta = sb_mix(0.0f,sv.w,wIn);
  float sweH = sv.x;

  float wF = swashFarWeight(ctx,xz);
  if (wF > 0.0f) {
    float4 sf = swashFar(ctx,xz,t);
    sweEta =sb_mix(sweEta,sf.w,wF);
    sweH =sb_mix(sweH,sf.x,wF);
  }
  gMacro =d;
  info =sb_vec4(crestFoam,sweH,sb_max(wIn,wF),chopW);
  return sweEta + eta;
}

__device__ float2 clampLen(GraphicsContext& ctx,float2 g,float m){ float l = length(g); return l > m ? g * (m / l) : g; }




__device__ float2 sweGradient(GraphicsContext& ctx,float2 xz,float e0,float4& far){
  float2 g = sb_vec2(0.0f);
  far =sb_vec4(0.0f);
  float wIn = sweInside(ctx,xz);
  if (wIn > 0.0f) {
    float2 uv = sweUV(ctx,xz); float2 e = ctx.uSweTexel * e0;
    float wE = __sb_textureLod(4,uv + sb_vec2(e.x,0.0f),0.0f).w, wW = __sb_textureLod(4,uv - sb_vec2(e.x,0.0f),0.0f).w;
    float wN = __sb_textureLod(4,uv + sb_vec2(0.0f,e.y),0.0f).w, wS = __sb_textureLod(4,uv - sb_vec2(0.0f,e.y),0.0f).w;
    g =wIn * sb_vec2(wE - wW,wN - wS)/ (2.0f* e * sb_sw_zw(ctx.uSweDom));
  }
  float wF = swashFarWeight(ctx,xz);
  if (wF > 0.0f) {

    float h = 0.03f;
    float3 w = sb_vec3(0.0f);
    for (int k = 0; k < 3 + sb_min(ctx.uEvtCount,0); k++) {
      float2 p = xz + (k == 1 ? sb_vec2(h,0.0f): (k == 2 ? sb_vec2(0.0f,h): sb_vec2(0.0f)));
      float4 fk = swashFar(ctx,p,ctx.uTime);
      if (k == 0) { w.x=fk.w; far =fk; } else if (k == 1) w.y=fk.w; else w.z=fk.w;
    }
    g =sb_mix(g,sb_vec2(w.y- w.x,w.z- w.x)/ h,wF);
  }
  return g;
}




__device__ float waterHeight(GraphicsContext& ctx,float2 xz,float t,float lod,float2& grad,float4& info){
  float2 gm, gc; float3 ch; float paw;
  float y = waterParts(ctx,xz,t,lod,gm,ch,gc,info,paw);
  grad =gm + gc;
  return y + ch.y;
}

























__device__ float4 crestGeometry(GraphicsContext& ctx,float2 xz,float t,float etaR,float3& aux,float3& faceNormal){
  aux =sb_vec3(0.0f,1.0f,0.0f); faceNormal=sb_vec3(0.0f,1.0f,0.0f);

  int best = (0-(1)); float bestD = 2.5f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f|| t < b.tb- 9.0f|| t > b.ti+ 0.6f) continue;
    float dC = sb_abs(xz.y- brkCrestZ(ctx,b,t));
    if (dC < bestD) { bestD =dC; best =i; }
  }
  if (best < 0) return sb_vec4(0.0f);
  Brk b = brkAt(ctx,best,xz.x);
  float tn = brkTn(ctx,b,t);
  if (tn < (0-(6.0f))|| tn > 0.85f) return sb_vec4(0.0f);
  BrkStage g = brkStage(ctx,tn);
  float2 A = brkApex(ctx,b,g,tn);

  float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str;
  float2 sh0 = brkShape(ctx,g,(xz.y- A.x) / b.s);
  float eta0 = sh0.x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y));
  aux.z=sb_max((0-(sh0.y))* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y)),0.0f);

  float fd = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  float ya = g.ya* b.s* amp * fd, yt = g.yt* b.s* amp * fd;
  eta0 =sb_clamp(etaR,yt,ya);
  float sFace = sb_clamp((ya - eta0) / sb_max(ya - yt,0.05f),0.0f,1.2f);



  if(g.st>.12f){
  float xiFace=brkFrontXi(ctx,g,sb_clamp(1.0f-sFace,.001f,.999f));
  float xiBack=(0-(g.lb))*acosh(sb_sqrt(sb_max(ya/sb_max(eta0,.0001f),1.00001f)));



  float shoulder=sb_max(.012f*b.s,sb_min(.065f*b.s,__sb_fwidth(xz.y)*1.5f));
  float dzSlope=sb_mix(brkShape(ctx,g,xiBack).y,brkShape(ctx,g,xiFace).y,sb_smoothstep((0-(shoulder)),shoulder,xz.y-A.x))*amp*fd;


  float zLeft=0.0f,zRight=0.0f;
  for(int n=0;n<2+sb_min(ctx.uEvtCount,0);n++){
    Brk nb=brkAt(ctx,best,xz.x+(float(n)-.5f)*.5f);
    float zc=nb.zI-b.c*(nb.ti-nb.D-b.ti);
    if(n==0)zLeft=zc;else zRight=zc;
  }
  float crestTilt=sb_clamp((zRight-zLeft)/.5f,(0-(.6f)),.6f);
  faceNormal=normalize(sb_vec3(crestTilt*dzSlope,1.0f,(0-(dzSlope))));
  }
  float hMax = eta0, occ = 0.0f;
  float rise = ctx.uSunDir.y/ sb_max((0-(ctx.uSunDir.z)),0.05f);
  for (int k = 1; k <= 8 + sb_min(ctx.uEvtCount,0); k++) {
    float dz = 0.04f* sb_pow(float(k),1.6f);
    float zk = xz.y- dz;
    float y = brkShape(ctx,g,(zk - A.x) / b.s).x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,zk));
    hMax =sb_max(hMax,y);
    occ =sb_max(occ,y - eta0 - rise * dz);
  }


  float support=1.0f-sb_smoothstep(1.45f,2.48f,bestD);
  aux.x=(hMax - eta0)*support;
  aux.z=aux.z*(support);



  float xi = (xz.y- A.x) / b.s;
  if (xz.y> (0-(9.0f))&& xz.y< 0.5f&& tn > (0-(1.6f))&& tn < 0.25f&& xi > (0-(0.3f))) {
    float ahead = (xi - g.lf) * b.s;
    float fa = sb_smoothstep((0-(0.1f)),0.1f,ahead);
    float live = sb_mix(1.0f- sb_smoothstep((0-(0.05f)),0.25f,tn),0.85f* (1.0f- sb_smoothstep((0-(0.45f)),(0-(0.15f)),tn)),fa);
    aux.y=1.0f- sb_smoothstep((0-(0.3f)),0.0f,xi)* sb_smoothstep(0.55f,0.1f,ahead)* sb_smoothstep((0-(1.6f)),(0-(0.9f)),tn)* live;
  }
  aux.y=sb_mix(1.0f,aux.y,support);
  return sb_vec4(sFace,g.st,occ*support,support);
}









__device__ float4 oceanSlopeLEAN(GraphicsContext& ctx,float2 xz,float paw,float w,float lodBias){
  float2 ex = __sb_dFdx(xz), ey = __sb_dFdy(xz);
  float lx = length(ex), ly = length(ey);
  float lmaj = sb_max(sb_max(lx,ly),1e-6f);
  float kb = sb_exp2(lodBias);
  if (lx < lmaj / 6.0f) ex =(lx > 1e-7f? ex / lx : sb_vec2(1.0f,0.0f)) * (lmaj / 6.0f);
  if (ly < lmaj / 6.0f) ey =(ly > 1e-7f? ey / ly : sb_vec2(0.0f,1.0f)) * (lmaj / 6.0f);
  ex =ex *(kb); ey =ey *(kb);



  float3 kc = sb_exp2(sb_sw_xyz(ctx.uSeaTune5));
  float4 s0 = __sb_textureGradArray(3,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),ctx.OCR0 * ex * kc.x/ ctx.uOceanL.x,ctx.OCR0 * ey * kc.x/ ctx.uOceanL.x);
  float4 s1 = __sb_textureGradArray(3,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),ctx.OCR1 * ex * kc.y/ ctx.uOceanL.y,ctx.OCR1 * ey * kc.y/ ctx.uOceanL.y);
  float4 s2 = __sb_textureGradArray(3,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),ctx.OCR2 * ex * kc.z/ ctx.uOceanL.z,ctx.OCR2 * ey * kc.z/ ctx.uOceanL.z);
  paw =sb_max(paw,0.0f);
  float3 a = sb_sw_xyz(ctx.uOceanAmp)* sb_vec3(oceanFarGain(ctx,xz),sb_sqrt(paw),paw)* sb_clamp(w,0.0f,1.0f);
  float2 m = (sb_sw_xy(s0)* ctx.OCR0) * a.x+ (sb_sw_xy(s1)* ctx.OCR1) * a.y+ (sb_sw_xy(s2)* ctx.OCR2) * a.z;
  float2 v = ocVar(ctx,sb_max(sb_sw_zw(s0)- sb_sw_xy(s0)* sb_sw_xy(s0),0.0f),ctx.OCC2.x)* a.x* a.x+ ocVar(ctx,sb_max(sb_sw_zw(s1)- sb_sw_xy(s1)* sb_sw_xy(s1),0.0f),ctx.OCC2.y)* a.y* a.y+ ocVar(ctx,sb_max(sb_sw_zw(s2)- sb_sw_xy(s2)* sb_sw_xy(s2),0.0f),ctx.OCC2.z)* a.z* a.z;
  return sb_vec4(m,v);
}








__device__ float facetNoise(GraphicsContext& ctx,float2 xz,float t){


  float2 rel = xz - sb_sw_xz(ctx.cameraPosition);
  float D = sb_max(length(rel),0.5f);
  float2 q0 = sb_vec2(sb_atan(rel.x,(0-(rel.y))),(0-(D ))- 0.9f* t);
  float pa = sb_max(sb_max(sb_abs(__sb_dFdx(q0.x)),sb_abs(__sb_dFdy(q0.x))),1e-6f);
  pa =sb_min(pa,0.01f);
  float pz = sb_max(sb_abs(__sb_dFdy(D)),sb_abs(__sb_dFdx(D)));
  float lz = sb_log2(sb_max(pz * ctx.uSeaTune6.z,1e-4f));
  float l0 = sb_floor(lz), f = lz - l0;
  float2 s0 = sb_vec2(pa * ctx.uSeaTune6.w,sb_exp2(l0)), s1 = sb_vec2(pa * ctx.uSeaTune6.w,sb_exp2(l0 + 1.0f));


  const SBMat2 FSH = sb_mat2(0.955f,(0-(0.296f)),0.296f,0.955f);
  float n0 = vnoise3(ctx,sb_vec3(FSH * (q0 / s0),t * 2.5f))- 0.5f;
  float n1 = vnoise3(ctx,sb_vec3(transpose(FSH)* (q0 / s1) + sb_vec2(17.0f,31.0f),t * 2.5f+ 7.3f))- 0.5f;
  return (n0 * (1.0f- f) + n1 * f) / sb_sqrt(sb_max((1.0f- f) * (1.0f- f) + f * f,1e-3f))* 5.5f;
}




__device__ float highCloudAmount(GraphicsContext& ctx,float3 d){
  float h = sb_max(d.y,0.09f);
  float2 q = sb_sw_xz(d)/ h;
  q =sb_mat2(0.92f,0.39f,(0-(0.39f)),0.92f)* q;
  float broad = vnoise(ctx,q * sb_vec2(0.38f,0.9f)+ 31.6f);
  float strands = vnoise(ctx,q * sb_vec2(0.7f,7.0f)+ sb_vec2(4.1f,broad * 2.0f));
  float fine = vnoise(ctx,q * sb_vec2(2.1f,21.0f)+ broad * 3.0f);
  float density = sb_smoothstep(0.57f,0.82f,broad)* sb_smoothstep(0.24f,0.76f,strands * 0.75f+ fine * 0.25f);
  return density * 0.095f* sb_smoothstep(0.08f,0.22f,d.y);
}

__device__ float3 highCloud(GraphicsContext& ctx,float3 d,float3 sky){
  float a = highCloudAmount(ctx,d);
  float3 cloud = sb_vec3(0.68f,0.73f,0.75f)+ ctx.uSunColor * 0.045f* sb_pow(sb_max(dot(d,ctx.uSunDir),0.0f),6.0f);
  return sb_mix(sky,cloud,a);
}


__device__ float skySunLobe(GraphicsContext& ctx,float g){ return 1.0f+ 4.05f* sb_exp((0-(g ))/ 0.7f); }


__device__ float3 skyAzimuthGain(GraphicsContext& ctx,float3 d){
  float sy = sb_clamp(d.y,0.0f,1.0f);
  float ch = sb_sqrt(sb_max(1.0f- sy * sy,0.0f));
  float2 hz = sb_sw_xz(d)/ sb_max(length(sb_sw_xz(d)),1e-5f);
  float3 dd = sb_vec3(hz.x* ch,sy,hz.y* ch);
  float g = acos(sb_clamp(dot(dd,ctx.uSunDir),(0-(1.0f)),1.0f));
  float g0 = acos(sb_clamp(sy * ctx.uSunDir.y- ch * ctx.uSunDir.z,(0-(1.0f)),1.0f));
  float F = skySunLobe(ctx,g)/ skySunLobe(ctx,g0);
  float fe = sb_clamp(degrees(asin(sy))/ 22.0f,0.0f,1.0f);
  return sb_pow(sb_vec3(F),sb_mix(sb_vec3(2.03f,1.0f,1.0f),sb_vec3(2.16f,1.26f,0.88f),fe));
}


__device__ float3 skyProfile(GraphicsContext& ctx,float elDeg){
  float e = sb_max(elDeg,0.0f);
  float3 c = sb_sw_yzw(ctx.uSkyLut[0]);
  for (int i = 1; i < 18; i++) {
    float4 a = ctx.uSkyLut[i - 1], b = ctx.uSkyLut[i];
    if (e >= a.x) c =sb_mix(sb_sw_yzw(a),sb_sw_yzw(b),sb_clamp((e - a.x) / (b.x- a.x),0.0f,1.0f));
  }
  return c;
}




__device__ float3 skyAureole(GraphicsContext& ctx,float g){
  return ctx.uSunColor * (1.6f* sb_exp((0-(g ))/ 0.011f)+ 0.30f* sb_exp((0-(g ))/ 0.035f)+ 0.05f* sb_exp((0-(g ))/ 0.12f)+ 0.012f* sb_exp((0-(g ))/ 0.35f));
}




__device__ float foamHoles(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float acc = 0.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float3 hh = hash32(ctx,i + g);
    float2 r = g + sb_sw_xy(hh)- f;
    float a = dot(r,t);
    float d = sb_sqrt(sb_max(dot(r,r)- k * a * a,0.0f))+ 0.9f* hh.z;
    acc =acc +(sb_exp((0-(d ))* 12.5f));
  }
  return (0-(0.08f))* sb_log(sb_max(acc,1e-30f));
}


__device__ float laceWall(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float f1 = 8.0f, f2 = 8.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float2 r = g + hash22(ctx,i + g)- f;
    float a = dot(r,t);
    float d = dot(r,r)- k * a * a;
    if (d < f1) { f2 =f1; f1 =d; } else if (d < f2) { f2 =d; }
  }
  return 0.5f* (sb_sqrt(f2)- sb_sqrt(f1));
}










__device__ FoamSet foamSet(GraphicsContext& ctx,float2 p,float seed,float fp,float2 t,float an,float anL,bool tearOn,bool netOn,float wmul){
  FoamSet s = sb_new_FoamSet(0.5f,0.0f,0.0f,0.0f,0.5f);

  float2 pw = p + ctx.uFoamLook2.w* sb_vec2(gnoise(ctx,p * 1.3f+ sb_vec2(seed,1.7f)),gnoise(ctx,p * 1.3f+ sb_vec2(4.1f- seed,(0-(2.3f)))));
  if (tearOn) {
    float2 q = pw * ctx.uFoamLook2.x;
    q =q +(0.6f* sb_vec2(gnoise(ctx,q * 0.7f+ sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 0.7f+ sb_vec2(5.2f- seed,0.0f))));
    float h = foamHoles(ctx,q + seed * 7.3f,t,1.0f- 1.0f/ (an * an))* sb_sqrt(an);

    float raw = h + 0.25f* gnoise(ctx,p * 1.7f+ sb_vec2(seed * 2.3f,(0-(seed))))- (0.78f+ 0.11f* (an - 1.0f));
    float ca = 0.57f+ 0.092f* (an - 1.0f);
    s.tear=sb_smoothstep((0-(ca)),ca,raw);
    float cw = 0.545f+ 0.1f* (an - 1.0f);
    s.wall=sb_smoothstep((0-(cw)),cw,h - (0.781f+ 0.112f* (an - 1.0f)));
  }
  if (netOn) {
    float2 q = pw * ctx.uFoamLook.x;
    q =q +(0.55f* sb_vec2(gnoise(ctx,q * 0.55f+ sb_vec2(seed,0.0f)),gnoise(ctx,q * 0.55f+ sb_vec2(5.2f- seed,0.0f)))+ 0.2f* sb_vec2(gnoise(ctx,q * 1.9f- sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 1.9f+ sb_vec2(seed + 1.7f,0.0f))));
    float lf = laceWall(ctx,q + seed * 13.1f,t,1.0f- 1.0f/ (anL * anL));


    float w0 = ctx.uFoamLook.y* wmul;
    float we = sb_max(w0,0.7f* fp * ctx.uFoamLook.x);
    float core = sb_exp((0-((lf * lf) ))/ (we * we))* (w0 / we);


    float seg = sb_smoothstep(0.34f,0.62f,0.5f+ 0.5f* gnoise(ctx,p * 13.0f+ seed * 2.9f));
    float pch = sb_smoothstep((0-(0.25f)),0.65f,gnoise(ctx,p * 2.1f+ sb_vec2(seed * 1.7f,3.1f))+ 0.5f* gnoise(ctx,p * 4.7f- sb_vec2(seed,0.0f)));
    s.net=core * seg * (0.5f+ 0.5f* sb_smoothstep((0-(0.6f)),0.6f,gnoise(ctx,p * 27.0f- seed * 4.1f))) * sb_mix(0.02f,1.55f,pch*pch);
  }


  float ga = 1.0f- sb_smoothstep(0.0015f,0.004f,fp);
  if (ga > 0.0f) s.grain=ga * (1.4f* (vnoise(ctx,p * 380.0f+ seed * 17.0f)- 0.5f) + 0.9f* (vnoise(ctx,p * 760.0f- seed * 9.0f)- 0.5f) * (1.0f- sb_smoothstep(0.0008f,0.002f,fp)));

  float gc = 1.0f- sb_smoothstep(0.006f,0.014f,fp);
  if (gc > 0.0f) s.clump=gc * (0.45f* gnoise(ctx,p * 19.0f- seed * 5.3f)+ 0.25f* gnoise(ctx,p * 43.0f+ seed * 3.1f));
  return s;
}






__device__ float lumpField(GraphicsContext& ctx,float2 p,float seed,float t){
  float n1 = gnoise(ctx,p * 4.5f+ seed), n2 = gnoise(ctx,p * 10.0f+ sb_vec2(0.9f* t,(0-(0.6f))* t)- seed);
  float fold = 1.0f- sb_abs(gnoise(ctx,p * sb_vec2(6.0f,4.0f)+ sb_vec2((0-(0.5f))* t,0.7f* t)+ seed * 0.3f));
  return 0.5f+ 0.5f* (0.6f* n1 + 0.4f* n2) - 0.35f* fold * fold * fold * fold;
}

__device__ float blanketLumps(GraphicsContext& ctx,float2 xz,float2 suv,float t,float wf,float2 farVel){
  const float T = 0.5f;
  float2 e = 3.0f* ctx.uSweTexel;
  float2 vel = 0.4f* sb_sw_yz(__sb_textureLod(4,suv,0.0f))+ 0.15f* (sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(0.0f,e.y),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(0.0f,e.y),0.0f)));
  vel =sb_mix(vel,farVel,wf);
  float2 d = vel * T;
  d =d *(sb_min(1.0f,0.4f/ sb_max(length(d),1e-4f)));
  float ca = t / T, cb = ca + 0.5f;
  float fa = sb_fract(ca), fb = sb_fract(cb);
  float w = 1.0f- sb_abs(2.0f* fa - 1.0f);
  float la = lumpField(ctx,xz - d * fa,sb_floor(ca)* 1.618f,t), lb = lumpField(ctx,xz - d * fb,sb_floor(cb)* 2.414f+ 0.5f,t);
  return 0.5f+ (w * (la - 0.5f) + (1.0f- w) * (lb - 0.5f)) / sb_sqrt(w * w + (1.0f- w) * (1.0f- w));
}



__device__ float4 surfaceFoam(GraphicsContext& ctx,float3 P,float t,float crestFoam,float2& flowUV,float& turb){
  float2 suv = sweUV(ctx,sb_sw_xz(P));
  float wIn = sweInside(ctx,sb_sw_xz(P));
  float4 fm = __sb_textureLod(5,suv,0.0f)* wIn;
  float4 lo = __sb_textureLod(6,suv,0.0f)* wIn;
  float4 handoffDelta = sb_vec4(0.0f);
  float4 svw = __sb_textureLod(4,suv,0.0f);


  float hE = __sb_textureLod(4,suv + sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x, hW = __sb_textureLod(4,suv - sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x;
  float hw = (2.0f* svw.x+ hE + hW) * 0.25f;
  float hMin = sb_min(svw.x,sb_min(hE,hW));
  float2 fvel = sb_sw_yz(svw);

  float wf = swashFarWeight(ctx,sb_sw_xz(P));
  float2 farVel = sb_vec2(0.0f);
  if (wf > 0.0f) {

    float2 fuv = swashFarUV(ctx,sb_sw_xz(P));
    float4 fV = __sb_textureLod(8,fuv,0.0f);
    float fD = __sb_textureLod(10,fuv,0.0f).z;
    fm =sb_mix(fm,__sb_textureLod(9,fuv,0.0f),wf);
    handoffDelta =sb_vec4(0.0f,(0-(fD)),0.0f,(0-(fD)))- lo;
    lo =lo +(wf * handoffDelta);
    hw =sb_mix(hw,fV.x,wf);
    farVel =sb_sw_yz(fV);
    fvel =sb_mix(fvel,farVel,wf);
  }
  turb =fm.z;

  float phA = ctx.uLacePhase.x;
  float wa = sb_smoothstep(0.0f,0.22f,phA)* (1.0f- sb_smoothstep(0.5f,0.72f,phA));
  float wb = 1.0f- wa;
  float2 pa = sb_sw_xz(P)+ sb_sw_xy(lo), pb = sb_sw_xz(P)+ sb_sw_zw(lo);


  flowUV =sb_sw_xz(P)+ 0.3f* (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo));


  float3 dPx = __sb_dFdx(P), dPy = __sb_dFdy(P);
  float fp = sb_max(sb_max(length(dPx),length(dPy)),1.0e-4f);
  float ny = sb_abs(normalize(cross(dPx,dPy)).y);
  float fpXZ = sb_max(length(sb_sw_xz(dPx))+ length(sb_sw_xz(dPy)),1.0e-5f);



  float4 frameDx = __sb_dFdx(lo)- handoffDelta * __sb_dFdx(wf);
  float4 frameDy = __sb_dFdy(lo)- handoffDelta * __sb_dFdy(wf);
  float strA = (length(sb_sw_xy(frameDx))+ length(sb_sw_xy(frameDy))) / fpXZ;
  float strB = (length(sb_sw_zw(frameDx))+ length(sb_sw_zw(frameDy))) / fpXZ;

  float cf = crestFoam * sb_smoothstep(0.35f,0.75f,ny)* sb_smoothstep(0.2f,0.8f,0.5f+ 0.5f* gnoise(ctx,sb_sw_xz(P)* sb_vec2(7.0f,11.0f)+ sb_vec2(0.0f,(0-(t ))* 3.0f))+ crestFoam * 0.5f);
  if (fm.x< 0.01f&& fm.y< 0.01f) return sb_vec4(cf,cf > 0.0f? 0.85f: 0.0f,0.0f,cf);

  float R = fm.x, G = sb_clamp(fm.y,0.0f,1.5f);


  float spd = length(fvel);
  float2 dir = spd > 1.0e-3f? fvel / spd : sb_vec2(0.0f,1.0f);

  float fast = sb_smoothstep(0.3f,1.2f,spd)* sb_smoothstep((0-(0.2f)),0.4f,fvel.y/ sb_max(spd,0.1f));

  float an = sb_mix(1.0f,ctx.uFoamLook2.y,fast), anL = sb_mix(1.0f,1.65f,sb_smoothstep(.25f,1.4f,spd));
  float amtG = 1.0f- sb_exp((0-(G ))/ 0.9f);


  float flatW = sb_smoothstep(0.5f,0.8f,ny);

  float keepA = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strA));
  float keepB = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strB));



  float edgeFade = sb_smoothstep(0.002f,0.009f,hw)* sb_smoothstep(0.0005f,0.004f,hMin + wf);
  float ribVis = 1.0f- sb_smoothstep(0.022f,0.12f,fp);

  float netVis = 1.0f- sb_smoothstep(0.16f,0.60f,fp * ctx.uFoamLook.x);


  float tearVis = ribVis * (1.0f- sb_smoothstep(1.05f,1.4f,R));
  bool torn = tearVis > 0.0f;
  bool laced = G > 0.02f&& R < 0.7f;
  bool netOn = laced && R < 0.45f&& netVis > 0.0f;
  float thin = 1.0f- sb_smoothstep(0.3f,1.0f,R);

  float tearAcc = 0.0f, netAcc = 0.0f, grainAcc = 0.0f, clumpAcc = 0.0f, wallAcc = 0.0f;
  for (int k = 0; k < 2 + sb_min(ctx.uEvtCount,0); k++) {
    float wk = k == 0 ? wa : wb;
    if (wk <= 0.0f) continue;
    FoamSet S = foamSet(ctx,k == 0 ? pa : pb,k == 0 ? ctx.uLaceSeeds.x: ctx.uLaceSeeds.y+ 3.3f,fp,dir,an,anL,torn,netOn,1.0f+ 2.5f* amtG * amtG);
    float kk = wk * (k == 0 ? keepA : keepB);
    tearAcc =tearAcc +(kk * (S.tear- 0.5f));
    wallAcc =wallAcc +(kk * (S.wall- 0.5f));
    netAcc =netAcc +(kk * S.net);


    grainAcc =grainAcc +(kk * S.grain);
    clumpAcc =clumpAcc +(kk * S.clump);
  }
  float ka = wa * keepA, kb = wb * keepB;
  float nrm = 1.0f/ sb_max(sb_sqrt(wa * wa + wb * wb),1e-3f);
  float clump = clumpAcc * nrm;


  float rib = 0.5f+ tearAcc * nrm * tearVis + 0.09f* clump;
  float wall = 0.5f+ wallAcc * nrm * tearVis + 0.08f* clump;
  float net = netAcc;
  float grain = grainAcc * nrm * ctx.uFoamLook2.z;
  float lump = R > 0.3f? sb_mix(0.5f,blanketLumps(ctx,sb_sw_xz(P),suv,t,wf,farVel),flatW*sb_smoothstep(.3f,.55f,R)): 0.5f;
  float sup = ka + kb;
  float strVis = sup * ribVis;




  float cB = (1.0f- sb_exp((0-(sb_pow(R / 0.42f,1.4f))))) * sb_smoothstep(0.02f,0.1f,R);


  float ew = sb_mix(0.16f,0.36f,sb_smoothstep(0.3f,0.8f,cB));
  float th = cB >= ew ? 1.0f- cB : 1.0f+ ew - 2.0f* sb_sqrt(ew * cB);


  float rbHi = sb_clamp(1.0f- 2.0f* (1.0f- cB) * (1.0f- rib),0.0f,1.0f);
  float rbLo = sb_clamp((rib - th) / (2.0f* ew) + 0.5f,0.0f,1.0f);
  rbLo =rbLo * rbLo * (3.0f- 2.0f* rbLo);


  float rb = sb_mix(cB * (1.0f- 0.65f* ribVis * (1.0f- sup)),sb_mix(rbLo,rbHi,sb_smoothstep(0.6f,0.8f,cB)),strVis);


  float pocket = (1.0f- sb_smoothstep(0.0f,0.3f,rib)) * sb_smoothstep(0.5f,1.2f,R)* strVis;


  float aR = sb_mix(0.7f,0.94f,sb_smoothstep(0.3f,1.2f,R))* (1.0f- 0.45f* pocket);
  float haze = 0.12f* sb_smoothstep(0.02f,0.5f,R + 0.12f* G)* thin;

  float blanket = rb * aR * sb_mix(sb_mix(0.62f,0.85f,sb_smoothstep(0.5f,0.9f,cB)),1.0f,sb_smoothstep(th,th + 0.45f,rib))* (1.0f+ (0.8f* grain + 0.3f* clump) * thin);
  blanket =sb_clamp(blanket + haze * (1.0f- blanket),0.0f,1.0f)* ctx.uFoamLook.w;



  float lace = 0.0f, laceD = 0.25f;
  if (laced) {

    float amt = amtG;


    float cL = 0.07f* amt * amt;
    float ewL = 0.2f;
    float thL = cL >= ewL ? 1.0f- cL : 1.0f+ ewL - 2.0f* sb_sqrt(ewL * cL);
    float rl = sb_clamp((wall - thL) / (2.0f* ewL) + 0.5f,0.0f,1.0f);
    float ribL = sb_mix(cL * (1.0f- 0.65f* ribVis * (1.0f- sup)),rl * rl * (3.0f- 2.0f* rl),strVis);

    float netMean = 0.09f* (1.0f+ 2.5f* amt * amt);
    float netL = sb_mix(netMean * (1.0f- 0.65f* netVis * (1.0f- sup)),net,sup * netVis)* sb_min(1.3f* amt,1.0f)* sb_smoothstep(0.45f,0.1f,R);

    float sL = 0.8f* sb_clamp(ribL * (1.0f+ grain + 0.35f* clump),0.0f,1.0f);
    float nL = sb_mix(ctx.uFoamLook.z,0.85f,sb_smoothstep(0.45f,0.8f,amt))* sb_clamp(netL * (1.0f+ grain + 0.3f* clump),0.0f,1.0f);
    lace =sb_max(sL,nL)* sb_smoothstep(0.02f,0.12f,G)* (1.0f- sb_smoothstep(0.3f,0.7f,R));
    laceD =sb_mix(sb_mix(0.25f,0.5f,sb_smoothstep(0.45f,0.8f,amt)),0.6f,sL / sb_max(sL + nL,1e-3f));
  }


  float milkyBack = sb_smoothstep(0.25f,0.55f,fm.w)* sb_smoothstep((0-(0.15f)),(0-(0.5f)),fvel.y)* (1.0f- sb_smoothstep(0.2f,0.5f,R)) * (ka + kb);
  milkyBack =milkyBack *(sb_smoothstep(0.0f,0.025f,milkyBack));
  if (milkyBack > 0.0f&& fp < 0.008f) {
    float2 rq = (sb_sw_xz(P)+ (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo))) / 0.07f;
    float3 wr = worley(ctx,rq + sb_vec2(ctx.uLaceSeeds.x* 3.1f,0.0f));
    float rr = sb_mix(0.1f,0.17f,sb_fract(wr.z* 7.31f));
    float rw = sb_max(0.035f,0.6f* fp / 0.07f);
    float ring = sb_exp((0-(sb_pow((wr.x- rr) / rw,2.0f))))* sb_step(wr.z,0.22f)* sb_min(1.0f,0.035f/ rw);
    lace =sb_max(lace,0.55f* ring * milkyBack * (1.0f- sb_smoothstep(0.005f,0.008f,fp)));
  }






  float dBl = sb_mix(0.6f,0.95f,sb_smoothstep(0.3f,1.2f,R))+ 1.1f* (lump - 0.5f) * (1.0f- thin) + (0.35f* grain + 0.1f* clump) * (1.0f- thin)
            - 0.3f* (1.0f- rb) * (1.0f- thin) - 0.35f* pocket;
  dBl =sb_mix(sb_clamp(dBl,0.0f,1.0f),sb_mix(0.3f,0.6f,rb)* (1.0f+ 0.5f* grain + 0.3f* clump),thin);
  float wBl = blanket * edgeFade, wLa = lace * edgeFade * (1.0f- wBl);
  float dense = sb_clamp((dBl * wBl + laceD * wLa + 0.85f* cf) / sb_max(wBl + wLa + cf,1e-3f),0.0f,1.0f);

  float cov = 1.0f- (1.0f- blanket * edgeFade) * (1.0f- lace * edgeFade) * (1.0f- cf);
  return sb_vec4(sb_clamp(cov,0.0f,1.0f),dense,lace * edgeFade,cf);
}


__device__ SBMat2 rot2(GraphicsContext& ctx,float a){ float c = sb_cos(a), s = sb_sin(a); return sb_mat2(c,(0-(s)),s,c); }



__device__ float2 rippleGrad(GraphicsContext& ctx,float2 p,float t,float dist,float strength){
  float2 g = sb_vec2(0.0f);
  float px = sb_max(dist * ctx.uPxAng,0.5f* sb_max(length(__sb_fwidth(p)),1e-5f));
  float L = 1.6f;
  for (int i = 0; i < 6 + sb_min(ctx.uEvtCount,0); i++) {
    float keep = sb_smoothstep(px * 3.0f,px * 9.0f,L);
    if (keep > 0.0f) {
      float2 q = rot2(ctx,float(i)* 1.93f)* p / L;
      float c = sb_sqrt(9.81f* L / 6.2831f);
      q =q +(rot2(ctx,float(i)* 1.93f)* ctx.uWind * t * c / L * 0.7f);
      float3 n = gnoised(ctx,q + float(i)* 17.3f);
      g =g +(sb_sw_yz(n)* 0.075f* keep);
    }
    L =L *(0.48f);
  }
  return g * strength;
}










__device__ float3 filmRipple(GraphicsContext& ctx,float2 p,float t,float px,float2& ridgeDir){



  float2 d0=normalize(sb_vec2(.18f,1.f)),d1=normalize(sb_vec2((0-(.43f)),.90f)),d2=normalize(sb_vec2(.94f,.34f));
  float warp=.42f*gnoise(ctx,p*1.7f);
  float a=dot(p,d0)*44.9f-t*14.8f+warp;
  float b=dot(p,d1)*89.8f-t*27.1f+.6f*gnoise(ctx,p*2.3f+7.1f);
  float c=dot(p,d2)*157.1f-t*43.7f-warp;
  float2 g=d0*(.030f*sb_sin(a))*(1.f-sb_smoothstep(.006f,.024f,px))
    +d1*(.018f*sb_sin(b))*(1.f-sb_smoothstep(.003f,.012f,px))
    +d2*(.009f*sb_sin(c))*(1.f-sb_smoothstep(.0018f,.007f,px));
  ridgeDir=d0;


  return sb_vec3(g,0.f);
}



__device__ float submergedAt(GraphicsContext& ctx,float3 p){
  if(ctx.uUnderwaterOn<.5f)return 0.f;
  float h=__sb_texelFetch(12,sb_ivec2(float(0),float(0)),0).x;
  float2 slope=sb_vec2(__sb_texelFetch(12,sb_ivec2(float(2),float(0)),0).x-__sb_texelFetch(12,sb_ivec2(float(1),float(0)),0).x,__sb_texelFetch(12,sb_ivec2(float(4),float(0)),0).x-__sb_texelFetch(12,sb_ivec2(float(3),float(0)),0).x)/.64f;
  return sb_smoothstep((0-(.018f)),.018f,h+dot(slope,sb_sw_xz(p)-ctx.uProbeOrigin)-p.y);
}

__device__ float3 waterTravel(GraphicsContext& ctx,float3 radiance,float distanceM){
  float3 tr=sb_exp((0-(ctx.UW_EXTINCTION))*sb_max(distanceM,0.f));
  return radiance*tr+ctx.UW_SCATTER*(1.f-tr);
}


__device__ float2 causticSlope(GraphicsContext& ctx,float2 p,float lod){
  float2 a=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR0*p/ctx.uOceanL.x,0.0f),lod))*ctx.OCR0;
  float2 b=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR1*p/ctx.uOceanL.y,1.0f),sb_max(lod-1.f,0.f)))*ctx.OCR1;
  float2 c=sb_sw_xy(__sb_textureLodArray(3,sb_vec3(ctx.OCR2*p/ctx.uOceanL.z,2.0f),sb_max(lod+sb_log2(ctx.uOceanL.x/ctx.uOceanL.z),0.f)))*ctx.OCR2;
  return a*ctx.uOceanAmp.x*oceanFarGain(ctx,p)+b*ctx.uOceanAmp.y*.7f+c*ctx.uOceanAmp.z*.55f;
}

__device__ float seabedCaustic(GraphicsContext& ctx,float3 p,float depth){
  if(depth<.025f||depth>12.f)return 1.f;
  float footprint=sb_max(length(__sb_dFdx(sb_sw_xz(p))),length(__sb_dFdy(sb_sw_xz(p))));
  float e=sb_max(.025f+depth*.012f,footprint*1.5f);
  float lod=sb_log2(e*256.f/ctx.uOceanL.x);
  float2 q=sb_sw_xz(p)-sb_sw_xz(ctx.uSunDir)*depth/sb_max(ctx.uSunDir.y,.4f)/1.333f;
  q=q-(causticSlope(ctx,q,lod)*depth*.25f);
  float2 dx=(causticSlope(ctx,q+sb_vec2(e,float(0)),lod)-causticSlope(ctx,q-sb_vec2(e,float(0)),lod))/(2.f*e);
  float2 dz=(causticSlope(ctx,q+sb_vec2(float(0),e),lod)-causticSlope(ctx,q-sb_vec2(float(0),e),lod))/(2.f*e);
  float k=sb_min(depth,5.f)*.25f;
  float jac=(1.f-k*dx.x)*(1.f-k*dz.y)-k*k*dx.y*dz.x;
  float width=.22f+depth*.015f+footprint*3.f;
  float focus=.97f+.72f*sb_exp((0-(jac))*jac/(width*width));
  float strength=sb_smoothstep(.025f,.16f,depth)*sb_exp((0-(depth))*.13f)*(1.f-sb_smoothstep(.08f,.35f,footprint));
  return sb_mix(1.f,focus,strength*.72f);
}

__device__ float undersideFresnel(GraphicsContext& ctx,float ci){
  ci=sb_clamp(ci,.0001f,1.f);
  float st2=1.333f*1.333f*(1.f-ci*ci);
  float ct=sb_sqrt(sb_max(1.f-st2,0.f));
  float rs=(1.333f*ci-ct)/sb_max(1.333f*ci+ct,.0001f);
  float rp=(ci-1.333f*ct)/sb_max(ci+1.333f*ct,.0001f);
  return st2>=1.f?1.f:.5f*(rs*rs+rp*rp);
}

__device__ float3 reflectedBed(GraphicsContext& ctx,float3 p,float3 ray){
  float travel=sb_clamp((bedHeight(ctx,sb_sw_xz(p))-p.y)/sb_min(ray.y,(0-(.04f))),0.f,35.f);
  for(int i=0;i<3;i++){
    float3 q=p+ray*travel;
    travel=sb_clamp((bedHeight(ctx,sb_sw_xz(q))-p.y)/sb_min(ray.y,(0-(.04f))),0.f,35.f);
  }
  float3 q=p+ray*travel;
  float3 photo=sb_sw_xyz(__sb_texture(15,sb_sw_xz(q)*.5f));
  float grain=sb_clamp(dot(photo,sb_vec3(.2126f,.7152f,.0722f))/.165f,.35f,2.2f);
  float3 alb=sb_vec3(.63f,.555f,.423f)*sb_vec3(.51f,.48f,.43f)*sb_pow(grain,.25f);
  float h=sb_max((0-(q.y)),0.f);
  float3 bed=alb*(ctx.uSunColor*sb_max(ctx.uSunDir.y,0.f)/3.14159265f*sb_exp((0-(ctx.UW_EXTINCTION))*h/sb_max(ctx.uSunDir.y,.3f))*seabedCaustic(ctx,q,h)+ctx.uSkyAmb*.75f);
  return waterTravel(ctx,bed,travel);
}

__device__ void main(GraphicsContext& ctx){
  float3 P=ctx.vWorld,V=normalize(ctx.cameraPosition-P),ray=(0-(V));
  float mask=submergedAt(ctx,ctx.cameraPosition+ray*ctx.uNear);
  float waterColumn=P.y-hydraulicBedHeight(ctx,sb_sw_xz(P));
  if(mask<.02f||waterColumn<.003f){ctx.discarded=true;return;}float3 macro=normalize(ctx.vNrm);



  if(ctx.vCrest.x>.001f){
    float3 aux,faceNormal;
    float4 crest=crestGeometry(ctx,sb_sw_xy(ctx.vXZ0),ctx.uTime,ctx.vCrest.w,aux,faceNormal);
    float face=sb_smoothstep(.05f,.18f,ctx.vCrest.w)*sb_smoothstep(.12f,.7f,crest.y)*sb_smoothstep(.04f,.20f,sb_abs(faceNormal.z))*crest.w;
    macro=normalize(sb_mix(macro,faceNormal,face));
  }




  float faceRipple=1.f-sb_smoothstep(.38f,.90f,macro.y);


  float shoaling=sb_smoothstep((0-(10.f)),(0-(5.f)),ctx.vXZ0.y)*(1.f-sb_smoothstep((0-(.5f)),1.f,ctx.vXZ0.y));
  float rippleKeep=sb_max(faceRipple,shoaling);
  float rippleWeight=sb_mix(ctx.vInfo.w,sb_max(ctx.vInfo.w,.82f*sb_smoothstep(.025f,.28f,waterColumn)),rippleKeep);


  float2 rippleUV=sb_sw_xy(ctx.vXZ0)-sb_vec2(0.f,P.y*macro.z*faceRipple);
  float4 lean=oceanSlopeLEAN(ctx,rippleUV,ctx.vXZ0.z,rippleWeight,0.f);

  float invUp=1.f/sb_max(1.f+macro.y,.001f);
  float3 tangentX=sb_vec3(1.f-macro.x*macro.x*invUp,(0-(macro.x)),(0-(macro.x))*macro.z*invUp);
  float3 tangentZ=sb_vec3((0-(macro.x))*macro.z*invUp,(0-(macro.z)),1.f-macro.z*macro.z*invUp);
  float3 flatNormal=normalize(sb_vec3((0-(macro.x))/sb_max(macro.y,.012f)+lean.x,(0-(1.f)),(0-(macro.z))/sb_max(macro.y,.012f)+lean.y));
  float3 faceNormal=normalize((0-(macro))+tangentX*lean.x+tangentZ*lean.y);
  float3 N=normalize(sb_mix(flatNormal,faceNormal,faceRipple));
  if(dot(N,V)<0.f)N=(0-(N));
  float ci=sb_clamp(dot(N,V),.0001f,1.f);



  float spread=sb_clamp(.65f*__sb_fwidth(ci)+.2f*sb_sqrt(sb_max(lean.z+lean.w,0.f)),.001f,.035f);
  float F=.25f*undersideFresnel(ctx,ci-spread)+.5f*undersideFresnel(ctx,ci)+.25f*undersideFresnel(ctx,ci+spread);
  float3 transmitted=sb_vec3(0.f);
  if(F<.99999f){


    float critical=sb_sqrt(1.f-1.f/(1.333f*1.333f));
    float ct=sb_max(ci,critical+sb_max(.0001f,spread*.3f));
    float3 tangent=N-V*ci;
    tangent=tangent/(sb_max(length(tangent),.00001f));
    float3 Nt=ct*V+tangent*sb_sqrt(sb_max(1.f-ct*ct,0.f));
    float3 d=normalize(refract(ray,Nt,1.333f));
    float el=degrees(asin(sb_clamp(d.y,(0-(1.f)),1.f)));
    float gamma=acos(sb_clamp(dot(d,ctx.uSunDir),(0-(1.f)),1.f));
    transmitted=highCloud(ctx,d,skyProfile(ctx,el)*skyAzimuthGain(ctx,d))+skyAureole(ctx,gamma);
    float disc=1.f-sb_smoothstep(.00465f-sb_max(__sb_fwidth(gamma),.001f),.00465f+sb_max(__sb_fwidth(gamma),.001f),gamma);
    transmitted=transmitted+(ctx.uSunColor*180.f*disc);



    if(d.y>0.f&&d.y<.25f){
      float travel=40.f,z=1.f,viewDepth=0.f;float2 uv=sb_vec2(0.f);
      float3 hit=sb_vec3(0.f);float clipW=0.f;
      for(int i=0;i<3;i++){
        float3 point=P+d*travel;
        float4 clip=ctx.projectionMatrix*ctx.viewMatrix*sb_vec4(point,1.f);
        clipW=clip.w;uv=sb_sw_xy(clip)/sb_max(clip.w,.001f)*.5f+.5f;
        z=__sb_textureLod(14,sb_clamp(uv,.001f,.999f),0.f).x;
        viewDepth=ctx.uNear*ctx.uFar/sb_max(ctx.uFar-z*(ctx.uFar-ctx.uNear),.0001f);
        hit=ctx.cameraPosition+(point-ctx.cameraPosition)*(viewDepth/sb_max(clip.w,.001f));
        travel=sb_clamp(dot(hit-P,d),4.f,140.f);
      }
      float valid=sb_smoothstep(.008f,.035f,uv.x)*(1.f-sb_smoothstep(.965f,.992f,uv.x))
        *sb_smoothstep(.008f,.035f,uv.y)*(1.f-sb_smoothstep(.965f,.992f,uv.y))*sb_step(.01f,clipW);
      float along=dot(hit-P,d),miss=length(hit-P-d*along);
      float consistent=1.f-sb_smoothstep(.10f,.65f,miss);
      float aboveWater=sb_smoothstep(.08f,.35f,hit.y);
      float weight=valid*consistent*aboveWater*sb_step(.5f,along)*sb_step(z,.99999f)*sb_smoothstep(0.f,.018f,d.y)*(1.f-sb_smoothstep(.16f,.25f,d.y));
      transmitted=sb_mix(transmitted,sb_sw_xyz(__sb_textureLod(13,sb_clamp(uv,.001f,.999f),0.f)),weight);
    }
  }
  float3 R=reflect(ray,N);


  float3 reflected=reflectedBed(ctx,P,normalize(sb_vec3(R.x,sb_min(R.y,(0-(.001f))),R.z)));
  float3 bounced=waterTravel(ctx,ctx.uSkyAmb*.65f,12.f);
  reflected=sb_mix(reflected,bounced,sb_smoothstep((0-(.06f)),.08f,R.y));
  float3 col=sb_mix(transmitted,reflected,F);
  float2 flowUV;float turb;
  float foam=surfaceFoam(ctx,P,ctx.uTime,ctx.vInfo.x,flowUV,turb).x;
  foam=sb_clamp(foam*.9f,0.f,.96f);
  float3 whitewater=(ctx.uSkyAmb*.42f+ctx.uSunColor*.075f)*sb_vec3(.76f,.88f,.83f);
  col=sb_mix(col,whitewater,foam);
  ctx.gl_FragColor=sb_vec4(col,1.f);
}

__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.WATER_SIGMA_A=sb_vec3(0.46f,0.075f,0.062f);
ctx.WATER_SIGMA_S=sb_vec3(0.020f,0.030f,0.032f);
ctx.OCR0=sb_mat2(0.9563048f,0.2923717f,(0-(0.2923717f)),0.9563048f);
ctx.OCR1=sb_mat2(0.8571673f,(0-(0.5150381f)),0.5150381f,0.8571673f);
ctx.OCR2=sb_mat2(0.7313537f,0.6819984f,(0-(0.6819984f)),0.7313537f);
ctx.OCC2=sb_vec3(0.9145188f,0.7347358f,0.5348782f);
ctx.UW_EXTINCTION=sb_vec3(.245f,.066f,.046f);
ctx.UW_SCATTER=sb_vec3(.022f,.155f,.185f);
main(ctx);output[0]=ctx;}

#endif

