__device__ float brkStairX(GraphicsContext& ctx,float x,float seed){
  float s = x / 0.45f+ sb_fract(seed * 3.0f+ 0.485f);
  return x + 0.25f* 0.45f* (sb_floor(s)+ sb_smoothstep(0.45f,1.0f,sb_fract(s))- s + 0.175f);
