struct GraphicsContext {
float3 UW_EXTINCTION;
float3 UW_SCATTER;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float2 uProbeOrigin;
float uUnderwaterOn;
float2 vUv;
float3 vP;
float vLife;
float vSeed;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant UW_EXTINCTION is initialized in each invocation.
// Constant UW_SCATTER is initialized in each invocation.
__device__ float submergedAt(GraphicsContext& ctx,float3 p){
  if(ctx.uUnderwaterOn<.5f)return 0.f;
  float h=__sb_texelFetch(0,sb_ivec2(float(0),float(0)),0).x;
  float2 slope=sb_vec2(__sb_texelFetch(0,sb_ivec2(float(2),float(0)),0).x-__sb_texelFetch(0,sb_ivec2(float(1),float(0)),0).x,__sb_texelFetch(0,sb_ivec2(float(4),float(0)),0).x-__sb_texelFetch(0,sb_ivec2(float(3),float(0)),0).x)/.64f;
  return sb_smoothstep((0-(.018f)),.018f,h+dot(slope,sb_sw_xz(p)-ctx.uProbeOrigin)-p.y);
}

__device__ float3 waterTravel(GraphicsContext& ctx,float3 radiance,float distanceM){
  float3 tr=sb_exp((0-(ctx.UW_EXTINCTION))*sb_max(distanceM,0.f));
  return radiance*tr+ctx.UW_SCATTER*(1.f-tr);
}


__device__ void main(GraphicsContext& ctx){
        float2 q=ctx.vUv*2.f-1.f;float r2=dot(q,q),r=sb_sqrt(r2),aa=sb_max(__sb_fwidth(r),.03f);
        float edge=1.f-sb_smoothstep(1.f-aa,1.f+aa,r);
        if(edge<.001f){ctx.discarded=true;return;}float nz=sb_sqrt(sb_max(1.f-r2,0.f));
        float fresnel=.0204f+.9796f*sb_pow(1.f-nz,5.f);
        float crescent=sb_pow(sb_max(dot(normalize(sb_vec3(q,nz)),normalize(sb_vec3((0-(.4f)),.75f,.5f))),0.f),22.f);
        float glint=sb_exp((0-(dot(q-sb_vec2((0-(.27f)),.48f),q-sb_vec2((0-(.27f)),.48f))))*65.f);
        float wet=submergedAt(ctx,ctx.cameraPosition+normalize(ctx.vP-ctx.cameraPosition)*.04f);
        float alpha=(.035f+.35f*fresnel+.38f*crescent+.36f*glint)*edge*ctx.vLife*wet;
        float3 col=sb_mix(sb_vec3(.10f,.24f,.25f),sb_vec3(.79f,.93f,.91f),sb_clamp(crescent+glint+fresnel*.45f,0.f,1.f));
        ctx.gl_FragColor=sb_vec4(col,alpha);
      }
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.UW_EXTINCTION=sb_vec3(.245f,.066f,.046f);
ctx.UW_SCATTER=sb_vec3(.022f,.155f,.185f);
main(ctx);output[0]=ctx;}

#endif

