__device__ Brk sb_new_Brk(float p_ti,float p_tb,float p_Tj,float p_H,float p_c,float p_cFar,float p_tauS,float p_zI,float p_zB,float p_kap,float p_vy0,float p_Tr,float p_style,float p_spill,float p_str,float p_seed,float p_s,float p_rs,float p_x,float p_D,float p_hold){Brk a;a.ti=p_ti;a.tb=p_tb;a.Tj=p_Tj;a.H=p_H;a.c=p_c;a.cFar=p_cFar;a.tauS=p_tauS;a.zI=p_zI;a.zB=p_zB;a.kap=p_kap;a.vy0=p_vy0;a.Tr=p_Tr;a.style=p_style;a.spill=p_spill;a.str=p_str;a.seed=p_seed;a.s=p_s;a.rs=p_rs;a.x=p_x;a.D=p_D;a.hold=p_hold;return a;}
__device__ BrkStage sb_new_BrkStage(float p_za,float p_ya,float p_yt,float p_lf,float p_uw,float p_hw,float p_m,float p_p,float p_st,float p_lb){BrkStage a;a.za=p_za;a.ya=p_ya;a.yt=p_yt;a.lf=p_lf;a.uw=p_uw;a.hw=p_hw;a.m=p_m;a.p=p_p;a.st=p_st;a.lb=p_lb;return a;}
