__device__ float linearizeDepth(GraphicsContext& ctx,float d){
  float z = d * 2.0f- 1.0f;
  return (2.0f* ctx.uNear * ctx.uFar) / (ctx.uFar + ctx.uNear - z * (ctx.uFar - ctx.uNear));
