__device__ float brkFarW(GraphicsContext& ctx,float far,float x){ return sb_mix(sb_smoothstep(5.0f,13.0f,sb_abs(x)),1.0f,sb_step(1e-9f,far))* sb_step(1e-9f,sb_abs(far)); }

__device__ Brk brkAt(GraphicsContext& ctx,int i,float x){
