SBMat4 projectionMatrix;
float3 cameraPosition;
float uPebW[5];
float uGrainW[5];
float uGritW[5];
int uZero;
float4 uL0[4];
float4 uL1[4];
float4 uL2[4];
float4 uL3[4];
float4 uL4[4];
float4 uBakeK;
float4 uBakeK2;
float2 vUv;
float4 outC;
float gH;
float3 gR0;
float3 gR1;
float2 gLoc;
float gA;
float gRR;
float gKind;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
// Constant MEAN_TINT is initialized in each invocation.
__device__ uint3 pcg3d(GraphicsContext& ctx,uint3 v){
  v =v * 1664525u + 1013904223u;
  v.x=v.x+(v.y* v.z); v.y=v.y+(v.z* v.x); v.z=v.z+(v.x* v.y);
  v =sb_uint_xor(v ,sb_uint_shr(v ,16u));
  v.x=v.x+(v.y* v.z); v.y=v.y+(v.z* v.x); v.z=v.z+(v.x* v.y);
  return v;
}

__device__ float3 rnd3(GraphicsContext& ctx,float2 c,int s){ return sb_vec3(pcg3d(ctx,make_uint3(uint(c.x),uint(c.y),uint(s + 7))))* (1.0f/ 4294967296.0f); }

__device__ float gauss(GraphicsContext& ctx,float2 u){ return sb_sqrt((0-(2.0f))* sb_log(sb_max(u.x,1e-6f)))* sb_cos(6.2831853f* u.y); }


__device__ float pnoise(GraphicsContext& ctx,float2 p,float n,int s){
  float2 q = p * n; float2 i = sb_floor(q); float2 f = q - i;
  f =f * f * (3.0f- 2.0f* f);
  float a = rnd3(ctx,sb_mod(i,n),s).x, b = rnd3(ctx,sb_mod(i + sb_vec2(float(1),float(0)),n),s).x;
  float c = rnd3(ctx,sb_mod(i + sb_vec2(float(0),float(1)),n),s).x, d = rnd3(ctx,sb_mod(i + sb_vec2(float(1),float(1)),n),s).x;
  return sb_mix(sb_mix(a,b,f.x),sb_mix(c,d,f.x),f.y);
}


__device__ float lnoise(GraphicsContext& ctx,float2 p,int s){
  float2 i = sb_floor(p); float2 f = p - i;
  f =f * f * (3.0f- 2.0f* f);
  float2 o = sb_vec2(4096.0f);
  float a = rnd3(ctx,i + o,s).x, b = rnd3(ctx,i + o + sb_vec2(float(1),float(0)),s).x;
  float c = rnd3(ctx,i + o + sb_vec2(float(0),float(1)),s).x, d = rnd3(ctx,i + o + sb_vec2(float(1),float(1)),s).x;
  return sb_mix(sb_mix(a,b,f.x),sb_mix(c,d,f.x),f.y);
}


__device__ float pickClass(GraphicsContext& ctx,float u,int set){
  for (int i = 0; i < 5; i++) {
    float w = set == 0 ? ctx.uPebW[i] : (set == 1 ? ctx.uGrainW[i] : ctx.uGritW[i]);
    if (u < w) return float(i);
  }
  return 5.0f;
}

__device__ float3 classAlbedo(GraphicsContext& ctx,int i,float& rough,float& pool){
  if (i == 0) { rough =0.200f; pool =0.450f; return sb_vec3(0.2672f,0.2027f,0.1659f); }
  if (i == 1) { rough =0.180f; pool =0.450f; return sb_vec3(0.0871f,0.0649f,0.0501f); }
  if (i == 2) { rough =0.220f; pool =0.350f; return sb_vec3(0.2415f,0.2049f,0.1753f); }
  if (i == 3) { rough =0.140f; pool =0.450f; return sb_vec3(0.7603f,0.6339f,0.5404f); }
  if (i == 4) { rough =0.200f; pool =0.000f; return sb_vec3(0.4669f,0.2767f,0.2105f); }
  if (i == 5) { rough =0.240f; pool =0.050f; return sb_vec3(0.3511f,0.2184f,0.1247f); }
  pool =0.0f;
  return sb_vec3(0.0f);
}

__device__ void layer(GraphicsContext& ctx,float2 p,float n,int seed,float kind,float2 dMed_dSig,float2 dRange,float occ,float2 asp,float2 thk,float2 zr,float pr,float tilt,float ang,float ridge){
  float cs = 1.2000f/ n;
  float2 q = p * n;
  float2 i0 = sb_floor(q);
  float2 f = q - i0;
  for (int k9 = 0; k9 < 9 + ctx.uZero; k9++) {
    int x = k9 % 3 - 1, y = k9 / 3 - 1;
    float2 c = sb_mod(i0 + sb_vec2(float(x),float(y)),n);
    float3 r0 = rnd3(ctx,c,seed), r1 = rnd3(ctx,c,seed + 101), r2 = rnd3(ctx,c,seed + 202);
    if (r2.x> occ) continue;
    float2 ctr = sb_vec2(float(x),float(y))+ 0.15f+ 0.7f* sb_sw_xy(r0);
    float2 d = (f - ctr) * cs;
    float D = sb_clamp(dMed_dSig.x* sb_exp(dMed_dSig.y* gauss(ctx,sb_sw_xy(r1))),dRange.x,dRange.y);
    float a = 0.5f* D;
    if (length(d)> a * 1.45f) continue;
    float ar = sb_mix(asp.x,asp.y,r0.z);
    if (kind > 3.5f&& r2.z< 0.08f) ar =ar *(0.62f);
    float an = r1.z* 6.2831853f;
    float ca = sb_cos(an), sa = sb_sin(an);
    float2 l = sb_vec2(ca * d.x+ sa * d.y,(0-(sa ))* d.x+ ca * d.y);
    float2 e = sb_vec2(l.x/ a,l.y/ (a * ar));
    float th = sb_atan(e.y,e.x);
    float wob = 1.0f+ 0.07f* r2.z* sb_sin(2.0f* th + r2.y* 31.0f)+ 0.06f* sb_sin(3.0f* th + r2.z* 17.0f)+ 0.035f* sb_sin(5.0f* th + r0.x* 23.0f)+ (kind < 3.5f? 0.03f* sb_sin(7.0f* th + r1.y* 11.0f): 0.0f);
    float re = length(e);
    if (ang > 0.0f) {

      float pd = 0.0f, ph = r2.y* 6.2831853f;
      for (int k = 0; k < 6 + ctx.uZero; k++) {
        float t = ph + float(k)* 1.0471976f+ 0.5f* (sb_fract(r0.x* 13.7f* float(k + 1))- 0.5f);
        pd =sb_max(pd,dot(e,sb_vec2(sb_cos(t),sb_sin(t))));
      }
      re =sb_mix(re,pd * 1.08f,ang);
    }
    float rr = re / wob;
    if (rr >= 1.0f) continue;

    if (kind > 3.5f&& r0.y> 0.972f&& D > 0.02f&& length(e - sb_vec2(0.12f,(0-(0.08f)))* (r1.x- 0.5f))< sb_mix(0.17f,0.27f,r1.y)) continue;
    float half_ = a * sb_mix(thk.x,thk.y,r2.y);
    float top = sb_mix(zr.x,zr.y,sb_fract(r2.z* 7.13f+ r0.x* 3.1f));
    if (kind > 3.5f) top =top +(ctx.uBakeK.x* a);
    float prof = sb_pow(sb_max(1.0f- sb_pow(rr,pr),0.0f),1.0f/ pr);

    float2 tv = (sb_vec2(r0.z,r2.y)* 2.0f- 1.0f) * tilt;

    float rt = r0.y* 6.2831853f;
    float cr = sb_abs(dot(l,sb_vec2(sb_cos(rt),sb_sin(rt)))- (r1.x- 0.5f) * 0.6f* a);
    float h = top - half_ + half_ * prof + dot(tv,l)* prof - ridge * cr * prof;
    if (h > ctx.gH) { ctx.gH =h; ctx.gR0 =r0; ctx.gR1 =r1; ctx.gLoc =l; ctx.gA =a; ctx.gRR =rr; ctx.gKind =kind; }
  }
}



__device__ void surface(GraphicsContext& ctx,float2 p,float4& A,float4& C){

  ctx.gH =(0-(0.0020f))+ 0.0006f* pnoise(ctx,p,640.0f,5)+ 0.0003f* pnoise(ctx,p,1280.0f,6);
  ctx.gKind =0.0f; {ctx.gR1 =sb_vec3(0.0f);ctx.gR0 =ctx.gR1 ;}ctx.gLoc =sb_vec2(0.0f); ctx.gA =0.001f; ctx.gRR =1.0f;
  for (int i = 0; i < 4 + ctx.uZero; i++) {
    float4 a0 = ctx.uL0[i], a1 = ctx.uL1[i], a2 = ctx.uL2[i], a3 = ctx.uL3[i]; float2 a4 = sb_sw_xy(ctx.uL4[i]);
    layer(ctx,p,sb_floor(1.2000f/ a0.x+ 0.5f),int(a0.y),a0.z,sb_sw_xy(a1),sb_sw_zw(a1),a0.w,sb_sw_xy(a2),sb_sw_zw(a2),sb_sw_xy(a3),a3.z,a3.w,a4.x,a4.y);
  }

  float3 alb; float rough, cls, pool;
  float crown = 0.0f, rnd = 0.0f;
  if (ctx.gKind < 0.5f) {

    float s = pnoise(ctx,p,2560.0f,9);
    float sp = sb_step(0.86f,pnoise(ctx,p,1900.0f,10));
    alb =sb_vec3(0.092f,0.075f,0.064f)* (0.75f+ 0.5f* s) + sb_vec3(0.10f,0.09f,0.08f)* sp;
    rough =0.55f;
  } else {
    bool peb = ctx.gKind > 3.5f;

    cls =pickClass(ctx,ctx.gR0.x* 0.999f,peb ? 0 : (ctx.gKind < 1.5f? 2 : 1));
    alb =classAlbedo(ctx,int(cls),rough,pool);

    float sig = peb ? 0.15f* ctx.uBakeK2.w: (ctx.gKind > 2.5f? 0.28f: 0.46f) * ctx.uBakeK2.z;
    alb =alb *(sb_exp(sig * sb_clamp(gauss(ctx,sb_sw_yx(ctx.gR1)),(0-(1.7f)),2.2f)));

    alb =alb *(1.0f+ 0.07f* (ctx.gR1.z- 0.5f) * sb_vec3(1.0f,(0-(0.15f)),(0-(0.8f))));

    float sp = lnoise(ctx,ctx.gLoc / 0.0006f+ sb_sw_yz(ctx.gR0)* 900.0f,3);
    float sp2 = lnoise(ctx,ctx.gLoc / 0.0011f+ sb_sw_zx(ctx.gR1)* 700.0f,5);
    float bl = lnoise(ctx,ctx.gLoc / 0.004f+ sb_sw_xy(ctx.gR1)* 300.0f,4);
    alb =alb *(0.92f+ 0.14f* sp + 0.12f* (bl - 0.5f));
    alb =alb *(1.0f+ (0.45f* sb_step(0.83f,sp2)- 0.18f* sb_step(sp2,0.12f)) * ctx.uBakeK.y);
    if (peb) {
      if (cls < 0.5f&& ctx.gR1.x> 0.7f) alb =alb *(0.9f+ 0.2f* sb_step(0.72f,lnoise(ctx,ctx.gLoc / 0.0012f+ 17.0f,8)));
      if (ctx.gR0.z> 0.85f) alb =alb *(1.0f- 0.35f* sb_step(0.86f,lnoise(ctx,ctx.gLoc / 0.0016f+ 3.0f,12)));
      if (cls < 1.5f&& ctx.gR1.y> 0.8f) {
        float vd = sb_abs(dot(ctx.gLoc,sb_vec2(sb_cos(ctx.gR1.z* 9.0f),sb_sin(ctx.gR1.z* 9.0f)))- (ctx.gR0.y- 0.5f) * ctx.gA);
        alb =sb_mix(alb,sb_vec3(0.55f,0.50f,0.46f),sb_smoothstep(0.0009f,0.0004f,vd)* 0.8f);
      }

      alb =alb *(sb_mix(1.05f,0.86f,sb_smoothstep(0.45f,1.0f,ctx.gRR))* (1.0f+ 0.10f* (bl - 0.5f)));
    } else {

      alb =alb *(sb_mix(1.0f+ 0.12f* ctx.uBakeK2.x,1.0f- 0.38f* ctx.uBakeK2.x,sb_smoothstep(0.30f,1.0f,ctx.gRR)));
    }

    pool =sb_mix(pool,1.0f,ctx.gKind < 1.5f? 0.75f: (ctx.gKind < 2.5f? 0.5f: (ctx.gKind < 3.5f? 0.25f: 0.0f)))* (peb ? ctx.uBakeK.w: ctx.uBakeK.z);
    pool =sb_min(pool,1.0f);
    alb =sb_mix(alb,dot(alb,sb_vec3(0.2126f,0.7152f,0.0722f))* ctx.MEAN_TINT,pool);

    float pk = pnoise(ctx,p,sb_floor(1.2000f/ 0.045f),14)* 0.65f+ pnoise(ctx,p,sb_floor(1.2000f/ 0.018f),15)* 0.35f- 0.5f;
    alb =alb *(1.0f+ 0.15f* ctx.uBakeK2.y* pk * sb_vec3(1.0f,(0-(0.35f)),(0-(0.55f))));

    float Lg = dot(alb,sb_vec3(0.2126f,0.7152f,0.0722f));
    if (Lg > 0.46f) alb =alb *((0.46f+ (Lg - 0.46f) * 0.5f) / Lg);

    if (Lg < 0.05f) alb =alb *((0.025f+ 0.5f* Lg) / sb_max(Lg,1e-4f));
    crown =1.0f- ctx.gRR * ctx.gRR;
    rnd =sb_fract(ctx.gR0.x* 13.7f+ ctx.gR1.y* 7.1f);
    rough =rough +(0.08f* (ctx.gR1.x- 0.5f));
  }
  A =sb_vec4(alb,ctx.gH);
  C =sb_vec4(sb_clamp(rough,0.05f,1.0f),crown,ctx.gKind > 3.5f? 1.0f: 0.0f,rnd);
}


__device__ void main(GraphicsContext& ctx){

  float4 A = sb_vec4(0.0f), C = sb_vec4(0.0f);
  for (int s = 0; s < 4 + ctx.uZero; s++) {
    float2 o = (sb_vec2(float(s & 1),float(s >> 1))- 0.5f) * 0.5f/ 2048.0f;
    float4 a, c;
    surface(ctx,ctx.vUv + o,a,c);
    A =A +(a); C =C +(c);
  }
  ctx.gl_FragColor =A * 0.25f;
  ctx.outC =C * 0.25f;
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.MEAN_TINT=sb_vec3(1.2500f,0.9483f,0.7758f);
main(ctx);output[0]=ctx;}

#endif

