struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
int uZero;
float2 vUv;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ uint3 pcg3d(GraphicsContext& ctx,uint3 v){
  v =v * 1664525u + 1013904223u;
  v.x=v.x+(v.y* v.z); v.y=v.y+(v.z* v.x); v.z=v.z+(v.x* v.y);
  v =sb_uint_xor(v ,sb_uint_shr(v ,16u));
  v.x=v.x+(v.y* v.z); v.y=v.y+(v.z* v.x); v.z=v.z+(v.x* v.y);
  return v;
}

__device__ float3 rnd3(GraphicsContext& ctx,float2 c,int s){ return sb_vec3(pcg3d(ctx,make_uint3(uint(c.x),uint(c.y),uint(s + 7))))* (1.0f/ 4294967296.0f); }

__device__ float gauss(GraphicsContext& ctx,float2 u){ return sb_sqrt((0-(2.0f))* sb_log(sb_max(u.x,1e-6f)))* sb_cos(6.2831853f* u.y); }


__device__ float pnoise(GraphicsContext& ctx,float2 p,float n,int s){
  float2 q = p * n; float2 i = sb_floor(q); float2 f = q - i;
  f =f * f * (3.0f- 2.0f* f);
  float a = rnd3(ctx,sb_mod(i,n),s).x, b = rnd3(ctx,sb_mod(i + sb_vec2(float(1),float(0)),n),s).x;
  float c = rnd3(ctx,sb_mod(i + sb_vec2(float(0),float(1)),n),s).x, d = rnd3(ctx,sb_mod(i + sb_vec2(float(1),float(1)),n),s).x;
  return sb_mix(sb_mix(a,b,f.x),sb_mix(c,d,f.x),f.y);
}


__device__ float lnoise(GraphicsContext& ctx,float2 p,int s){
  float2 i = sb_floor(p); float2 f = p - i;
  f =f * f * (3.0f- 2.0f* f);
  float2 o = sb_vec2(4096.0f);
  float a = rnd3(ctx,i + o,s).x, b = rnd3(ctx,i + o + sb_vec2(float(1),float(0)),s).x;
  float c = rnd3(ctx,i + o + sb_vec2(float(0),float(1)),s).x, d = rnd3(ctx,i + o + sb_vec2(float(1),float(1)),s).x;
  return sb_mix(sb_mix(a,b,f.x),sb_mix(c,d,f.x),f.y);
}


__device__ float hAt(GraphicsContext& ctx,float2 q){ q =sb_ivec2(sb_mod(sb_vec2(q),2048.0f)); return __sb_texelFetch(0,q,0).w; }

__device__ void main(GraphicsContext& ctx){
  float2 p = sb_ivec2(sb_sw_xy(ctx.gl_FragCoord));
  float px = 1.2000f/ 2048.0f;
  float h00 = hAt(ctx,p + sb_ivec2((0-(1)),(0-(1)))), h10 = hAt(ctx,p + sb_ivec2(float(0),(0-(1)))), h20 = hAt(ctx,p + sb_ivec2(float(1),(0-(1))));
  float h01 = hAt(ctx,p + sb_ivec2((0-(1)),float(0))), h11 = hAt(ctx,p), h21 = hAt(ctx,p + sb_ivec2(float(1),float(0)));
  float h02 = hAt(ctx,p + sb_ivec2((0-(1)),float(1))), h12 = hAt(ctx,p + sb_ivec2(float(0),float(1))), h22 = hAt(ctx,p + sb_ivec2(float(1),float(1)));
  float dx = ((h20 + 2.0f* h21 + h22) - (h00 + 2.0f* h01 + h02)) / (8.0f* px);
  float dy = ((h02 + 2.0f* h12 + h22) - (h00 + 2.0f* h10 + h20)) / (8.0f* px);
  float3 n = normalize(sb_vec3((0-(dx)),(0-(dy)),1.0f));


  float occ = 0.0f;
  for (int i = 0; i < 12 + ctx.uZero; i++) {
    float a = (float(i)+ 0.5f) * 0.5235988f;
    float2 dir = sb_vec2(sb_cos(a),sb_sin(a));
    float tmax = 0.0f;
    for (int k = 1; k <= 5 + ctx.uZero; k++) {
      float r = 0.0005f* sb_pow(1.65f,float(k));
      float2 q = p + sb_ivec2(sb_round(dir * r / px));
      tmax =sb_max(tmax,(hAt(ctx,q)- h11) / r);
    }
    occ =occ +(tmax / sb_sqrt(1.0f+ tmax * tmax));
  }
  float ao = sb_clamp(1.0f- occ / 12.0f* 1.15f,0.0f,1.0f);
  ctx.gl_FragColor =sb_vec4(n * 0.5f+ 0.5f,ao);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

