struct Face { float w; float h; float u; float v; };

struct GraphicsContext {
float THETA;
float EPS4;
float VMAX;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float4 uDom;
float2 uN;
float uDt;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ Face sb_new_Face(float p_w,float p_h,float p_u,float p_v){Face a;a.w=p_w;a.h=p_h;a.u=p_u;a.v=p_v;return a;}
// Constant THETA is initialized in each invocation.
// Constant EPS4 is initialized in each invocation.
// Constant VMAX is initialized in each invocation.
__device__ float2 cellXZ(GraphicsContext& ctx,float2 ij){ return sb_vec2(ctx.uDom.x+ (float(int(ij.x))+ 0.5f) * ctx.uDom.z,ctx.uDom.y+ (float(int(ij.y))+ 0.5f) * ctx.uDom.w); }


__device__ float2 ghost(GraphicsContext& ctx,float2 p){
  float2 q = p;
  if (int(q.x)< 0) q.x=(0-(int(q.x)))- 1; else if (int(q.x)>= int(ctx.uN.x)) q.x=2 * int(ctx.uN.x)- int(q.x)- 1;
  if (int(q.y)>= int(ctx.uN.y)) q.y=2 * int(ctx.uN.y)- int(q.y)- 1;
  return sb_clamp(q,sb_ivec2(float(0)),ctx.uN - 1);
}

__device__ float3 St(GraphicsContext& ctx,float2 p){
  float3 U = sb_sw_xyz(__sb_texelFetch(0,ghost(ctx,p),0));
  if (int(p.x)< 0 || int(p.x)>= int(ctx.uN.x)) U.y=(0-(U.y));
  if (int(p.y)>= int(ctx.uN.y)) U.z=(0-(U.z));
  return U;
}

__device__ float3 Bd(GraphicsContext& ctx,float2 p){ return sb_sw_xyz(__sb_texelFetch(1,ghost(ctx,p),0)); }


__device__ float mm3(GraphicsContext& ctx,float a,float b,float c){
  if (a > 0.0f&& b > 0.0f&& c > 0.0f) return sb_min(a,sb_min(b,c));
  if (a < 0.0f&& b < 0.0f&& c < 0.0f) return sb_max(a,sb_max(b,c));
  return 0.0f;
}

__device__ float3 mmv(GraphicsContext& ctx,float3 l,float3 c,float3 r){
  float3 a = ctx.THETA * (c - l), b = 0.5f* (r - l), d = ctx.THETA * (r - c);
  return sb_vec3(mm3(ctx,a.x,b.x,d.x),mm3(ctx,a.y,b.y,d.y),mm3(ctx,a.z,b.z,d.z));
}


__device__ void recon(GraphicsContext& ctx,float3 Ul,float3 Uc,float3 Ur,float Bm,float Bp,float3& Um,float3& Up){
  float3 s = mmv(ctx,Ul,Uc,Ur);
  Up =Uc + 0.5f* s; Um =Uc - 0.5f* s;



  if (Up.x< Bp || Um.x< Bm) {
    Up=Uc;Um=Uc;
  }
}

__device__ Face mkFace(GraphicsContext& ctx,float3 U,float B){
  Face f; f.h=sb_max(U.x- B,0.0f); f.w=B + f.h;
  float h4 = f.h* f.h* f.h* f.h;
  float den = sb_sqrt(h4 + sb_max(h4,ctx.EPS4));
  f.u=sb_clamp(1.41421356f* f.h* U.y/ den,(0-(ctx.VMAX)),ctx.VMAX);
  f.v=sb_clamp(1.41421356f* f.h* U.z/ den,(0-(ctx.VMAX)),ctx.VMAX);
  return f;
}


__device__ float3 kpFlux(GraphicsContext& ctx,Face L,Face R,int dir){
  float unL = dir == 0 ? L.u: L.v, unR = dir == 0 ? R.u: R.v;
  float cL = sb_sqrt(9.81f* L.h), cR = sb_sqrt(9.81f* R.h);
  float ap = sb_max(sb_max(unL + cL,unR + cR),0.0f);
  float am = sb_min(sb_min(unL - cL,unR - cR),0.0f);
  float d = ap - am;
  if (d < 1.0e-7f) return sb_vec3(0.0f);
  float pL = 0.5f* 9.81f* L.h* L.h, pR = 0.5f* 9.81f* R.h* R.h;
  float3 FL, FR;
  if (dir == 0) {
    FL =sb_vec3(L.h* L.u,L.h* L.u* L.u+ pL,L.h* L.u* L.v);
    FR =sb_vec3(R.h* R.u,R.h* R.u* R.u+ pR,R.h* R.u* R.v);
  } else {
    FL =sb_vec3(L.h* L.v,L.h* L.u* L.v,L.h* L.v* L.v+ pL);
    FR =sb_vec3(R.h* R.v,R.h* R.u* R.v,R.h* R.v* R.v+ pR);
  }
  float3 UL = sb_vec3(L.w,L.h* L.u,L.h* L.v), UR = sb_vec3(R.w,R.h* R.u,R.h* R.v);
  return (ap * FL - am * FR) / d + (ap * am / d) * (UR - UL);
}


__device__ void main(GraphicsContext& ctx){
  float2 p = sb_ivec2(sb_sw_xy(ctx.gl_FragCoord));
  float2 ex = sb_ivec2(float(1),float(0)), ez = sb_ivec2(float(0),float(1));
  float3 C = St(ctx,p), E = St(ctx,p + ex), W = St(ctx,p - ex), N = St(ctx,p + ez), S = St(ctx,p - ez);
  float3 EE = St(ctx,p + 2 * ex), WW = St(ctx,p - 2 * ex), NN = St(ctx,p + 2 * ez), SS = St(ctx,p - 2 * ez);
  float3 bC = Bd(ctx,p), bE = Bd(ctx,p + ex), bW = Bd(ctx,p - ex), bN = Bd(ctx,p + ez), bS = Bd(ctx,p - ez);
  float3 bWW = Bd(ctx,p - 2 * ex), bSS = Bd(ctx,p - 2 * ez);



  float BeC=bC.y,BwC=bW.y,BnC=bC.z,BsC=bS.z;

  float3 UwC, UeC, UsC, UnC, UwE, UeE, UwW, UeW, UsN, UnN, UsS, UnS;
  recon(ctx,W,C,E,BwC,BeC,UwC,UeC);
  recon(ctx,C,E,EE,BeC,bE.y,UwE,UeE);
  recon(ctx,WW,W,C,bWW.y,BwC,UwW,UeW);
  recon(ctx,S,C,N,BsC,BnC,UsC,UnC);
  recon(ctx,C,N,NN,BnC,bN.z,UsN,UnN);
  recon(ctx,SS,S,C,bSS.z,BsC,UsS,UnS);

  float3 HE = kpFlux(ctx,mkFace(ctx,UeC,BeC),mkFace(ctx,UwE,BeC),0);
  float3 HW = kpFlux(ctx,mkFace(ctx,UeW,BwC),mkFace(ctx,UwC,BwC),0);
  float3 GN = kpFlux(ctx,mkFace(ctx,UnC,BnC),mkFace(ctx,UsN,BnC),1);
  float3 GS = kpFlux(ctx,mkFace(ctx,UnS,BsC),mkFace(ctx,UsC,BsC),1);




  float4 h0=sb_max(sb_vec4(C.x)-sb_vec4(BeC,BwC,BnC,BsC),sb_vec4(0.0f));
  float Sx=.5f*9.81f*(h0.x*h0.x-h0.y*h0.y)/ctx.uDom.z;
  float Sz=.5f*9.81f*(h0.z*h0.z-h0.w*h0.w)/ctx.uDom.w;

  float3 U = C - ctx.uDt / ctx.uDom.z* (HE - HW) - ctx.uDt / ctx.uDom.w* (GN - GS) + ctx.uDt * sb_vec3(0.0f,Sx,Sz);
  float h = U.x- bC.x;
  if (h < 1.0e-5f) { U =sb_vec3(bC.x,0.0f,0.0f); }
  else {

    float sp = length(sb_sw_yz(U))/ h;
    if (sp > ctx.VMAX) {float2 sb_write0=sb_sw_yz(U)*(ctx.VMAX / sp);U.y=sb_write0.x;U.z=sb_write0.y;}}
  ctx.gl_FragColor =sb_vec4(U,0.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.THETA=1.3f;
ctx.EPS4=1.0e-8f;
ctx.VMAX=7.5f;
main(ctx);output[0]=ctx;}

#endif

