    l0 =sb_vec4((0-(0.1000000f)),8.000000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.000000f,(0-(1.000000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,4.000000f); q1 =sb_vec4(0.000000f,0.000000f,0.000000f,(0-(0.2000000f))); }
  else if (tn < (0-(3.000000f))) { t0 =(0-(4.000000f)); iw =1.000000f; cz =sb_vec4((0-(15.50000f)),3.900000f,0.5500000f,(0-(0.2500000f))); cy =sb_vec4(0.2400000f,0.02666667f,0.02166667f,(0-(0.008333333f)));
    l0 =sb_vec4((0-(0.1000000f)),7.000000f,0.3000000f,0.5000000f); l1 =sb_vec4(0.000000f,(0-(1.000000f)),0.000000f,0.000000f); q0 =sb_vec4(1.600000f,2.000000f,0.000000f,3.800000f); q1 =sb_vec4(0.000000f,0.000000f,0.000000f,(0-(0.2000000f))); }
