  float tauR = ctx.uFoamK.x* sb_mix(1.0f,ctx.uFoamM.z,persist)* (1.0f+ ctx.uFoamS2.x* sb_max(R - 0.5f,0.0f))
             * sb_mix(ctx.uFoamS2.z,1.0f,sb_max(sb_smoothstep(0.15f,0.5f,sp),sb_smoothstep(0.03f,0.08f,h)));
  float loss = R * (1.0f- sb_exp((0-(ctx.uDtS ))/ tauR));
  R =R -(loss);
  float tauG = sb_mix(ctx.uFoamK.z,ctx.uFoamK.w,sb_smoothstep(0.12f,0.45f,h));
  Gf =Gf +(ctx.uFoamK.y* loss);
  Gf =Gf *(sb_exp((0-(ctx.uDtS ))/ tauG));
  float drained = 1.0f- sb_smoothstep(0.0004f,0.0022f,h);
  R =R *(sb_exp((0-(ctx.uDtS ))* 10.0f* drained));
  Gf =Gf *(sb_exp((0-(ctx.uDtS ))* 7.0f* drained));



  float shear = sb_smoothstep(0.1f,0.9f,sp)* sb_smoothstep(0.002f,0.012f,h)* (1.0f- sb_smoothstep(0.15f,0.4f,h));

  K =K +(ctx.uDtS * (6.0f* inj.x+ 1.5f* front + ctx.uFoamK2.x* shear + 2.0f* jump * sb_mix(1.0f,0.35f,sb_smoothstep(0.2f,0.6f,(0-(vN.y))))));
  K =K *(sb_exp((0-(ctx.uDtS ))/ sb_mix(0.7f,ctx.uFoamS2.w,sb_smoothstep(0.05f,0.2f,h))));





  Mk =Mk +(ctx.uFoamS.z* (loss + ctx.uDtS * inj.x) + ctx.uDtS * ctx.uFoamK2.y* shear * sb_smoothstep(0.02f,0.045f,h)* (1.0f- sb_smoothstep(0.2f,0.7f,(0-(vel.y)))));
  Mk =Mk *(sb_exp((0-(ctx.uDtS ))/ (ctx.uFoamM.x* sb_mix(0.5f,1.0f,sb_smoothstep(0.01f,0.04f,h))))* sb_exp((0-(ctx.uDtS ))* (4.0f* drained + 2.5f* jump * sb_smoothstep(0.1f,0.5f,(0-(vN.y))))));
  ctx.gl_FragColor =sb_vec4(sb_clamp(R,0.0f,ctx.uFoamRMax),sb_clamp(Gf,0.0f,2.0f),sb_clamp(K,0.0f,4.0f),sb_clamp(Mk,0.0f,1.0f));
  ctx.outUV =L;
}
