  b.s=b.H/ 0.45f;
  b.rs=sb_sqrt(b.s);
  b.c=B.x;
  b.cFar=E.x;
  b.tauS=E.y;
  b.spill=E.z;
  b.kap=C.x;
  b.style=C.w;
