  float2 fc = brkFcos(ctx,u), fs = brkFsteep(ctx,u,g.uw,g.hw,g.m,g.p);
  float2 F = sb_mix(fc,fs,g.st);
  return sb_vec2(g.yt+ (g.ya- g.yt) * F.x,(g.ya- g.yt) * F.y/ g.lf);
}




__device__ float brkFrontXi(GraphicsContext& ctx,BrkStage g,float h){
  float lo = 0.0f, hi = 1.0f;
  int nIt = 12 + sb_min(ctx.uEvtCount,0);
  for (int k = 0; k < nIt; k++) {
    float u = 0.5f* (lo + hi);
    float F = sb_mix(brkFcos(ctx,u).x,brkFsteep(ctx,u,g.uw,g.hw,g.m,g.p).x,g.st);
    if (F > h) lo =u; else hi =u;
  }
  return 0.5f* (lo + hi) * g.lf;
}






__device__ float3 brkProfileS(GraphicsContext& ctx,Brk b,BrkStage g,float2 A,float tn,float z){
  if (b.str<= 0.0f|| tn < (0-(6.0f))|| tn > 0.85f) return sb_vec3(0.0f);
  float2 e = brkShape(ctx,g,(z - A.x) / b.s);


  float birth=sb_smoothstep((0-(18.0f)),(0-(11.0f)),A.x);
  float amp = birth * (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str;
  float fade = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,z);
  float k = amp * fade;


  float xi = (z - A.x) / b.s;


  float crestW = xi < 0.0f? sb_exp((0-(sb_pow(xi / 0.12f,2.0f)))): sb_exp((0-(sb_pow((g.ya- e.x) / (0.025f+ 0.1f* b.spill),2.0f))))* (1.0f- sb_smoothstep(((0-(0.42f)))      - 0.06f,((0-(0.42f)))     ,tn)* (1.0f- sb_smoothstep(0.0f,0.1f,tn)));
  return sb_vec3(e.x* b.s* k,e.y* k,crestW * k);
}

__device__ float3 brkProfile(GraphicsContext& ctx,Brk b,float z,float t){
  float tn = brkTn(ctx,b,t);
  float3 result = sb_vec3(0.0f);
  {
  BrkStage g = brkStage(ctx,tn);
  result =brkProfileS(ctx,b,g,brkApex(ctx,b,g,tn),tn,z);
  }
  return result;
}









__device__ float brkArrival(GraphicsContext& ctx,Brk b,float t){ return (t - b.ti+ b.D) / b.rs; }



__device__ float brkWhitecapOnset(GraphicsContext& ctx,Brk b){ return sb_mix((0-(0.85f)),(0-(0.30f)),sb_smoothstep(0.3f,0.9f,b.spill))- 0.45f* (1.0f- sb_smoothstep(0.35f,0.6f,b.s)); }

__device__ float brkWhitecap(GraphicsContext& ctx,Brk b,float t){
  float patchy = sb_smoothstep(0.15f,0.75f,0.5f+ 0.5f* sb_sin(b.x* 3.3f+ b.seed* 17.0f)* sb_sin(b.x* 1.7f+ b.seed* 5.0f+ 1.0f));
  float spill = sb_smoothstep(0.3f,0.9f,b.spill);
  float a = brkArrival(ctx,b,t)- brkWhitecapOnset(ctx,b);

  return sb_mix(sb_smoothstep(0.0f,0.4f,a)* 0.45f* patchy,sb_smoothstep(0.0f,0.12f,a),spill);
}




__device__ float brkCrestFoam(GraphicsContext& ctx,Brk b,float t,float crestW){
  float tn = brkTn(ctx,b,t);

  float post = 0.08f* sb_smoothstep(0.02f,0.12f,tn)* (1.0f- sb_smoothstep(0.15f,0.35f,tn));
  return crestW * post;
}



__device__ float brkSurface(GraphicsContext& ctx,float2 xz,float t,float2& d,float& crestFoam){
  float eta = 0.0f; d =sb_vec2(0.0f); crestFoam =0.0f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    float3 p = brkProfile(ctx,b,xz.y,t);
    eta =eta +(p.x);
    d.y=d.y+(p.y);
    if (p.z> 0.01f) crestFoam =sb_max(crestFoam,brkCrestFoam(ctx,b,t,p.z));
  }
  return eta;
}





__device__ float brkCrestWidth(GraphicsContext& ctx,float2 xz,float y,float t){
  float best = (0-(1.0f));
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tn = brkTn(ctx,b,t);
    if (tn < (0-(2.0f))|| tn > 0.3f) continue;
    BrkStage g = brkStage(ctx,tn);
    float2 A = brkApex(ctx,b,g,tn);
    float amp = sb_smoothstep((0-(18.0f)),(0-(11.0f)),A.x)* b.str;
    float ya = g.ya* b.s* amp, yt = g.yt* b.s* amp;
    float h = (y - yt) / sb_max(ya - yt,1e-3f);
    if (h < 0.35f|| h > 1.02f) continue;
    float xi = (xz.y- A.x) / b.s;
    if (xi < (0-(1.5f))|| xi > g.lf) continue;

    float r = sb_sqrt(sb_max(ya,1e-3f)/ sb_max(y,1e-3f));
    float xb = y > 0.0f? (0-(g.lb))* sb_log(r + sb_sqrt(sb_max(r * r - 1.0f,0.0f))): (0-(3.0f));
    float xf = brkFrontXi(ctx,g,sb_clamp(h,0.0f,1.0f));
    float w = sb_max(xf - xb,0.0f)* b.s;
    best =best < 0.0f? w : sb_min(best,w);
  }
  return best;
}

__device__ float brkSurfaceOnly(GraphicsContext& ctx,float2 xz,float t){
  float eta = 0.0f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    eta =eta +(brkProfile(ctx,brkAt(ctx,i,xz.x),xz.y,t).x);
  }
  return eta;
}







__device__ float2 brkLipV0(GraphicsContext& ctx,Brk b){ return sb_vec2(1.05f* (1.0f+ b.kap) * sb_mix(0.55f,1.0f,b.style),(0-(0.10f)))* b.rs; }

__device__ BrkLip brkLip(GraphicsContext& ctx,Brk b,float t){
  BrkLip L;
  float tn = sb_max(brkTnLip(ctx,b,t),((0-(0.42f)))     );
  L.tn=tn;
  BrkStage g = brkStage(ctx,tn);
  L.g=g;
  L.A=brkApex(ctx,b,g,tn);
  L.grow=sb_smoothstep(((0-(0.42f)))     ,((0-(0.42f)))      + 0.06f,tn);
  L.wR=0.075f* b.s;


  L.R=L.A+ sb_vec2(sb_mix(0.02f,0.10f,sb_smoothstep(((0-(0.42f)))     ,((0-(0.33f)))      + 0.05f,tn))* b.s,(0-(0.5f))* L.wR);
  float2 rel = sb_vec2(0.17f,(0-(0.043f)))* b.s;
  if (tn < ((0-(0.33f)))     ) {
    float f = sb_smoothstep(((0-(0.42f)))     ,((0-(0.33f)))     ,tn);
    L.T=L.A+ sb_mix(sb_vec2(0.03f,(0-(0.06f)))* b.s,rel,f);
    L.vT=sb_vec2(1.5f,(0-(0.3f)))* b.rs;
    L.fl=0.0f;
  } else {
    BrkStage gE = brkStage(ctx,((0-(0.33f)))     );
    float2 Te = brkApex(ctx,b,gE,((0-(0.33f)))     )+ rel;
    float2 V0 = brkLipV0(ctx,b);
    L.fl=(tn - ((0-(0.33f)))     ) * b.rs;
    float fb = sb_min(L.fl,b.Tj);
    L.T=Te + V0 * fb + sb_vec2(0.0f,(0-(0.5f))* 9.81f* fb * fb);
    L.vT=V0 + sb_vec2(0.0f,(0-(9.81f))* fb);
    if (L.fl> b.Tj) {

      float a = L.fl- b.Tj;
      L.T=L.T+(sb_vec2(V0.x* a * 0.6f,(0-(0.25f))* b.s* sb_smoothstep(0.0f,0.25f* b.rs,a)));
    }
  }
  float2 ch = L.T- L.R;
  float len = sb_max(length(ch),1e-4f);
  float2 dT = normalize(ch / len + normalize(L.vT));
  L.P1=L.R+ sb_vec2(0.45f* sb_max(ch.x,0.02f* b.s)+ 0.1f* len,0.0f);
  L.P2=L.T- dT * 0.35f* len;
  L.wT=0.035f* b.s* (1.0f- 0.5f* sb_min(L.fl/ 0.3f,1.0f)) * L.grow;
  return L;
}


__device__ float4 brkLipCurve(GraphicsContext& ctx,BrkLip L,float sg){
  float u = 1.0f- sg;
  float2 p = u * u * u * L.R+ 3.0f* u * u * sg * L.P1+ 3.0f* u * sg * sg * L.P2+ sg * sg * sg * L.T;
  float2 dp = 3.0f* u * u * (L.P1- L.R) + 6.0f* u * sg * (L.P2- L.P1) + 3.0f* sg * sg * (L.T- L.P2);
  float l = length(dp);
  return sb_vec4(p,l > 1e-6f? dp / l : sb_vec2(1.0f,0.0f));
}

__device__ float brkLipWidth(GraphicsContext& ctx,BrkLip L,float sg){ return L.wT+ (L.wR- L.wT) * sb_pow(1.0f- sb_clamp(sg,0.0f,1.0f),0.8f); }



__device__ float3 brkJet(GraphicsContext& ctx,Brk b,float sigma,float t){
  BrkLip L = brkLip(ctx,b,t);
  float sg = 1.0f- sb_clamp(sigma,0.0f,1.0f);
  float4 c = brkLipCurve(ctx,L,sg);
  return sb_vec3(sb_sw_xy(c),brkLipWidth(ctx,L,sg));
}


__device__ float brkImpactSpeed(GraphicsContext& ctx,Brk b){
  float2 v = brkLipV0(ctx,b)+ sb_vec2(0.0f,(0-(9.81f))* b.Tj);
  return length(v);
}






__device__ float brkGamma(GraphicsContext& ctx,float tau,float T){ return tau > 0.0f? tau / (T * T) * sb_exp((0-(tau ))/ T): 0.0f; }



__device__ float brkThrow(GraphicsContext& ctx,Brk b){ return sb_mix(0.3f,1.0f,sb_smoothstep(0.4f,0.75f,b.style)); }








__device__ float brkLobes(GraphicsContext& ctx,Brk b){
  float x = b.x;
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float ph = far * 2.5f* sb_sin(0.37f* x + b.seed* 5.1f+ 1.7f* sb_sin(0.13f* x));
  float am = sb_mix(1.0f,0.45f+ 0.9f* (0.5f+ 0.5f* sb_sin(0.29f* x + b.seed* 3.3f)* sb_sin(0.71f* x + 1.1f)),far);

  float wm = 1.1f* sb_sin(1.9f* x + b.seed* 13.7f)+ 0.6f* sb_sin(4.4f* x + b.seed* 29.3f);
  float fine = 0.6f* sb_sin(24.1f* x + b.seed* 53.3f+ 2.1f* sb_sin(3.7f* x + b.seed* 9.0f))+ 0.4f* sb_sin(37.9f* x + b.seed* 71.9f+ 1.7f* sb_sin(5.9f* x + b.seed* 4.0f));
  return am * (ctx.uInjL.x* sb_sin(5.236f* x + b.seed* 37.1f+ ph)+ ctx.uInjL.y* sb_sin(14.96f* x + b.seed* 91.7f+ wm + 1.9f* ph)+ ctx.uInjL.z* fine);
}






__device__ float brkRunupMod(GraphicsContext& ctx,float x,float seed){
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float und = 0.6f* sb_sin(0.21f* x + seed * 7.3f+ 0.5f* sb_sin(0.09f* x + seed * 3.1f))+ 0.4f* sb_sin(0.47f* x + seed * 13.1f);
  float cph = x / 17.0f+ 0.25f* sb_sin(x / 23.0f+ 1.1f);
  float horn = 1.0f- sb_abs(sb_sin(3.14159f* cph));
  return far * (0.14f* und + 0.13f* (1.0f- 2.0f* horn * horn));
}

__device__ float3 brkInjection(GraphicsContext& ctx,float2 xz,float t){
  float3 src = sb_vec3(0.0f);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float hs = sb_sqrt(b.H/ 0.45f);

    float M = ctx.uInjMass * 0.2025f* sb_pow(b.H/ 0.45f,1.5f)* b.str* sb_max(ctx.uEvtG[i].x,0.0f);

    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = 0.22f* hs + 0.20f* tJ;
    float qJ = M * ctx.uInjJ.x* brkGamma(ctx,tJ,ctx.uInjJ.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f))/ (2.5066f* sJ);

    float tR = tau - ctx.uInjR.x;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ ctx.uInjR.z* sb_max(tR,0.0f);
    float sR = 0.30f* hs + 0.15f* sb_max(tR,0.0f);
    float qR = M * (1.0f- ctx.uInjJ.x) * brkGamma(ctx,tR,ctx.uInjR.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f))/ (2.5066f* sR);

    float thr = brkThrow(ctx,b);
    float mz = ctx.uInjSpeed * (qJ * ctx.uInjJ.w* sb_mix(0.5f,1.0f,thr)+ qR * ctx.uInjR.w* sb_mix(0.6f,1.0f,thr))
             * (1.0f+ brkLobes(ctx,b)) * (1.0f+ 0.5f* brkRunupMod(ctx,b.x,b.seed));
    src =src +(sb_vec3(qJ + qR,mz,mz * ctx.uInjL.w));
  }
  return src;
}





__device__ float brkFoam(GraphicsContext& ctx,float2 xz,float t){
  float f = 0.0f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;




    float spl = sb_smoothstep(0.5f,0.9f,b.spill)* (1.0f- sb_smoothstep(0.1f,0.3f,b.style)) * b.str;

    if (spl > 0.0f&& tau > (0-(0.3f))&& tau < 2.4f) {


      float on = sb_smoothstep((0-(0.3f)),0.0f,tau)* (1.0f- sb_smoothstep(ctx.uFoamSpillK.y- 1.1f,ctx.uFoamSpillK.y,tau));
      float zc = b.zI+ 0.1f+ ctx.uFoamSpillK.x* sb_max(tau,0.0f);
      f =f +(ctx.uFoamSpill * spl * (b.H/ 0.45f) * on * sb_exp((0-(0.5f))* sb_pow((xz.y- zc) / (0.3f+ 0.2f* sb_max(tau,0.0f)),2.0f)));
    }
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float E = (b.H* b.H) / (0.45f* 0.45f) * b.str* sb_mix(0.6f,1.0f,b.style);
    float2 gain = sb_max(sb_sw_xy(ctx.uEvtG[i]),sb_vec2(0.0f));
    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = ctx.uFoamSrc.w* (0.25f+ 0.30f* sb_max(tJ,0.0f));
    f =f +(E * gain.y* ctx.uFoamSrc.x* brkGamma(ctx,tJ,ctx.uFoamSrc.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f)));

    float tR = tau - 0.21f;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ 0.55f* sb_max(tR,0.0f);
    float sR = 0.35f+ 0.2f* sb_max(tR,0.0f);
    f =f +(E * gain.x* ctx.uFoamSrc.z* brkGamma(ctx,tR,0.4f)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f)));
  }
  return f;
}








__device__ float brkSweFoamKeep(GraphicsContext& ctx,float2 xz,float t){
  float keep = 1.0f;
  if (xz.y< (0-(9.0f))|| xz.y> 0.6f) return keep;
  float fade = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tn = brkTn(ctx,b,t);
    if (tn < (0-(2.4f))|| tn > 0.5f) continue;
    BrkStage g = brkStage(ctx,tn);
    float2 A = brkApex(ctx,b,g,tn);
    float xi = (xz.y- A.x) / b.s;
    if (xi < (0-(0.8f))|| xi > g.lf) continue;
    float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str* fade;
    float eta = brkShape(ctx,g,xi).x* b.s* amp;
    float raised = sb_smoothstep(0.012f,0.06f,eta - 0.5f* g.yt* b.s* amp);
    float front = sb_smoothstep((0-(0.8f)),(0-(0.2f)),xi);
    float grown = sb_smoothstep((0-(2.4f)),(0-(1.5f)),tn);
    float live = 1.0f- sb_smoothstep(0.1f,0.5f,tn);
    keep =sb_min(keep,1.0f- front * raised * grown * live);
  }
  return keep;
}


__device__ float2 ocVar(GraphicsContext& ctx,float2 v,float c2){ return sb_vec2(c2 * v.x+ (1.0f- c2) * v.y,(1.0f- c2) * v.x+ c2 * v.y); }






__device__ float pawFbm(GraphicsContext& ctx,float2 p,float fz,int oct){
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 5; i++) {
    if (i >= oct) break;
