      float ph = ctx.uTime / ctx.uBilT + 0.8f* __sb_textureLod(12,sb_sw_xz(Pw)* 0.37f+ 0.13f,0.0f).x;
      float f1 = sb_fract(ph), f2 = sb_fract(ph + 0.5f);
      float w1 = 1.0f- sb_abs(2.0f* f1 - 1.0f);
      float2 o1 = (0-(vf ))* f1 * ctx.uBilT, o2 = (0-(vf ))* f2 * ctx.uBilT + sb_vec2(0.37f,0.71f);

