    float lod = sb_log2(sb_max(0.5f* rt,1.0f));
    float c0 = HL(ctx,ctx.vUv,lod);
    float hxp = HL(ctx,ctx.vUv + sb_vec2(e.x* rt,0.0f),lod), hxm = HL(ctx,ctx.vUv - sb_vec2(e.x* rt,0.0f),lod);
