  nL =nL *(sb_smoothstep(0.0f,0.08f,Dt.y)* sb_mix(1.0f,ctx.uSplashK.x,splash));


  float3 nV = normalize(sb_vec3((0-(grad.x))+ ctx.uFoamK3.w* nL.x,sb_max((0-(grad.y))+ ctx.uFoamK3.w* nL.y,ctx.uFoamK3.x),1.0f));

