struct GraphicsContext {
SBMat4 modelMatrix;
SBMat4 modelViewMatrix;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
SBMat3 normalMatrix;
float3 cameraPosition;
float3 position;
float3 normal;
float2 uv;
float3 vDir;
float4 gl_Position;
int gl_VertexID;
int gl_InstanceID;
};
__device__ void main(GraphicsContext& ctx){
  ctx.vDir =ctx.position;
  float4 p = ctx.projectionMatrix * sb_mat4(sb_mat3(ctx.viewMatrix))* sb_vec4(ctx.position,1.0f);
  ctx.gl_Position =sb_sw_xyww(p);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

