__device__ float zoneScale(GraphicsContext& ctx,float2 xz){
  float z = xz.y+ 0.6f* sb_sin(xz.x* 0.21f+ 0.7f)+ 0.4f* sb_sin(xz.x* 0.53f+ 2.1f);
  float zc = z - 19.6f- 0.8f* sb_sin(xz.x* 0.07f+ 1.3f);

