  return 1.0f+ 1.0f* sb_smoothstep(4.0f,9.0f,z)+ 1.3f* sb_smoothstep(10.0f,17.0f,z)+ 0.9f* sb_exp((0-(zc ))* zc / 2.0f)+ 0.45f* horn - 0.5f* sb_smoothstep(22.0f,28.0f,z);
