__device__ void hexSetup(GraphicsContext& ctx,float2 xz,float2 dx,float2 dy){
  float2 st = xz / 0.55f;
  float2 sk = sb_vec2(st.x,(0-(0.57735027f))* st.x+ 1.15470054f* st.y);
  float2 b = sb_floor(sk);
  float3 t = sb_vec3(sb_fract(sk),0.0f);
  t.z=1.0f- t.x- t.y;
  float s = sb_step(0.0f,(0-(t.z))), s2 = 2.0f* s - 1.0f;
  ctx.hw =sb_vec3((0-(t.z))* s2,s - t.y* s2,s - t.x* s2);
  float2 v1 = b + sb_vec2(s,s), v2 = b + sb_vec2(s,1.0f- s), v3 = b + sb_vec2(1.0f- s,s);
  float3 r1 = hash32(ctx,v1 * sb_vec2(1.13f,0.87f)+ 31.7f), r2 = hash32(ctx,v2 * sb_vec2(1.13f,0.87f)+ 31.7f), r3 = hash32(ctx,v3 * sb_vec2(1.13f,0.87f)+ 31.7f);
  ctx.hc1 =sb_vec2(sb_cos(r1.z* 6.2831853f),sb_sin(r1.z* 6.2831853f)); ctx.ho1 =sb_sw_xy(r1);
  ctx.hc2 =sb_vec2(sb_cos(r2.z* 6.2831853f),sb_sin(r2.z* 6.2831853f)); ctx.ho2 =sb_sw_xy(r2);
  ctx.hc3 =sb_vec2(sb_cos(r3.z* 6.2831853f),sb_sin(r3.z* 6.2831853f)); ctx.ho3 =sb_sw_xy(r3);
  ctx.hs1 =vScale(ctx,v1); ctx.hs2 =vScale(ctx,v2); ctx.hs3 =vScale(ctx,v3);
  float ls = lodScale(ctx,ctx.gDist)* ctx.gBlur;
  float2 dxt = dx * ls / 1.2000f, dyt = dy * ls / 1.2000f;
  ctx.gx1 =rotF(ctx,ctx.hc1,dxt / ctx.hs1); ctx.gy1 =rotF(ctx,ctx.hc1,dyt / ctx.hs1);
  ctx.gx2 =rotF(ctx,ctx.hc2,dxt / ctx.hs2); ctx.gy2 =rotF(ctx,ctx.hc2,dyt / ctx.hs2);
  ctx.gx3 =rotF(ctx,ctx.hc3,dxt / ctx.hs3); ctx.gy3 =rotF(ctx,ctx.hc3,dyt / ctx.hs3);
}

__device__ float2 uv1(GraphicsContext& ctx,float2 xz){ return rotF(ctx,ctx.hc1,xz / (1.2000f* ctx.hs1))+ ctx.ho1; }

__device__ float2 uv2(GraphicsContext& ctx,float2 xz){ return rotF(ctx,ctx.hc2,xz / (1.2000f* ctx.hs2))+ ctx.ho2; }

__device__ float2 uv3(GraphicsContext& ctx,float2 xz){ return rotF(ctx,ctx.hc3,xz / (1.2000f* ctx.hs3))+ ctx.ho3; }


__device__ void pickDominant(GraphicsContext& ctx){
  if (ctx.hw.x>= ctx.hw.y&& ctx.hw.x>= ctx.hw.z) { ctx.hcD =ctx.hc1; ctx.hoD =ctx.ho1; ctx.gxD =ctx.gx1; ctx.gyD =ctx.gy1; ctx.hsD =ctx.hs1; }
  else if (ctx.hw.y>= ctx.hw.z) { ctx.hcD =ctx.hc2; ctx.hoD =ctx.ho2; ctx.gxD =ctx.gx2; ctx.gyD =ctx.gy2; ctx.hsD =ctx.hs2; }
  else { ctx.hcD =ctx.hc3; ctx.hoD =ctx.ho3; ctx.gxD =ctx.gx3; ctx.gyD =ctx.gy3; ctx.hsD =ctx.hs3; }
}

__device__ float domHeight(GraphicsContext& ctx,float2 xz){ return __sb_textureGrad(8,rotF(ctx,ctx.hcD,xz / (1.2000f* ctx.hsD))+ ctx.hoD,ctx.gxD,ctx.gyD).w* ctx.hsD; }



__device__ float sparkle(GraphicsContext& ctx,float2 xz,float cell,float dens,float tseed,float foot,float sz){
  float2 q = xz / cell;
  float2 c = sb_floor(q);
  float2 f = q - c;
  float3 r = hash33(ctx,sb_vec3(c,tseed));
  if (r.x> dens * cell * cell) return 0.0f;
  float2 pos = 0.2f+ 0.6f* hash22(ctx,c * 1.37f+ sb_vec2(tseed * 3.7f,11.0f));
  float rg = sb_mix(0.0005f,0.0015f,r.y)* sz;
  float2 d = (f - pos) * cell;
