__device__ float caustics(GraphicsContext& ctx,float2 p,float t){
  float2 q = p / 0.07f;
  q =q +(0.35f* sb_vec2(gnoise(ctx,q * 0.31f+ sb_vec2(t * 0.55f,0.0f)),gnoise(ctx,q * 0.31f+ sb_vec2(5.2f,(0-(t ))* 0.47f))));
