__device__ void main(GraphicsContext& ctx){
  float3 P = ctx.vWorld;
  float3 V = normalize(ctx.cameraPosition - P);
  float dist = ctx.vViewZ;
  ctx.gDist =dist;
  float2 dx = __sb_dFdx(sb_sw_xz(P)), dy = __sb_dFdy(sb_sw_xz(P));
  float foot = 0.5f* sb_max(length(dx),length(dy));
  float3 Nb = normalize(ctx.vNb);
  float3 Tx = normalize(sb_vec3(Nb.y,(0-(Nb.x)),0.0f));
  float3 Tz = cross(Tx,Nb);
  float3 Vs = sb_vec3(dot(V,Tx),dot(V,Tz),dot(V,Nb));
  float texW = 1.0f- sb_smoothstep(13.0f,18.0f,dist);
  float pomW = 1.0f- sb_smoothstep(4.4f,5.6f,dist);




  float2 suv = sweUV(ctx,sb_sw_xz(P));
  float wOn = 1.0f- ctx.uBeachDebug.x;
  float wSolver = sweInside(ctx,sb_sw_xz(P))* (1.0f- swashFarWeight(ctx,sb_sw_xz(P)));
  float wIn = wSolver * wOn;
  float wFar = (1.0f- wSolver) * wOn;
  float4 sv = __sb_textureLod(3,suv,0.0f);
  float4 swF = sb_vec4(0.0f), fmF = sb_vec4(0.0f);
  float2 wtF = sb_vec2(0.0f);
  if (wFar > 0.0f&& P.z< 6.0f) { swF =swashFar(ctx,sb_sw_xz(P),ctx.uTime); fmF =swashFarFoam(ctx,sb_sw_xz(P),ctx.uTime); }
  if (wFar > 0.0f&& P.z< 12.0f) wtF =swashFarWet(ctx,sb_sw_xz(P),ctx.uTime);
  float hS = wIn * sv.x;
  float hF = wFar * swF.x;
  ctx.gBlur =1.0f+ 0.8f* sb_smoothstep(0.004f,0.03f,hS + hF);


  float3 meanA = sb_sw_xyz(__sb_textureLod(8,sb_vec2(0.5f),14.0f));
  float3 alb = meanA;
  float3 albLo = meanA;
  float3 nS = sb_vec3(0.0f,0.0f,1.0f);
  float ao = 0.8f, rough = 0.35f, crown = 0.3f, peb = 0.0f, hgt = 0.0f, rnd = 0.5f, nLen = 1.0f;
  float hN = 0.5f;
  float shadow = 1.0f;
  float2 xz = sb_sw_xz(P);
  float3 L = ctx.uSunDir;

  if (texW > 0.0f) {
    hexSetup(ctx,sb_sw_xz(P),dx,dy);
    pickDominant(ctx);

    float hsK = sb_max(sb_max(ctx.hs1,sb_max(ctx.hs2,ctx.hs3))/ 1.2f,1.0f);
    float hmax = 0.0120f* hsK, hmin = (0-(0.0026f))* hsK;

    if (pomW > 0.0f) {
      float2 sh = sb_sw_xy(Vs)/ sb_max(Vs.z,0.25f)* pomW;
      const int NS = 10;
      float dh = (hmax - hmin) / float(NS);
      float hk = hmax, Hk = domHeight(ctx,xz + sh * hk);
      float hp = hk, Hp = Hk;
      for (int k = 0; k < NS; k++) {
        if (Hk >= hk) break;
        hp =hk; Hp =Hk;
        hk =hk -(dh);
        Hk =domHeight(ctx,xz + sh * hk);
      }
      float d0 = Hp - hp, d1 = Hk - hk;
      float tt = sb_clamp(d0 / sb_min(d0 - d1,(0-(1e-6f))),0.0f,1.0f);
      if (Hk < hk) tt =1.0f;
      xz =xz +(sh * sb_mix(hp,hk,tt));
    }
    float2 u1 = uv1(ctx,xz), u2 = uv2(ctx,xz), u3 = uv3(ctx,xz);
    float4 A1 = __sb_textureGrad(8,u1,ctx.gx1,ctx.gy1);
    float4 A2 = __sb_textureGrad(8,u2,ctx.gx2,ctx.gy2);
    float4 A3 = __sb_textureGrad(8,u3,ctx.gx3,ctx.gy3);
    A1.w=A1.w*(ctx.hs1); A2.w=A2.w*(ctx.hs2); A3.w=A3.w*(ctx.hs3);
    float3 sb = sb_vec3(A1.w,A2.w,A3.w)+ 0.0060f* ctx.hw;
    float sm = sb_max(sb.x,sb_max(sb.y,sb.z));
    float3 bw = sb_max(sb - sm + 0.00045f,0.0f);
    bw =bw /(bw.x+ bw.y+ bw.z);
    alb =sb_sw_xyz(A1)* bw.x+ sb_sw_xyz(A2)* bw.y+ sb_sw_xyz(A3)* bw.z;
    albLo =sb_sw_xyz(__sb_textureGrad(8,u1,ctx.gx1 * 8.0f,ctx.gy1 * 8.0f))* ctx.hw.x+ sb_sw_xyz(__sb_textureGrad(8,u2,ctx.gx2 * 8.0f,ctx.gy2 * 8.0f))* ctx.hw.y+ sb_sw_xyz(__sb_textureGrad(8,u3,ctx.gx3 * 8.0f,ctx.gy3 * 8.0f))* ctx.hw.z;
    hgt =dot(sb_vec3(A1.w,A2.w,A3.w),bw);
    float3 nw = sb_vec3(0.0f); float4 cc = sb_vec4(0.0f); float aoS = 0.0f;
    if (bw.x> 0.0f) { float4 B = __sb_textureGrad(9,u1,ctx.gx1,ctx.gy1); float3 n = sb_sw_xyz(B)* 2.0f- 1.0f; nw =nw +(bw.x* sb_vec3(rotB(ctx,ctx.hc1,sb_sw_xy(n)),n.z)); aoS =aoS +(bw.x* B.w); cc =cc +(bw.x* __sb_textureGrad(10,u1,ctx.gx1,ctx.gy1)); }
    if (bw.y> 0.0f) { float4 B = __sb_textureGrad(9,u2,ctx.gx2,ctx.gy2); float3 n = sb_sw_xyz(B)* 2.0f- 1.0f; nw =nw +(bw.y* sb_vec3(rotB(ctx,ctx.hc2,sb_sw_xy(n)),n.z)); aoS =aoS +(bw.y* B.w); cc =cc +(bw.y* __sb_textureGrad(10,u2,ctx.gx2,ctx.gy2)); }
    if (bw.z> 0.0f) { float4 B = __sb_textureGrad(9,u3,ctx.gx3,ctx.gy3); float3 n = sb_sw_xyz(B)* 2.0f- 1.0f; nw =nw +(bw.z* sb_vec3(rotB(ctx,ctx.hc3,sb_sw_xy(n)),n.z)); aoS =aoS +(bw.z* B.w); cc =cc +(bw.z* __sb_textureGrad(10,u3,ctx.gx3,ctx.gy3)); }
    nLen =sb_clamp(length(nw),0.05f,1.0f);
