  float m1 = gnoise(ctx,sb_sw_xz(P)/ 0.30f)* 0.6f* octKeep(ctx,0.30f,foot)+ gnoise(ctx,sb_sw_xz(P)/ 0.13f+ 3.7f)* 0.3f* octKeep(ctx,0.13f,foot);
