  float3 seaAlb = ctx.uSeabed * sb_pow(sb_max(lum(ctx,alb)/ sb_max(lum(ctx,meanA * ctx.uBeachGain),1e-3f),0.0f),0.55f)* (1.0f+ 0.08f* m2);
