  float4 fm = __sb_textureLod(4,suv,0.0f)* wIn + fmF * wFar;
  float brk = (P.z< 1.2f&& P.z> (0-(8.0f))) ? brkSurfaceOnly(ctx,sb_sw_xz(P),ctx.uTime): 0.0f;

  float dSmooth = sb_mix(sb_max(sb_max(brk - P.y,0.0f),swF.x),(hS > 2e-4f? hS : 0.0f) + brk,wIn);
  dSmooth =sb_max(dSmooth,0.0f);
  float wDepth = dSmooth > 2e-4f? sb_max(dSmooth - hgt,0.0f): 0.0f;
  float sub = sb_smoothstep(0.0002f,0.0016f,wDepth);


  float edgeN = vnoise(ctx,sb_sw_xz(P)* 41.0f)* 0.0016f+ vnoise(ctx,sb_sw_xz(P)* 7.0f)* 0.0018f;
  float meshCover = sb_smoothstep(0.0009f+ edgeN,0.0021f+ edgeN,dSmooth);



  float fTau = sb_max(ctx.uBeachFilmTau,0.05f);
  float gloss = sb_max(sb_pow(sb_clamp(wt.x,0.0f,1.0f),fTau / 0.35f),sub);

  float retention=sb_mix(.70f,1.55f,rnd)*sb_mix(1.28f,.82f,hN);
