  float wetMem = sb_max(recent,0.82f* (1.0f- sb_smoothstep(0.36f,0.72f,bEff)) * wOn);
  float dry0 = (1.0f- sb_smoothstep(0.12f,0.85f,wetMem)) * (1.0f- sea);

