    float nd = macroNoiseG(ctx,sb_sw_xz(P),sb_vec2(0.7f),dx,dy).y* 0.7f+ macroNoiseG(ctx,sb_sw_xz(P)+ 3.0f,sb_vec2(0.23f),dx,dy).z* 0.3f;
