}






__device__ float3 sheetResidual(GraphicsContext& ctx,float3 own,float2 xz,float t,float ownDX){
  float2 gr; float4 inf;
  float wh = waterHeight(ctx,xz,t,0.016f,gr,inf);

  return sb_vec3(wh - own.x,gr.x- (ownDX - own.x) / 0.04f,gr.y- own.y);
}


__device__ void main(GraphicsContext& ctx){
  float x = lipColumn(ctx,ctx.position.x+ ctx.uLipX0.x);
  float4 meta = sb_vec4(0.0f,(0-(2.0f)),9.0f,0.0f), meta2 = sb_vec4(1.0f,0.0f,0.0f,0.0f); float2 knee = sb_vec2(0.0f);
  float4 EA = ctx.uEvtA[ctx.uSlot];
  float2 q = sb_vec2(EA.z- 0.5f,(0-(0.25f))* EA.y/ 0.45f);
  float above = (0-(1.0f));
  if (!lipCulled(ctx,x,EA)) {
    Brk b = brkAt(ctx,ctx.uSlot,x);
    q =sheetRaw(ctx,b,ctx.aRow,ctx.uTime,meta,meta2,knee);
    above =q.y- brkProfile(ctx,b,q.x,ctx.uTime).x;
  }
  float2 gr; float4 inf;
  bool hidden = meta.y< (0-(1.5f));
  float res = hidden ? 0.0f: waterHeight(ctx,sb_vec2(x,q.x),ctx.uTime,0.016f,gr,inf)- (q.y- above);
  if (hidden) { meta.y=(0-(2.0f)); above =(0-(1.0f)); }
  float3 P = sb_vec3(x,q.y+ res,q.x);
  ctx.vWorld =P; ctx.vNrm =sb_vec3(0.0f,1.0f,0.0f);
  ctx.vLip =sb_vec4(ctx.aRow,meta.x,meta.y,above);
  ctx.vLip2 =sb_vec4(meta.z,meta.w,res,x);
  ctx.vLip3 =meta2;
  ctx.vKnee =knee;
  float4 mv = ctx.viewMatrix * sb_vec4(P,1.0f);
  ctx.vViewZ =(0-(mv.z));
  ctx.gl_Position =ctx.projectionMatrix * mv;
}
