  float3 emitW = glow * fill * (1.0f- Fr) + sb_sw_xyz(rr)+ sb_min(spec * 0.3f,sb_vec3(1.0f));
  float opac = 1.0f- (1.0f- Fr) * (1.0f- fill) * Tm;

