  fc =fc *(sb_mix(0.8f,1.04f,sb_smoothstep(0.35f,0.85f,th)));
  float cov = sb_clamp(aer,0.0f,1.0f);
  float alpha = sb_mix(opac,1.0f,cov);
  float3 emit = emitW * (1.0f- cov) + fc * cov;
  if (row < 1.0f) {

    float3 hf = shadeWater(ctx,s,sb_sw_xy(ctx.gl_FragCoord));
