    gone =1.0f- sb_smoothstep(0.1f,0.3f,tn);
  }
  ctx.gl_FragColor =sb_vec4(emit,alpha)* (born * gone * wet);

  float3 fs = shadeFoam(ctx,normalize(sb_mix(N,sb_vec3(0.0f,1.0f,0.0f),0.6f)),spillW)* swv.y;
  ctx.gl_FragColor =ctx.gl_FragColor * (1.0f- spillW) + sb_vec4(fs * spillW,spillW)* wet;
  if (ctx.uLipDebug == 3) ctx.gl_FragColor =sb_vec4(sb_vec3(aer),1.0f);
  if (ctx.uLipDebug == 4) ctx.gl_FragColor =sb_vec4(opac,Fr * 5.0f,fill,1.0f);
}

__device__ void main(GraphicsContext& ctx){
  lipMain(ctx);


  float edge = lipEdge(ctx,ctx.vWorld.x)* sb_smoothstep(0.12f,0.45f,ctx.vViewZ);
  if (edge < 1.0f) ctx.gl_FragColor =ctx.gl_FragColor *(edge);
  if (ctx.gl_FragColor.w< 0.003f) {ctx.discarded=true;return;}}
