__device__ float chopWeight(GraphicsContext& ctx,float depth0){ return sb_smoothstep(0.05f,1.2f,depth0); }




__device__ float waterParts(GraphicsContext& ctx,float2 xz,float t,float lod,float2& gMacro,float3& chop,float2& gChop,float4& info,float& paw){
  float2 d = sb_vec2(0.0f); float crestFoam = 0.0f;


  float aa = 1.0f- sb_smoothstep(0.08f,0.35f,lod);
  float eta = 0.0f;
  eta =brkSurface(ctx,xz,t,d,crestFoam);
  float etaX = brkSurfaceOnly(ctx,xz + sb_vec2(0.04f,0.0f),t);
  d.x=(etaX - eta) / 0.04f;
  eta =eta *(aa); d =d *(aa); crestFoam =crestFoam *(aa);
  ctx.gBrkEta =eta;
  float B = bedProfileT(ctx,xz.y);
  float depth0 = sb_max((0-(B)),0.0f);
  float chopW = chopWeight(ctx,depth0);

  chopW =chopW *(1.0f/ (1.0f+ 1.5f* dot(d,d)));
  paw =catsPaw(ctx,xz,t,lod);
  chop =sb_vec3(0.0f); gChop =sb_vec2(0.0f);



  float chopFar = 1.0f- sb_smoothstep(ctx.uSeaTune4.z,ctx.uSeaTune4.w,viewDistH(ctx,xz));
  if (chopW > 0.0f) { chop =oceanDisp(ctx,xz,lod,paw,gChop)* chopW; gChop =gChop *(chopW); }
  chop =chop *(chopFar);

  {float2 sb_write3=sb_sw_xz(chop)*(1.0f- sb_smoothstep(0.04f,0.2f,eta));chop.x=sb_write3.x;chop.z=sb_write3.y;}float wIn = sweInside(ctx,xz);
  float4 sv = __sb_textureLod(4,sweUV(ctx,xz),0.0f);
  float sweEta = sb_mix(0.0f,sv.w,wIn);
  float sweH = sv.x;

  float wF = swashFarWeight(ctx,xz);
  if (wF > 0.0f) {
    float4 sf = swashFar(ctx,xz,t);
    sweEta =sb_mix(sweEta,sf.w,wF);
    sweH =sb_mix(sweH,sf.x,wF);
  }
  gMacro =d;
  info =sb_vec4(crestFoam,sweH,sb_max(wIn,wF),chopW);
  return sweEta + eta;
}

__device__ float2 clampLen(GraphicsContext& ctx,float2 g,float m){ float l = length(g); return l > m ? g * (m / l) : g; }




__device__ float2 sweGradient(GraphicsContext& ctx,float2 xz,float e0,float4& far){
  float2 g = sb_vec2(0.0f);
  far =sb_vec4(0.0f);
  float wIn = sweInside(ctx,xz);
  if (wIn > 0.0f) {
    float2 uv = sweUV(ctx,xz); float2 e = ctx.uSweTexel * e0;
    float wE = __sb_textureLod(4,uv + sb_vec2(e.x,0.0f),0.0f).w, wW = __sb_textureLod(4,uv - sb_vec2(e.x,0.0f),0.0f).w;
    float wN = __sb_textureLod(4,uv + sb_vec2(0.0f,e.y),0.0f).w, wS = __sb_textureLod(4,uv - sb_vec2(0.0f,e.y),0.0f).w;
    g =wIn * sb_vec2(wE - wW,wN - wS)/ (2.0f* e * sb_sw_zw(ctx.uSweDom));
  }
  float wF = swashFarWeight(ctx,xz);
  if (wF > 0.0f) {

    float h = 0.03f;
    float3 w = sb_vec3(0.0f);
    for (int k = 0; k < 3 + sb_min(ctx.uEvtCount,0); k++) {
      float2 p = xz + (k == 1 ? sb_vec2(h,0.0f): (k == 2 ? sb_vec2(0.0f,h): sb_vec2(0.0f)));
      float4 fk = swashFar(ctx,p,ctx.uTime);
      if (k == 0) { w.x=fk.w; far =fk; } else if (k == 1) w.y=fk.w; else w.z=fk.w;
    }
    g =sb_mix(g,sb_vec2(w.y- w.x,w.z- w.x)/ h,wF);
  }
  return g;
}




__device__ float waterHeight(GraphicsContext& ctx,float2 xz,float t,float lod,float2& grad,float4& info){
  float2 gm, gc; float3 ch; float paw;
  float y = waterParts(ctx,xz,t,lod,gm,ch,gc,info,paw);
  grad =gm + gc;
  return y + ch.y;
}

























__device__ float4 crestGeometry(GraphicsContext& ctx,float2 xz,float t,float etaR,float3& aux,float3& faceNormal){
  aux =sb_vec3(0.0f,1.0f,0.0f); faceNormal=sb_vec3(0.0f,1.0f,0.0f);

  int best = (0-(1)); float bestD = 2.5f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f|| t < b.tb- 9.0f|| t > b.ti+ 0.6f) continue;
    float dC = sb_abs(xz.y- brkCrestZ(ctx,b,t));
    if (dC < bestD) { bestD =dC; best =i; }
  }
  if (best < 0) return sb_vec4(0.0f);
  Brk b = brkAt(ctx,best,xz.x);
  float tn = brkTn(ctx,b,t);
  if (tn < (0-(6.0f))|| tn > 0.85f) return sb_vec4(0.0f);
  BrkStage g = brkStage(ctx,tn);
  float2 A = brkApex(ctx,b,g,tn);

  float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str;
  float2 sh0 = brkShape(ctx,g,(xz.y- A.x) / b.s);
  float eta0 = sh0.x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y));
  aux.z=sb_max((0-(sh0.y))* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y)),0.0f);

  float fd = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  float ya = g.ya* b.s* amp * fd, yt = g.yt* b.s* amp * fd;
  eta0 =sb_clamp(etaR,yt,ya);
  float sFace = sb_clamp((ya - eta0) / sb_max(ya - yt,0.05f),0.0f,1.2f);



  if(g.st>.12f){
  float xiFace=brkFrontXi(ctx,g,sb_clamp(1.0f-sFace,.001f,.999f));
  if(xz.y<A.x) xiFace=(0-(g.lb))*acosh(sb_sqrt(sb_max(ya/sb_max(eta0,.0001f),1.00001f)));
  float dzSlope=brkShape(ctx,g,xiFace).y*amp*fd;


  float zLeft=0.0f,zRight=0.0f;
  for(int n=0;n<2+sb_min(ctx.uEvtCount,0);n++){
    Brk nb=brkAt(ctx,best,xz.x+(float(n)-.5f)*.5f);
    float zc=nb.zI-b.c*(nb.ti-nb.D-b.ti);
    if(n==0)zLeft=zc;else zRight=zc;
  }
  float crestTilt=sb_clamp((zRight-zLeft)/.5f,(0-(.6f)),.6f);
  faceNormal=normalize(sb_vec3(crestTilt*dzSlope,1.0f,(0-(dzSlope))));
  }
  float hMax = eta0, occ = 0.0f;
  float rise = ctx.uSunDir.y/ sb_max((0-(ctx.uSunDir.z)),0.05f);
  for (int k = 1; k <= 8 + sb_min(ctx.uEvtCount,0); k++) {
    float dz = 0.04f* sb_pow(float(k),1.6f);
    float zk = xz.y- dz;
    float y = brkShape(ctx,g,(zk - A.x) / b.s).x* b.s* amp * (1.0f- sb_smoothstep((0-(1.0f)),0.1f,zk));
    hMax =sb_max(hMax,y);
    occ =sb_max(occ,y - eta0 - rise * dz);
  }


  float support=1.0f-sb_smoothstep(1.45f,2.48f,bestD);
  aux.x=(hMax - eta0)*support;
  aux.z=aux.z*(support);



  float xi = (xz.y- A.x) / b.s;
  if (xz.y> (0-(9.0f))&& xz.y< 0.5f&& tn > (0-(1.6f))&& tn < 0.25f&& xi > (0-(0.3f))) {
    float ahead = (xi - g.lf) * b.s;
    float fa = sb_smoothstep((0-(0.1f)),0.1f,ahead);
    float live = sb_mix(1.0f- sb_smoothstep((0-(0.05f)),0.25f,tn),0.85f* (1.0f- sb_smoothstep((0-(0.45f)),(0-(0.15f)),tn)),fa);
    aux.y=1.0f- sb_smoothstep((0-(0.3f)),0.0f,xi)* sb_smoothstep(0.55f,0.1f,ahead)* sb_smoothstep((0-(1.6f)),(0-(0.9f)),tn)* live;
  }
  aux.y=sb_mix(1.0f,aux.y,support);
  return sb_vec4(sFace,g.st,occ*support,support);
}









__device__ float4 oceanSlopeLEAN(GraphicsContext& ctx,float2 xz,float paw,float w,float lodBias){
  float2 ex = __sb_dFdx(xz), ey = __sb_dFdy(xz);
  float lx = length(ex), ly = length(ey);
  float lmaj = sb_max(sb_max(lx,ly),1e-6f);
  float kb = sb_exp2(lodBias);
  if (lx < lmaj / 6.0f) ex =(lx > 1e-7f? ex / lx : sb_vec2(1.0f,0.0f)) * (lmaj / 6.0f);
  if (ly < lmaj / 6.0f) ey =(ly > 1e-7f? ey / ly : sb_vec2(0.0f,1.0f)) * (lmaj / 6.0f);
  ex =ex *(kb); ey =ey *(kb);



  float3 kc = sb_exp2(sb_sw_xyz(ctx.uSeaTune5));
  float4 s0 = __sb_textureGradArray(3,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),ctx.OCR0 * ex * kc.x/ ctx.uOceanL.x,ctx.OCR0 * ey * kc.x/ ctx.uOceanL.x);
  float4 s1 = __sb_textureGradArray(3,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),ctx.OCR1 * ex * kc.y/ ctx.uOceanL.y,ctx.OCR1 * ey * kc.y/ ctx.uOceanL.y);
  float4 s2 = __sb_textureGradArray(3,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),ctx.OCR2 * ex * kc.z/ ctx.uOceanL.z,ctx.OCR2 * ey * kc.z/ ctx.uOceanL.z);
  paw =sb_max(paw,0.0f);
  float3 a = sb_sw_xyz(ctx.uOceanAmp)* sb_vec3(oceanFarGain(ctx,xz),sb_sqrt(paw),paw)* sb_clamp(w,0.0f,1.0f);
  float2 m = (sb_sw_xy(s0)* ctx.OCR0) * a.x+ (sb_sw_xy(s1)* ctx.OCR1) * a.y+ (sb_sw_xy(s2)* ctx.OCR2) * a.z;
  float2 v = ocVar(ctx,sb_max(sb_sw_zw(s0)- sb_sw_xy(s0)* sb_sw_xy(s0),0.0f),ctx.OCC2.x)* a.x* a.x+ ocVar(ctx,sb_max(sb_sw_zw(s1)- sb_sw_xy(s1)* sb_sw_xy(s1),0.0f),ctx.OCC2.y)* a.y* a.y+ ocVar(ctx,sb_max(sb_sw_zw(s2)- sb_sw_xy(s2)* sb_sw_xy(s2),0.0f),ctx.OCC2.z)* a.z* a.z;
  return sb_vec4(m,v);
}








__device__ float facetNoise(GraphicsContext& ctx,float2 xz,float t){


  float D = sb_max(ctx.cameraPosition.z- xz.y,0.5f);
  float2 q0 = sb_vec2(xz.x/ D,xz.y- 0.9f* t);
  float pa = sb_max(sb_max(sb_abs(__sb_dFdx(q0.x)),sb_abs(__sb_dFdy(q0.x))),1e-6f);
  float pz = sb_max(sb_abs(__sb_dFdy(xz.y)),sb_abs(__sb_dFdx(xz.y)));
  float lz = sb_log2(sb_max(pz * ctx.uSeaTune6.z,1e-4f));
  float l0 = sb_floor(lz), f = lz - l0;
  float2 s0 = sb_vec2(pa * ctx.uSeaTune6.w,sb_exp2(l0)), s1 = sb_vec2(pa * ctx.uSeaTune6.w,sb_exp2(l0 + 1.0f));


  const SBMat2 FSH = sb_mat2(0.955f,(0-(0.296f)),0.296f,0.955f);
  float n0 = vnoise3(ctx,sb_vec3(FSH * (q0 / s0),t * 2.5f))- 0.5f;
  float n1 = vnoise3(ctx,sb_vec3(transpose(FSH)* (q0 / s1) + sb_vec2(17.0f,31.0f),t * 2.5f+ 7.3f))- 0.5f;
  return (n0 * (1.0f- f) + n1 * f) / sb_sqrt(sb_max((1.0f- f) * (1.0f- f) + f * f,1e-3f))* 5.5f;
}


__device__ float3 shadeFoam(GraphicsContext& ctx,float3 N,float dense){

  float wrap = sb_clamp((dot(N,ctx.uSunDir)+ 0.8f) / 1.8f,0.0f,1.0f);

  float3 albedo = sb_vec3(0.91f,0.93f,0.905f);
  float3 c = albedo * (ctx.uSunColor * wrap / 3.14159f+ skyAmbient(ctx,N)* 1.0f);
  return c * sb_mix(1.0f,0.93f,dense);
}




__device__ float3 skyRefl(GraphicsContext& ctx,float3 d){

  float sy = sb_max(d.y,0.0f);
  float3 c = sb_sw_xyz(__sb_textureLod(11,sb_vec2(sb_sqrt(sy)* (255.0f/ 256.0f) + 0.5f/ 256.0f,0.5f),0.0f));
  float azs = sb_clamp(d.x/ sb_max(length(sb_sw_xz(d)),1e-3f),(0-(0.985f)),0.985f);
  float fe = sb_clamp(sy * 2.63f,0.0f,1.0f);



  c =c *((1.0f+ sb_mix(0.0029f,0.0043f,fe)* 57.3f* azs) * (1.0f+ sb_vec3(0.005f,0.0011f,(0-(0.0005f)))* fe * fe * 57.3f* azs));
  return sb_mix(ctx.uDeepColor * 1.1f+ sb_vec3(0.02f,0.05f,0.06f),c,sb_smoothstep((0-(0.07f)),0.009f,d.y));
}






__device__ float smithG1(GraphicsContext& ctx,float tE,float sigS){
  if (tE <= 0.0f) return 0.0f;
  float a = tE / (1.41421f* sb_max(sigS,1e-3f));
  if (a >= 1.6f) return 1.0f;
  float L = (1.0f- 1.259f* a + 0.396f* a * a) / (3.535f* a + 2.181f* a * a);
  return 1.0f/ (1.0f+ L);
}



__device__ float4 roughReflection(GraphicsContext& ctx,float3 N,float3 V,float sigV,float sigS){
  float mu0 = sb_clamp(dot(N,V),(0-(1.0f)),1.0f);
  float3 e = V - N * mu0;
  float le = length(e);
  e =le > 1e-5f? e / le : sb_vec3(0.0f,0.0f,1.0f);
  float d0 = asin(sb_clamp(mu0,(0-(1.0f)),1.0f));
  float sLo = sb_max((0-(3.0f))* sigV,tan((0-(d0 ))+ 0.002f));
  float sHi = 3.2f* sigV;
  if (sHi <= sLo) { sLo =tan((0-(d0 ))+ 0.002f); sHi =sLo + 0.1f; }
  float3 acc = sb_vec3(0.0f); float fAcc = 0.0f, wAcc = 0.0f;
  const int K = 5;


  float s0 = sb_max(sLo,0.0f);
  float iv = 0.5f/ sb_max(sigV * sigV,1e-6f);
  for (int i = 0; i < K + sb_min(ctx.uEvtCount,0); i++) {
    float s = sb_mix(sLo,sHi,(float(i)+ 0.5f) / float(K));
    float3 n = normalize(N + s * e);
    float mu = dot(n,V);
    if (mu <= 0.0f) continue;
    float g = sb_exp((0-(sb_min((s * s - s0 * s0) * iv,60.0f))));
    float w = g * mu / dot(n,N);
    float3 r = reflect((0-(V)),n);
    float F = fresnelWater(ctx,mu);


    float G = smithG1(ctx,r.y/ sb_max(length(sb_sw_xz(r)),1e-4f),sigS);
    acc =acc +(w * F * sb_mix(ctx.uDeepColor * 1.1f+ sb_vec3(0.02f,0.05f,0.06f),skyRefl(ctx,r),G));
    fAcc =fAcc +(w * F);
    wAcc =wAcc +(w);
  }
  float4 result = sb_vec4(0.0f);
  if (wAcc < 1e-12f) result =sb_vec4(skyRefl(ctx,reflect((0-(V)),N)),1.0f);
  else result =sb_vec4(acc / wAcc,fAcc / wAcc);
  return result;
}



__device__ float3 bedRadiance(GraphicsContext& ctx,float3 Pb,float hCol,float3 sigT){
  float cs = sb_sqrt(1.0f- (1.0f- ctx.uSunDir.y* ctx.uSunDir.y) / (1.333f* 1.333f));
  float e = 0.08f;
  float bz = (bedProfileT(ctx,Pb.z+ e)- bedProfileT(ctx,Pb.z- e)) / (2.0f* e);
  float3 Nb = normalize(sb_vec3(0.0f,1.0f,(0-(bz))));
  float ndl = sb_max(dot(Nb,ctx.uSunDir),0.0f);

  float patchy = 0.7f+ 0.25f* vnoise(ctx,sb_sw_xz(Pb)* sb_vec2(0.35f,0.5f)+ 3.7f);


  float uL = sb_clamp((0-(Pb.x))/ (0.36f* sb_max(ctx.cameraPosition.z- Pb.z,1.0f)),(0-(1.0f)),1.0f);
  float3 alb = ctx.uBedAlbedo * patchy * (1.0f+ ctx.uBedAlbedoLR * uL);

  alb =alb *(sb_mix(sb_vec3(0.48f,0.72f,0.72f),sb_vec3(1.0f),sb_smoothstep((0-(5.5f)),(0-(9.5f)),Pb.z)));
  float3 Tsun = sb_exp((0-(sigT ))* hCol / cs);
  float3 Tsky = sb_exp((0-(sigT ))* hCol * 1.25f);
  return alb * (ctx.uSunColor * ndl * Tsun / 3.14159f+ ctx.uSkyAmb * Tsky * 0.85f);
}





__device__ float3 screenBed(GraphicsContext& ctx,float3 Pb){
  float4 c = ctx.projectionMatrix * (ctx.viewMatrix * sb_vec4(Pb,1.0f));
  if (c.w<= 0.0f) return sb_vec3((0-(1.0f)));
  float2 uv = sb_sw_xy(c)/ c.w* 0.5f+ 0.5f;
  if (any(lessThan(uv,sb_vec2((0-(0.03f)))))|| any(greaterThan(uv,sb_vec2(1.03f)))) return sb_vec3((0-(1.0f)));
  uv =sb_clamp(uv,0.5f/ ctx.uResolution,1.0f- 0.5f/ ctx.uResolution);
  float dS = linearizeDepth(ctx,__sb_textureLod(9,uv,0.0f).x);
  if (dS < c.w- 0.05f- 0.03f* c.w) return sb_vec3((0-(1.0f)));
  return sb_sw_xyz(__sb_textureLod(8,uv,0.0f));
}


__device__ float hash13g(GraphicsContext& ctx,float3 p3){ p3 =sb_fract(p3 * 0.1031f); p3 =p3 +(dot(p3,sb_sw_zyx(p3)+ 31.32f)); return sb_fract((p3.x+ p3.y) * p3.z); }





__device__ float3 shadeWaterFull(GraphicsContext& ctx,WIn s,float2 fragXY,float2 sig2,float rough,float4 crest,float facetTilt){

  float3 N = s.N, V = s.V, L = ctx.uSunDir;
  float NoV = sb_max(dot(N,V),1e-4f);
  float micro = ctx.uOptics.x+ sb_clamp(s.turb,0.0f,2.0f)* 0.05f;
  float2 var2 = sb_max(sig2,sb_vec2(0.0f))+ micro * micro;

  float3 e = normalize(V - N * dot(N,V)+ sb_vec3(0.0f,1e-5f,0.0f));
  float sigV = sb_sqrt(var2.x* e.x* e.x+ var2.y* e.z* e.z+ micro * micro * e.y* e.y);


  float graze = 1.0f- sb_smoothstep(ctx.uSeaTune2.y,ctx.uSeaTune2.z,V.y);
  float xr = rough * graze;




  float skewH = ctx.uSeaTune6.x* (1.0f- sb_smoothstep(0.0f,ctx.uSeaTune6.y,V.y));
  float3 Nr = normalize(N + e * ((ctx.uSeaTune3.z+ facetTilt) * graze + skewH));
  float4 rr = roughReflection(ctx,Nr,V,sb_sqrt(sigV * sigV + xr * xr),ctx.uSeaTune2.x);
  float3 refl = sb_sw_xyz(rr);
  float F = rr.w;

  float3 H = normalize(V + L);
  float NoL = sb_max(dot(N,L),0.0f);
  float cH = sb_max(dot(H,N),0.05f);
  float3 Ht = H / cH - N;


  float3 tangentX=normalize(sb_vec3(1.0f,0.0f,0.0f)-N*N.x+sb_vec3(0.0f,0.00001f,0.0f));
  float3 tangentZ=normalize(cross(tangentX,N));
  float2 sl = sb_vec2(dot(Ht,tangentX),dot(Ht,tangentZ));



  float sGmin = sb_mix(ctx.uSeaTune3.x,ctx.uSeaTune3.w,graze), sGmax = sb_mix(ctx.uSeaTune3.y,ctx.uSeaTune3.w,graze);
  float crestG = 1.0f+ ctx.uGlint.z* sb_clamp(s.crest,0.0f,1.0f);
  sGmin =sGmin *(crestG); sGmax =sGmax *(crestG);


  sGmin =sb_mix(sGmin,ctx.uFilm.y,s.film); sGmax =sb_mix(sGmax,0.4f,s.film);
  float2 varG = sb_clamp(var2,sb_vec2(sGmin * sGmin),sb_vec2(sGmax * sGmax));
  float ex = sb_min(0.5f* (sl.x* sl.x/ varG.x+ sl.y* sl.y/ varG.y),80.0f);
  float Dsun = sb_exp((0-(ex)))/ (6.2831853f* sb_sqrt(varG.x* varG.y)* cH * cH * cH * cH);
  float Fs = fresnelWater(ctx,sb_max(dot(V,H),0.0f));

  float sG = sb_sqrt(sb_max(varG.x,varG.y));
  float Gs = smithG1(ctx,NoV / sb_sqrt(sb_max(1.0f- NoV * NoV,1e-4f)),sG)* smithG1(ctx,NoL / sb_sqrt(sb_max(1.0f- NoL * NoL,1e-4f)),sG);
  float3 sunMean = ctx.uSunColor * sb_min(Dsun * Fs * Gs * 0.25f/ sb_max(NoV,0.05f),2000.0f);




  float3 sunSpec = sunMean;
  {
    const float3 LUM = sb_vec3(0.2126f,0.7152f,0.0722f);
    float3 dPx = __sb_dFdx(s.P), dPy = __sb_dFdy(s.P);
    float Apx = sb_max(length(cross(dPx,dPy)),1e-9f);
    const float Af = 1.0e-4f;
    float lumG = dot(ctx.uSunColor,LUM)* (Fs / 6.8e-5f);
    float frac = dot(sunMean,LUM)/ sb_max(lumG,1e-6f);
    float gain = sb_max(ctx.uOptics.y,1e-3f);
    float pxW = sb_sqrt(Apx);




    float sres = sb_min(ctx.uResolution.x,ctx.uResolution.y)/ 1080.0f;
    float sig = sb_max(ctx.uGlint.x* sres,0.4f* sb_sqrt(Af)/ pxW);
    float C = 4.0f* sig;
    float mu = frac * C * C * Apx / Af * gain;


    mu =mu *(sb_mix(1.0f,ctx.uGlint.w,crest.w* (1.0f- sb_clamp(s.crest,0.0f,1.0f))));


    float cl = vnoise(ctx,sb_sw_xz(s.P)* sb_vec2(2.2f,3.4f)+ sb_vec2(0.6f,(0-(0.9f)))* ctx.uTime);
    mu =mu *(sb_mix(0.03f,14.0f,sb_smoothstep(0.6f,0.9f,cl)));


    float sigM = sig * pxW;
    float peak = sb_min(Af / (6.2831853f* sigM * sigM) / gain * lumG,ctx.uGlint.y);
    float fr = sb_floor(ctx.uTime * 60.0f+ 0.5f);
    float dense = sb_smoothstep(0.8f,3.0f,mu);
    float acc = 0.0f;
    if (mu > 1e-4f&& dense < 1.0f&& ctx.uDbg.x> (0-(1.5f))) {
      float2 v = fragXY / C;
      float2 c0 = sb_floor(v - 0.5f);
      for (int n = 0; n < 4 + sb_min(ctx.uEvtCount,0); n++) {
        float2 cid = c0 + sb_vec2(float(n - (n / 2) * 2),float(n / 2));
        float3 h = hash33(ctx,sb_vec3(cid + 7919.0f,fr));
        float k = sb_floor(mu + h.x);
        float2 dv = (v - cid - 0.2f- 0.6f* sb_sw_yz(h)) * C;

        acc =acc +(k * sb_exp((0-(0.5f))* dot(dv * sb_vec2(0.85f,1.2f),dv * sb_vec2(0.85f,1.2f))/ (sig * sig))* sb_smoothstep(0.7f* C,0.4f* C,length(dv)));
      }
    }

    float3 tint = normalize(ctx.uSunColor)* 1.732f* sb_vec3(0.65f,1.0f,1.05f);
    float3 sunGl = sb_min(acc * peak * tint,sb_vec3(ctx.uSeaTune2.w));
    if (dense > 0.0f) {
      float spk = (0-(sb_log(sb_max(hash13g(ctx,sb_vec3(fragXY,fr)),1e-3f))));
      sunGl =sb_mix(sunGl,sb_min(sunMean * spk,sb_vec3(ctx.uSeaTune2.w)),dense);
    }

    sunSpec =sb_mix(sunGl,sb_min(sunMean,sb_vec3(ctx.uSeaTune2.w)),s.film);
  }



  float2 suv = fragXY / ctx.uResolution;
  float dScene = linearizeDepth(ctx,__sb_textureLod(9,suv,0.0f).x);
  float ib = __sb_textureLod(10,suv,0.0f).x;
  float dBack = ib > 0.0f? 1.0f/ ib : 1.0e6f;
  bool exitsBack = dBack > s.viewZ+ 0.003f&& dBack < dScene;
  float thick = sb_max((exitsBack ? dBack : dScene) - s.viewZ,0.0f);
  if (s.thickHint> 0.0f) { thick =sb_min(thick,s.thickHint); exitsBack =true; }



  float turbid = sb_smoothstep((0-(5.0f)),(0-(3.2f)),s.P.z)* ctx.uTurbidColor.w;
  float3 sigT = sb_mix(ctx.uWaterAtten,ctx.uTurbidAtten,turbid);
  float3 Lin = sb_mix(ctx.uDeepColor,sb_sw_xyz(ctx.uTurbidColor),turbid);


  float aer = sb_clamp(s.aer,0.0f,1.0f);
  float silt = sb_clamp(s.silt* ctx.uSilt.w,0.0f,1.0f);
  sigT =sigT +(ctx.uAerate.z* aer + 12.0f* silt);
  float3 body;
  float3 Tr = refract((0-(V)),N,1.0f/ 1.333f);
  {

    float hC = sb_max(s.P.y- hydraulicBedHeight(ctx,sb_sw_xz(s.P)),0.0f);
    float ty = sb_max((0-(Tr.y)),0.12f);
    float3 Pb = s.P+ Tr * (hC / ty);
    float hB = sb_max(s.P.y- hydraulicBedHeight(ctx,sb_sw_xz(Pb)),0.0f);
    Pb =s.P+ Tr * (hB / ty);
    float sPath = length(Pb - s.P);
    float3 Lbed = sb_vec3((0-(1.0f)));
    float nearW = sb_smoothstep((0-(6.0f)),(0-(4.5f)),s.P.z);
    if (nearW > 0.0f) {


      float rb = sb_clamp(hB * 0.22f,0.0015f,0.03f);
      float3 b0 = screenBed(ctx,Pb);
      if (b0.x>= 0.0f) {
        float3 b1 = screenBed(ctx,Pb + sb_vec3(rb,0.0f,0.5f* rb));
        float3 b2 = screenBed(ctx,Pb - sb_vec3(0.5f* rb,0.0f,rb));
        float3 acc = b0; float n = 1.0f;
        if (b1.x>= 0.0f) { acc =acc +(b1); n =n +(1.0f); }
        if (b2.x>= 0.0f) { acc =acc +(b2); n =n +(1.0f); }
        Lbed =acc / n;
      } else if (dScene > s.viewZ) {

        Lbed =sb_sw_xyz(__sb_textureLod(8,suv,0.0f));
      }
    }


    float3 T = sb_exp((0-((sigT + ctx.uCrestShade.w* crest.w* crest.w* crest.w) ))* sPath);
    float3 Lan = T.y> 0.004f? bedRadiance(ctx,Pb,s.P.y- Pb.y,sigT): sb_vec3(0.0f);
    if (Lbed.x< 0.0f) Lbed =Lan; else Lbed =sb_mix(Lan,Lbed,nearW);









    float fw = crest.w;
    float3 top = sb_mix(sb_sw_xyz(ctx.uFaceThick),sb_sw_xyz(ctx.uFaceGlow),sb_smoothstep(0.1f,0.9f,crest.y));
    float3 faceIn = top * sb_max(1.0f- sb_sw_xyz(ctx.uFaceSig)* crest.x* crest.x,sb_vec3(0.15f));
    float3 LinF = sb_mix(Lin,faceIn,fw);


    LinF =sb_mix(sb_vec3(dot(LinF,sb_vec3(0.2126f,0.7152f,0.0722f))),LinF,1.0f- sb_exp((0-(sPath ))* 2.5f));

    float3 shade = sb_mix(sb_vec3(1.0f),sb_sw_xyz(ctx.uCrestShade),(1.0f- sb_exp((0-(crest.z))/ ctx.uFaceSig.w)) * (1.0f- fw));
    body =(Lbed * T + LinF * (1.0f- T)) * shade;
  }



  if(exitsBack){
    float path=thick/sb_max(NoV*.55f+.45f,.25f);
    float3 T=sb_exp((0-(sigT))*path);
    float phase=.18f+.82f*sb_pow(sb_max(dot((0-(V)),L),0.0f),5.0f);
    float3 scatter=sb_mix(Lin,ctx.uGlowTint*ctx.uOptics.z*.30f*phase,.55f);
    float3 behind=sb_sw_xyz(__sb_textureLod(8,suv,0.0f));
    float3 sheet=behind*T+scatter*(1.0f-T);
    float confidence=sb_smoothstep(.004f,.055f,thick)*(1.0f-sb_smoothstep(.12f,.65f,path));
    confidence=confidence*(sb_smoothstep(.01f,.16f,dScene-dBack));
    if(s.thickHint>0.0f) confidence=1.0f;
    body=sb_mix(body,sheet,confidence);
  }



  float skyLum = dot(skyAmbient(ctx,N),sb_vec3(0.2126f,0.7152f,0.0722f));
  float3 lit = ctx.uSunColor * 0.25f+ sb_vec3(skyLum);


  float dW = s.P.y- hydraulicBedHeight(ctx,sb_sw_xz(s.P));
  float swFilm = sb_smoothstep((0-(1.8f)),(0-(0.6f)),s.P.z)* (1.0f- sb_smoothstep(0.02f,0.25f,dW));
  float milkAmt = sb_max(sb_clamp(s.milk* ctx.uAerate.y,0.0f,1.0f),ctx.uAerate.x* aer);
  milkAmt =sb_max(milkAmt,ctx.uMilkBase * swFilm);

  milkAmt =milkAmt *(1.0f- crest.w);


  float toe = sb_smoothstep(ctx.uToe.w,ctx.uToe.w+ 0.9f,s.turb)* sb_smoothstep(0.04f,0.1f,dW)* (1.0f- crest.w);
  milkAmt =milkAmt *(1.0f- 0.6f* toe);


  body =sb_mix(body,sb_sw_xyz(ctx.uMurk),sb_clamp(s.murk* ctx.uMurk.w,0.0f,1.0f)* (1.0f- crest.w));

  body =sb_mix(body,sb_sw_xyz(ctx.uSilt)* lit * 0.5f,silt * (1.0f- sb_exp((0-(thick ))* 25.0f)));

  body =sb_mix(body,ctx.uMilkColor * lit * 0.5f,milkAmt * (1.0f- sb_exp((0-(thick ))* 7.0f)));
  body =sb_mix(body,sb_sw_xyz(ctx.uToe),0.7f* toe);


  body =sb_mix(body,sb_sw_xyz(ctx.uFoamShade),sb_clamp(s.under,0.0f,1.0f)* ctx.uFoamShade.w);




  refl =refl *(1.0f- ctx.uFilm.z* s.film);



  float swS = sb_clamp(s.swash,0.0f,1.0f)* ctx.uSwashRefl.x;
  refl =sb_mix(refl,sb_vec3(dot(refl,sb_vec3(0.2126f,0.7152f,0.0722f)))* sb_vec3(1.04f,1.0f,0.92f),swS)* (1.0f- ctx.uSwashRefl.y* swS);
  if (ctx.uDbg.z> 0.5f) refl =refl *(ctx.uDbg.w);
  float3 col = body * (1.0f- F) + refl + sunSpec;



  float3 fc = shadeFoam(ctx,normalize(sb_mix(N,sb_vec3(0.0f,1.0f,0.0f),0.3f)),s.foamDense);
  float dns = sb_clamp(s.foamDense,0.0f,1.0f);
  fc =sb_mix(sb_mix(fc,body,0.12f),fc,dns)* sb_mix(0.82f,1.1f,dns);
  col =sb_mix(col,fc,sb_clamp(s.foam,0.0f,1.0f));
  if (ctx.uDbg.x> 0.5f) {
    float q = ctx.uDbg.x< 1.5f? crest.x: ctx.uDbg.x< 2.5f? crest.y: ctx.uDbg.x< 3.5f? crest.z: ctx.uDbg.x< 4.5f? crest.w: ctx.uDbg.x< 5.5f? turbid : ctx.uDbg.x< 6.5f? milkAmt : ctx.uDbg.x< 7.5f? aer : ctx.uDbg.x< 8.5f? s.murk: ctx.uDbg.x< 9.5f? F : s.foam;
    col =ctx.uDbg.x< 10.5f? sb_vec3(q * ctx.uDbg.y): ctx.uDbg.x< 11.5f? body : refl;
  }
  return col;
}



__device__ float3 shadeWater(GraphicsContext& ctx,WIn s,float2 fragXY){

  if (dot(s.N,s.V)< 0.0f) s.N=(0-(s.N));
  float r = sb_max(s.rough- ctx.uOptics.x,0.0f);
  s.aer=0.0f; s.murk=0.0f; s.film=0.0f; s.silt=0.0f; s.swash=0.0f; s.under=0.0f;


  float fwL = sb_smoothstep(0.05f,0.5f,s.N.z);
  return shadeWaterFull(ctx,s,fragXY,sb_vec2(r * r),ctx.uSeaTune.x,sb_vec4(0.2f,1.0f,0.0f,fwL),0.0f);
}




__device__ float foamHoles(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float acc = 0.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float3 hh = hash32(ctx,i + g);
    float2 r = g + sb_sw_xy(hh)- f;
    float a = dot(r,t);
    float d = sb_sqrt(sb_max(dot(r,r)- k * a * a,0.0f))+ 0.9f* hh.z;
    acc =acc +(sb_exp((0-(d ))* 12.5f));
  }
  return (0-(0.08f))* sb_log(sb_max(acc,1e-30f));
}


__device__ float laceWall(GraphicsContext& ctx,float2 q,float2 t,float k){
  float2 i = sb_floor(q), f = sb_fract(q);
  float f1 = 8.0f, f2 = 8.0f;
  for (int y = (0-(1)); y <= 1; y++) for (int x = (0-(1)); x <= 1; x++) {
    float2 g = sb_vec2(float(x),float(y));
    float2 r = g + hash22(ctx,i + g)- f;
    float a = dot(r,t);
    float d = dot(r,r)- k * a * a;
    if (d < f1) { f2 =f1; f1 =d; } else if (d < f2) { f2 =d; }
  }
  return 0.5f* (sb_sqrt(f2)- sb_sqrt(f1));
}










__device__ FoamSet foamSet(GraphicsContext& ctx,float2 p,float seed,float fp,float2 t,float an,float anL,bool tearOn,bool netOn,float wmul){
  FoamSet s = sb_new_FoamSet(0.5f,0.0f,0.0f,0.0f,0.5f);

  float2 pw = p + ctx.uFoamLook2.w* sb_vec2(gnoise(ctx,p * 1.3f+ sb_vec2(seed,1.7f)),gnoise(ctx,p * 1.3f+ sb_vec2(4.1f- seed,(0-(2.3f)))));
  if (tearOn) {
    float2 q = pw * ctx.uFoamLook2.x;
    q =q +(0.6f* sb_vec2(gnoise(ctx,q * 0.7f+ sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 0.7f+ sb_vec2(5.2f- seed,0.0f))));
    float h = foamHoles(ctx,q + seed * 7.3f,t,1.0f- 1.0f/ (an * an))* sb_sqrt(an);

    float raw = h + 0.25f* gnoise(ctx,p * 1.7f+ sb_vec2(seed * 2.3f,(0-(seed))))- (0.78f+ 0.11f* (an - 1.0f));
    float ca = 0.57f+ 0.092f* (an - 1.0f);
    s.tear=sb_smoothstep((0-(ca)),ca,raw);
    float cw = 0.545f+ 0.1f* (an - 1.0f);
    s.wall=sb_smoothstep((0-(cw)),cw,h - (0.781f+ 0.112f* (an - 1.0f)));
  }
  if (netOn) {
    float2 q = pw * ctx.uFoamLook.x;
    q =q +(0.55f* sb_vec2(gnoise(ctx,q * 0.55f+ sb_vec2(seed,0.0f)),gnoise(ctx,q * 0.55f+ sb_vec2(5.2f- seed,0.0f)))+ 0.2f* sb_vec2(gnoise(ctx,q * 1.9f- sb_vec2(seed * 1.3f,0.0f)),gnoise(ctx,q * 1.9f+ sb_vec2(seed + 1.7f,0.0f))));
    float lf = laceWall(ctx,q + seed * 13.1f,t,1.0f- 1.0f/ (anL * anL));


    float w0 = ctx.uFoamLook.y* wmul;
    float we = sb_max(w0,0.7f* fp * ctx.uFoamLook.x);
    float core = sb_exp((0-((lf * lf) ))/ (we * we))* (w0 / we);


    float seg = sb_smoothstep(0.34f,0.62f,0.5f+ 0.5f* gnoise(ctx,p * 13.0f+ seed * 2.9f));
    float pch = sb_smoothstep((0-(0.25f)),0.65f,gnoise(ctx,p * 2.1f+ sb_vec2(seed * 1.7f,3.1f))+ 0.5f* gnoise(ctx,p * 4.7f- sb_vec2(seed,0.0f)));
    s.net=core * seg * (0.5f+ 0.5f* sb_smoothstep((0-(0.6f)),0.6f,gnoise(ctx,p * 27.0f- seed * 4.1f))) * sb_mix(0.02f,1.55f,pch*pch);
  }


  float ga = 1.0f- sb_smoothstep(0.0015f,0.004f,fp);
  if (ga > 0.0f) s.grain=ga * (1.4f* (vnoise(ctx,p * 380.0f+ seed * 17.0f)- 0.5f) + 0.9f* (vnoise(ctx,p * 760.0f- seed * 9.0f)- 0.5f) * (1.0f- sb_smoothstep(0.0008f,0.002f,fp)));

  float gc = 1.0f- sb_smoothstep(0.006f,0.014f,fp);
  if (gc > 0.0f) s.clump=gc * (0.45f* gnoise(ctx,p * 19.0f- seed * 5.3f)+ 0.25f* gnoise(ctx,p * 43.0f+ seed * 3.1f));
  return s;
}






__device__ float lumpField(GraphicsContext& ctx,float2 p,float seed,float t){
  float n1 = gnoise(ctx,p * 4.5f+ seed), n2 = gnoise(ctx,p * 10.0f+ sb_vec2(0.9f* t,(0-(0.6f))* t)- seed);
  float fold = 1.0f- sb_abs(gnoise(ctx,p * sb_vec2(6.0f,4.0f)+ sb_vec2((0-(0.5f))* t,0.7f* t)+ seed * 0.3f));
  return 0.5f+ 0.5f* (0.6f* n1 + 0.4f* n2) - 0.35f* fold * fold * fold * fold;
}

__device__ float blanketLumps(GraphicsContext& ctx,float2 xz,float2 suv,float t,float wf,float2 farVel){
  const float T = 0.5f;
  float2 e = 3.0f* ctx.uSweTexel;
  float2 vel = 0.4f* sb_sw_yz(__sb_textureLod(4,suv,0.0f))+ 0.15f* (sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(e.x,0.0f),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv + sb_vec2(0.0f,e.y),0.0f))+ sb_sw_yz(__sb_textureLod(4,suv - sb_vec2(0.0f,e.y),0.0f)));
  vel =sb_mix(vel,farVel,wf);
  float2 d = vel * T;
  d =d *(sb_min(1.0f,0.4f/ sb_max(length(d),1e-4f)));
  float ca = t / T, cb = ca + 0.5f;
  float fa = sb_fract(ca), fb = sb_fract(cb);
  float w = 1.0f- sb_abs(2.0f* fa - 1.0f);
  float la = lumpField(ctx,xz - d * fa,sb_floor(ca)* 1.618f,t), lb = lumpField(ctx,xz - d * fb,sb_floor(cb)* 2.414f+ 0.5f,t);
  return 0.5f+ (w * (la - 0.5f) + (1.0f- w) * (lb - 0.5f)) / sb_sqrt(w * w + (1.0f- w) * (1.0f- w));
}



__device__ float4 surfaceFoam(GraphicsContext& ctx,float3 P,float t,float crestFoam,float2& flowUV,float& turb){
  float2 suv = sweUV(ctx,sb_sw_xz(P));
  float wIn = sweInside(ctx,sb_sw_xz(P));
  float4 fm = __sb_textureLod(5,suv,0.0f)* wIn;
  float4 lo = __sb_textureLod(6,suv,0.0f)* wIn;
  float4 handoffDelta = sb_vec4(0.0f);
  float4 svw = __sb_textureLod(4,suv,0.0f);


  float hE = __sb_textureLod(4,suv + sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x, hW = __sb_textureLod(4,suv - sb_vec2(2.0f* ctx.uSweTexel.x,0.0f),0.0f).x;
  float hw = (2.0f* svw.x+ hE + hW) * 0.25f;
  float hMin = sb_min(svw.x,sb_min(hE,hW));
  float2 fvel = sb_sw_yz(svw);

  float wf = swashFarWeight(ctx,sb_sw_xz(P));
  float2 farVel = sb_vec2(0.0f);
  turb =fm.z;

  float phA = ctx.uLacePhase.x;
  float wa = sb_smoothstep(0.0f,0.22f,phA)* (1.0f- sb_smoothstep(0.5f,0.72f,phA));
  float wb = 1.0f- wa;
  float2 pa = sb_sw_xz(P)+ sb_sw_xy(lo), pb = sb_sw_xz(P)+ sb_sw_zw(lo);


  flowUV =sb_sw_xz(P)+ 0.3f* (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo));


  float3 dPx = __sb_dFdx(P), dPy = __sb_dFdy(P);
  float fp = sb_max(sb_max(length(dPx),length(dPy)),1.0e-4f);
  float ny = sb_abs(normalize(cross(dPx,dPy)).y);
  float fpXZ = sb_max(length(sb_sw_xz(dPx))+ length(sb_sw_xz(dPy)),1.0e-5f);



  float4 frameDx = __sb_dFdx(lo)- handoffDelta * __sb_dFdx(wf);
  float4 frameDy = __sb_dFdy(lo)- handoffDelta * __sb_dFdy(wf);
  float strA = (length(sb_sw_xy(frameDx))+ length(sb_sw_xy(frameDy))) / fpXZ;
  float strB = (length(sb_sw_zw(frameDx))+ length(sb_sw_zw(frameDy))) / fpXZ;

  float cf = crestFoam * sb_smoothstep(0.35f,0.75f,ny)* sb_smoothstep(0.2f,0.8f,0.5f+ 0.5f* gnoise(ctx,sb_sw_xz(P)* sb_vec2(7.0f,11.0f)+ sb_vec2(0.0f,(0-(t ))* 3.0f))+ crestFoam * 0.5f);
  if (fm.x< 0.01f&& fm.y< 0.01f) return sb_vec4(cf,cf > 0.0f? 0.85f: 0.0f,0.0f,cf);

  float R = fm.x, G = sb_clamp(fm.y,0.0f,1.5f);


  float spd = length(fvel);
  float2 dir = spd > 1.0e-3f? fvel / spd : sb_vec2(0.0f,1.0f);

  float fast = sb_smoothstep(0.3f,1.2f,spd)* sb_smoothstep((0-(0.2f)),0.4f,fvel.y/ sb_max(spd,0.1f));

  float an = sb_mix(1.0f,ctx.uFoamLook2.y,fast), anL = sb_mix(1.0f,1.65f,sb_smoothstep(.25f,1.4f,spd));
  float amtG = 1.0f- sb_exp((0-(G ))/ 0.9f);


  float flatW = sb_smoothstep(0.5f,0.8f,ny);

  float keepA = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strA));
  float keepB = flatW * (1.0f- sb_smoothstep(0.35f,1.0f,strB));



  float edgeFade = sb_smoothstep(0.002f,0.009f,hw)* sb_smoothstep(0.0005f,0.004f,hMin + wf);
  float ribVis = 1.0f- sb_smoothstep(0.022f,0.12f,fp);

  float netVis = 1.0f- sb_smoothstep(0.16f,0.60f,fp * ctx.uFoamLook.x);


  float tearVis = ribVis * (1.0f- sb_smoothstep(1.05f,1.4f,R));
  bool torn = tearVis > 0.0f;
  bool laced = G > 0.02f&& R < 0.7f;
  bool netOn = laced && R < 0.45f&& netVis > 0.0f;
  float thin = 1.0f- sb_smoothstep(0.3f,1.0f,R);

  float tearAcc = 0.0f, netAcc = 0.0f, grainAcc = 0.0f, clumpAcc = 0.0f, wallAcc = 0.0f;
  for (int k = 0; k < 2 + sb_min(ctx.uEvtCount,0); k++) {
    float wk = k == 0 ? wa : wb;
    if (wk <= 0.0f) continue;
    FoamSet S = foamSet(ctx,k == 0 ? pa : pb,k == 0 ? ctx.uLaceSeeds.x: ctx.uLaceSeeds.y+ 3.3f,fp,dir,an,anL,torn,netOn,1.0f+ 2.5f* amtG * amtG);
    float kk = wk * (k == 0 ? keepA : keepB);
    tearAcc =tearAcc +(kk * (S.tear- 0.5f));
    wallAcc =wallAcc +(kk * (S.wall- 0.5f));
    netAcc =netAcc +(kk * S.net);


    grainAcc =grainAcc +(kk * S.grain);
    clumpAcc =clumpAcc +(kk * S.clump);
  }
  float ka = wa * keepA, kb = wb * keepB;
  float nrm = 1.0f/ sb_max(sb_sqrt(wa * wa + wb * wb),1e-3f);
  float clump = clumpAcc * nrm;


  float rib = 0.5f+ tearAcc * nrm * tearVis + 0.09f* clump;
  float wall = 0.5f+ wallAcc * nrm * tearVis + 0.08f* clump;
  float net = netAcc;
  float grain = grainAcc * nrm * ctx.uFoamLook2.z;
  float lump = R > 0.3f? sb_mix(0.5f,blanketLumps(ctx,sb_sw_xz(P),suv,t,wf,farVel),flatW*sb_smoothstep(.3f,.55f,R)): 0.5f;
  float sup = ka + kb;
  float strVis = sup * ribVis;




  float cB = (1.0f- sb_exp((0-(sb_pow(R / 0.42f,1.4f))))) * sb_smoothstep(0.02f,0.1f,R);


  float ew = sb_mix(0.16f,0.36f,sb_smoothstep(0.3f,0.8f,cB));
  float th = cB >= ew ? 1.0f- cB : 1.0f+ ew - 2.0f* sb_sqrt(ew * cB);


  float rbHi = sb_clamp(1.0f- 2.0f* (1.0f- cB) * (1.0f- rib),0.0f,1.0f);
  float rbLo = sb_clamp((rib - th) / (2.0f* ew) + 0.5f,0.0f,1.0f);
  rbLo =rbLo * rbLo * (3.0f- 2.0f* rbLo);


  float rb = sb_mix(cB * (1.0f- 0.65f* ribVis * (1.0f- sup)),sb_mix(rbLo,rbHi,sb_smoothstep(0.6f,0.8f,cB)),strVis);


  float pocket = (1.0f- sb_smoothstep(0.0f,0.3f,rib)) * sb_smoothstep(0.5f,1.2f,R)* strVis;


  float aR = sb_mix(0.7f,0.94f,sb_smoothstep(0.3f,1.2f,R))* (1.0f- 0.45f* pocket);
  float haze = 0.12f* sb_smoothstep(0.02f,0.5f,R + 0.12f* G)* thin;

  float blanket = rb * aR * sb_mix(sb_mix(0.62f,0.85f,sb_smoothstep(0.5f,0.9f,cB)),1.0f,sb_smoothstep(th,th + 0.45f,rib))* (1.0f+ (0.8f* grain + 0.3f* clump) * thin);
  blanket =sb_clamp(blanket + haze * (1.0f- blanket),0.0f,1.0f)* ctx.uFoamLook.w;



  float lace = 0.0f, laceD = 0.25f;
  if (laced) {

    float amt = amtG;


    float cL = 0.07f* amt * amt;
    float ewL = 0.2f;
    float thL = cL >= ewL ? 1.0f- cL : 1.0f+ ewL - 2.0f* sb_sqrt(ewL * cL);
    float rl = sb_clamp((wall - thL) / (2.0f* ewL) + 0.5f,0.0f,1.0f);
    float ribL = sb_mix(cL * (1.0f- 0.65f* ribVis * (1.0f- sup)),rl * rl * (3.0f- 2.0f* rl),strVis);

    float netMean = 0.09f* (1.0f+ 2.5f* amt * amt);
    float netL = sb_mix(netMean * (1.0f- 0.65f* netVis * (1.0f- sup)),net,sup * netVis)* sb_min(1.3f* amt,1.0f)* sb_smoothstep(0.45f,0.1f,R);

    float sL = 0.8f* sb_clamp(ribL * (1.0f+ grain + 0.35f* clump),0.0f,1.0f);
    float nL = sb_mix(ctx.uFoamLook.z,0.85f,sb_smoothstep(0.45f,0.8f,amt))* sb_clamp(netL * (1.0f+ grain + 0.3f* clump),0.0f,1.0f);
    lace =sb_max(sL,nL)* sb_smoothstep(0.02f,0.12f,G)* (1.0f- sb_smoothstep(0.3f,0.7f,R));
    laceD =sb_mix(sb_mix(0.25f,0.5f,sb_smoothstep(0.45f,0.8f,amt)),0.6f,sL / sb_max(sL + nL,1e-3f));
  }


  float milkyBack = sb_smoothstep(0.25f,0.55f,fm.w)* sb_smoothstep((0-(0.15f)),(0-(0.5f)),fvel.y)* (1.0f- sb_smoothstep(0.2f,0.5f,R)) * (ka + kb);
  milkyBack =milkyBack *(sb_smoothstep(0.0f,0.025f,milkyBack));
  if (milkyBack > 0.0f&& fp < 0.008f) {
    float2 rq = (sb_sw_xz(P)+ (wa * sb_sw_xy(lo)+ wb * sb_sw_zw(lo))) / 0.07f;
    float3 wr = worley(ctx,rq + sb_vec2(ctx.uLaceSeeds.x* 3.1f,0.0f));
    float rr = sb_mix(0.1f,0.17f,sb_fract(wr.z* 7.31f));
    float rw = sb_max(0.035f,0.6f* fp / 0.07f);
    float ring = sb_exp((0-(sb_pow((wr.x- rr) / rw,2.0f))))* sb_step(wr.z,0.22f)* sb_min(1.0f,0.035f/ rw);
    lace =sb_max(lace,0.55f* ring * milkyBack * (1.0f- sb_smoothstep(0.005f,0.008f,fp)));
  }






  float dBl = sb_mix(0.6f,0.95f,sb_smoothstep(0.3f,1.2f,R))+ 1.1f* (lump - 0.5f) * (1.0f- thin) + (0.35f* grain + 0.1f* clump) * (1.0f- thin)
            - 0.3f* (1.0f- rb) * (1.0f- thin) - 0.35f* pocket;
  dBl =sb_mix(sb_clamp(dBl,0.0f,1.0f),sb_mix(0.3f,0.6f,rb)* (1.0f+ 0.5f* grain + 0.3f* clump),thin);
  float wBl = blanket * edgeFade, wLa = lace * edgeFade * (1.0f- wBl);
  float dense = sb_clamp((dBl * wBl + laceD * wLa + 0.85f* cf) / sb_max(wBl + wLa + cf,1e-3f),0.0f,1.0f);

  float cov = 1.0f- (1.0f- blanket * edgeFade) * (1.0f- lace * edgeFade) * (1.0f- cf);
  return sb_vec4(sb_clamp(cov,0.0f,1.0f),dense,lace * edgeFade,cf);
}


__device__ SBMat2 rot2(GraphicsContext& ctx,float a){ float c = sb_cos(a), s = sb_sin(a); return sb_mat2(c,(0-(s)),s,c); }



__device__ float2 rippleGrad(GraphicsContext& ctx,float2 p,float t,float dist,float strength){
  float2 g = sb_vec2(0.0f);
  float px = dist * 0.00065f;
  float L = 1.6f;
  for (int i = 0; i < 6 + sb_min(ctx.uEvtCount,0); i++) {
    float keep = sb_smoothstep(px * 3.0f,px * 9.0f,L);
    if (keep > 0.0f) {
      float2 q = rot2(ctx,float(i)* 1.93f)* p / L;
      float c = sb_sqrt(9.81f* L / 6.2831f);
      q =q +(rot2(ctx,float(i)* 1.93f)* ctx.uWind * t * c / L * 0.7f);
      float3 n = gnoised(ctx,q + float(i)* 17.3f);
      g =g +(sb_sw_yz(n)* 0.075f* keep);
    }
    L =L *(0.48f);
  }
  return g * strength;
}










__device__ float3 filmRipple(GraphicsContext& ctx,float2 p,float t,float px,float2& ridgeDir){
  float2 g = sb_vec2(0.0f);
  float ridge = 0.0f;
  ridgeDir =sb_vec2(0.0f,1.0f);
  float lam = 0.11f, h = 0.0013f;
  for (int i = 0; i < 2 + sb_min(ctx.uEvtCount,0); i++) {
    float keep = 1.0f- sb_smoothstep(lam * 0.12f,lam * 0.3f,px);
    if (keep > 0.0f) {
      float2 q = sb_vec2(p.x* 0.85f,p.y)/ lam + sb_vec2(0.13f,(0-(0.21f)))* t + float(i)* 7.31f;
      float3 n = gnoised(ctx,q + 0.35f* sb_vec2(sb_sin(t * 0.9f+ q.y* 0.7f),sb_cos(t * 0.7f+ q.x* 0.6f)));
      float a = 1.0f- sb_min(sb_abs(n.x),1.0f);
      g =g +(keep * ((0-(3.0f))* a * a * sb_sign(n.x)) * (sb_sw_yz(n)* sb_vec2(0.85f,1.0f)) * (h / lam));
      float rk = keep * sb_smoothstep(0.9f,0.985f,a)* (i == 0 ? 1.0f: 0.6f);
      if (rk > ridge) { ridge =rk; ridgeDir =normalize(sb_sw_yz(n)* sb_vec2(0.85f,1.0f)+ 1e-5f); }
    }
    lam =lam *(0.52f); h =h *(0.5f);
  }
  return sb_vec3(g,ridge);
}



__device__ void main(GraphicsContext& ctx){
  float3 P = ctx.vWorld;
  float B = hydraulicBedHeight(ctx,sb_sw_xz(P));
  float depth = P.y- B;
  float edgeN = vnoise(ctx,sb_sw_xz(P)* 41.0f)* 0.0016f+ vnoise(ctx,sb_sw_xz(P)* 7.0f)* 0.0018f;
  if (depth < 0.0009f+ edgeN) {ctx.discarded=true;return;}if (ctx.uPerf.x> 0.5f) { ctx.gl_FragColor =sb_vec4(0.1f,0.3f,0.3f,1.0f); return; }

  float dist = ctx.vViewZ;
  float3 V = normalize(ctx.cameraPosition - P);
  float pxFoot = sb_max(length(__sb_fwidth(sb_sw_xz(P))),1e-4f);
  float2 flowUV = sb_sw_xz(P); float turb = 0.0f;
  float4 foam = sb_vec4(0.0f);

  if ((ctx.vInfo.z> 0.0f|| ctx.vInfo.x> 0.0f) && ctx.uPerf.y< 0.5f) foam =surfaceFoam(ctx,P,ctx.uTime,ctx.vInfo.x,flowUV,turb);
  turb =sb_clamp(turb,0.0f,2.0f);



  float4 crest = sb_vec4(0.0f);
  float3 faceNormal=sb_vec3(0.0f,1.0f,0.0f);
  float keep = 1.0f, hAbove = 0.0f, crestProx = 0.0f;
  if (ctx.vCrest.y> 0.001f&& ctx.uDbg.x> (0-(0.5f))&& ctx.uPerf.z< 0.5f) {
    float3 aux;
    crest =crestGeometry(ctx,sb_sw_xy(ctx.vXZ0),ctx.uTime,ctx.vCrest.w,aux,faceNormal);
    float gate=sb_smoothstep(.001f,.20f,ctx.vCrest.y);
    crest.w=crest.w*(gate);crest.z=crest.z*(gate);aux.x=aux.x*(gate);aux.z=aux.z*(gate);aux.y=sb_mix(1.0f,aux.y,gate);
    float faceSlope = sb_max(ctx.vCrest.z,aux.z);
    hAbove =aux.x;

    crestProx =crest.w* sb_exp((0-(crest.x))* crest.x/ 0.05f)* sb_smoothstep(0.03f,0.12f,P.y);


    crest.w=crest.w*(sb_smoothstep(ctx.uFaceSlope.x,ctx.uFaceSlope.y,faceSlope));


    crest.x=crest.x*(sb_mix(0.55f,1.0f,sb_smoothstep(0.2f,0.8f,faceSlope)));







    keep =aux.y;
    float sweFoam = 1.0f- (1.0f- foam.x) / sb_max(1.0f- foam.w,1e-3f);
    foam.x=1.0f- (1.0f- sb_clamp(sweFoam,0.0f,1.0f)* keep) * (1.0f- foam.w);
    foam.y=foam.y*(keep);
    turb =turb *(keep);
  }


  float3 N = normalize(ctx.vNrm);
  float faceBlend=sb_smoothstep(.05f,.18f,ctx.vCrest.w)*sb_smoothstep(.12f,.7f,crest.y)*sb_smoothstep(.04f,.20f,sb_abs(faceNormal.z));
  faceBlend=faceBlend*(sb_smoothstep(.001f,.20f,ctx.vCrest.y));
  N=normalize(sb_mix(N,faceNormal,faceBlend));
  float wIn = sweInside(ctx,sb_sw_xz(P));
  float2 g = sb_vec2(0.0f);
  if (wIn > 0.0f) {
    float2 uv = sweUV(ctx,sb_sw_xz(P)); float2 e = ctx.uSweTexel;
    float wE = __sb_textureLod(4,uv + sb_vec2(e.x,0.0f),0.0f).w, wW = __sb_textureLod(4,uv - sb_vec2(e.x,0.0f),0.0f).w;
    float wN = __sb_textureLod(4,uv + sb_vec2(0.0f,e.y),0.0f).w, wS = __sb_textureLod(4,uv - sb_vec2(0.0f,e.y),0.0f).w;
    float2 gs = sb_vec2(wE - wW,wN - wS)/ (2.0f* e * sb_sw_zw(ctx.uSweDom));



    g =g +(clampLen(ctx,wIn * 0.35f* gs,ctx.uSweSlope.y)* sb_smoothstep(0.3f,0.7f,ctx.vNrm.y));
  }
  float chopW = ctx.vInfo.w;
  float paw = ctx.vXZ0.z;
  float4 lean = oceanSlopeLEAN(ctx,sb_sw_xy(ctx.vXZ0),paw,chopW,ctx.uSeaTune.y);
  g =g +(sb_sw_xy(lean));
  float2 sig2 = sb_sw_zw(lean);

  float shallowCalm = sb_smoothstep(0.02f,0.5f,depth);
  float rw = 1.0f- chopW;

  float swashCoverage=wIn;
  float film = swashCoverage * (1.0f- sb_smoothstep(0.04f,0.14f,depth)) * (1.0f- sb_smoothstep(0.3f,0.8f,foam.y));
  float rippleStrength = (0.7f* sb_mix(0.35f,1.0f,shallowCalm)+ turb * 0.6f) * rw * (1.0f- film) * sb_smoothstep(0.3f,0.7f,ctx.vNrm.y);
  float2 rp = sb_mix(sb_sw_xz(P),flowUV,swashCoverage * (1.0f- shallowCalm * 0.5f));
  if (rippleStrength > 0.0f&& ctx.uPerf.w< 0.5f) g =g +(rippleGrad(ctx,rp,ctx.uTime,dist,rippleStrength));
  float ridge = 0.0f; float2 ridgeDir = sb_vec2(0.0f,1.0f);
  if (film > 0.0f) { float3 fr = filmRipple(ctx,rp,ctx.uTime,pxFoot,ridgeDir);
    g =g +(film * ctx.uFilm.x* sb_sw_xy(fr)); ridge =film * fr.z; }
  sig2 =sig2 +(sb_vec2(0.0025f+ turb * 0.01f* (1.0f- 0.8f* film))* rw + ctx.uFilm.w* ridge);
  N =normalize(N - sb_vec3(g.x,0.0f,g.y));

  WIn s;
  s.P=P; s.N=N; s.V=V; s.viewZ=dist; s.thickHint=(0-(1.0f));

  s.foam=foam.x; s.foamDense=foam.y; s.turb=turb * (1.0f- 0.8f* film); s.film=film;
  s.crest=sb_clamp(sb_max(ctx.vInfo.x* 1.5f+ sb_smoothstep(0.1f,0.6f,P.y)* 0.6f,crestProx),0.0f,1.0f);
  s.rough=0.05f;
  float4 fmS = wIn * __sb_textureLod(5,sweUV(ctx,sb_sw_xz(P)),0.0f);


  float clearW = keep;


  float deepW = sb_smoothstep(0.2f,0.5f,depth);
  s.milk=fmS.w* clearW * (1.0f- deepW);


  s.murk=fmS.w* deepW * clearW;


  float spd = length(sb_sw_yz(__sb_textureLod(4,sweUV(ctx,sb_sw_xz(P)),0.0f)))* wIn;
  s.silt=sb_smoothstep(0.35f,1.3f,spd)* sb_smoothstep(0.015f,0.06f,depth)* keep;
  s.swash=wIn * (1.0f- sb_smoothstep(0.06f,0.25f,depth)) * clearW * (1.0f- crest.w);


  s.aer=(sb_smoothstep(0.05f,0.8f,fmS.x)* 0.7f+ sb_smoothstep(0.8f,2.0f,fmS.z)* 0.35f* sb_smoothstep(0.06f,0.2f,depth)) * clearW;
  s.under=sb_smoothstep(0.2f,0.9f,fmS.x)* clearW;

  float xr = ctx.uSeaTune.x* sb_mix(1.0f,sb_clamp(paw,0.3f,1.8f),ctx.uSeaTune.z);





  float ftilt = 0.0f;
  if (V.y< ctx.uSeaTune2.z&& P.z< (0-(9.0f))) {
    float fnz = sb_clamp(facetNoise(ctx,sb_sw_xy(ctx.vXZ0),ctx.uTime),(0-(2.5f)),2.5f);
    float thr = ctx.uSeaTune4.x- 0.45f* sb_clamp(paw - 1.0f,(0-(1.0f)),1.0f);
    ftilt =(ctx.uSeaTune.w* 0.6f* fnz + ctx.uSeaTune4.y* sb_smoothstep(thr,thr + 0.4f,fnz))*(1.0f-sb_smoothstep((0-(22.0f)),(0-(9.0f)),P.z));
  }
  float3 col = shadeWaterFull(ctx,s,sb_sw_xy(ctx.gl_FragCoord),sig2,xr,crest,ftilt);


  if (ridge > 0.0f) {
    float3 Hs = normalize(V + ctx.uSunDir);
    float2 hs = (0-(sb_sw_xz(Hs)))/ sb_max(Hs.y,0.2f);
    float along = dot(hs,ridgeDir), across = sb_abs(hs.x* ridgeDir.y- hs.y* ridgeDir.x);

    float on = (0.35f+ 0.65f* sb_exp((0-(across ))* across / 0.03f)) * (1.0f- sb_smoothstep(0.6f,1.0f,sb_abs(along)));
    col =sb_mix(col,col + ctx.uSunColor * ctx.uFilm2.x,ridge * on * (1.0f- sb_clamp(s.foam,0.0f,1.0f)));
  }
  if (ctx.uDbg.x> 20.5f) col =sb_vec3((ctx.uDbg.x< 21.5f? film : ctx.uDbg.x< 22.5f? turb * 0.5f: ctx.uDbg.x< 23.5f? depth * 5.0f: length(g)) * ctx.uDbg.y);
  ctx.gl_FragColor =sb_vec4(col,1.0f);
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];ctx.WATER_SIGMA_A=sb_vec3(0.46f,0.075f,0.062f);
ctx.WATER_SIGMA_S=sb_vec3(0.020f,0.030f,0.032f);
ctx.OCR0=sb_mat2(0.9563048f,0.2923717f,(0-(0.2923717f)),0.9563048f);
ctx.OCR1=sb_mat2(0.8571673f,(0-(0.5150381f)),0.5150381f,0.8571673f);
ctx.OCR2=sb_mat2(0.7313537f,0.6819984f,(0-(0.6819984f)),0.7313537f);
ctx.OCC2=sb_vec3(0.9145188f,0.7347358f,0.5348782f);
main(ctx);output[0]=ctx;}

#endif

