}






__device__ float brkTnLip(GraphicsContext& ctx,Brk b,float t){
  float Dn = b.D/ b.rs;
  float a = (t - b.ti) / b.rs+ Dn;
  float Ts = (0-(0.47f))- 0.6f* Dn;
  return a - Dn * sb_smoothstep(Ts,Ts + sb_max(1.6f* Dn,1e-3f),a);
}








__device__ float brkTn(GraphicsContext& ctx,Brk b,float t){
  float tn = brkTnLip(ctx,b,t);
  float a = 0.6f* b.hold, w = sb_max(0.8f* b.hold,1e-4f);
  float u = sb_clamp((tn - a) / w,0.0f,1.0f);

  float I = w * u * u * u * (1.0f- 0.5f* u) + sb_max(tn - a - w,0.0f);
  return sb_mix(tn,0.15f* tn + (1.0f- 0.15f) * I,sb_step(0.0f,tn)* sb_step(1e-9f,b.hold));
}


__device__ float2 brkApex(GraphicsContext& ctx,Brk b,BrkStage g,float tn){
