struct GraphicsContext {
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
float3 cameraPosition;
float4 vShape0;
float4 vShape1;
float4 gl_FragColor;
float4 gl_FragCoord;
int gl_FrontFacing;
float gl_FragDepth;
int discarded;
};
__device__ void main(GraphicsContext& ctx){
  float x=(ctx.gl_FragCoord.x/256.0f)*1024.0f-512.0f;
  float z=(0-(6.0f))-8.0f*(sb_exp((ctx.gl_FragCoord.y/512.0f)*sb_log(81.5f))-1.0f);
  float xi=(z-ctx.vShape0.x)/ctx.vShape0.y;
  float ya=ctx.vShape0.z,yt=ctx.vShape0.w,lf=ctx.vShape1.x,lb=ctx.vShape1.y;
  float h,dz;
  if(xi<0.0f){float a=xi/lb;float e=sb_exp((0-(sb_abs(a))));float sec=2.0f*e/(1.0f+e*e);h=ya*sec*sec;dz=h*((0-(2.0f))/lb)*sb_tanh(a);}
  else if(xi>lf){float a=(xi-lf)/1.5f;h=yt*sb_exp((0-(a))*a);dz=h*((0-(2.0f))*a/1.5f);}
  else {float a=3.14159265f*xi/lf;h=yt+(ya-yt)*(.5f+.5f*sb_cos(a));dz=(0-((ya-yt)))*1.5707963f*sb_sin(a)/lf;}
  h=h*(ctx.vShape0.y*ctx.vShape1.z);dz=dz*(ctx.vShape1.z);
  ctx.gl_FragColor=sb_vec4(h,__sb_dFdx(h)/4.0f,dz,float(0));
}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

