__device__ float4 sb_lookup(const float4* lookup,float2 uv,float lod){
 float px=sb_clamp(uv.x*4096.0f-0.5f,0.0f,4095.0f),py=sb_clamp(uv.y*4.0f-0.5f,0.0f,3.0f);
