__device__ float4 brkLipCurve(GraphicsContext& ctx,BrkLip L,float sg){
  float u = 1.0f- sg;
  float2 p = u * u * u * L.R+ 3.0f* u * u * sg * L.P1+ 3.0f* u * sg * sg * L.P2+ sg * sg * sg * L.T;
  float2 dp = 3.0f* u * u * (L.P1- L.R) + 6.0f* u * sg * (L.P2- L.P1) + 3.0f* sg * sg * (L.T- L.P2);
  float l = length(dp);
  return sb_vec4(p,l > 1e-6f? dp / l : sb_vec2(1.0f,0.0f));
}

__device__ float brkLipWidth(GraphicsContext& ctx,BrkLip L,float sg){ return L.wT+ (L.wR- L.wT) * sb_pow(1.0f- sb_clamp(sg,0.0f,1.0f),0.8f); }



__device__ float3 brkJet(GraphicsContext& ctx,Brk b,float sigma,float t){
  BrkLip L = brkLip(ctx,b,t);
  float sg = 1.0f- sb_clamp(sigma,0.0f,1.0f);
  float4 c = brkLipCurve(ctx,L,sg);
  return sb_vec3(sb_sw_xy(c),brkLipWidth(ctx,L,sg));
}


__device__ float brkImpactSpeed(GraphicsContext& ctx,Brk b){
  float2 v = brkLipV0(ctx,b)+ sb_vec2(0.0f,(0-(9.81f))* b.Tj);
  return length(v);
}






__device__ float brkGamma(GraphicsContext& ctx,float tau,float T){ return tau > 0.0f? tau / (T * T) * sb_exp((0-(tau ))/ T): 0.0f; }



__device__ float brkThrow(GraphicsContext& ctx,Brk b){ return sb_mix(0.3f,1.0f,sb_smoothstep(0.4f,0.75f,b.style)); }








__device__ float brkLobes(GraphicsContext& ctx,Brk b){
  float x = b.x;
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float ph = far * 2.5f* sb_sin(0.37f* x + b.seed* 5.1f+ 1.7f* sb_sin(0.13f* x));
  float am = sb_mix(1.0f,0.45f+ 0.9f* (0.5f+ 0.5f* sb_sin(0.29f* x + b.seed* 3.3f)* sb_sin(0.71f* x + 1.1f)),far);

  float wm = 1.1f* sb_sin(1.9f* x + b.seed* 13.7f)+ 0.6f* sb_sin(4.4f* x + b.seed* 29.3f);
  float fine = 0.6f* sb_sin(24.1f* x + b.seed* 53.3f+ 2.1f* sb_sin(3.7f* x + b.seed* 9.0f))+ 0.4f* sb_sin(37.9f* x + b.seed* 71.9f+ 1.7f* sb_sin(5.9f* x + b.seed* 4.0f));
  return am * (ctx.uInjL.x* sb_sin(5.236f* x + b.seed* 37.1f+ ph)+ ctx.uInjL.y* sb_sin(14.96f* x + b.seed* 91.7f+ wm + 1.9f* ph)+ ctx.uInjL.z* fine);
}






__device__ float brkRunupMod(GraphicsContext& ctx,float x,float seed){
  float far = sb_smoothstep(4.0f,8.0f,sb_abs(x));
  float und = 0.6f* sb_sin(0.21f* x + seed * 7.3f+ 0.5f* sb_sin(0.09f* x + seed * 3.1f))+ 0.4f* sb_sin(0.47f* x + seed * 13.1f);
  float cph = x / 17.0f+ 0.25f* sb_sin(x / 23.0f+ 1.1f);
  float horn = 1.0f- sb_abs(sb_sin(3.14159f* cph));
  return far * (0.14f* und + 0.13f* (1.0f- 2.0f* horn * horn));
}

__device__ float3 brkInjection(GraphicsContext& ctx,float2 xz,float t){
  float3 src = sb_vec3(0.0f);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float hs = sb_sqrt(b.H/ 0.45f);

    float M = ctx.uInjMass * 0.2025f* sb_pow(b.H/ 0.45f,1.5f)* b.str* sb_max(ctx.uEvtG[i].x,0.0f);

    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = 0.22f* hs + 0.20f* tJ;
    float qJ = M * ctx.uInjJ.x* brkGamma(ctx,tJ,ctx.uInjJ.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f))/ (2.5066f* sJ);

    float tR = tau - ctx.uInjR.x;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ ctx.uInjR.z* sb_max(tR,0.0f);
    float sR = 0.30f* hs + 0.15f* sb_max(tR,0.0f);
    float qR = M * (1.0f- ctx.uInjJ.x) * brkGamma(ctx,tR,ctx.uInjR.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f))/ (2.5066f* sR);

    float thr = brkThrow(ctx,b);
    float mz = ctx.uInjSpeed * (qJ * ctx.uInjJ.w* sb_mix(0.5f,1.0f,thr)+ qR * ctx.uInjR.w* sb_mix(0.6f,1.0f,thr))
             * (1.0f+ brkLobes(ctx,b)) * (1.0f+ 0.5f* brkRunupMod(ctx,b.x,b.seed));
    src =src +(sb_vec3(qJ + qR,mz,mz * ctx.uInjL.w));
  }
  return src;
}





__device__ float brkFoam(GraphicsContext& ctx,float2 xz,float t){
  float f = 0.0f;
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tau = t - b.ti;




    float spl = sb_smoothstep(0.5f,0.9f,b.spill)* (1.0f- sb_smoothstep(0.1f,0.3f,b.style)) * b.str;

    if (spl > 0.0f&& tau > (0-(0.3f))&& tau < 2.4f) {


      float on = sb_smoothstep((0-(0.3f)),0.0f,tau)* (1.0f- sb_smoothstep(ctx.uFoamSpillK.y- 1.1f,ctx.uFoamSpillK.y,tau));
      float zc = b.zI+ 0.1f+ ctx.uFoamSpillK.x* sb_max(tau,0.0f);
      f =f +(ctx.uFoamSpill * spl * (b.H/ 0.45f) * on * sb_exp((0-(0.5f))* sb_pow((xz.y- zc) / (0.3f+ 0.2f* sb_max(tau,0.0f)),2.0f)));
    }
    if (tau < (0-(0.1f))|| tau > 3.0f) continue;
    float E = (b.H* b.H) / (0.45f* 0.45f) * b.str* sb_mix(0.6f,1.0f,b.style);
    float2 gain = sb_max(sb_sw_xy(ctx.uEvtG[i]),sb_vec2(0.0f));
    float tJ = tau + 0.04f;
    float zJ = b.zI+ 0.10f+ ctx.uInjJ.z* brkThrow(ctx,b)* tJ;
    float sJ = ctx.uFoamSrc.w* (0.25f+ 0.30f* sb_max(tJ,0.0f));
    f =f +(E * gain.y* ctx.uFoamSrc.x* brkGamma(ctx,tJ,ctx.uFoamSrc.y)* sb_exp((0-(0.5f))* sb_pow((xz.y- zJ) / sJ,2.0f)));

    float tR = tau - 0.21f;
    float zR = sb_mix(brkCrestZ(ctx,b,b.ti),b.zI,0.5f)+ 0.55f* sb_max(tR,0.0f);
    float sR = 0.35f+ 0.2f* sb_max(tR,0.0f);
    f =f +(E * gain.x* ctx.uFoamSrc.z* brkGamma(ctx,tR,0.4f)* sb_exp((0-(0.5f))* sb_pow((xz.y- zR) / sR,2.0f)));
  }
  return f;
}








__device__ float brkSweFoamKeep(GraphicsContext& ctx,float2 xz,float t){
  float keep = 1.0f;
  if (xz.y< (0-(9.0f))|| xz.y> 0.6f) return keep;
  float fade = 1.0f- sb_smoothstep((0-(1.0f)),0.1f,xz.y);
  for (int i = 0; i < ctx.uEvtCount; i++) {
    Brk b = brkAt(ctx,i,xz.x);
    if (b.str<= 0.0f) continue;
    float tn = brkTn(ctx,b,t);
    if (tn < (0-(2.4f))|| tn > 0.5f) continue;
    BrkStage g = brkStage(ctx,tn);
    float2 A = brkApex(ctx,b,g,tn);
    float xi = (xz.y- A.x) / b.s;
    if (xi < (0-(0.8f))|| xi > g.lf) continue;
    float amp = sb_smoothstep((0-(23.0f)),(0-(13.0f)),A.x)* (1.0f- sb_smoothstep(0.6f,0.85f,tn)) * b.str* fade;
    float eta = brkShape(ctx,g,xi).x* b.s* amp;
    float raised = sb_smoothstep(0.012f,0.06f,eta - 0.5f* g.yt* b.s* amp);
    float front = sb_smoothstep((0-(0.8f)),(0-(0.2f)),xi);
    float grown = sb_smoothstep((0-(2.4f)),(0-(1.5f)),tn);
    float live = 1.0f- sb_smoothstep(0.1f,0.5f,tn);
    keep =sb_min(keep,1.0f- front * raised * grown * live);
  }
  return keep;
}


__device__ float2 ocVar(GraphicsContext& ctx,float2 v,float c2){ return sb_vec2(c2 * v.x+ (1.0f- c2) * v.y,(1.0f- c2) * v.x+ c2 * v.y); }






__device__ float pawFbm(GraphicsContext& ctx,float2 p,float fz,int oct){
  float s = 0.0f, a = 0.5f;
  for (int i = 0; i < 5; i++) {
    if (i >= oct) break;
    s =s +(a * gnoise(ctx,p)* (1.0f- sb_smoothstep(0.25f,0.5f,fz)));
    p =sb_mat2(1.6f,1.2f,(0-(1.2f)),1.6f)* p; a =a *(0.5f); fz =fz *(2.0f);
  }
  return s;
}

__device__ float catsPaw(GraphicsContext& ctx,float2 xz,float t,float fp){
  float2 q = xz * sb_vec2(0.055f,0.16f);
  float a = pawFbm(ctx,q + sb_vec2(0.021f,(0-(0.12f)))* t,fp * 0.16f,4);
  float b = pawFbm(ctx,q * 1.7f+ sb_vec2((0-(0.05f)),(0-(0.2f)))* t + 11.3f,fp * 0.27f,3);
  float f = 0.5f+ 0.8f* (0.62f* a + 0.38f* b);
  float D = sb_max(ctx.cameraPosition.z- xz.y,1.0f);
  float u = sb_clamp(xz.x/ (0.72f* D),(0-(0.5f)),0.5f);
  float lr = 1.0f- 1.1f* u;
  return sb_mix(1.0f,sb_clamp(f,0.15f,1.6f)* lr,ctx.uOceanAmp.w);
}




__device__ float oceanFarGain(GraphicsContext& ctx,float2 xz){ return sb_mix(ctx.uSeaTune5.w,1.0f,sb_smoothstep(15.0f,40.0f,ctx.cameraPosition.z- xz.y)); }

__device__ float viewDistH(GraphicsContext& ctx,float2 xz){ return ctx.cameraPosition.z- xz.y; }




__device__ float3 oceanDisp(GraphicsContext& ctx,float2 xz,float fp,float paw,float2& slope){
  float3 d = sb_vec3(0.0f); slope =sb_vec2(0.0f);
  float lf = sb_log2(sb_max(fp,1e-4f)* 256.0f)+ 0.5f;
  float l0 = lf - sb_log2(ctx.uOceanL.x), l1 = lf - sb_log2(ctx.uOceanL.y), l2 = lf - sb_log2(ctx.uOceanL.z);
  paw =sb_max(paw,0.0f);
  float3 a = sb_sw_xyz(ctx.uOceanAmp)* sb_vec3(oceanFarGain(ctx,xz),sb_sqrt(paw),paw);
  float4 D = __sb_textureLodArray(1,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),l0);
  float4 S = __sb_textureLodArray(2,sb_vec3(ctx.OCR0 * xz / ctx.uOceanL.x,0.0f),l0);
  d.y=D.y* a.x; {float2 sb_write0=(sb_sw_xz(D)* ctx.OCR0) * a.x;d.x=sb_write0.x;d.z=sb_write0.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR0) * a.x);
  if (l1 < 8.0f) {
    D =__sb_textureLodArray(1,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),l1); S =__sb_textureLodArray(2,sb_vec3(ctx.OCR1 * xz / ctx.uOceanL.y,1.0f),l1);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l1);
    d.y=d.y+(D.y* a.y* keep); {float2 sb_write1=sb_sw_xz(d)+((sb_sw_xz(D)* ctx.OCR1) * a.y* keep);d.x=sb_write1.x;d.z=sb_write1.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR1) * a.y* keep);
  }
  if (l2 < 8.0f) {
    D =__sb_textureLodArray(1,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),l2); S =__sb_textureLodArray(2,sb_vec3(ctx.OCR2 * xz / ctx.uOceanL.z,2.0f),l2);
    float keep=1.0f-sb_smoothstep(6.0f,8.0f,l2);
    d.y=d.y+(D.y* a.z* keep); {float2 sb_write2=sb_sw_xz(d)+((sb_sw_xz(D)* ctx.OCR2) * a.z* keep);d.x=sb_write2.x;d.z=sb_write2.y;}slope =slope +((sb_sw_xy(S)* ctx.OCR2) * a.z* keep);
  }
  return d;
}



__device__ float3 chopWaves(GraphicsContext& ctx,float2 xz,float t,float lod){
  float2 s; float3 d = oceanDisp(ctx,xz,lod,1.0f,s);
  return sb_vec3(d.y,s);
}


__device__ float2 sweUV(GraphicsContext& ctx,float2 xz){ return (xz - sb_sw_xy(ctx.uSweDom)) / sb_sw_zw(ctx.uSweDom); }

__device__ float sweInside(GraphicsContext& ctx,float2 xz){
  float2 uv = sweUV(ctx,xz);
  float2 e = sb_min(uv,1.0f- uv);

  return sb_smoothstep(0.0f,0.04f,sb_min(e.x,e.y* ctx.uSweDom.w/ 9.8f));
}


__device__ float plungeFactor(GraphicsContext& ctx,float style){ return sb_smoothstep(0.35f,0.75f,style); }

__device__ float gpulse(GraphicsContext& ctx,float tau,float T){ return tau <= 0.0f? 0.0f: tau / (T * T) * sb_exp((0-(tau ))/ T); }

__device__ float boilEnvG(GraphicsContext& ctx,float tau,float dec,float t0){ return tau <= t0 ? 0.0f: sb_min((tau - t0) / 0.15f,1.0f)* sb_exp((0-(sb_max(tau - t0 - 0.15f,0.0f)))/ dec); }

__device__ float spillStart(GraphicsContext& ctx,float D,float hs){ return sb_clamp((0-(D ))- 0.1f,(0-(0.9f)),(0-(0.3f)))- 0.3f* (1.0f- sb_smoothstep(0.4f,0.7f,hs)); }

__device__ float spillEnd(GraphicsContext& ctx,float hs){ return 0.05f- 0.4f* (1.0f- sb_smoothstep(0.4f,0.7f,hs)); }

__device__ float domePhase(GraphicsContext& ctx,float seed){ return 2.250f* sb_fract(seed * 3.7f)- 2.8273f; }

__device__ float domeField(GraphicsContext& ctx,float x,float seed){
  float ph = domePhase(ctx,seed);
  float k0 = sb_floor((x - ph) / 2.250f+ 0.5f);
  float a = 0.0f;
  for (int j = (0-(1)); j <= 1; j++) {
    float k = k0 + float(j);
    float c = ph + k * 2.250f+ 0.2f* (hash11(ctx,k * 7.13f+ seed * 91.7f)- 0.5f);
    bool even = sb_mod(k,2.0f)< 0.5f;
    float amp = (even ? 1.0f: 0.85f) * (0.92f+ 0.16f* hash11(ctx,k * 3.71f+ seed * 17.3f));
    float sg = even ? (x < c ? 0.3f: 0.6f) : (x < c ? 0.4f: 0.6f);
    a =sb_max(a,amp * sb_exp((0-(0.5f))* sb_pow((x - c) / sg,2.0f)));
  }
  return a;
}

__device__ float jetCentre(GraphicsContext& ctx,float x,float seed){
  float ph = domePhase(ctx,seed);
  float c1 = ph + sb_floor((x - ph - 2.15f) / (2.0f* 2.250f) + 0.5f)* 2.0f* 2.250f+ 2.15f;
  float c2 = ph + sb_floor((x - ph - 0.35f) / (2.0f* 2.250f) + 0.5f)* 2.0f* 2.250f+ 0.35f;
  return sb_abs(x - c1)< sb_abs(x - c2)? c1 : c2;
}

__device__ float jetMask(GraphicsContext& ctx,float x,float seed){
  float ph = domePhase(ctx,seed);
  float c1 = ph + sb_floor((x - ph - 2.15f) / (2.0f* 2.250f) + 0.5f)* 2.0f* 2.250f+ 2.15f;
  float c2 = ph + sb_floor((x - ph - 0.35f) / (2.0f* 2.250f) + 0.5f)* 2.0f* 2.250f+ 0.35f;
  return sb_max(sb_exp((0-(0.5f))* sb_pow((x - c1) / 0.17f,2.0f)),0.6f* sb_exp((0-(0.5f))* sb_pow((x - c2) / 0.17f,2.0f)));
}

__device__ float hasJetG(GraphicsContext& ctx,float seed){ return sb_step(0.35f,hash11(ctx,seed * 131.9f)); }

__device__ float featherPatch(GraphicsContext& ctx,float x,float tau,float seed){
  float r = 0.0f;
  for (int slot = 0; slot < 3; slot++) {
    float fs = float(slot);
    float xo = hash11(ctx,fs * 5.3f+ seed * 13.1f)* 1.9f;
    float cell = sb_floor((x + xo) / 1.9f);
    float h1 = hash11(ctx,cell * 1.91f+ fs * 7.7f+ seed * 31.3f);
    float h2 = hash11(ctx,cell * 3.17f+ fs * 2.9f+ seed * 11.9f);
    float h3 = hash11(ctx,cell * 0.73f+ fs * 4.1f+ seed * 5.7f);
    float cx = (cell + 0.3f+ 0.4f* h1) * 1.9f- xo;
    float half_ = 0.2f+ 0.2f* h2;
    float t0 = (0-(0.75f))+ 0.25f* h3 + fs * 0.12f;
    float dur = 0.2f+ 0.2f* h2;
    if (sb_abs(x - cx)< half_ && tau > t0 && tau < t0 + dur) r =r +(1.0f/ dur);
  }
  return r;
}


__device__ float domeLaunch(GraphicsContext& ctx,int i,float x,float ti){
  float tR = brkAt(ctx,i,x + 0.45f).ti, tL = brkAt(ctx,i,x - 0.45f).ti;
  float dtdx = (tR - tL) / 0.90f;
  return 0.25f* (tL + tR) + 0.5f* ti + sb_clamp(0.25f- 2.5f* sb_abs(dtdx),0.030f,0.25f);
}


__device__ float emitWeight(GraphicsContext& ctx,int k,int i,Brk b,float x){
  float tau = ctx.uTime - b.ti;
  float P = plungeFactor(ctx,b.style);
  float w = 0.0f;
  if (k == 0) w =gpulse(ctx,tau + 0.02f,0.045f)+ 0.4f* gpulse(ctx,tau - 0.04f,0.22f);
  else if (k == 7) { float hs = b.H/ 0.45f, s0 = spillStart(ctx,b.D,hs), s1 = spillEnd(ctx,hs); w =sb_smoothstep(0.4f,0.85f,b.spill)* sb_smoothstep(s0,s0 + 0.15f,tau)* (1.0f- sb_smoothstep(s1,s1 + 0.3f,tau)); }
  else if (k == 1 || k == 9 || k == 13) {
    float tl = ctx.uTime - domeLaunch(ctx,i,x,b.ti);
    w =gpulse(ctx,tl + 0.03f,0.065f)+ (k == 1 ? 0.12f* gpulse(ctx,tl - 0.08f,0.2f): 0.0f);
  }
  else if (k == 2) w =gpulse(ctx,tau + 0.010f,0.06f);
  else if (k == 8) w =gpulse(ctx,tau + 0.01f,0.07f)+ (tau > 0.2f? 0.6f* boilEnvG(ctx,tau,0.5f,0.12f): 0.0f);
  else if (k == 3 || k == 10) w =featherPatch(ctx,x,tau,b.seed);
  else if (k == 11) w =(ctx.uTime > b.tb+ 0.08f&& ctx.uTime < b.ti) ? 1.0f: 0.0f;
  else if (k == 4 || k == 12 || k == 14) w =gpulse(ctx,tau - 0.500f+ 0.03f,0.045f)* jetMask(ctx,x,b.seed)* hasJetG(ctx,b.seed);
  else if (k == 6) w =(1.0f+ (1.0f- P)) * sb_smoothstep(0.1f,0.3f,tau)* (1.0f- sb_smoothstep(1.5f,2.3f,tau));
  else w =(1.0f+ 1.2f* (1.0f- P)) * boilEnvG(ctx,tau,0.5f+ 0.6f* (1.0f- P),0.12f* P);

  if (k == 1 || k == 9 || k == 13 || k == 4 || k == 12 || k == 14) w =w *(ctx.uEvtG[i].y);
  else if (k == 6) w =w *(sb_sqrt(sb_max(ctx.uEvtG[i].x,0.0f)));
  return w;
}


__device__ bool isBlob(GraphicsContext& ctx,int k){ return k <= 7; }

__device__ bool isLig(GraphicsContext& ctx,int k){ return k >= 13; }

__device__ bool isRoller(GraphicsContext& ctx,int k){ return k == 0 || k == 5 || k == 6 || k == 7; }


__device__ float fragT(GraphicsContext& ctx,int k){ return isRoller(ctx,k)? 0.35f: k == 1 ? 0.22f: (k == 2 ? 0.25f: (k == 3 ? 0.10f: (k == 4 ? 0.12f: 0.3f))); }

__device__ float lifeMax(GraphicsContext& ctx,int k){
  if (k == 0 || k == 1) return 1.7f;
  if (k == 2) return 0.6f;
  if (k == 3) return 0.55f;
  if (k == 4) return 1.2f;
  if (k == 5) return 1.3f;
  if (k == 6) return 0.95f;
  if (k == 7) return 1.2f;
  return 2.0f;
}


__device__ float sheetness(GraphicsContext& ctx,int k){ return k == 1 ? 0.68f: (k == 2 || k == 3 || k == 4 ? 1.0f: 0.35f); }


__device__ float wLevel(GraphicsContext& ctx,float2 xz){
  float2 uv = sweUV(ctx,xz);
  float s = (uv.x< 0.0f|| uv.y< 0.0f|| uv.x> 1.0f|| uv.y> 1.0f) ? 0.0f: __sb_textureLod(10,uv,0.0f).x;
  return s;
}

__device__ void main(GraphicsContext& ctx){
  int id = ctx.gl_InstanceID;
  float2 ij = sb_ivec2(id % 384,id / 384);
  float4 P = __sb_texelFetch(7,ij,0);
  float4 Vl = __sb_texelFetch(8,ij,0);
  float4 At = __sb_texelFetch(9,ij,0);
  float age = P.w;
  int kd = int(Vl.w+ 0.5f);
  bool landed = kd >= 16;
  if (landed) kd =kd -(16);
