  else if (kd == 2) wfr =0.7f;
  else if (kd == 3) wfr =0.66f;
  else if (kd == 4) wfr =0.74f;
  else if (isRoller(ctx,kd)) wfr =sb_mix(0.8f,0.5f,sb_smoothstep(0.03f,0.12f,hw));
  else wfr =0.5f;

  if (kd == 1 && !landed) { float gs = sb_smoothstep(0.45f,0.2f,fph); sh =sb_mix(sh,1.0f,gs); wfr =sb_mix(wfr,0.85f,gs); }
  float fF = (1.0f- wfr) * (kd == 1 ? sb_smoothstep(0.1f,0.9f,fph)* 0.8f+ 0.2f: fph);


