  else if ((kd == 1 && !landed) || (kd == 7 && landed)) fF =fF *(sb_smoothstep((0-(0.01f)),ctx.uBaseH,hw));

  if (kd == 1) {wfr =wfr *(1.0f- 0.25f* ero);fF =fF *(1.0f- 0.45f* ero);}
  ctx.vPh =sb_vec2(fF,wfr);
  float4 mv = ctx.viewMatrix * sb_vec4(sb_sw_xyz(P),1.0f);

  if (d * r < 0.012f) { ctx.gl_Position =sb_vec4(2.0f,2.0f,2.0f,1.0f); return; }


  float3 vv = sb_mat3(ctx.viewMatrix)* sb_sw_xyz(Vl);
  float sp = length(sb_sw_xy(vv));
  float st = landed ? 1.0f: 1.0f+ 0.38f* sb_smoothstep(0.6f,1.0f,sh)* sb_smoothstep(0.5f,3.0f,sp);
  float2 dir = sp > 1e-3f? sb_sw_xy(vv)/ sp : sb_vec2(0.0f,1.0f);
  float2 perp = sb_vec2((0-(dir.y)),dir.x);
  float ra = r * st, rb = r / sb_sqrt(st);
  if (isRoller(ctx,kd)&& !landed) {
    float an = seed * 71.3f, asp = sb_mix(1.0f,2.2f,sb_fract(seed * 29.7f));
    dir =sb_vec2(sb_cos(an),sb_sin(an)); perp =sb_vec2((0-(dir.y)),dir.x);
    ra =r * sb_sqrt(asp); rb =r / sb_sqrt(asp);
  }
