  if (landed && kd == 7) { ra =r * 1.6f; rb =r * 0.75f; }

  float pxm = (0-(mv.z))* ctx.uPxScale;
  ctx.vFine =0.0f;
  float grow2 = sb_max(1.0f,1.3f* pxm / sb_max(rb,1e-4f));
