__device__ float brkEtaC(GraphicsContext& ctx,float H){ return 1.229f* H; }

__device__ float brkEtaT(GraphicsContext& ctx,float H){ return (0-(0.151f))* H; }









__device__ float brkStairX(GraphicsContext& ctx,float x,float seed){
  float s = x / 0.45f+ sb_fract(seed * 3.0f+ 0.485f);
  return x + 0.25f* 0.45f* (sb_floor(s)+ sb_smoothstep(0.45f,1.0f,sb_fract(s))- s + 0.175f);
}



__device__ float brkPeel(GraphicsContext& ctx,float4 D,float4 F,float x0,float x){
  float d = x - x0;
  float ds = sb_sqrt(d * d + 0.25f)- 0.5f;
  float a1 = d >= 0.0f? D.x: D.z, a2 = d >= 0.0f? D.y: D.w;
  if (a2 < 0.0f) ds =sb_min(ds,(0-(a1 ))/ (2.0f* a2));
  return a1 * ds + a2 * ds * ds + F.x/ (1.0f+ sb_exp((0-((x - F.y) ))/ sb_max(F.z,1e-3f)));
}




__device__ float brkClampX(GraphicsContext& ctx,float x){
  float e = sb_max(sb_abs(x)- 5.0f,0.0f);
  return x - sb_sign(x)* (e - 3.0f* e / (e + 3.0f));
}





__device__ float2 brkFarSD(GraphicsContext& ctx,float x,float ph){
  float3 a = sb_vec3(0.185f,0.33f,0.57f)* x + sb_vec3(6.2831853f* ph,17.1f* ph + 1.3f,41.7f* ph + 2.9f);
