  float3 T0 = normalize(sb_vec3(sgn * sb_cos(phi),sb_sin(phi),0.35f* (hash11(ctx,seed * 5.9f)- 0.5f)));
  float3 B0 = normalize(sb_vec3(T0.y,(0-(T0.x)),0.0f)+ sb_vec3(0.0f,(0-(0.4f)),0.0f));
  float Lr = At.y* (1.0f+ 0.8f* life);
  float bend = (hash11(ctx,seed * 3.1f)- 0.5f) * 0.7f;
  float uu = s - 0.5f;
  float3 Qa = sb_sw_xyz(P)+ T0 * (Lr * uu) + B0 * (bend * Lr * (uu * uu - 0.25f));
  float3 Ta = T0 + B0 * (bend * 2.0f* uu);

  float sp = sb_max(length(V),0.4f);
  float span = sb_min(At.y/ sp,sb_max(age - 0.03f,0.0f));
  float sg = s * span;
  float3 Qs = sb_sw_xyz(P)- V * sg - sb_vec3(0.0f,0.5f* 9.81f,0.0f)* sg * sg;
  float3 Ts = (0-((V + sb_vec3(0.0f,9.81f* sg,0.0f))));

  float3 T1 = normalize(V + sb_vec3(0.0f,0.0f,1e-3f));
  float3 B1 = normalize(cross(T1,sb_vec3(0.0f,0.0f,1.0f))+ sb_vec3(0.0f,0.0f,0.3f* (hash11(ctx,seed * 7.7f)- 0.5f)));
