struct GraphicsContext {
SBMat4 modelMatrix;
SBMat4 modelViewMatrix;
SBMat4 viewMatrix;
SBMat4 projectionMatrix;
SBMat3 normalMatrix;
float3 cameraPosition;
float3 position;
float3 normal;
float2 uv;
float2 vUv;
float4 gl_Position;
int gl_VertexID;
int gl_InstanceID;
};
__device__ void main(GraphicsContext& ctx){float2 p=sb_vec2(float((ctx.gl_VertexID<<1)&2),float(ctx.gl_VertexID&2));ctx.vUv=p;ctx.gl_Position=sb_vec4(p*2.0f-1.0f,0.0f,1.0f);}
__global__ void graphicsStage(const GraphicsContext* input,GraphicsContext* output){GraphicsContext ctx=input[0];
main(ctx);output[0]=ctx;}

